-- AP&E glossary — Machine B batch 1 — PASTE FILE 3 of 6
-- Paste this whole file into the Supabase SQL editor and Run. Order between files does not matter.
-- Idempotent: safe to re-run. Backup already exists (glossary_backup_mb_batch1_20260721).
BEGIN;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"0ee0816d-afe8-47e5-aa18-fc8e9bb5a605": {"definition": "In Ableton Live, the non-linear workspace where audio and MIDI clips sit in a grid of tracks (columns) and scenes (rows) and can be launched in any order, rather than along a fixed timeline. It is used for improvising, performing, and building ideas, in contrast to the timeline-based Arrangement View.", "plain_english": "In Ableton Live, it is a grid where you trigger short musical clips in any order instead of following one fixed timeline. It works like a set of buttons you press live to bring parts in and out.", "purpose_function": "It supports live performance and free experimentation by letting clips be started and combined on the fly, which a straight timeline cannot do easily. This makes it central to improvising and jamming.", "practical_application": "A performer loads loops into Session View, launches scenes to move through a song, and records the chosen order into the Arrangement View afterward.", "category": "DAW Interface", "related_terms": ["Arrangement View", "Clip", "Scene", "Return track", "Send level", "Clip launch"], "common_mistakes": ["Expecting clips to play in a fixed order, when Session View is random-access.", "Forgetting that only one clip per track plays at a time, so launching a new clip stops the old one.", "Not capturing a performance into Arrangement View, then losing the played order."], "scenario_contexts": ["Performing a live set by launching scenes in a chosen order.", "Jamming with loops to test arrangement ideas before committing them.", "Triggering backing parts on stage from a controller."]}, "8df98717-5162-4e2d-8c47-1b54ed72ad4b": {"definition": "A mixing goal of balancing the lead vocal so it sits clearly in front of and above the rest of the mix in perceived level and clarity, staying intelligible and present without being buried by the instruments. It is reached through level balance, EQ, compression, and effects that keep the voice forward.", "plain_english": "It means making the main singing clearly the loudest, front-most thing you hear over the music. It is like making sure a speaker's voice stands out over background chatter.", "purpose_function": "It ensures the listener follows the lyric and melody, which are usually the focus of a song, so the message and hook come across. A vocal that is too low leaves the song feeling unfocused.", "practical_application": "An engineer rides or compresses the vocal, carves space with EQ, and sets its level so it stays clearly audible over the loudest parts of the mix.", "category": "Mixing Technique", "related_terms": ["Lead vocal", "Level balance", "Compression", "De-essing", "Equalization", "Vocal ride"], "common_mistakes": ["Turning the vocal up so far it disconnects from the track and sounds pasted on.", "Fixing masking with volume alone instead of also using EQ to make room.", "Setting the level only in a quiet section, so the vocal disappears in the loud choruses."], "scenario_contexts": ["Balancing a pop mix where the lead vocal must stay clearly out front.", "Using compression to keep a dynamic vocal steady above a dense band.", "Checking the vocal level on small speakers to be sure it still cuts through."]}, "c201daf7-3df3-4c04-aa7d-b2568cb8a0a3": {"definition": "The overall operating sound level at which a live performance is actually run for the audience, typically at front of house, as distinct from lower soundcheck or rehearsal levels. It reflects the mix's real loudness during the show and is bounded by venue limits and hearing-safety exposure guidelines.", "plain_english": "It is how loud the mix is actually run during the real show, which is usually louder than at soundcheck. Bands and crowds push the energy up, so the level rises once the show starts.", "purpose_function": "Knowing show level lets an engineer set gain structure, headroom, and system tuning for the real performance rather than the quieter soundcheck, so the mix holds together when it counts. It also guides safe, legal loudness for the audience.", "practical_application": "An engineer leaves headroom at soundcheck because levels will climb at show level, then manages the mix and total loudness to stay within the venue's limits during the performance.", "category": "Live Sound Levels", "related_terms": ["Gain structure", "Headroom", "Sound pressure level", "Soundcheck", "Front of house", "System tuning"], "common_mistakes": ["Mixing tight at soundcheck with no headroom, then clipping when the show gets louder.", "Assuming crowd noise and stage volume stay the same from soundcheck to show.", "UNSAFE: Running show level so loud it exceeds safe exposure limits; follow OSHA occupational noise-exposure guidance, set SPL limits, and provide hearing protection to protect the audience and crew."], "scenario_contexts": ["Setting the PA and leaving headroom at soundcheck for a louder show level.", "Managing front-of-house loudness to a venue's SPL limit during the performance.", "Comparing quiet soundcheck balances against how the mix holds up at show level."]}, "e985a7ed-d7fa-4842-ba96-a7b0aa8301c9": {"definition": "The playback of pre-recorded audio material — backing tracks, click, sound effects, and cues — during a live performance or theatrical show, run from a dedicated playback system and triggered in time with the event.", "plain_english": "Show playback is the pre-recorded sound played during a live show, like backing tracks or sound effects. A person starts each clip at the right moment, like a DJ cueing songs on time.", "purpose_function": "It adds parts that cannot be performed live and keeps timed elements such as clicks, effects, and video sync accurate, so the show runs the same way every night.", "practical_application": "A playback operator loads the session, sends a click and backing tracks to the band via in-ears, and fires cues on the stage manager's call.", "category": "Playback", "related_terms": ["Click track", "Backing track", "Cue", "Timecode", "In-ear monitoring", "Stem"], "common_mistakes": ["Running playback with no backup machine or redundancy, so one crash stops the show", "Sending the click track to the front-of-house mix instead of only to the performers", "Not checking sample rate and tempo, so tracks drift out of sync with the band"], "scenario_contexts": ["A touring band runs backing synths and a click to in-ears while the drummer plays to the click", "A musical theatre production fires sound-effect cues from a playback rig on the operator's cue", "A corporate event plays walk-on music and stingers timed to the presenter"]}, "76d43a27-a08c-4be1-a0fa-e6762a944c09": {"definition": "In Ableton Live, the routing that feeds a device such as Compressor or Gate from a separate track or input (the sidechain source), so that the source's level, rather than the audio passing through the device, controls how much processing is applied.", "plain_english": "Sidechain routing in Ableton Live lets one track control an effect on another track. For example, a kick drum can automatically turn down the bass each time it hits, so both sounds fit together.", "purpose_function": "It lets one sound trigger dynamics on another — most often ducking bass or music under a kick or a voice — to create space and keep the mix clear.", "practical_application": "You open the Compressor's sidechain section, switch on the external input, and pick the kick track as the source so the bass ducks on every kick.", "category": "Signal Routing", "related_terms": ["Sidechain compression", "Ducking", "Compressor", "Gate", "Bus routing", "Threshold"], "common_mistakes": ["Forgetting to enable the external sidechain, so the compressor still reacts to the track's own signal", "Setting the threshold so low that the effect never releases, or so high that it never triggers", "Confusing the sidechain SC Gain with output volume — it only changes how strongly the source triggers the device"], "scenario_contexts": ["Ducking a bass line under the kick drum in a dance track", "Making a pad breathe in time with the kick for a pumping effect", "Ducking background music under a voiceover clip"]}, "25364e7e-d7ae-40ec-9547-0a7be3d8a0bd": {"definition": "The systematic process of confirming that audio travels correctly and at the proper level through every stage of a signal chain — source, cabling, processing, routing, and output — so faults are found and fixed before they affect the program.", "plain_english": "This means checking that sound really flows all the way through the system, from the input to the speaker. It is like following a hose from the tap to the nozzle to be sure water comes out where it should.", "purpose_function": "It catches broken cables, wrong routing, muted channels, and bad gain staging before a session or show, preventing dead channels and last-minute failures.", "practical_application": "A tech line-checks each input, watches the meters stage by stage, and listens at the output to confirm every source reaches the mix at the right level.", "category": "Signal Flow", "related_terms": ["Line check", "Signal flow", "Gain staging", "Metering", "Solo (in-place)", "Patch"], "common_mistakes": ["Checking only that sound reaches the output but not the level at each stage, missing gain-staging problems", "Skipping the check under time pressure and finding a dead channel during the show", "Assuming a lit meter means the correct source, without verifying it is the right input"], "scenario_contexts": ["Line-checking every input on a console before doors open", "Tracing why a channel is silent by testing each point from mic to monitor", "Verifying a new patch or routing change before recording a take"]}, "c1e9cea8-5410-49d5-ae07-3a1f272a3e79": {"definition": "In Logic Pro, a list editor that displays and edits a project's time and key signature changes as text entries with their bar positions, letting you add, move, or delete signature events precisely.", "plain_english": "The Signature List in Logic Pro is a text list of every time and key signature change in a song. You use it to see and edit exactly where the beat count or key changes, instead of dragging things on the timeline.", "purpose_function": "It gives an exact, numeric way to manage meter and key changes, which is useful for scores, tempo maps, and pieces that switch time signatures.", "practical_application": "A composer opens the Signature List to insert a 3/4 bar in the middle of a 4/4 song or to fix the bar where a key change lands.", "category": "DAW Editing", "related_terms": ["Signature track (Logic)", "Time signature", "Key signature", "Tempo List", "Event List", "Bar ruler"], "common_mistakes": ["Confusing the Signature List with the Tempo List — signatures set the beat grouping, not the speed", "Editing a signature and not checking that later bars still line up", "Entering a key-signature change and expecting it to transpose audio — it only affects notation"], "scenario_contexts": ["Adding a time-signature change for a bridge section", "Setting up a correct meter map so notation and the bar ruler line up", "Cleaning up stray signature events imported with a MIDI file"]}, "37f93d61-1d0e-4a2f-9d2c-e796de93b9ff": {"definition": "In Logic Pro, a global track that shows a project's time and key signature changes along the timeline, where you can create and edit signature events directly in line with the bar ruler and the other tracks.", "plain_english": "The Signature track in Logic Pro is a strip above your song that shows where the time and key signatures change. You can click on it to add or move a change, right where it happens on the timeline.", "purpose_function": "It gives a visual, timeline-based place to manage meter and key changes so they line up with the music, complementing the text-based Signature List.", "practical_application": "An engineer shows the Signature track, then clicks to drop a 6/8 change at the chorus so the metronome and grid follow the song.", "category": "DAW Editing", "related_terms": ["Signature List", "Global tracks", "Time signature", "Key signature", "Tempo track", "Bar ruler"], "common_mistakes": ["Leaving global tracks hidden and not finding the Signature track when a meter change is needed", "Placing a signature change off the bar line, causing an unexpected short bar", "Expecting a key-signature change to retune audio rather than only affect notation"], "scenario_contexts": ["Dropping a time-signature change at a section boundary so the click follows", "Building a meter map for a film cue that shifts between 4/4 and 7/8", "Matching the grid to a live recording that changes meter"]}, "bfc20fa1-22da-4a75-a24b-b129d11dd05d": {"definition": "A working mode in a sampler or DAW audio editor in which a sample is divided into individual slices at transient or grid points, and the slice markers can be added, moved, merged, or deleted to control where each segment begins.", "plain_english": "Slice edit mode lets you cut a sound, like a drum loop, into separate pieces and adjust where each cut lands. It is like slicing a loaf of bread and moving the cuts so each slice is the size you want.", "purpose_function": "It gives precise control over where a sample splits, so each hit or note can be triggered, moved, or re-timed on its own.", "practical_application": "A beginner opens a drum loop in slice edit mode, nudges the slice markers onto each drum hit, and then plays the slices from pads or keys.", "category": "Audio Editing", "related_terms": ["Slicing mode", "Transient", "Sampler", "Drum Rack", "Warping", "Quantize"], "common_mistakes": ["Setting the slice sensitivity too high, creating many false slices between the real hits", "Moving a slice marker past the transient so the hit's attack is cut off", "Confusing editing slice markers with permanently cutting the audio file"], "scenario_contexts": ["Fixing slice points on a break so each drum hit triggers cleanly", "Preparing a vocal chop to be played from a keyboard", "Tightening a loop so slices land exactly on the beat"]}, "dc1a0203-1771-4bd3-85e6-f386d4f93deb": {"definition": "A sampler or DAW mode that detects transients (or uses a beat or region grid) to split a sample into slices and maps each slice to a separate pad or key, so the segments can be played and re-sequenced independently.", "plain_english": "Slicing mode automatically chops a sample into pieces at each beat or hit and spreads them across your pads or keys. Then you can replay the pieces in any order, like rearranging beads on a string.", "purpose_function": "It turns a fixed audio loop into playable, re-arrangeable parts, so a loop can be re-timed, reordered, or rebuilt into a new pattern.", "practical_application": "An engineer uses Ableton's Slice to New MIDI Track command, and Live spreads each slice across a Drum Rack so the loop can follow a new tempo and pattern.", "category": "Audio Editing", "related_terms": ["Slice edit mode", "Transient", "Drum Rack", "Sampler", "Warping", "MIDI"], "common_mistakes": ["Slicing by beat when the loop is not tightly in time, so the slices miss the hits", "Forgetting that the slices still depend on warp and tempo settings for their timing", "Creating too many slices, making the loop hard to play and manage"], "scenario_contexts": ["Slicing a breakbeat to a Drum Rack to rearrange the groove", "Making a loop follow the project tempo by playing its slices", "Turning a melodic phrase into playable notes across a keyboard"]}, "d2eb6c77-f7cc-44c0-b9c1-f79f653d9b64": {"definition": "In Logic Pro, a set of on-screen controls mapped to key parameters of a track's channel strip and plug-ins, so several related settings can be adjusted together from one simplified panel and easily assigned to hardware controllers.", "plain_english": "Smart Controls in Logic Pro are a small panel of knobs and sliders. They set a track's most useful settings all at once. It is like a car dashboard. You get the main controls without opening every part under the hood.", "purpose_function": "They simplify sound tweaking by putting the most important parameters in one place and make it easy to map those controls to a MIDI keyboard or control surface for hands-on control.", "practical_application": "A producer opens the Smart Controls for a synth track and turns one knob that has been mapped to both the filter cutoff and the reverb amount.", "category": "DAW Control", "related_terms": ["Channel strip", "Plug-in", "Automation", "MIDI controller", "Patch", "Macro control"], "common_mistakes": ["Assuming Smart Controls are separate effects rather than remote controls for existing plug-in parameters", "Re-mapping a screen control and forgetting it now moves a different parameter", "Overlooking that saving the patch also stores the Smart Control mappings"], "scenario_contexts": ["Mapping a hardware knob to a Smart Control for live tweaking", "Adjusting a patch's tone quickly without opening each plug-in", "Automating a Smart Control to change several parameters at once"]}, "19fefb2d-e824-4fa1-98af-8336435d0d36": {"definition": "A class of equalizer that analyzes the incoming audio and automatically generates or suggests an EQ curve — smoothing resonances, balancing the tonal spectrum, or matching a target profile — which the user can then refine, rather than setting every band by ear alone.", "plain_english": "A Smart EQ listens to your sound and sets a starting EQ for you by itself. It is like a photo app that fixes the colors for you, giving a good result you can still change.", "purpose_function": "It speeds up tone shaping and helps less-experienced users by finding problem frequencies and a balanced curve quickly, which can then be fine-tuned by hand.", "practical_application": "An engineer plays a few seconds of a vocal through a Smart EQ, lets it learn and set a curve, then tweaks a band or two to taste.", "category": "Equalization", "related_terms": ["Equalizer", "Parametric EQ", "Resonance", "Spectral analysis", "Tonal balance", "Match EQ"], "common_mistakes": ["Trusting the automatic curve blindly without listening to it in the full mix", "Letting it learn from a bad or unrepresentative section, giving a wrong curve", "Assuming a smart EQ replaces learning EQ fundamentals rather than assisting them"], "scenario_contexts": ["Getting a fast starting EQ on a vocal before manual tweaks", "Taming harsh resonances on a recorded instrument", "Matching a track's tonal balance to a reference"]}, "9923a422-d4a4-44fb-9617-babff356b2c2": {"definition": "Smart Tempo is a tempo-management feature in Apple Logic Pro that analyzes the tempo of a performance or audio recording and either conforms that audio to the project tempo or sets the project tempo to follow the performance. It offers Keep, Adapt, and Automatic modes and can flex audio to the grid without manual time-stretching.", "plain_english": "Smart Tempo is a Logic Pro tool that works out the speed of a recording. It can then bend the recording to match the song's beat, or make the song follow the player's timing instead.", "purpose_function": "It exists to reconcile tempo differences between recorded material and the project grid, so freely played or imported audio can line up with the metronome and the other tracks without tedious hand editing.", "practical_application": "An engineer records a guitarist who plays without a click, then uses Smart Tempo's Adapt mode to build a tempo map from the performance so added drums and edits stay in time.", "category": "Tempo & Timing", "related_terms": ["Tempo map", "Flex Time", "Beat mapping", "Click track", "Quantization"], "common_mistakes": ["Leaving Smart Tempo in Automatic when importing loops, so Logic re-analyzes and shifts a tempo the user meant to keep", "Trusting the automatic beat detection on rubato or sparse material without checking beat markers in the Smart Tempo Editor", "Confusing flexing the audio to the tempo (Keep) with adapting the tempo to the audio (Adapt)"], "scenario_contexts": ["Aligning a freely recorded vocal take to a programmed drum grid", "Importing a two-bar drum loop and matching it to the session tempo", "Building a tempo map from a live band recording so overdubs stay in time"]}, "8775ec4e-b48f-45f7-95fc-e20a1ce78a9c": {"definition": "Smartphone translation is how well a finished mix holds up when played on a phone's small, band-limited built-in speaker or cheap earbuds. Because such speakers reproduce little low end and a narrow stereo image, engineers reference the mix on a phone to confirm that vocals, key elements, and overall balance stay clear.", "plain_english": "This means checking whether a mix still sounds good on a phone's tiny speaker. Phones play almost no bass and are nearly mono, so a mix that works there usually works everywhere else too.", "purpose_function": "It exists because most listeners hear music on phones, so testing on that speaker catches balance problems, such as a buried vocal or a missing bass line, that large studio monitors can hide.", "practical_application": "After mixing on studio monitors, an engineer plays the bounce through a phone speaker to make sure the lead vocal and the groove still come through before the mix is approved.", "category": "Mix Translation", "related_terms": ["Translation", "Reference monitors", "Nearfield monitor", "Mono compatibility", "A/B referencing"], "common_mistakes": ["Assuming a mix that sounds full on big monitors will translate to a phone, then finding the bass and vocal disappear", "Judging tonal balance from a phone speaker instead of using it only as a reality check", "Forgetting that phone speakers are essentially mono, so mono compatibility problems show up there"], "scenario_contexts": ["Checking a pop vocal balance on a phone before client sign-off", "Confirming a podcast stays intelligible on a phone at low volume", "Testing whether the kick and bass still read on a small speaker"]}, "acf42b29-cef9-4c9e-a229-237795e23922": {"definition": "Snapshot recall automation is the automated storing and recall of a complete console or mix state, such as fader levels, mutes, routing, and processing settings, saved as named snapshots (scenes) that can be triggered on cue. On digital consoles, recall filters and safes let selected parameters be excluded so live changes carry across snapshots.", "plain_english": "A snapshot saves every setting on the mixer at once. That includes faders, mutes, and effects, all under one name. Recall automation calls those settings back on cue. The whole desk jumps to a new setup in an instant.", "purpose_function": "It exists to reconfigure a large mix instantly for different songs, scenes, or moments, letting one operator manage far more changes than could ever be made by hand in real time.", "practical_application": "A theatre engineer stores a snapshot for each scene, then steps through them with a footswitch or MIDI cue so mics, levels, and effects change exactly on the script.", "category": "Automation", "related_terms": ["Scene recall", "Mix automation", "Recall safe", "Cue list", "MIDI control"], "common_mistakes": ["Forgetting to set recall safes, so a snapshot overrides a fader the operator is riding live", "Storing snapshots with the wrong parameters included, causing unexpected routing or gain jumps on recall", "UNSAFE: Recalling a snapshot that unmutes or raises outputs without checking, risking sudden high levels and feedback"], "scenario_contexts": ["Stepping through scene changes in a musical or play", "Recalling a fresh channel setup between bands at a festival", "Jumping to a preset monitor mix for a guest performer"]}, "ee668bed-e8e4-4e95-88a1-f1346d0f5295": {"definition": "Snare layering is the blending of one or more additional snare sounds, such as samples or separately recorded hits, underneath or alongside the original snare track to reinforce its body, attack, or tone. The layers are time-aligned and balanced so they read as a single, stronger snare.", "plain_english": "Snare layering means stacking extra snare sounds on top of the recorded one. It is like adding a second snare hit in the background to make the main hit sound bigger or punchier.", "purpose_function": "It exists to fix or enhance a weak, dull, or inconsistent recorded snare by adding the crack, ring, or weight it lacks, all without re-recording the drums.", "practical_application": "A mixer triggers a snare sample in time with each recorded hit and blends it low under the original to add attack that cuts through a dense rock mix.", "category": "Drum Processing", "related_terms": ["Snare sample", "Drum replacement", "Sample triggering", "Transient shaping", "Phase alignment"], "common_mistakes": ["Adding a layer without checking phase, so the combined snare sounds thinner instead of bigger", "Letting the sample's tone or tuning clash with the original snare's pitch", "Layering so loud that the sample replaces the natural drum instead of supporting it"], "scenario_contexts": ["Reinforcing a flat studio snare in a rock mix", "Adding consistent attack to uneven live-recorded hits", "Blending a bright sample under a dull snare to help it cut"]}, "2a56725b-987a-471e-8082-ceea20bcafdd": {"definition": "A snare sample is a pre-recorded digital recording of a single snare-drum hit, stored for playback so it can reinforce, replace, or program snare sounds in a mix. Samples are commonly triggered from the recorded snare's transients or sequenced within a drum instrument.", "plain_english": "A snare sample is a saved recording of one snare hit. Engineers play it back to add to or swap out the real snare in a song, a bit like using a stock sound in place of the recorded one.", "purpose_function": "It exists to give the engineer a controlled, consistent snare sound on demand, useful for reinforcing a weak recording, replacing a bad one, or building programmed drums.", "practical_application": "When a recorded snare sounds thin, an engineer loads a snare sample into a trigger plug-in that fires it in sync with each original hit.", "category": "Drum Samples", "related_terms": ["Snare layering", "Drum replacement", "Sample triggering", "Sampler", "One-shot"], "common_mistakes": ["Choosing a sample whose room sound or tone does not match the rest of the kit", "Triggering from a snare mic with bleed, so hi-hat hits fire the sample by mistake", "Aligning the sample late so its attack smears against the original hit"], "scenario_contexts": ["Replacing an unusable live snare recording", "Programming snare hits in a beat with a drum sampler", "Reinforcing a recorded snare during mixdown"]}, "81b79ec2-8704-4158-a4cc-722d894073c8": {"definition": "In MOTU Digital Performer, a song chunk is a type of chunk that arranges sequence chunks into an ordered playlist, letting sections or songs be strung together into a larger arrangement within one project. Chunks (sequences, songs, and V-racks) coexist in a single project file and share resources.", "plain_english": "In Digital Performer, a song chunk is a playlist that lines up separate sections in order to build a full song. Think of it as an arrangement list that plays your saved parts one after another.", "purpose_function": "It exists so an arranger can build and reorder a full piece from independent sections without copying data, keeping every version and arrangement inside one project.", "practical_application": "A composer writes the verse and chorus as separate sequence chunks, then uses a song chunk to play them in order and try different arrangements quickly.", "category": "Session Management", "related_terms": ["Soundbite", "Sequence", "V-rack", "Playlist", "Arrangement"], "common_mistakes": ["Confusing a song chunk (a playlist of sequences) with a single sequence chunk", "Editing a source sequence and not realizing the change appears everywhere the song chunk uses it", "Expecting a song chunk to store its own audio rather than referencing existing sequences"], "scenario_contexts": ["Assembling verse and chorus sequences into a finished song", "Trying alternate song arrangements from the same sections", "Building a live set order from separate sequences"]}, "e5a381c2-cd9d-4644-bd2b-c52140f1daab": {"definition": "A sound-effects stem is the submixed group of all sound-effects elements, such as hard effects, Foley, and backgrounds, delivered as one balanced audio unit within the dialogue-music-effects (DME) stem structure of a film or broadcast mix. Kept separate from the dialogue and music stems, it can be re-balanced or swapped for different formats and languages.", "plain_english": "A sound-effects stem holds all the sounds that are not music or speech. Think of footsteps, doors, and background noise, all mixed into one track. Keeping it apart lets editors change the effects later without touching the words or the music.", "purpose_function": "It exists so the effects portion of a mix can be adjusted, archived, or reused on its own, which is key for foreign-language versions where dialogue is replaced but music and effects are retained.", "practical_application": "A re-recording mixer prints separate dialogue, music, and effects stems so the distributor can create a music-and-effects (M&E) version for dubbing into other languages.", "category": "Stems", "related_terms": ["Stem", "DME", "M&E", "Dialogue stem", "Music stem"], "common_mistakes": ["Bouncing effects into the dialogue or music stem, which breaks M&E deliverables", "Assuming a single effects stem when the spec calls for split Foley and backgrounds", "Forgetting that summing the DME stems must reproduce the full final mix"], "scenario_contexts": ["Delivering DME stems for a film master", "Creating an M&E mix for foreign-language dubbing", "Rebalancing the effects level without remixing dialogue"]}, "3f41541e-5f1f-40a5-8843-13d8943abc0a": {"definition": "In MOTU Digital Performer, a soundbite is the program's term for a single clip of audio, that is, a region of an audio file that appears in a track and can be edited, arranged, and processed. Soundbites reference audio stored on disk and are managed in the Soundbites window.", "plain_english": "In Digital Performer, a soundbite is one clip of audio you place on a track. It is simply that program's name for an audio chunk you can move, trim, and edit, like a clip in any other editor.", "purpose_function": "It exists as DP's basic unit of audio, letting the user handle recorded or imported sound as discrete, editable pieces rather than as one long file.", "practical_application": "An editor drags a vocal soundbite earlier on the timeline and trims its edges to tighten the phrasing of a take.", "category": "Audio Editing", "related_terms": ["Soundbites window", "Song chunk", "Region", "Waveform editor", "Take"], "common_mistakes": ["Deleting a soundbite from a track but expecting the source audio file to be removed from disk", "Confusing a soundbite (a clip reference) with the underlying audio file itself", "Trimming a soundbite and thinking the audio data has been permanently cut"], "scenario_contexts": ["Comping vocal takes from several soundbites", "Trimming and moving audio clips on a track", "Arranging imported sound effects as soundbites"]}, "66536b42-2d7b-4a80-b57e-bfbc50eb3640": {"definition": "In MOTU Digital Performer, the Soundbites window is the browser that lists and manages every soundbite (audio clip) in the project, showing details such as name, duration, sample rate, and source file. From it the user can audition, rename, import, and drag soundbites into tracks.", "plain_english": "The Soundbites window in Digital Performer is a list of all the audio clips in your project. You use it to find, preview, and drag any clip onto a track, like a library of your sounds.", "purpose_function": "It exists to give one central place to organize and reuse a project's audio, so clips can be found, previewed, and placed without hunting through the tracks.", "practical_application": "A mixer opens the Soundbites window to audition several recorded snare hits, then drags the best one onto a track.", "category": "Audio Editing", "related_terms": ["Soundbite", "Song chunk", "Audio pool", "Region list", "Import audio"], "common_mistakes": ["Deleting a soundbite from the window and unintentionally removing it from the project", "Assuming the window stores audio when it only references files on disk", "Overlooking the window as the place to import and organize audio"], "scenario_contexts": ["Auditioning takes before placing them on tracks", "Managing all imported sound effects in one list", "Renaming clips to keep a session organized"]}, "c2eed830-1250-4d80-a5db-7017244d554a": {"definition": "The reference signal and monitoring levels established for each input and output during soundcheck, used as the baseline settings from which the engineer mixes once the performance begins.", "plain_english": "The volume settings the sound engineer dials in during soundcheck. They act as a starting point, so the mix is close to right the moment the show begins.", "purpose_function": "It gives the engineer a known, repeatable starting point for gain structure and for monitor and front-of-house levels, reducing surprises and feedback risk when the show starts.", "practical_application": "During soundcheck a technician sets input gains and fader positions per source, notes or saves them, then fine-tunes from those soundcheck levels during the actual performance.", "category": "Live Sound", "related_terms": ["Gain structure", "Monitor mix", "Front of house", "Line check", "Feedback"], "common_mistakes": ["Assuming soundcheck levels will hold during the show, when a full room and energetic performers change stage volume and gain needs.", "Setting levels with only one player instead of the full band, so the balance falls apart once the whole song plays.", "UNSAFE: Pushing monitor or PA levels far above soundcheck settings without regard to safe hearing-exposure limits."], "scenario_contexts": ["Setting each channel's gain and fader during a pre-show soundcheck at a club.", "Recalling saved soundcheck levels on a digital console before a second night of a tour.", "Adjusting up from soundcheck levels once the venue fills with an audience."]}, "8e06a77c-5205-4c52-be13-7632048435e2": {"definition": "Sonarworks' monitor and headphone calibration software that measures the frequency response of a room and speakers, or applies a stored headphone profile, and inserts a correction filter to flatten playback toward a neutral reference response.", "plain_english": "Software from Sonarworks that fixes the sound of your speakers or headphones. It measures how they color the sound, then evens out the tone so your mixes translate well to other systems.", "purpose_function": "It exists to remove the tonal coloring of a room, speakers, or headphones so mixing decisions rest on a neutral reference rather than a flattering or misleading playback.", "practical_application": "An engineer measures the room with the supplied microphone or loads a headphone model, then runs the SoundID Reference plugin on the monitor path to hear a corrected, flat response while mixing.", "category": "Monitoring", "related_terms": ["Room correction", "Monitor calibration", "Frequency response", "Reference monitor", "Translation"], "common_mistakes": ["Trusting the correction after moving the speakers or listening far off-axis, which invalidates the original measurement.", "Believing correction fully fixes a bad room, when acoustic treatment is still needed for reflections and low-frequency problems.", "Leaving the calibration plugin active on the output at export, so the correction is printed into the final file."], "scenario_contexts": ["Calibrating a project-studio monitor setup before starting a mix.", "Loading a headphone profile to mix while travelling.", "Comparing mix translation between corrected and uncorrected monitoring."]}, "2dc0f80a-9701-450c-b82d-7c38b2a35bca": {"definition": "The degree to which the frequency content or tonal balance of audio stays uniform over time and between related elements, such as across sections of a song, between edited takes, or across different playback systems.", "plain_english": "How steady the tone of a sound stays from moment to moment. If the brightness and weight do not jump around between parts, the mix has good spectral consistency.", "purpose_function": "Keeping it steady makes a mix or edit sound cohesive and professional, so the listener is not distracted by sudden shifts in brightness, thickness, or tonal color.", "practical_application": "A technician checks spectral consistency when comping vocal takes or matching a punch-in, using EQ or a spectrum analyzer so the joined parts share the same tonal balance.", "category": "Mix Fundamentals", "related_terms": ["Tonal balance", "Equalization", "Spectrum analyzer", "Frequency response", "Comping"], "common_mistakes": ["Comping takes recorded on different mics or positions without matching EQ, so the tone shifts audibly between phrases.", "Judging balance only by ear on colored monitors, missing a buildup in a narrow frequency band.", "Chasing a perfectly flat analyzer reading instead of a musical tonal balance."], "scenario_contexts": ["Matching the tone of two vocal takes joined at a comp edit.", "Ensuring verse and chorus guitars keep a consistent tonal balance.", "Checking that a mix holds its tonal balance on phone, car, and studio speakers."]}, "40ec5efd-47d2-40c9-bbc8-5c0d4be61950": {"definition": "In Logic Pro's Flex Time, the Speed algorithm time-stretches audio by changing playback speed like a tape machine, so the material's pitch rises or falls together with its tempo instead of being held constant.", "plain_english": "Speed mode stretches or shrinks audio by playing it faster or slower, like speeding up a tape. When it plays faster the pitch goes up, and when it plays slower the pitch goes down.", "purpose_function": "It provides a resampling-style, varispeed time-stretch that deliberately couples pitch to tempo, giving vintage tape character that pitch-preserving algorithms remove; it exists as a creative/FX option in the Flex Time algorithm set.", "practical_application": "An engineer selects the Speed algorithm on a Flex-enabled region when they want tape-style pitch-and-tempo shifts on drums or effects rather than a transparent tempo change.", "category": "Time-Stretch Algorithm", "related_terms": ["Tempophone mode", "Flex Time", "Varispeed", "Time stretching", "Tempo set"], "common_mistakes": ["Assuming Speed keeps the original pitch; it deliberately changes pitch with tempo, unlike the Monophonic or Polyphonic modes.", "Using it on tonal, harmonic material and expecting a clean result, when it is best suited to percussive or effect sounds.", "Confusing the Flex Time Speed algorithm with a global transport or project varispeed."], "scenario_contexts": ["Speeding up a drum loop so it rises in pitch like a classic tape pull-up.", "Creating a downward pitch-and-tempo drop as a transition effect.", "Fitting a percussive sample to the session tempo when the retro pitch shift is wanted."]}, "6de0914f-a6e4-4cd0-b49f-e9963b5ae551": {"definition": "A utility device in Reason Studios' Reason that combines several audio signals into one and splits one audio signal into several, providing a merge section (multiple inputs summed to a single output) and a splitter section (one input copied to multiple outputs).", "plain_english": "A tool in the Reason music program that joins audio cables together or splits one into many. Think of it like a power strip for audio signals inside the software.", "purpose_function": "It exists to work around the fixed number of jacks on Reason devices, letting you feed several sources into one input or send one output to many destinations.", "practical_application": "On the back of the Reason rack a user patches, for example, one instrument output through the splitter to several effects, or merges several returns into a single mixer channel.", "category": "Signal Routing", "related_terms": ["Signal routing", "Patch cable", "Mixer", "Send effect", "Spider Control Voltage Merger and Splitter"], "common_mistakes": ["Confusing the merge and splitter halves and patching a source into an output jack.", "Expecting the merge section to sum many hot signals cleanly without watching for clipping.", "Using the audio Spider for modulation duties, which need the CV Spider instead."], "scenario_contexts": ["Sending one synth output to three different effect chains at once.", "Merging several instrument outputs into one channel for group processing.", "Expanding limited device connections in a complex Reason rack."]}, "656023f4-eb33-49f3-bca3-ed7020974e57": {"definition": "A utility device in Reason that merges and splits control-voltage (CV) and gate signals, with a merge section that sums several CV sources into one output and a splitter section that copies one CV signal to multiple outputs, including inverted outputs for reversed modulation.", "plain_english": "This is a tool in the Reason program for modulation signals. Those are the hidden controls that move knobs by themselves. It sends one control signal out to many places. It can also combine several signals into one.", "purpose_function": "It lets one modulation source, such as an LFO or envelope, drive several parameters at once, or lets several modulation sources be combined before reaching a destination.", "practical_application": "A user patches an LFO into the CV splitter to sweep filter cutoff on several synths together, or uses an inverted output so one control opens one parameter while closing another.", "category": "Signal Routing", "related_terms": ["Control voltage", "Gate signal", "LFO", "Modulation", "Spider Audio Merger and Splitter"], "common_mistakes": ["Patching audio through the CV Spider, which is meant for control and gate signals, not audio.", "Forgetting that merged CV signals add together, producing more modulation depth than expected.", "Overlooking the built-in inverted outputs and hand-patching a second reversed modulation source instead."], "scenario_contexts": ["Driving several synth parameters from a single LFO.", "Combining an envelope and an LFO into one modulation signal.", "Using an inverted CV output for opposing modulation of two parameters."]}, "cf54c0d5-6b8e-4ffa-8769-77640aad96b4": {"definition": "An informal term for audio that has been heavily compressed or limited so its dynamic range is greatly reduced, often to the point of audibly flattened transients and diminished punch or life.", "plain_english": "A word for sound that has been compressed so hard it loses its punch. The loud and quiet parts get pushed to almost the same level, so it can sound flat or lifeless.", "purpose_function": "The term flags an audible side effect of over-processing dynamics, warning that too much compression or limiting has traded transient impact and openness for loudness or consistency.", "practical_application": "An engineer calls a drum bus or master squashed when a compressor or limiter is set too hard, then eases the ratio, threshold, or make-up gain to restore dynamics.", "category": "Dynamics", "related_terms": ["Compression", "Limiting", "Dynamic range", "Transient", "Loudness war"], "common_mistakes": ["Adding heavy master limiting for loudness and squashing the mix until it loses impact.", "Confusing a squashed, over-compressed sound with a naturally dense arrangement.", "Judging loudness on quiet monitors and over-compressing until the mix is squashed."], "scenario_contexts": ["Diagnosing a lifeless master that has been limited too hard.", "Describing an over-compressed drum bus during a mix review.", "Comparing a dynamic mix with a squashed, loudness-maximized version."]}, "e4d388d0-8bce-4e8f-a4f2-f41f4f10259f": {"definition": "A stage wash is a broad, even, relatively soft field of light that covers the whole stage or a large area of it, produced with wash or flood fixtures rather than tightly focused spotlights, to supply general illumination and overall colour or tone for a scene.", "plain_english": "A stage wash is a wide, even blanket of light that covers the whole stage at once. It lights everything softly instead of pointing a tight beam at one spot.", "purpose_function": "It provides the base layer of visibility and colour across the performance area so performers can be seen everywhere, on top of which sharper specials and spotlights are added.", "practical_application": "A lighting technician builds a stage wash by hanging and focusing wash fixtures to blend into even coverage, often in a chosen colour, then balances specials and spots against it.", "category": "Stage Lighting", "related_terms": ["Front of house", "Backlight", "Spotlight", "Colour wash", "Lighting cue"], "common_mistakes": ["Confusing a wash (broad, soft coverage) with a spot (narrow, focused beam).", "Assuming 'stage wash' is an audio term; it is a stage-lighting term and appears here under a mismatched topic.", "Relying on a wash alone with no specials, leaving the scene flat and without focus."], "scenario_contexts": ["Lighting a full band evenly before adding solo spotlights.", "Setting a coloured wash to establish the mood of a theatrical scene.", "Providing overall even visibility across a conference stage for camera."]}, "c9fad748-eca7-42ed-b105-2e2e9d436714": {"definition": "Stealth music is a low-intensity, tense music state used in games and stealth-themed media that plays while the player is sneaking or avoiding detection; it is typically quiet and sparse to convey caution, and is designed to transition into combat or alert music if the player is discovered.", "plain_english": "Stealth music is the quiet, tense music that plays in a game while you sneak around trying not to be seen. If a guard spots you, it usually switches to louder action music.", "purpose_function": "It reinforces the sneaking gameplay state and player caution, and serves as one node in an adaptive music system that changes with the player's situation.", "practical_application": "A game-audio implementer sets up a stealth cue as a music state in middleware such as Wwise or FMOD, then defines transitions to combat or exploration music based on game parameters.", "category": "Score Cue Type", "related_terms": ["Suspense music", "Victory music", "Transition matrix", "Transition segment", "Tension layer"], "common_mistakes": ["Making stealth music too busy or loud, which undercuts the tense, quiet feel.", "Failing to author smooth transitions to combat music, causing an abrupt jump when the player is detected.", "Treating it as a fixed track rather than an adaptive state that responds to gameplay."], "scenario_contexts": ["Sneaking past guards in a stealth action game.", "Infiltrating a base while avoiding detection.", "Switching from stealth to combat music the moment an alarm triggers."]}, "ae730278-1940-4668-a8e3-dd55b5e26e24": {"definition": "The quality-control process of checking exported stems (grouped submixes such as drums, bass, and vocals) to confirm they are complete, in sync, free of clipping, in the correct format, and sum back to match the reference full mix before delivery.", "plain_english": "Stems are grouped mixdowns, like all the drums bounced into one file. Stem validation means checking these files to make sure they play in time, do not distort, and add back up to sound like the finished mix.", "purpose_function": "It exists to catch errors before delivery, ensuring the stems a client, mastering engineer, or post house receives will recombine into the intended mix without missing parts, level jumps, or timing offsets.", "practical_application": "After bouncing stems, an engineer imports them into a fresh session at unity gain, sums them, and null-tests or listens against the reference mix to verify they match before sending them out.", "category": "Mix Validation", "related_terms": ["Stem", "Bounce", "Reference mix", "Null test", "Stereo compatibility validation", "Gain staging"], "common_mistakes": ["Bouncing stems with different start points or lengths so they no longer line up when reimported", "Leaving master-bus processing on individual stems, so they no longer sum to the reference mix", "Assuming stems are correct without actually summing them back and comparing to the mix"], "scenario_contexts": ["Preparing drum, bass, music, and vocal stems for a mastering engineer", "Delivering stems to a film or TV post house for the re-recording mix", "Creating stems for a live performance backing-track rig"]}, "dbaf5fca-51b5-4f3d-bc37-ff68f8de0adb": {"definition": "In a step sequencer, the length of time a triggered step's note sounds, usually set as a gate value that is a percentage of the step's time slot; a shorter duration produces staccato notes while a longer one sustains the note toward or into the next step.", "plain_english": "In a step sequencer, step duration is how long each note is held. A short setting makes clipped, punchy notes; a long setting lets the note ring out until the next one.", "purpose_function": "It shapes the rhythmic feel and articulation of a pattern, letting a programmer choose between tight, detached notes and smooth, connected ones without changing the pattern's timing grid.", "practical_application": "A producer shortens step duration on a bassline for a plucky, staccato groove, or lengthens it and adds ties to create sustained, legato lines.", "category": "Step Sequencing", "related_terms": ["Step resolution", "Step velocity", "Step repeat", "Step Editor", "Tie", "Gate time"], "common_mistakes": ["Confusing step duration (how long the note sounds) with step resolution (how far apart steps are)", "Setting very long durations and then wondering why overlapping notes sound stuck or muddy", "Forgetting that gate/duration is a percentage of the step, so it changes with tempo and step rate"], "scenario_contexts": ["Programming a staccato synth bassline", "Creating legato pad movement in a pattern", "Tightening a hi-hat pattern by shortening gate times"]}, "07c3ddc9-013d-4929-9119-814ced6601e0": {"definition": "A grid-based MIDI editor that displays the note and controller events of a region as vertical beams within a user-defined time grid, where each beam's height represents a value such as velocity or a controller amount, enabling fast step-based creation and editing of drum patterns and control data.", "plain_english": "The Step Editor is a grid-style MIDI editor. Each note or control value shows up as a bar, and taller bars mean bigger values, so you can quickly draw and tweak drum hits and how loud they are.", "purpose_function": "It exists to make repetitive rhythmic and controller editing fast and precise, showing several lanes of MIDI data at once so a user can build patterns and adjust values like velocity without dragging tiny points.", "practical_application": "A producer uses the Step Editor to punch in a drum groove, then adjusts the velocity beams to accent certain hits and draws in controller moves such as filter cutoff.", "category": "MIDI Editing", "related_terms": ["Step velocity", "Step duration", "MIDI controller", "Piano Roll", "Step Sequencer", "Velocity"], "common_mistakes": ["Confusing the Step Editor (a MIDI event editor) with a step sequencer that generates patterns automatically", "Editing the wrong lane, so velocity or controller changes land on the wrong data type", "Not setting the correct grid or lane set, so events do not align as expected"], "scenario_contexts": ["Building and refining a drum pattern's velocities", "Drawing MIDI controller automation such as modulation or cutoff", "Quickly correcting note velocities across a busy percussion part"]}, "daa20a55-9370-4497-96b7-ef55a1628eeb": {"definition": "A per-step sequencer setting that defines the percentage chance a step will trigger on any given pass; at 100% it always plays and at 50% it plays roughly half the time, with each step evaluated independently to produce randomized variation.", "plain_english": "Step probability sets the odds that a step actually plays. At 100% it plays every time; at 50% it plays about half the time, like a coin flip each loop, which adds surprise and variety.", "purpose_function": "It exists to add controlled randomness and human-like unpredictability to patterns, keeping loops from sounding identical every bar and generating fills and variations automatically.", "practical_application": "A producer lowers probability on ghost snare hits so they appear only now and then, making a looped beat feel less mechanical over a long section.", "category": "Step Sequencing", "related_terms": ["Step velocity", "Step repeat", "Step Sequencer", "Randomization", "Step duration", "Groove"], "common_mistakes": ["Expecting the exact same pattern every loop when probability is set below 100%", "Setting key downbeats below 100% and losing the groove's backbone", "Confusing per-step probability with a global randomizer that affects the whole pattern"], "scenario_contexts": ["Adding occasional ghost notes to a drum loop", "Creating evolving, generative melodies", "Introducing fills that appear at random over a long arrangement"]}, "d1902980-314e-490a-95b2-ff35d189a61e": {"definition": "A per-step function that retriggers a step's note multiple times within its single time slot (also called note repeat or ratcheting), subdividing the step into rapid repeated hits, for example turning one sixteenth-note step into two or four faster notes.", "plain_english": "Step repeat makes one step fire several fast notes instead of one. It chops a single slot into quick repeats, like a drum roll packed into one beat.", "purpose_function": "It exists to create rolls, stutters, and rhythmic subdivisions inside a pattern without adding more steps, adding energy and detail to drums and synth lines.", "practical_application": "A producer sets step repeat to 4 on a snare step to make a quick roll into a drop, or ratchets a hi-hat step for a burst of faster notes.", "category": "Step Sequencing", "related_terms": ["Step duration", "Step velocity", "Step resolution", "Ratcheting", "Step Sequencer", "Step probability"], "common_mistakes": ["Confusing step repeat (repeats inside one step) with looping the whole pattern", "Setting high repeat counts that clutter the groove and lose punch", "Forgetting that very fast repeats depend on the tempo and step rate"], "scenario_contexts": ["Building a snare roll leading into a drop", "Adding hi-hat stutters and rolls", "Creating trap-style rapid hi-hat subdivisions"]}, "78ee5a7b-9126-43b1-8914-cb774c0e407e": {"definition": "The note value assigned to each step in a sequencer pattern (its step rate), setting how much musical time one step represents (for example 1/16 makes each step a sixteenth note), which together with the pattern length determines the timing grid and total pattern duration.", "plain_english": "Step resolution is how much time each step stands for, like a sixteenth note. It sets how fast the steps march along and how fine the timing grid is.", "purpose_function": "It exists to define a pattern's rhythmic grid and speed, letting a programmer choose coarse or fine timing and control how long the whole pattern lasts.", "practical_application": "A producer sets step resolution to 1/16 for a standard 16-step bar, then switches to 1/32 to double the speed of a hi-hat pattern.", "category": "Step Sequencing", "related_terms": ["Step duration", "Pattern length", "Step Sequencer", "Step repeat", "Quantization", "Tempo"], "common_mistakes": ["Confusing step resolution (spacing between steps) with step duration (how long each note sounds)", "Changing the resolution and not realizing the whole pattern's length changed too", "Assuming 16 steps always equals one bar regardless of the resolution setting"], "scenario_contexts": ["Setting a 16-step pattern to 1/16 for one bar", "Doubling hi-hat speed by switching to 1/32", "Making a slow, spacious pattern with 1/8 resolution"]}, "9a357033-6b62-45bb-9b4a-ea794dc37a5e": {"definition": "A per-step adjustment that shifts a step's start time earlier or later than its grid position, typically expressed as a percentage of the step rate (for example -50% to +50%), used to add swing, push, drag, or micro-timing feel to a pattern.", "plain_english": "Step timing offset nudges a single step a little earlier or later than the grid. It lets you push or drag notes off the strict beat to add swing and a human feel.", "purpose_function": "It exists to loosen the rigid sequencer grid, letting a programmer create groove, swing, and natural timing variation instead of perfectly quantized, mechanical hits.", "practical_application": "A producer nudges snare or hat steps slightly late to add a laid-back swing, or pushes a step early to give a part more urgency.", "category": "Step Sequencing", "related_terms": ["Swing", "Quantization", "Step resolution", "Step duration", "Step Sequencer", "Groove"], "common_mistakes": ["Confusing a per-step offset with a global swing or quantize setting", "Offsetting so far that a step overlaps or crosses into a neighboring step", "Nudging every step the same amount, which just moves the pattern instead of adding groove"], "scenario_contexts": ["Adding a laid-back feel to a hi-hat pattern", "Pushing a snare slightly to change the groove", "Dialing in swing on a programmed drum beat"]}, "134ec08f-8bb4-4660-a388-029e5b586ce1": {"definition": "The MIDI velocity value assigned to an individual step in a sequencer, ranging from 1 to 127, which sets how hard that step's note is struck and typically controls its loudness and, depending on the instrument, its tone or brightness.", "plain_english": "Step velocity is how hard each step's note is hit, on a scale of 1 to 127. Higher velocity usually means louder and often brighter, just like hitting a drum harder.", "purpose_function": "It exists to add dynamics and accents to an otherwise flat pattern, letting a programmer emphasize certain hits and shape the groove's feel through changes in loudness and tone.", "practical_application": "A producer raises velocity on downbeat kicks and lowers it on ghost snares so a looped beat breathes with natural accents instead of sounding uniform.", "category": "Step Sequencing", "related_terms": ["Velocity", "Step duration", "Step probability", "Accent", "Step Editor", "Dynamics"], "common_mistakes": ["Leaving every step at the same velocity, giving a lifeless, machine-like groove", "Assuming velocity only changes volume when many instruments also change tone with it", "Confusing velocity (how hard a note is struck) with the track's overall fader level"], "scenario_contexts": ["Accenting downbeats in a drum pattern", "Creating dynamic ghost notes on a snare", "Adding expression to a programmed synth line"]}, "c787486d-70b6-481c-8300-74e11fefce48": {"definition": "The process of checking that a stereo mix still holds together when summed to mono, verifying that phase relationships between the left and right channels do not cause elements to lose level or disappear, so the mix translates correctly on mono playback systems.", "plain_english": "This means checking that a stereo mix still sounds right when both sides are added into one mono signal. If the left and right fight each other, parts can get quieter or vanish, so you test for it.", "purpose_function": "It exists to guarantee a mix survives mono playback on phones, clubs, TV, and public-address systems, where out-of-phase content can cancel and make instruments or vocals drop out.", "practical_application": "An engineer sums the master to mono and listens for level drops or missing parts, watches a correlation meter, and then fixes wide stereo effects or out-of-phase tracks that cancel.", "category": "Mix Validation", "related_terms": ["Mono compatibility", "Phase", "Correlation meter", "Mid-side", "Stem validation", "Phase cancellation"], "common_mistakes": ["Never checking the mix in mono until after it is released", "Using heavy out-of-phase stereo wideners that collapse or cancel when summed to mono", "Assuming stereo headphones reveal mono problems, when only summing to mono exposes them"], "scenario_contexts": ["Checking a mix before broadcast delivery where it may be summed to mono", "Ensuring a track holds up on a mono club or PA system", "Verifying vocals stay present when a phone speaker plays in mono"]}, "4da9aa47-82ce-4b5a-83b6-27142809be74": {"definition": "A stinger cue is a playback cue that fires a stinger: a short, sharp musical or sound-effect accent used to punctuate a moment in a show, broadcast, or production. It is triggered on demand by the operator, normally as a one-shot that plays once without looping.", "plain_english": "A stinger cue is a button that plays a short, sharp sound to mark a big moment. Think of the quick 'sting' you hear on a game show when someone gives a wrong answer.", "purpose_function": "It lets an operator drop a brief, attention-grabbing sound on cue to punctuate an action, reveal, or transition without interrupting the main audio flow.", "practical_application": "In live theatre or broadcast, a sound operator loads stingers into a cue list, for example in QLab, and fires one on the exact beat, such as a dramatic hit at a scene reveal.", "category": "Playback Cue", "related_terms": ["Cue list", "One-shot sample", "Bumper", "Sound effect (SFX)", "Playback engine"], "common_mistakes": ["Looping a stinger instead of setting it as a one-shot, so it repeats", "Setting the stinger level too low to cut through the mix", "Firing the stinger a beat late because the cue was not pre-loaded and armed"], "scenario_contexts": ["Punctuating a wrong answer on a live game show", "Adding a dramatic hit at a scene reveal in theatre", "Marking a transition between segments in a live broadcast"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"68c8339a-46c7-4095-add0-23e7fa486686": {"definition": "Streaming compliance is the practice of preparing a mix or master so it meets the loudness, true-peak, and delivery specifications of streaming platforms. Common platform normalization targets are around -14 LUFS integrated loudness with a maximum true peak of -1 dBTP to avoid codec-induced clipping, though AES TD1008 itself recommends a quieter target near -16 LUFS for music.", "plain_english": "Streaming compliance means making sure your song fits the rules of services like Spotify or Apple Music. The main rule is keeping the loudness and peak levels in the range they ask for, so the track plays back cleanly.", "purpose_function": "It exists so a release plays back at a consistent, predictable level and does not distort after a platform turns it down or encodes it, keeping the artist's intended sound intact.", "practical_application": "Before uploading, an engineer checks the master on a loudness meter and adjusts level and limiting so the integrated loudness and true peak land inside the platform's targets.", "category": "Streaming Delivery", "related_terms": ["LUFS", "True peak", "Loudness normalization", "Integrated loudness", "Streaming compliance verification", "Mastering"], "common_mistakes": ["Mastering far louder than the target, which the platform just turns down and which often adds true-peak distortion", "Ignoring true peak and letting the codec clip on peaks near 0 dBFS", "Assuming every platform uses the same target when their normalization levels differ"], "scenario_contexts": ["Preparing a single for release on Spotify and Apple Music", "Checking a podcast episode meets a distributor's loudness spec", "Delivering a mastered album that stays consistent across streaming services"]}, "a8315cb5-8b5c-4fae-9585-4f072944923b": {"definition": "Streaming compliance verification is the quality-control step of measuring a finished mix or master against a streaming platform's delivery specification. Using an ITU-R BS.1770 or EBU R128 loudness meter, the engineer confirms integrated loudness, true peak, and often loudness range fall within the required limits before delivery.", "plain_english": "This is the final check that your song follows the streaming rules before you send it out. You run the track through a loudness meter and read the numbers to make sure they are in range.", "purpose_function": "It catches level and true-peak problems before release, so the track is not rejected, turned down unexpectedly, or distorted after encoding.", "practical_application": "An engineer runs the bounced master through a metering plugin, reads integrated LUFS and true peak, and re-exports if any value is out of spec.", "category": "Streaming Delivery", "related_terms": ["Streaming compliance", "LUFS", "True peak", "Loudness meter", "Integrated loudness", "Quality control (QC)"], "common_mistakes": ["Reading momentary or short-term loudness instead of integrated loudness for the whole track", "Verifying with a meter that is not ITU-R BS.1770 compliant", "Skipping true-peak metering and only checking sample peak"], "scenario_contexts": ["Final QC pass on a master before uploading to a distributor", "Confirming a broadcast deliverable meets EBU R128", "Batch-checking loudness across an album so tracks match"]}, "6e268346-48ae-48db-98dc-41f34b5aeea9": {"definition": "A streaming mix is a mix balanced and leveled with streaming playback in mind, where platforms apply loudness normalization and lossy codec encoding. It prioritizes clarity, controlled dynamics, mono compatibility, and headroom over raw loudness, so the balance survives normalization.", "plain_english": "A streaming mix is a mix made to sound good on services like Spotify, which even out the volume of every song. Because loudness gets matched, you focus on a clean, clear balance instead of just making it loud.", "purpose_function": "It ensures the song still sounds full, clear, and correctly balanced after a platform normalizes its level and compresses it into a streaming codec.", "practical_application": "A mix engineer references the track on earbuds and phone speakers, checks the mono fold-down, and leaves headroom so the mastering stage can hit streaming loudness targets cleanly.", "category": "Streaming Delivery", "related_terms": ["Streaming compliance", "Loudness normalization", "Mono compatibility", "Headroom", "Streaming translation", "LUFS"], "common_mistakes": ["Over-compressing the mix to chase loudness the platform will only turn down", "Leaving no headroom for the mastering and limiting stage", "Not checking how the mix folds to mono on phone speakers"], "scenario_contexts": ["Mixing a single destined mainly for Spotify and Apple Music", "Delivering a mix that must hold up on phone and earbud playback", "Preparing a mix so the master can meet streaming loudness targets"]}, "404b6f71-dd4a-43b1-9a7c-4fee4850802a": {"definition": "Streaming translation refers to how well a mix or master holds up, or translates, after streaming platforms apply loudness normalization and lossy codec encoding. Good streaming translation means the balance, tonality, and impact stay consistent across services and playback devices despite that processing.", "plain_english": "Streaming services change your song's volume. They also squash it into a smaller file. Streaming translation is how well your song survives that. If it still sounds balanced and clear on any service or phone, it translates well.", "purpose_function": "It matters because a mix that sounds great in the studio can shift once a platform normalizes and encodes it; aiming for good translation keeps the artist's intended sound intact for listeners.", "practical_application": "An engineer auditions a codec preview, for example an AAC or Ogg encode, at the platform's playback level to hear tonal or peak changes, then adjusts the mix or master to compensate.", "category": "Streaming Delivery", "related_terms": ["Mix translation", "Loudness normalization", "Lossy codec", "True peak", "Streaming compliance", "Reference monitoring"], "common_mistakes": ["Judging the mix only at full studio level, not the platform's normalized level", "Ignoring codec artifacts on bright, peaky material", "Assuming all platforms sound the same after encoding"], "scenario_contexts": ["Comparing a master before and after AAC encoding", "Checking a release sounds consistent on Spotify, Apple Music, and YouTube", "Diagnosing why a loud master sounds dull after normalization"]}, "f6bf16ac-abfe-4b80-b21d-f34ab17ba5c6": {"definition": "In PreSonus Studio One, a Project is the mastering document used to assemble finished songs into a sequenced album or release. It provides a mastering chain, track spacing and metadata, and export to disc image, digital files, and DDP, with a link that updates it when a source Song changes.", "plain_english": "A Studio One Project is the part of the program where you turn finished songs into a full album. You line up the tracks, set the gaps and loudness, add final polish, and export the whole release.", "purpose_function": "It exists to handle mastering and album assembly separately from mixing, so an engineer can level-match songs, sequence them, and produce consistent delivery files.", "practical_application": "After mixing each Song, an engineer adds them to a Project, applies mastering plugins, sets spacing and metadata, then exports the album for streaming or disc.", "category": "DAW Document Type", "related_terms": ["Studio One Song", "Studio One Show", "Mastering", "DDP", "LUFS", "Sequencing"], "common_mistakes": ["Confusing the Project (mastering) page with the Song (mixing) page", "Trying to record or arrange audio in a Project instead of a Song", "Forgetting to update the Project after re-mixing a linked Song"], "scenario_contexts": ["Assembling and mastering an album from individual mixed songs", "Level-matching and sequencing tracks for a release", "Exporting a mastered set as a DDP image for replication"]}, "712dfcc9-c528-47c1-b91c-09db3071c73c": {"definition": "In PreSonus Studio One, a Show is the live-performance document created on the Show Page. It organizes a setlist of songs, with backing tracks, virtual instruments, and per-song patches, plus a performance view for playing a set in real time on stage.", "plain_english": "A Studio One Show is a file built for playing live. It holds your setlist, backing tracks, and instrument sounds so you can move through a gig one song at a time.", "purpose_function": "It exists so musicians can arrange, rehearse, and perform a whole set live from the DAW, switching songs and sounds without loading separate sessions.", "practical_application": "A performer builds a Show, adds each song's backing tracks and patches, sets the setlist order, then runs the gig from the Show Page's performance view.", "category": "DAW Document Type", "related_terms": ["Studio One Song", "Studio One Project", "Setlist", "Patch", "Backing track", "Virtual instrument"], "common_mistakes": ["Confusing a Show (live performance) with a Song (recording and mixing)", "Not testing patch changes before the gig, causing gaps between songs", "Overloading the CPU with too many live instruments and no freezing or bouncing"], "scenario_contexts": ["Running a live set with backing tracks and instrument patches", "Rehearsing a setlist in performance order", "Switching songs and sounds hands-free during a show"]}, "e10f6ac7-99bc-46db-b335-e19319d34bfc": {"definition": "In PreSonus Studio One, a Song is the primary document for recording, editing, arranging, and mixing a single piece of music. It contains the audio and instrument tracks, the arrangement, and the mix console, and can be sent to a Project for mastering.", "plain_english": "A Studio One Song is the main file where you record and mix one track. It holds your recordings, the arrangement, and the mixer, all in one place.", "purpose_function": "It is the working session where all recording, editing, and mixing happen for one piece of music before it is mastered.", "practical_application": "An engineer opens a Song to track parts, edit takes, and mix, then adds the finished Song to a Project for mastering.", "category": "DAW Document Type", "related_terms": ["Studio One Project", "Studio One Show", "Arrangement", "Mix console", "Track", "Session"], "common_mistakes": ["Trying to master or sequence an album inside a Song instead of a Project", "Confusing a Song with a Show used for live performance", "Not setting the correct sample rate before recording a Song"], "scenario_contexts": ["Recording and mixing a single track", "Editing takes and comping vocals in the arrangement", "Sending a finished mix to a Project for mastering"]}, "4c6c1e3c-2a13-4ab9-9372-32703a06f28f": {"definition": "In Logic Pro, a Summing Stack is a type of Track Stack that routes the outputs of its subtracks to a shared bus, with the main track becoming an aux (audio subgroup) that sums them into a submix. Unlike a Folder Stack, which groups tracks without changing their routing, a Summing Stack lets the whole group be processed and controlled as one.", "plain_english": "A Summing Stack in Logic Pro is a folder that combines several tracks into one submix. All the tracks feed into a single channel, so you can add effects and control their volume together.", "purpose_function": "It lets you build a submix, for example all drums or all backing vocals, so shared processing and level control apply to the whole group through one aux channel.", "practical_application": "A mixer selects the drum tracks and creates a Summing Stack so the kit runs through one bus, then adds glue compression and rides the group with a single fader.", "category": "Track Routing", "related_terms": ["Folder Stack", "Track Stack", "Aux channel", "Bus", "Submix", "VCA"], "common_mistakes": ["Confusing a Summing Stack (routes to a bus) with a Folder Stack (VCA control, no routing change)", "Expecting individual subtrack outputs to stay direct after summing", "Adding duplicate processing on both the subtracks and the summing aux"], "scenario_contexts": ["Creating a drum submix on one bus for glue compression", "Grouping backing vocals to process and fade together", "Building stems by summing related tracks to shared auxes"]}, "935244ee-898c-492c-839f-17cd08c1aff0": {"definition": "A DAW command that temporarily disables the reading and writing of pan automation, so recorded pan moves are ignored and no new ones are captured until it is re-enabled. The stored pan automation data is preserved and resumes when suspension is turned off.", "plain_english": "Pan automation is saved left-right moves for a track. This command pauses those moves for now. The pan stays where you set it by hand. Your saved moves are kept and come back when you turn it on again.", "purpose_function": "It lets an engineer freeze automated panning so they can set or audition a static pan without erasing or fighting recorded pan moves.", "practical_application": "During a mix, a technician suspends pan automation to reposition a source by hand or compare a static pan to the automated version, then re-enables it.", "category": "Automation", "related_terms": ["Suspend volume automation", "Suspend send automation", "Suspend plug-in automation", "Automation mode", "Pan automation pass", "Read automation mode"], "common_mistakes": ["Forgetting to turn pan automation back on, so recorded pan moves stay silent for the rest of the session.", "Confusing suspending automation, which keeps the data, with clearing automation, which deletes it.", "Not realizing suspend can be set globally, so pan moves are off across the whole session, not just one track."], "scenario_contexts": ["Auditioning a fixed pan position against the automated version during a mix.", "Turning off pan moves while troubleshooting a stereo-image problem.", "Holding pan still while re-recording other automation passes."]}, "d5ee58fd-bd7e-4aed-9805-1c7be356e964": {"definition": "A DAW command that temporarily disables the reading and writing of automation on plug-in parameters, so automated plug-in settings hold at fixed values and no new plug-in automation is captured until it is re-enabled. The stored automation data is preserved.", "plain_english": "Plug-ins can have settings that move on their own, saved as automation. This command pauses those moving settings. The plug-in knobs hold still for now. The saved moves are kept and return when you switch it back on.", "purpose_function": "It lets an engineer hold automated plug-in settings still so they can dial in or compare fixed values without overwriting recorded parameter moves.", "practical_application": "A technician suspends plug-in automation to tweak an EQ or reverb control while auditioning, then re-enables it so the recorded moves play back.", "category": "Automation", "related_terms": ["Suspend volume automation", "Suspend pan automation", "Suspend send automation", "Automation mode", "Plug-in automation", "Write automation mode"], "common_mistakes": ["Leaving plug-in automation suspended, so a needed filter or level sweep never plays back.", "Thinking suspend erases the plug-in automation, when it only pauses playback and recording.", "Suspending all plug-in automation when only one parameter needed adjusting."], "scenario_contexts": ["Dialing in a static EQ setting while its automation is temporarily paused.", "Comparing a plug-in's fixed setting against its automated moves.", "Bypassing plug-in automation while chasing a gain-staging issue."]}, "bc9ab745-350d-43a3-b691-fcb400ce2053": {"definition": "A DAW command that temporarily disables the reading and writing of automation on aux send controls such as send level, pan, and mute, so send settings hold at fixed values and no new send automation is captured until re-enabled. The stored data is preserved.", "plain_english": "A send feeds part of a track to an effect like reverb. Its level can move on its own from saved automation. This command pauses those send moves. The send holds still, and the saved moves come back when you turn it on again.", "purpose_function": "It lets an engineer hold automated send levels still so they can set or audition a fixed send without overwriting recorded send moves.", "practical_application": "A technician suspends send automation to set a fixed effect send by hand, then re-enables it so automated throws return on playback.", "category": "Automation", "related_terms": ["Suspend volume automation", "Suspend pan automation", "Suspend plug-in automation", "Send automation pass", "Aux send", "Automation mode"], "common_mistakes": ["Forgetting to re-enable send automation, so an automated reverb or delay throw goes missing.", "Confusing suspend, which is temporary, with deleting the send automation data.", "Overlooking that send pan and send mute automation are suspended along with send level."], "scenario_contexts": ["Setting a static reverb send while comparing it to the automated throws.", "Pausing send automation to rebalance an effect return by hand.", "Turning off send moves while troubleshooting a level issue."]}, "5737556a-8f86-4161-8c8b-17fe81b10953": {"definition": "A DAW command that temporarily disables the reading and writing of volume (fader) automation, so recorded level moves are ignored and no new ones are captured until it is re-enabled. The stored volume automation data is preserved and resumes when suspension is turned off.", "plain_english": "Volume automation is saved fader moves for a track. This command pauses those moves for now. The level stays where you set it by hand. The saved moves are kept and return when you switch it on again.", "purpose_function": "It lets an engineer freeze automated fader levels so they can set or audition a static level without erasing or fighting recorded volume moves.", "practical_application": "A technician suspends volume automation to rebalance a fader by hand or audition a static level, then re-enables it to restore the recorded ride.", "category": "Automation", "related_terms": ["Suspend pan automation", "Suspend send automation", "Suspend plug-in automation", "Automation mode", "Fader automation", "Read automation mode"], "common_mistakes": ["Forgetting to switch volume automation back on, so fader rides never play back.", "Confusing suspending automation with deleting it, and losing recorded moves that were only paused.", "Suspending volume automation globally and wondering why no fader on any track responds."], "scenario_contexts": ["Auditioning a fixed fader level against an automated vocal ride.", "Pausing volume moves to rebalance a track by hand.", "Holding levels static while re-recording pan or plug-in automation."]}, "19921ded-9e00-4d3c-9d78-d7092fd16706": {"definition": "Suspense music is underscore written to build and sustain tension, unease, or anticipation in the audience during a film, television, or game scene, typically using sustained dissonance, low drones, sparse rhythmic pulses, and gradual dynamic build rather than clear melody or resolution.", "plain_english": "Suspense music is background music that makes a scene feel tense, so you feel something bad might happen. It often uses low, uneasy sounds that slowly grow.", "purpose_function": "It shapes the audience's emotional response, signalling threat or anticipation and heightening dramatic tension in step with the on-screen action.", "practical_application": "A composer or music editor places a suspense cue under a stalking or countdown scene and mixes it to swell as tension peaks, often resolving into a stinger or a sudden release.", "category": "Score Cue Type", "related_terms": ["Stealth music", "Victory music", "Tension layer", "Stinger", "Underscore"], "common_mistakes": ["Overloading a suspense cue with melody or resolution, which releases the tension too early.", "Mixing it too loud so it competes with dialogue instead of supporting the scene.", "Confusing suspense (building anticipation) with a jump-scare stinger (a single sudden hit)."], "scenario_contexts": ["Underscoring a character creeping through a dark house.", "Building tension during a bomb-defusal countdown.", "Scoring the slow reveal of a threat in a thriller."]}, "7dfa8285-1b77-4a9b-8203-9b06e0b701d5": {"definition": "In a layered sampled or synthesized instrument, the sustain layer is the component that supplies the steady, held portion of a note after the initial attack, sounding for as long as the note is held. It is combined or crossfaded with attack and release layers to form a complete note.", "plain_english": "A note has a start, a held middle, and an end. The sustain layer is the held middle part. It keeps sounding while you hold the key down. Sampled instruments blend it with the sharp start to sound real.", "purpose_function": "It supplies the continuous body of a note, separating the steady held tone from the transient attack so an instrument can hold and be shaped naturally.", "practical_application": "When programming a sampled instrument, a technician balances the sustain layer against the attack layer to control how much a note holds versus punches.", "category": "Sound Design", "related_terms": ["Attack layer", "Velocity layer", "ADSR envelope", "Sample library", "Round robin", "Crossfade"], "common_mistakes": ["Assuming the sustain layer alone sounds realistic without a matching attack layer.", "Setting the sustain layer too loud, so notes lose their natural attack punch.", "Confusing the sustain layer of a sampled instrument with the sustain stage of an ADSR envelope."], "scenario_contexts": ["Programming a sampled string patch that holds while a key is pressed.", "Balancing attack and sustain layers to shape a synth pad.", "Adjusting how long the sustained body of a note rings in a sampler."]}, "0e69306f-b3a3-4583-8b27-2b5e70ca8f25": {"definition": "Swing amount is a groove parameter that sets how far the off-beat notes of each pair are delayed from their strict grid position, usually expressed as a percentage, to create a swung, less mechanical rhythmic feel. At 50 percent the timing is straight; higher values push the off-beats later toward a triplet feel.", "plain_english": "A grid keeps notes perfectly even, which can sound stiff. Swing amount nudges every other note a little late. This gives the beat a bouncy, groovy feel. Turn it up for more bounce.", "purpose_function": "It humanizes programmed rhythms by shifting off-beats, letting a producer move a stiff quantized part toward a natural swung groove.", "practical_application": "A technician raises the swing amount on a drum or hi-hat pattern in the sequencer until the programmed groove feels right against the track.", "category": "Sequencing", "related_terms": ["Quantize", "Groove template", "Shuffle", "Sequencer", "Ratcheting", "Tempo"], "common_mistakes": ["Applying heavy swing to straight material where it fights the song's feel.", "Assuming 50 percent swing adds groove, when 50 percent is actually straight timing.", "Swinging every track by a different amount, so the groove no longer locks together."], "scenario_contexts": ["Adding swing to a programmed hi-hat pattern to loosen the groove.", "Matching a drum machine's swing to a sampled loop's feel.", "Dialing back swing on a part that sounds too loose against the band."]}, "67c81746-cd2c-4bfd-b837-1c419aa18f86": {"definition": "System limiting is the use of limiters within a sound system's signal chain, typically in loudspeaker-management or amplifier DSP, to cap output level and protect drivers and amplifiers from over-excursion, overheating, and clipping. Thresholds are set to the components' rated limits so peaks are held back rather than allowed to cause damage.", "plain_english": "Speakers and amps can be wrecked by too much level. System limiting sets a ceiling the signal cannot pass. It catches loud peaks before they damage the gear. Think of it as a safety cap on volume.", "purpose_function": "It protects loudspeakers and amplifiers from over-excursion, overheating, and clipping damage while keeping the system within safe operating limits.", "practical_application": "During system tuning, a technician sets limiter thresholds in the loudspeaker processor or amplifier DSP to the manufacturer's rated limits so the rig cannot be driven into damage.", "category": "System Processing", "related_terms": ["Loudspeaker management", "Limiter", "Amplifier headroom", "Gain structure", "Peak limiter", "Driver protection"], "common_mistakes": ["UNSAFE: Raising or bypassing system limiters to chase more level, which can destroy drivers and amplifiers.", "Setting limiter thresholds by ear instead of to the loudspeaker and amplifier manufacturer's rated limits.", "Relying on limiting to cover an undersized system instead of providing proper headroom.", "Assuming a limiter removes all risk, when sustained abuse can still overheat voice coils."], "scenario_contexts": ["Setting limiter thresholds in a loudspeaker processor during system tuning.", "Protecting subwoofers from over-excursion at a high-SPL show.", "Configuring amplifier DSP limiters to the driver's rated power."]}, "c1346793-79b5-4a64-91bf-d0d491779ac1": {"definition": "\"Take a lap\" is informal studio slang for stepping away from a session for a short break, leaving the room or building, to rest fatigued ears and regain objective perspective before making further mixing or performance decisions.", "plain_english": "Take a lap means step away and take a short break during a session. Resting your ears helps you hear the mix clearly again when you come back.", "purpose_function": "It counteracts the ear fatigue and loss of objectivity that build up over a long session, so decisions are made with fresh, reliable hearing.", "practical_application": "When a mix stops improving or the room grows tense, an engineer or producer calls a short break, leaves the control room, then returns with fresh ears and quickly notes any problems.", "category": "Studio Workflow", "related_terms": ["Ear fatigue", "Reference track", "Monitoring level", "Fresh ears", "Mixdown"], "common_mistakes": ["Staying at the desk on a phone instead of truly leaving the acoustic space, which does not reset your hearing.", "Ignoring fatigue and pushing on, then making changes you regret once your ears are rested.", "Forgetting that fresh ears last only a short time, so failing to note issues quickly on return."], "scenario_contexts": ["Pausing a long mix session to rest the ears before final balancing.", "Stepping out after many tracking takes to reset before overdubs.", "Leaving the control room to break tension during a difficult session."]}, "4ea6549f-5f9e-45ac-826f-c036987a9b2c": {"definition": "In REAPER, Take FX is an effects chain applied to a single media item (take) rather than to the whole track, so the plugins process only that one item's audio and travel with it. In the signal path the Take FX chain runs before the track's own FX chain.", "plain_english": "Take FX are effects that you put on just one recorded clip instead of the whole track. It is like adding a filter to a single photo in an album, not to every photo at once.", "purpose_function": "It lets you process or repair one specific take or clip without affecting other items on the same track, and keeps that processing attached to the clip if it is moved.", "practical_application": "A REAPER user adds a de-esser or pitch plugin as Take FX on one vocal comp clip while leaving the rest of the track untouched.", "category": "DAW Editing", "related_terms": ["Track FX", "Comping", "Insert effect", "Signal chain", "Take"], "common_mistakes": ["Confusing Take FX with Track FX and wondering why an effect only changes one clip.", "Forgetting that Take FX are lost if the take is deleted or the item is glued/flattened.", "Applying corrective processing as Take FX and then not carrying it when moving the clip to another track."], "scenario_contexts": ["Fixing a single loud breath or click on one vocal clip during comping.", "Time-stretching or pitch-correcting one imported loop without changing the whole track.", "Adding a temporary effect to audition an idea on a single item."]}, "e6f7113d-a9a2-4c75-b17e-eda682efb027": {"definition": "A function in a mixer, mixer-amplifier, or paging system by which a designated talk or announcement microphone automatically overrides other inputs, ducking or muting them while it is in use so the spoken message is heard clearly. Priority is set by input assignment, a press-to-talk contact, or voice-activated (VOX) detection.", "plain_english": "This is a setting that lets one microphone cut through by turning down the music or other sound while someone talks. It works like a car radio that drops the volume when the GPS voice speaks.", "purpose_function": "It ensures paging and announcement messages stay intelligible by automatically lowering competing audio, without an operator having to ride the faders.", "practical_application": "An installer wires a paging mic to the priority input of a commercial mixer-amplifier so store announcements duck the background music.", "category": "Routing & Control", "related_terms": ["Ducking", "Talkback", "Paging", "VOX", "Mute group"], "common_mistakes": ["Assuming the loudest mic automatically wins; priority must be configured on the input.", "Setting the VOX threshold too low so background noise falsely triggers ducking.", "UNSAFE: Relying on a background-music paging system for emergency messages without confirming it meets the site's life-safety and evacuation requirements."], "scenario_contexts": ["A retail store where staff announcements must duck the background music.", "A house of worship where a speaker's mic takes priority over the music mix.", "A transit hub where safety pages override all other audio zones."]}, "91478040-24df-4b57-9e30-b6c6c2912187": {"definition": "A target EQ curve is a defined desired frequency-response shape that an engineer equalizes toward, used as a reference for matching a mix, master, or monitoring system to a chosen tonal balance. Match-EQ and room-correction tools measure the source and apply filtering to move its response closer to the target.", "plain_english": "A target EQ curve is the tone shape you are aiming for, drawn as a line across the frequencies. It is like a recipe that says how much bass, mids, and treble the finished sound should have.", "purpose_function": "It gives an objective goal for tonal balance so mixes translate consistently and monitoring systems can be corrected to a known standard.", "practical_application": "A mastering engineer loads a reference track's target curve into a match-EQ plugin, or a mixer applies a room-correction target curve to flatten studio monitors.", "category": "EQ & Tone", "related_terms": ["Match EQ", "Room correction", "Reference track", "Frequency response", "Tonal balance", "Equalization"], "common_mistakes": ["Matching a target curve so hard that the mix sounds unnatural or phasey.", "Treating one target curve as correct for every genre and every playback system.", "Confusing a monitor room-correction target with an EQ move on the mix itself."], "scenario_contexts": ["Matching a mix's tonal balance to a commercial reference in the same genre.", "Calibrating studio monitors to a house or Harman-style target curve.", "Keeping a series of album tracks tonally consistent against one target."]}, "cf164386-5f79-49f5-a002-ffd818364561": {"definition": "A technical acceptance test is a formal, specification-based check performed before a deliverable or installed system is accepted, verifying that measurable technical criteria (such as loudness, level, format, connectivity, or system performance) meet the agreed requirements. Passing it is the condition for sign-off and handover.", "plain_english": "This is a final check to prove the work meets the agreed rules before anyone accepts it. It is like a home inspection that must pass before you buy the house.", "purpose_function": "It protects both parties by confirming, with objective measurements, that a delivery or system does what the contract or spec requires before responsibility transfers.", "practical_application": "A post engineer runs a technical acceptance test to confirm a mix's loudness and true-peak meet the broadcaster's delivery spec, or an integrator verifies an installed system against ANSI/AVIXA performance criteria.", "category": "Delivery & QC", "related_terms": ["Quality control", "Delivery spec", "Loudness normalization", "Commissioning", "Technical checklist", "True peak"], "common_mistakes": ["Treating a subjective listen as an acceptance test instead of measuring against the written spec.", "Skipping the test and only discovering a failed deliverable after handover.", "Testing one parameter such as loudness while ignoring format or channel-map requirements."], "scenario_contexts": ["QC of a broadcast mix against EBU R128 or ATSC A/85 delivery specs.", "Commissioning and signing off a newly installed sound system.", "Verifying a mastered file set before uploading to a distributor."]}, "c58cd591-5f86-49ef-b3b1-dbb6a5c920ce": {"definition": "A technical checklist is a predetermined, itemized list of technical checks used to verify that required settings, conditions, or specifications are met at a defined stage of a workflow, such as before a session, show, or delivery. It standardizes verification so nothing critical is overlooked.", "plain_english": "A technical checklist is a written list of things to check off so you do not forget any step. It works like a pilot's pre-flight list that makes sure everything is ready before takeoff.", "purpose_function": "It reduces human error and keeps work consistent by turning expert knowledge into repeatable, verifiable steps.", "practical_application": "A live engineer works through a technical checklist during setup to confirm every input, monitor, and safety item before doors open.", "category": "Workflow", "related_terms": ["Technical acceptance test", "Soundcheck", "Line check", "Delivery spec", "Commissioning", "Quality control"], "common_mistakes": ["Copying a generic checklist without adapting it to the specific rig or delivery.", "Checking items off from memory instead of actually verifying each one.", "Never updating the checklist after a failure reveals a missing step."], "scenario_contexts": ["Pre-show line check of every input and monitor on a live console.", "Pre-delivery verification of file format, loudness, and metadata.", "Studio session setup confirming routing, clocking, and record paths."]}, "ee24ce79-9659-42bb-91dc-0de7ab8a8ade": {"definition": "Television translation refers to how well a mix holds up when played back over television systems, especially small built-in TV speakers and downmixed or loudness-normalized broadcast paths. A mix with good television translation keeps its balance, dialogue clarity, and impact on those systems, not only on studio monitors.", "plain_english": "Television translation is how good your mix still sounds through a TV's small speakers. A mix can sound great in the studio but lose its bass or clear voices on a cheap TV, and that is a translation problem.", "purpose_function": "Checking translation to television makes sure the audience actually hears the intended balance, since most viewers listen on modest built-in speakers.", "practical_application": "A broadcast mixer checks television translation by auditioning the mix on small speakers and in mono to confirm dialogue stays clear after the broadcast downmix.", "category": "Monitoring & Translation", "related_terms": ["Mix translation", "Downmix", "Mono compatibility", "Loudness normalization", "Reference monitor", "Dialogue intelligibility"], "common_mistakes": ["Mixing only on large full-range monitors and never checking small or mono playback.", "Overloading low end a TV speaker cannot reproduce, which masks the dialogue.", "Assuming a great studio mix will automatically translate to broadcast playback."], "scenario_contexts": ["Mixing a TV show and checking it on a small reference speaker.", "Confirming dialogue stays clear after a stereo-to-mono TV downmix.", "Balancing music and effects so they do not bury speech on built-in TV speakers."]}, "ceb61064-d1a9-47fd-a1e8-8563a0bd87ab": {"definition": "Television-score mixing is the practice of balancing and processing the musical score for a television program so it supports the picture and sits correctly with dialogue and sound effects within the show's overall mix and delivery specification. It emphasizes clarity, consistent levels across episodes, and translation to home playback.", "plain_english": "This is how you set the level of the music for a TV show. You balance it to fit under the voices and sound effects. The music should set the mood, but never cover up what people say.", "purpose_function": "It shapes the score to support the story and emotion while staying out of the way of dialogue, and to meet broadcast loudness and delivery rules.", "practical_application": "A music or re-recording mixer sets score levels and EQ so the music supports each scene yet never masks speech, then checks it against the broadcaster's loudness spec.", "category": "Broadcast/Post", "related_terms": ["Dialogue intelligibility", "Stems", "Loudness normalization", "Re-recording mix", "Television translation", "Balance"], "common_mistakes": ["Mixing the score too loud so it competes with the dialogue.", "Ignoring level consistency, so the music jumps between scenes or episodes.", "Judging the score in isolation instead of against dialogue and effects in the final mix."], "scenario_contexts": ["Balancing an episode's music under dialogue before delivery.", "Keeping score levels consistent across a whole season.", "Fitting a composer's cues into the final broadcast mix and its loudness spec."]}, "5c612bc4-36c1-47f7-b673-41f388e0a019": {"definition": "Tempo analysis is the process of determining the tempo (beats per minute) and beat positions of recorded audio, either manually or with a DAW's automatic detection, so the material can be aligned to a project's grid or a tempo map. It produces a tempo value or a series of tempo events that follow the performance.", "plain_english": "Tempo analysis is figuring out how fast a piece of music is in beats per minute. Software listens for the beats and works out the speed, like tapping your foot to find the pace.", "purpose_function": "It lets recorded audio line up with a DAW's bars-and-beats grid so edits, loops, quantizing, and added parts stay in time.", "practical_application": "An engineer runs tempo analysis on a live drum recording so the session's tempo map follows the band and new overdubs snap to the grid.", "category": "Tempo & Timing", "related_terms": ["Tempo map", "Tempo List", "Warping", "Quantization", "Beat detection", "Grid"], "common_mistakes": ["Trusting automatic detection blindly, which may lock onto half or double the real tempo.", "Running analysis on a rubato or drifting performance and expecting one fixed tempo.", "Confusing detecting the tempo with time-stretching the audio to a new tempo."], "scenario_contexts": ["Building a tempo map from a click-free live recording.", "Matching an imported loop to the project tempo.", "Preparing a song for editing so quantize and grid tools work correctly."]}, "6844d91c-7d7f-44e2-b047-6e3b8a87a52f": {"definition": "In Logic Pro, the Tempo List is a list editor that displays all the tempo events in a project in chronological order and lets you create, view, and edit them precisely by position and value. It gives numerical control over tempo changes that complements the graphical Tempo track.", "plain_english": "The Tempo List in Logic Pro is a table that shows every tempo change in a song and where each one happens. It lets you type exact speeds instead of dragging a line on a graph.", "purpose_function": "It gives precise, numeric editing of tempo changes, which is useful for scoring and complex tempo maps where exact values and positions matter.", "practical_application": "A composer opens the Tempo List to enter exact tempo changes at specific bars when syncing music to picture cues.", "category": "Tempo & Timing", "related_terms": ["Tempo track", "Tempo analysis", "Tempo map", "Event List", "Smart Tempo", "Marker"], "common_mistakes": ["Confusing the Tempo List with the graphical Tempo track; they edit the same events two ways.", "Entering tempo changes in the wrong tempo set so they do not take effect.", "Deleting a tempo event and unexpectedly shifting the timing of everything after it."], "scenario_contexts": ["Entering precise tempo changes to hit film or TV cues.", "Cleaning up messy tempo events after automatic tempo detection.", "Building a controlled ritardando or accelerando with exact values."]}, "f59ca61e-c6c6-43aa-9730-5f0ae5680641": {"definition": "The action of establishing a session's master tempo, in beats per minute, which governs the metronome click, the bars-and-beats grid, and any tempo-locked (tick-based) material in a DAW project.", "plain_english": "Tempo set means telling your music software how fast the song plays, in beats per minute. After that, the click and the grid lines all match that speed.", "purpose_function": "It fixes the timing reference for the whole session so the click, MIDI, loops, quantize grid, and edits all line up to one shared beat.", "practical_application": "Before recording to a click, an engineer sets the session tempo to match the song so overdubs, imported loops, and quantize snap to the right beats.", "category": "Tempo & Timing", "related_terms": ["Tempo track (Logic)", "Tick-based Track", "Click track", "Quantize", "Timing humanization"], "common_mistakes": ["Recording a whole take before setting the correct tempo, so the grid never lines up with the performance.", "Assuming one fixed tempo when the song actually speeds up or slows down, instead of building a tempo map.", "Confusing the displayed session tempo with the real tempo of imported audio, so loops fight the grid."], "scenario_contexts": ["Starting a new pop session by entering the target BPM before tracking.", "Matching session tempo to a rough demo so stems import in time.", "Setting tempo so a drummer can record to a steady click."]}, "73094ada-a96c-4bc8-8026-95247c477b07": {"definition": "In Apple Logic Pro, the Tempo track is a global track that stores and edits tempo events over time, letting a project hold a single fixed tempo or follow a curve of tempo changes.", "plain_english": "In Logic Pro, the Tempo track is a lane where you set how fast the song plays. You can keep one steady speed or make it speed up and slow down through the song.", "purpose_function": "It centralizes all tempo information so the whole project's grid, click, and tempo-locked regions follow one editable map instead of scattered settings.", "practical_application": "An editor opens the Tempo track to add a slow-down at the end of a song or to beat-map the click to a live, drifting performance.", "category": "Tempo & Timing", "related_terms": ["Tempo set", "Tick-based Track", "Click track", "Quantize", "Timing humanization"], "common_mistakes": ["Trying to change tempo on individual regions instead of the global Tempo track, causing conflicts.", "Forgetting a hidden tempo curve is active, then wondering why the grid drifts away from the beat.", "Deleting tempo events and losing the map that tick-based tracks rely on."], "scenario_contexts": ["Adding a gradual slow-down to the final bars of a ballad in Logic Pro.", "Beat-mapping a freely played piano take so the grid follows it.", "Programming tempo changes for a film or game cue."]}, "920d744f-541a-4a3a-9b31-5ff0da3c7a65": {"definition": "In Logic Pro's Flex Time, the Tempophone algorithm time-stretches audio using grain-based (granular) processing that emulates the Springer Tempophone, a historical tape machine with a rotating head drum; it holds pitch while changing timing but adds pronounced mechanical, grainy artifacts.", "plain_english": "Tempophone mode stretches audio into tiny grains, like chopping it into small pieces and spacing them out. It keeps the pitch but adds a rough, choppy, robot-like sound on purpose.", "purpose_function": "It recreates the artifact-rich character of the mechanical Tempophone/Springer time-stretcher, giving mixers a deliberately lo-fi, granular time-stretch as a creative effect rather than a transparent one.", "practical_application": "A technician selects the Tempophone algorithm on a Flex region, then adjusts the grain-size and crossfade parameters, when they want a gritty, granular stretch on vocals, pads, or sound design.", "category": "Time-Stretch Algorithm", "related_terms": ["Speed mode", "Flex Time", "Granular synthesis", "Time stretching", "Tempo set"], "common_mistakes": ["Expecting clean, transparent stretching; Tempophone is designed to add granular artifacts.", "Ignoring the grain-size and crossfade controls, which strongly shape the resulting sound.", "Choosing it for routine tempo matching instead of the Rhythmic, Monophonic, or Polyphonic modes."], "scenario_contexts": ["Designing a gritty, mechanical texture from a sustained vocal note.", "Stretching a pad far beyond its length for an ambient sound-design bed.", "Adding vintage granular character to a sample as a creative effect."]}, "8107e261-29a4-4846-a120-13ee23545e58": {"definition": "A supplementary arrangement element, such as a sustained pad, drone, rising noise sweep, or dissonant texture, layered beneath or between the main parts to build unease and anticipation across a section.", "plain_english": "A tension layer is an extra background sound added to make part of a song feel tense or on edge. It is like the low hum in a scary movie that warns something is coming.", "purpose_function": "It shapes the emotional arc of an arrangement, adding drama and pull toward a chorus, drop, or scene change without carrying the main melody.", "practical_application": "A producer runs a slowly rising noise sweep and a dissonant pad through the last bars before a chorus to raise the tension before the payoff.", "category": "Arrangement", "related_terms": ["Riser", "Pad", "Automation", "Arrangement", "Build-up"], "common_mistakes": ["Making the tension layer so loud it masks the lead parts instead of supporting them.", "Leaving a rising tension layer running past the payoff, so the release never lands.", "Confusing a background tension layer with the main melodic hook of the section."], "scenario_contexts": ["Adding a drone under a film scene to signal that danger is near.", "Building energy into an EDM drop with a noise sweep and dissonant pad.", "Filling a quiet pre-chorus with a subtle tense texture."]}, "5be87a82-5809-4bf7-9563-8c0277439ba6": {"definition": "The final, approved multichannel mixdown of a film's soundtrack formatted for cinema exhibition (for example 5.1 or 7.1 surround), created from the re-recording mix stems and used as the master from which release prints and digital cinema audio derive.", "plain_english": "The theatrical printmaster is the finished movie soundtrack, made to play in cinemas. It is the final surround mix. That mix is copied onto the cinema release.", "purpose_function": "It is the master deliverable that carries the fully mixed, level-calibrated cinema soundtrack, so every theater plays the film at the intended balance and loudness.", "practical_application": "After the re-recording mix is signed off, the team creates the theatrical printmaster in the cinema surround format and checks it at reference level before delivery.", "category": "Post-Production", "related_terms": ["Stems", "Re-recording mix", "Dialog stem", "5.1 surround", "Reference level"], "common_mistakes": ["Mixing or checking the printmaster at the wrong monitoring reference level, so it plays too loud or too quiet in cinemas.", "Delivering a near-field or home version in place of the true theatrical printmaster.", "Failing to keep the matching stems alongside the printmaster for later re-versioning."], "scenario_contexts": ["Creating the final 5.1 cinema master after the last dub is approved.", "Delivering the printmaster audio for a Digital Cinema Package.", "Checking the printmaster on a calibrated dub stage at reference level."]}, "13dc5329-b5d4-41c0-8923-0382df82f73d": {"definition": "A track whose timing is measured in musical ticks (subdivisions of beats) rather than absolute clock time, so its material repositions to stay locked to the bars-and-beats grid when the session tempo changes.", "plain_english": "A tick-based track counts time in beats, not in seconds. So when you change the song's speed, its notes move to stay on the beat.", "purpose_function": "It keeps MIDI and rhythmic parts aligned to the musical grid, so tempo edits automatically move events instead of leaving them stranded at fixed clock times.", "practical_application": "An engineer sets MIDI and virtual-instrument tracks to tick-based so they follow tempo changes, while leaving recorded dialog or vocals on sample-based tracks.", "category": "Tempo & Timing", "related_terms": ["Sample-based track", "Tempo track (Logic)", "Tempo set", "Quantize", "Timeline Selection"], "common_mistakes": ["Leaving recorded audio on a tick-based track, so a tempo change shifts and stretches it unexpectedly.", "Assuming every track follows tempo, when audio tracks often default to sample-based.", "Mixing tick- and sample-based tracks without noticing why some parts move and others do not on a tempo edit."], "scenario_contexts": ["Keeping a programmed drum part on the grid after slowing the session tempo.", "Setting virtual instruments to tick-based in Pro Tools before drawing a tempo map.", "Locking loop regions to beats so they follow tempo changes."]}, "692c502e-063e-4e1e-844b-d889631e569b": {"definition": "In Pro Tools, the position in the Timebase rulers from which transport playback and recording begin, shown by the insertion marker; with 'Insertion Follows Playback' enabled it relocates to wherever playback stops.", "plain_english": "The Timeline Insertion Point is the spot on the timeline where playback will start. It is like putting your finger on a page to mark where to begin reading.", "purpose_function": "It tells the DAW where transport playback and new recordings start, kept separate from the material you have selected to edit.", "practical_application": "A technician clicks in the timeline ruler to set the insertion point, then presses play to audition from exactly that spot.", "category": "DAW Workflow", "related_terms": ["Timeline Selection", "Edit Selection", "Playhead", "Transport", "Tick-based Track"], "common_mistakes": ["Confusing the Timeline Insertion Point with the Edit selection, so playback starts somewhere unexpected.", "Leaving 'Insertion Follows Playback' on and losing the original start point after stopping.", "Setting the insertion point in the wrong timebase ruler."], "scenario_contexts": ["Clicking in the ruler to start playback from the chorus.", "Setting a record start point before a punch-in.", "Auditioning an edit from one fixed position."]}, "48dc2b0a-2a73-43b7-8c08-535b2c90c655": {"definition": "In Pro Tools, the range marked in the Timebase rulers that sets the transport's play and record range and loop boundaries, distinct from the Edit selection; the two can be linked or unlinked.", "plain_english": "The Timeline Selection is the stretch of time you highlight on the ruler to set where playback or recording will run or loop. It marks a start and an end on the timeline.", "purpose_function": "It defines the play/record range and loop boundaries, letting you control what plays back independently of what you have selected to edit.", "practical_application": "An engineer drags a Timeline Selection over a verse to loop it during playback while editing a different clip.", "category": "DAW Workflow", "related_terms": ["Timeline Insertion Point", "Edit Selection", "Loop playback", "Transport", "Pre-roll"], "common_mistakes": ["Unlinking the Timeline and Edit selections without realizing it, so the play range no longer matches the edit range.", "Setting a Timeline Selection in the wrong ruler timebase.", "Expecting edits to apply to the Timeline Selection when they actually apply to the Edit selection."], "scenario_contexts": ["Looping a chorus for playback by setting a timeline range.", "Defining a record range for a punch-in.", "Setting pre- and post-roll around a selected section."]}, "d5ce56a8-c16b-42c8-a963-865fbf34fdeb": {"definition": "The deliberate introduction of small, often randomized deviations to the start times of quantized or programmed notes, so a rigidly gridded performance sounds more natural and human-played.", "plain_english": "Timing humanization adds tiny, slightly random shifts to notes that sit perfectly on the beat. This makes a computer part sound more like a real person playing.", "purpose_function": "It counteracts the mechanical stiffness of hard quantization, restoring the small timing variations that make rhythmic parts feel alive and groove.", "practical_application": "After quantizing a MIDI drum pattern, a producer applies a small humanize amount to nudge hits slightly off the exact grid so they feel less robotic.", "category": "Tempo & Timing", "related_terms": ["Quantize", "Groove template", "Swing", "MIDI velocity", "Tempo set"], "common_mistakes": ["Applying too much humanization, so timing drifts and the part sounds sloppy rather than natural.", "Humanizing before quantizing, which compounds errors instead of loosening a tight grid.", "Using random timing on parts that need to stay tight, like a machine-tight electronic kick."], "scenario_contexts": ["Loosening a stiff, hard-quantized hi-hat pattern.", "Making a programmed string section feel like an ensemble.", "Adding subtle timing spread to layered percussion."]}, "9b6c8fff-3701-4159-8c68-7112bc8f34e0": {"definition": "A timing shift is the deliberate movement of a recorded element earlier or later in time relative to the project grid or to other tracks, applied during editing to correct or adjust its rhythmic placement.", "plain_english": "A timing shift means nudging a recorded sound a little earlier or later so it sits better with the beat. It is like sliding a sticker left or right until it lands in the right spot.", "purpose_function": "It lets an engineer tighten loose performances or intentionally push or pull parts so elements lock together rhythmically or feel more relaxed.", "practical_application": "An editor nudges a snare hit a few milliseconds forward to sit tighter with the kick, or slides a doubled guitar back so it aligns with the main take.", "category": "Editing", "related_terms": ["Quantization", "Nudge", "Groove", "Phase alignment", "Comping"], "common_mistakes": ["Shifting a track without watching its transients, so the move lands on the wrong beat.", "Moving only one mic of a multi-mic source, causing phase problems with the other mics.", "Over-tightening every element to the grid until the performance loses its natural feel."], "scenario_contexts": ["Aligning a late bass note to the kick drum in a pop mix.", "Pushing a rhythm guitar slightly behind the beat for a laid-back feel.", "Correcting a drummer's rushed fill during editing."]}, "c23611c4-e376-48a8-aca9-734beeb352b7": {"definition": "A tom sample is a recorded, individual tom-tom drum hit stored as an audio file for use in drum programming, layering, or drum replacement.", "plain_english": "A tom sample is a recording of one hit on a tom drum, saved so you can play it back later. It is like a photo of a single drum hit that you can drop into your song when you need it.", "purpose_function": "It gives producers a clean, ready-made tom sound to program beats or to reinforce or replace weak recorded toms.", "practical_application": "An engineer triggers a tom sample under a dull recorded tom to add attack and body, or programs toms from samples when no live kit was recorded.", "category": "Sampling", "related_terms": ["Drum replacement", "Sample library", "Trigger", "Layering", "Velocity"], "common_mistakes": ["Using a tom sample at one fixed velocity, making programmed fills sound robotic.", "Forgetting to check tuning, so the sample clashes with the rest of the kit.", "Leaving the sample out of phase when layering it under the original tom track."], "scenario_contexts": ["Reinforcing weak recorded toms in a rock mix.", "Programming a tom fill in a hip-hop beat from a sample library.", "Replacing bleed-heavy tom mics with clean samples."]}, "37c7272a-da1b-4ab9-a51e-3284ccee4044": {"definition": "Tonal consistency is the degree to which the timbre and frequency balance of a sound source, or of a whole mix, stays uniform across a performance, song, or album.", "plain_english": "Tonal consistency means a sound keeps the same color and balance from start to finish. It is like making sure every photo in an album has the same lighting so they look like they belong together.", "purpose_function": "It keeps a mix or record feeling coherent so listeners are not distracted by a voice or instrument that suddenly changes character.", "practical_application": "A mixer uses matched EQ and compression across sections, or careful editing between takes, so a lead vocal keeps the same tone from verse to chorus.", "category": "Mixing", "related_terms": ["Tonal balance", "Equalization", "Reference track", "Gain staging", "Automation"], "common_mistakes": ["Editing between takes with very different tone, so the vocal jumps in character.", "Judging consistency at different playback levels, which hides real tonal shifts.", "Fixing tone on one section only and forgetting to match the rest of the song."], "scenario_contexts": ["Matching vocal tone across verses comped from several takes.", "Keeping guitar tone even across an album's songs.", "Ensuring a podcast host sounds the same across episodes."]}, "e15c6b58-201a-4331-98ee-dd20a6ef9a65": {"definition": "A track alternative is one of several independent content versions stored on a single track that share the same channel strip and plug-ins, letting a user switch between different arrangements or takes without duplicating the track.", "plain_english": "A track alternative is a saved second version of what a track plays, using the same volume and effects. It is like keeping two drafts of a page so you can flip between them and pick the best one.", "purpose_function": "It lets engineers try out different ideas, keep earlier stages, and compare edits on one track while leaving the mixer setup unchanged.", "practical_application": "A producer keeps one alternative with a busy guitar part and another with a simpler part, switching between them to decide which fits the mix.", "category": "Editing", "related_terms": ["Comping", "Playlist", "Take", "Track Archive", "Track Commit"], "common_mistakes": ["Assuming each alternative has its own effects, when they actually share one channel strip.", "Losing track of which alternative is active because only the active one is shown.", "Confusing track alternatives with fully duplicated tracks."], "scenario_contexts": ["Auditioning two different vocal comps on one track.", "Archiving an early arrangement before trying a new idea.", "Comparing a simple and a busy bass part in the same session."]}, "b3a194e9-d744-4d41-b2da-4e7811f1ee18": {"definition": "A track archive is an exported file containing selected tracks along with their events and settings, saved so those tracks can be imported into another project. In Cubase and Nuendo it is an XML-based export used to transfer or back up tracks between sessions.", "plain_english": "A track archive is a saved file that holds chosen tracks and their parts so you can drop them into another project later. It is like copying a few pages out of one document to paste into a different one.", "purpose_function": "It lets engineers move or reuse specific tracks between projects and back up work without saving the whole session.", "practical_application": "An engineer exports the drum tracks as a track archive and imports them into a new song to reuse the same performance.", "category": "File Management", "related_terms": ["Track Commit", "Track alternative", "Stem export", "Session backup", "Track Color"], "common_mistakes": ["Expecting a track archive to store the actual audio files when it may only reference them.", "Assuming archives transfer perfectly between different DAW brands.", "Forgetting to include all needed media, so imported tracks are missing audio."], "scenario_contexts": ["Reusing a recorded string section in another song.", "Handing selected tracks to another engineer's session.", "Backing up key tracks before a major edit."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"93fc73c5-ad97-4805-b9b1-10ef8e841883": {"definition": "Track Assistant is a feature in iZotope Neutron that analyzes a few seconds of a track's audio, identifies the source type, and generates a custom starting preset of EQ, compression, and other processing tuned to that material.", "plain_english": "Track Assistant is a tool that listens to a track for a few seconds and then sets up a first-try mix for it on its own. It is like a helper that hands you a rough draft you can then clean up yourself.", "purpose_function": "It gives engineers a fast, tailored starting point for processing a track, which they can keep tweaking or discard.", "practical_application": "A user plays a vocal through Neutron, runs Track Assistant, and starts from the EQ and compression settings it suggests instead of from scratch.", "category": "Mixing Tools", "related_terms": ["Equalization", "Compression", "Mixing", "Preset", "Spectral analysis"], "common_mistakes": ["Treating the suggested settings as final instead of a starting point.", "Not playing a clear 4-10 seconds, so the analysis misjudges the source.", "Assuming it replaces knowing how EQ and compression actually work."], "scenario_contexts": ["Getting a quick EQ starting point on a lead vocal.", "Learning how a plugin might treat a bass track.", "Speeding up rough mixes on a large session."]}, "dbf27cfc-c372-446e-b88d-5feb207ef927": {"definition": "Track color is a user-assigned color applied to a track, and often to its regions and channel strip, in a DAW to visually distinguish and group tracks.", "plain_english": "Track color is a color you give a track so it is easy to spot on screen. It is like using colored folders so you can find your papers at a glance.", "purpose_function": "It speeds up navigation and organization in large sessions by letting an engineer identify related tracks by color at a glance.", "practical_application": "An engineer colors all drum tracks red and all vocals blue so they can find and select groups quickly while mixing.", "category": "Organization", "related_terms": ["Track control panel", "Track naming", "Folder track", "Grouping", "Session template"], "common_mistakes": ["Using too many similar colors, so groups are hard to tell apart.", "Relying on color alone instead of also naming tracks clearly.", "Forgetting to save a color scheme into a template for reuse."], "scenario_contexts": ["Color-coding a large orchestral session by section.", "Marking finished tracks a different color while mixing.", "Setting up a template with a consistent color scheme."]}, "02b7c6dc-cc6e-4cd2-90ba-d54b8b694633": {"definition": "Track commit is the process of rendering a track's real-time processing, such as virtual instruments and plug-ins, to a new audio track, freeing CPU resources and locking in the sound while typically keeping the original track available.", "plain_english": "Track commit turns a track that uses live effects or instruments into a plain audio file. The file just plays back the sound. It is like baking a cake so you no longer need the recipe steps running.", "purpose_function": "It cuts the computer's processing load and locks a sound in place, which makes big sessions run smoothly and keeps mixes easy to move.", "practical_application": "An engineer commits a CPU-heavy software synth to audio so the session plays back without glitches, keeping the original for later edits.", "category": "Rendering", "related_terms": ["Freeze", "Bounce", "Track Archive", "Consolidation", "Latency"], "common_mistakes": ["Committing a track without keeping the original, losing the ability to edit it later.", "Forgetting that committed audio no longer follows tempo or MIDI changes.", "Committing before finishing effects that still need adjusting."], "scenario_contexts": ["Reducing CPU load from many virtual instruments in a large session.", "Locking a synth sound before sharing a session with another studio.", "Printing effects so a mix opens on a less powerful computer."]}, "a5e26d63-735b-4c5c-b316-1abccf2a2f99": {"definition": "The track control panel is the area of a DAW track, usually in the track list or inspector, that holds its controls and status indicators such as name, mute, solo, record-enable, monitor, and volume.", "plain_english": "The track control panel is the strip of buttons and readouts for one track, like its name, mute, and solo. It is like the dashboard for that track, where you reach its main controls.", "purpose_function": "It gives quick access to a track's key controls and status so an engineer can manage playback, recording, and monitoring without leaving the arrange view.", "practical_application": "An engineer clicks mute and solo in the track control panel to isolate a part, or arms record-enable there before a take.", "category": "Interface", "related_terms": ["Track Color", "Mute", "Solo", "Record enable", "Inspector"], "common_mistakes": ["Confusing the record-enable button with the input-monitor button.", "Leaving a track soloed and forgetting the control is engaged.", "Overlooking that the visible controls can be customized, so a needed button seems missing."], "scenario_contexts": ["Arming a track for recording before a take.", "Muting and soloing tracks to check a part.", "Renaming and coloring tracks while organizing a session."]}, "ac04b9f1-0a10-46f1-9d8b-690c53f2ebfc": {"definition": "A DAW function that renders a track together with its active plug-ins to a temporary audio file and plays back that file instead of processing the effects in real time. The original track, its plug-ins, and settings are preserved and can be unfrozen to resume editing.", "plain_english": "Track freeze records a track and its effects into a plain audio file. The computer then plays that file instead of running the effects live. This saves computer power. You can unfreeze the track later to make changes.", "purpose_function": "It reduces CPU and RAM load from plug-in and virtual-instrument processing so a large project can play back without dropouts, while keeping the ability to revert to full editing later.", "practical_application": "When a session with many virtual instruments and effects starts glitching or overloading the CPU, an engineer freezes finished tracks to recover processing headroom, then unfreezes any track that needs further tweaks.", "category": "Workflow", "related_terms": ["Bounce", "Commit", "CPU load", "Virtual instrument", "Insert effect", "Latency"], "common_mistakes": ["Thinking a frozen track is permanently rendered, when it can be unfrozen to restore full editing", "Forgetting to unfreeze before changing plug-in settings, then wondering why edits have no effect", "Freezing tracks to save CPU but leaving so many unfrozen that the project still overloads"], "scenario_contexts": ["Freezing software-instrument tracks to recover CPU in a large session", "Freezing effect-heavy tracks so playback stops glitching", "Unfreezing a track to adjust its plug-ins before mixdown"]}, "3bbf3efd-c24d-4061-9c03-d1d8782383ec": {"definition": "The ordered set of insert effects and processors loaded on a single track, through which the track's signal passes in series from top to bottom. In REAPER this collection is managed in the track's FX window and can be saved and recalled as an FX chain file.", "plain_english": "A track FX chain is the line-up of effects on one track. The sound flows through them one after another, from top to bottom. The order changes how the final sound turns out. You can save the whole chain and reuse it later.", "purpose_function": "It shapes a track's tone and dynamics by cascading processors in a defined order, and lets that processing be stored and reused across tracks or projects.", "practical_application": "An engineer stacks an EQ, compressor, and reverb on a vocal track, reorders them to taste, then saves the FX chain to drop the same treatment onto other vocals.", "category": "Signal Processing", "related_terms": ["Insert effect", "Signal chain", "Plug-in", "Send", "EQ", "Compressor"], "common_mistakes": ["Assuming processor order does not matter, when EQ-before-compression versus compression-before-EQ gives different results", "Confusing insert FX in the chain with send/aux effects", "Leaving CPU-heavy plug-ins active on many chains instead of freezing or bypassing them"], "scenario_contexts": ["Building a vocal chain of EQ, de-esser, and compressor", "Saving a mastering FX chain to reuse on other songs", "Troubleshooting tone or phase problems caused by effect order"]}, "d2ed20d5-bed5-4bfd-bc59-6ec95d5e3ac7": {"definition": "The adjustable vertical size of a track lane in a DAW's arrange or edit window, controlling how tall the track and its waveform or MIDI display appear. It affects visibility and editing precision but not the audio itself.", "plain_english": "Track height is how tall a track looks in the edit window. Making a track taller shows the waveform in more detail. Making it shorter lets you fit more tracks on screen. It only changes the view, not the sound.", "purpose_function": "It lets an editor trade screen space for detail, enlarging a track for precise waveform or automation editing and shrinking others to see the whole session.", "practical_application": "When drawing detailed volume automation or editing a drum waveform, a technician increases that track's height for accuracy, then collapses it to scan the full arrangement.", "category": "Editing Interface", "related_terms": ["Zoom", "Arrange window", "Waveform", "Automation lane", "Track manager"], "common_mistakes": ["Thinking track height changes level or the recorded audio, when it only changes the display", "Not knowing per-track versus global height shortcuts, so all tracks resize at once", "Working at tiny track heights and making imprecise edits"], "scenario_contexts": ["Enlarging a track to draw fine automation", "Collapsing tracks to view a large session at a glance", "Zooming into a waveform for a precise crossfade"]}, "84d37bb8-dc40-43d0-af2b-e34c4e7febd5": {"definition": "A DAW window or panel that lists all tracks in a project and lets the user show, hide, filter, and organize them without deleting anything. In REAPER it is the Track Manager; Cubase's Track Visibility offers comparable control.", "plain_english": "A track manager is a list of every track in your song. From it you can hide or show tracks to cut clutter. Hidden tracks still play and are not deleted. It helps you find your way around a big project.", "purpose_function": "It manages visual complexity in large sessions by controlling track visibility and organization, so an engineer can focus on relevant tracks while keeping all of them active.", "practical_application": "In a session with dozens of tracks, an engineer opens the track manager to hide finished or unused tracks, then reveals a group when it is time to mix it.", "category": "Session Management", "related_terms": ["Track visibility", "Folder track", "Track Stack", "Arrange window", "Mixer"], "common_mistakes": ["Believing hiding a track in the manager mutes or removes it, when it only affects visibility", "Losing track of hidden tracks that are still playing in the mix", "Confusing show/hide state with mute/solo state"], "scenario_contexts": ["Hiding finished tracks to declutter a large session", "Showing only drum tracks while editing the kit", "Managing visibility of many tracks during a mix"]}, "05a7815b-9990-41e9-902c-f75b2157ac7b": {"definition": "A saved file capturing a track's configuration, such as its channel settings, insert effects, EQ, and routing, that can be recalled to create or configure a track instantly. In Cubase these are Track Presets storing inserts, EQ, and channel-strip settings.", "plain_english": "A track preset is a saved setup for a track. It can hold the effects, EQ, and settings you like. Loading it sets up a new track the same way in seconds. It saves you from building the same thing again.", "purpose_function": "It speeds up setup and enforces consistency by storing a track's processing and settings for reuse across projects.", "practical_application": "An engineer who always processes a snare a certain way saves it as a track preset, then recalls it on new sessions instead of rebuilding the chain each time.", "category": "Session Management", "related_terms": ["Track template", "Track Preset Recall", "Channel strip", "Track FX chain", "Preset"], "common_mistakes": ["Confusing a track preset with a single plug-in preset, which stores only one effect's settings", "Expecting a preset to carry recorded audio, when it stores settings only", "Overwriting a saved preset by not using Save As"], "scenario_contexts": ["Saving a favorite vocal channel strip for reuse", "Recalling a drum bus setup on a new project", "Standardizing settings across an engineer's sessions"]}, "e7fd5992-b205-4584-a3ea-4845a0fe3e26": {"definition": "The act of loading a previously saved track preset onto a track, applying its stored settings, effects, and routing. It restores a known configuration without rebuilding it manually.", "plain_english": "Track preset recall means loading a saved track setup. It brings back the effects and settings you stored before. The track is ready in one step. It is like opening a saved template instead of starting over.", "purpose_function": "It restores consistent, known-good track configurations quickly, supporting fast setup and repeatable results across sessions.", "practical_application": "At the start of a new session, an engineer recalls a saved vocal track preset so the channel strip and effects load exactly as on previous mixes.", "category": "Session Management", "related_terms": ["Track preset", "Track template", "Recall", "Channel strip", "Track FX chain"], "common_mistakes": ["Assuming recall imports audio as well as settings", "Recalling a preset that relies on plug-ins missing from the current system", "Overwriting current track settings by recalling without checking"], "scenario_contexts": ["Loading a saved vocal chain at session start", "Restoring a standard drum bus configuration", "Recalling a mastering chain preset for a new song"]}, "67491d63-f991-407d-992f-ef55a112609e": {"definition": "In REAPER, a send routes a copy or portion of a track's signal to another track, folder, or hardware output, with its own volume, pan, and pre- or post-fader tap point. Sends feed aux/effect tracks, submixes, and separate monitor mixes.", "plain_english": "A send in REAPER copies a track's sound to another track or output. It has its own volume and pan. Engineers use sends to feed effects like reverb, or to build a submix. The original track keeps playing as normal.", "purpose_function": "It enables flexible routing so one source can feed shared effects, submixes, or separate monitor mixes without duplicating the track.", "practical_application": "An engineer creates a reverb track and sends several vocals to it, adjusting each send level to control how wet each vocal sounds while sharing one reverb.", "category": "Signal Routing", "related_terms": ["Aux send", "Receive", "Bus", "Return track", "Pre-fader", "Post-fader"], "common_mistakes": ["Confusing pre-fader and post-fader sends, which changes whether the channel fader affects the send level", "Creating a feedback loop by sending a track back into its own signal path", "Adding a send but leaving its level down, so no signal reaches the destination"], "scenario_contexts": ["Sending multiple vocals to a shared reverb track", "Building a pre-fader monitor mix for a performer", "Routing drums to a parallel compression bus"]}, "d49eec68-d1e6-4c87-9f84-0fe9e09041fb": {"definition": "In Logic Pro, a Track Stack groups multiple tracks under a single main track for organization and control; a Folder Stack organizes them visually, while a Summing Stack also routes their outputs to a shared bus for combined processing. It collapses a group into one track header.", "plain_english": "A track stack in Logic bundles several tracks under one main track. It tidies the screen by hiding the group until you need it. A summing stack also sends the whole group through one bus. That lets you control and process them together.", "purpose_function": "It organizes related tracks and, in summing form, creates a submix so a group can be leveled and processed with shared effects from one place.", "practical_application": "An engineer puts all drum tracks into a summing stack, then uses the main track's fader and compressor to control and glue the whole kit at once.", "category": "Track Organization", "related_terms": ["Folder track", "Summing Stack", "Bus", "Submix", "VCA", "Track manager"], "common_mistakes": ["Confusing a Folder Stack, which only organizes, with a Summing Stack, which also routes to a bus", "Expecting shared bus processing from a Folder Stack that does not sum outputs", "Losing track of individual routing after collapsing a stack"], "scenario_contexts": ["Grouping drum tracks into a summing stack for bus processing", "Organizing backing vocals under one folder stack", "Building a submix bus with combined compression"]}, "f0f70cfc-c94c-4556-9518-028e5476772b": {"definition": "A saved file containing one or more preconfigured tracks, including routing, effects, instruments, and settings, that can be inserted into a project to reproduce a setup instantly. In REAPER these are Track Templates; Cubase offers comparable Track Archives and presets.", "plain_english": "A track template is a ready-made track or group of tracks you save. It keeps the routing, effects, and settings in place. Loading it drops the whole setup into a new project. It saves you from building the same tracks over and over.", "purpose_function": "It standardizes and speeds up session setup by storing complete track configurations for reuse across projects.", "practical_application": "A live-recording engineer saves a full drum-mic track template with inputs, routing, and gates, then inserts it whenever tracking a new band to skip the setup.", "category": "Session Management", "related_terms": ["Track preset", "Project template", "Track Stack", "Routing", "Track FX chain"], "common_mistakes": ["Confusing a track template with a full project template, which loads an entire session", "Expecting a template to include recorded audio rather than just track setup", "Loading a template whose plug-ins are not installed on the current system"], "scenario_contexts": ["Inserting a saved drum-mic setup when tracking a band", "Reusing a standard vocal track across projects", "Sharing a configured track setup with a collaborator"]}, "5c4634a9-96fc-4a6c-9ddf-b35c41cc8b44": {"definition": "A stored alternative of a single track's content (its regions, events, or parts) that shares the track's channel strip, routing, and settings; you can create several and make any one active for playback while the others stay hidden. In Cubase this feature is called Track Versions, and in Logic Pro the equivalent is Track Alternatives.", "plain_english": "A track version is a saved copy of what is on one track. You can keep a few versions and flip between them. It works like saving different drafts of an essay in one file, so you can pick the best one later.", "purpose_function": "It lets an engineer keep several takes or arrangement ideas for one part inside a single track, instead of cluttering the project with duplicate tracks, so alternatives can be compared and recalled without losing work.", "practical_application": "A technician records a second vocal take onto a new track version, then A/B switches between versions during the mix to choose the best performance while keeping the same plug-ins and fader settings.", "category": "Track Management", "related_terms": ["Take folder", "Track Alternatives", "Comping", "Channel strip", "Playlist"], "common_mistakes": ["Confusing a track version with a separate track; versions share one channel strip and only one plays at a time.", "Assuming plug-in and channel-strip settings are stored per version, when track-level settings are shared across all versions.", "Losing track of which version is active and mixing the wrong take."], "scenario_contexts": ["Keeping several vocal takes on one track and switching to compare them.", "Trying two different arrangement ideas for a chorus without duplicating the track.", "Recalling an earlier edit after a client asks to hear the original."]}, "837b7a59-720e-4df0-8a88-a2d8fd34790c": {"definition": "In REAPER, a graphical view within the routing window that draws each track as a block and shows the signal connections between them, hardware inputs, track-to-track sends and receives, and hardware outputs, as a visual patch or flow diagram that can be edited directly.", "plain_english": "This is a picture that shows how your tracks are wired together. It draws the path the sound takes from the inputs, through the tracks, to the outputs. Think of it like a subway map for your audio signal.", "purpose_function": "It exists to make complex routing easy to see and change at a glance, turning an abstract grid of sends and receives into a visual signal-flow diagram.", "practical_application": "An engineer opens the track wiring view to trace why a reverb bus is receiving the wrong signal, then drags a connection in the diagram to reroute the send.", "category": "Routing", "related_terms": ["Routing matrix", "Send", "Bus", "Signal flow", "Aux return"], "common_mistakes": ["Mistaking the wiring view for the mixer; it shows routing, not levels.", "Overlooking that a hidden send shown in the diagram is still passing signal.", "Creating a feedback loop by wiring a track's output back into its own input path."], "scenario_contexts": ["Troubleshooting a routing error in a large session.", "Setting up parallel compression by drawing a new send.", "Teaching signal flow by showing the visual diagram."]}, "a4e3cf94-be17-4bd4-b1e0-1a38ccd91cc0": {"definition": "In Logic Pro, the main working area of the arrange window where audio and MIDI regions are recorded, displayed, and arranged along a timeline; each track appears as a horizontal lane with a track header on the left and its regions laid out left to right in time.", "plain_english": "The Tracks area is the main part of the screen where you build a song. Each track is a row that holds your recorded clips. You stack and line up these rows to arrange the whole piece.", "purpose_function": "It is the central workspace for building an arrangement, letting the engineer organize, edit, and time-align all the parts of a project in one timeline view.", "practical_application": "A technician drags recorded regions along the Tracks area to line up a chorus, mutes lanes to audition parts, and uses the track headers to solo and set levels.", "category": "DAW Interface", "related_terms": ["Region", "Track header", "Arrange window", "Playhead", "Track stack"], "common_mistakes": ["Confusing the Tracks area with the Mixer; the Tracks area arranges regions in time, while the Mixer sets levels and routing.", "Editing in the wrong lane because the selected track header was not checked.", "Dragging regions off-screen past the visible timeline and losing sight of them."], "scenario_contexts": ["Arranging a song's sections along the timeline.", "Comping takes by editing regions in a lane.", "Importing audio files and placing them on tracks."]}, "5aaac3db-9fa9-418f-8ffe-fc39068a2e56": {"definition": "An introductory overview of tracks in a DAW: the horizontal lanes that hold and organize the audio and MIDI material of a project, where each track carries one source or part and is typically assigned to its own mixer channel strip for processing.", "plain_english": "Tracks are the rows that hold your recordings in a project. Each row keeps one part, like drums or vocals, separate from the others. This makes it easy to see and control every sound on its own.", "purpose_function": "The concept exists to explain how a DAW keeps each part separate and controllable, which is the foundation of arranging and mixing.", "practical_application": "A beginner learns from a tracks overview that each instrument goes on its own track, so drums, bass, and vocals can be edited and balanced independently.", "category": "Track Basics", "related_terms": ["Track", "Tracks area", "Audio track", "Software instrument track", "Channel strip"], "common_mistakes": ["Thinking a track and its channel strip are the same thing; a track holds material in time, while the channel strip processes the sound.", "Recording several instruments onto one track and losing separate control of them.", "Believing global tracks such as tempo and key are the same as audio or instrument tracks."], "scenario_contexts": ["Learning the layout of a DAW project for the first time.", "Deciding how many tracks a session needs before recording a band.", "Explaining to a client why each mic gets its own track."]}, "68473dc0-cb44-4221-8a27-2489a108a7a8": {"definition": "A mix prepared specifically for a film, game, or TV trailer, engineered for maximum short-form impact: high perceived loudness, strong low-end and sub impacts (braams, hits, risers), a wide stereo image, and tightly controlled dynamics so the material cuts through on any playback system in a brief, attention-grabbing form.", "plain_english": "A trailer mix is a mix made for a movie or game trailer. It is very loud and punchy, with big hits and deep bass. The goal is to grab your attention fast in a short clip.", "purpose_function": "It exists to make a short promotional piece hit hard and stay loud and clear, because a trailer must grab a distracted audience quickly and translate well on cinema, TV, and phone speakers alike.", "practical_application": "An engineer mixing to trailer spec pushes impacts and sub hits, rides risers into big downbeats, and uses firm bus limiting to keep the whole piece loud and punchy while meeting the delivery loudness target.", "category": "Mix Types", "related_terms": ["Stem", "Loudness", "Limiting", "Sub-bass", "Mastering"], "common_mistakes": ["Over-limiting until the impacts lose their punch instead of gaining it.", "Ignoring mono and small-speaker translation for phone playback.", "Letting sub-bass hits swamp the mix and mask the dialogue or melody."], "scenario_contexts": ["Mixing a cinematic trailer cue for a game reveal.", "Delivering loud, punchy stems for a movie teaser.", "Balancing braams and risers under a voiceover."]}, "5ad4f000-dee8-4688-af28-0c7d734e87d8": {"definition": "In PreSonus Studio One, a command that renders a track through its insert effects (and, for an instrument track, through its virtual instrument) to a new static audio file that replaces the original in the signal path, freeing CPU; it is reversible with Transform to Real-Time Audio, which restores the original track, instrument, and effects.", "plain_english": "This turns a track and its effects into a plain audio file. The computer plays the effects once and records the result. That frees up your computer, and you can switch it back to editable form later if you need to.", "purpose_function": "It exists to lighten the computer's processing load and lock in a sound by baking effects or an instrument into plain audio, while keeping the option to return to the fully editable state later.", "practical_application": "When a CPU-heavy synth patch strains the system, an engineer transforms the instrument track to rendered audio to free resources, then transforms it back to real-time audio when a sound change is needed.", "category": "Rendering", "related_terms": ["Freeze", "Bounce", "Render in place", "Insert effect", "Virtual instrument"], "common_mistakes": ["Assuming the change is permanent, when Transform to Real-Time Audio reverses it.", "Rendering with the wrong effects in the chain and having to redo the transform.", "Forgetting that reverb or delay tails need extra time, so the rendered file gets cut off."], "scenario_contexts": ["Freeing CPU from a demanding virtual instrument.", "Committing a processed sound before sharing a session.", "Locking in an effect chain to mix on a slower computer."]}, "d365c12e-0319-45e4-8988-db3d6528a715": {"definition": "In layered sound design, a supplementary sound layer chosen to supply the initial transient, the short high-energy attack, of a composite sound; it is blended beneath the main body or sustain layer to add punch, click, or definition, most commonly when building drum and percussion sounds.", "plain_english": "A transient is the short, sharp start of a sound, like the click of a drum hit. A transient layer is an extra sound added just for that punchy start. You blend it under the main sound to make hits snappier.", "purpose_function": "It exists to give a layered sound a sharper, more defined attack than the main sample provides, improving cut-through and perceived punch in a dense mix.", "practical_application": "To make a soft kick hit harder, an engineer layers a short click sample as the transient layer, filters or gates it to isolate the attack, and blends it under the kick's body.", "category": "Layering", "related_terms": ["Layering", "Transient", "Transient designer", "Attack", "Parallel processing"], "common_mistakes": ["Letting the transient layer's tail overlap the body layer and cause phase or timing smear.", "Failing to time-align the layers, which weakens the combined attack.", "Adding so much transient layer that the sound becomes clicky and harsh."], "scenario_contexts": ["Building a punchy kick from two samples.", "Adding snap to a dull snare.", "Reinforcing the attack of a sampled instrument."]}, "dd41f971-54ac-4e31-bcf0-c946c190c55a": {"definition": "In Logic Pro, a marker that identifies a transient, a point of sharp energy increase such as a drum attack, within an audio file; markers are detected automatically in Transient Editing mode (and can be added, moved, or removed by hand) and serve as anchor points for editing, slicing, quantizing, and selecting audio.", "plain_english": "A transient marker is a tag that Logic places at each sharp attack in an audio clip. The program finds these hit points for you. You then use them to cut, move, or line up the audio in time.", "purpose_function": "They exist to give the software accurate hit points in an audio file, so that timing-based edits such as quantizing, slicing, and Flex time correction can lock to the real rhythm of the performance.", "practical_application": "An engineer tightens a loose drum take by letting Logic detect transient markers, then quantizes or Flex-edits the audio so each hit snaps to the grid, nudging or adding markers by hand where detection was poor.", "category": "Audio Editing", "related_terms": ["Flex Time", "Quantize", "Transient", "Slice", "Zero crossing"], "common_mistakes": ["Trusting automatic detection on soft or blurry material without checking the markers.", "Leaving false markers in place, which creates glitches when slicing or quantizing.", "Confusing transient markers with arrangement or region markers."], "scenario_contexts": ["Quantizing a live drum performance.", "Slicing a drum loop into individual hits.", "Time-aligning a multitracked kit before mixing."]}, "5bba5be9-639d-4986-98e1-9164feeb88bb": {"definition": "A cue point or marker that indicates where one section of a piece or program changes into the next; it flags or triggers transition material such as fills, risers, sweeps, or crossfades, and coordinates mix moves, playback, or automation at that point.", "plain_english": "A transition cue is a marker that shows where one section changes into the next. It reminds you when to bring in a build-up or a big drop. It works like a signpost telling you a turn is coming.", "purpose_function": "It exists to mark section boundaries clearly, so the engineer or the system knows exactly when to launch a transition element or execute a planned mix change.", "practical_application": "An engineer drops a transition cue at each chorus entry, then uses it to time a riser and a filter automation move so the build resolves precisely on the downbeat.", "category": "Arrangement", "related_terms": ["Marker", "Riser", "Fill", "Automation", "Crossfade"], "common_mistakes": ["Placing the cue slightly off the beat, so the transition lands late.", "Relying on memory instead of markers and missing the change.", "Cluttering the timeline with unlabeled cues that become hard to read."], "scenario_contexts": ["Marking chorus entries for a build-up.", "Cueing a scene change in post-production audio.", "Coordinating a live playback transition between songs."]}, "fe704389-053f-487e-95a3-ab0c60ce6b9e": {"definition": "In interactive game music, such as in Audiokinetic Wwise, the transition matrix is a grid inside a music switch container in which each row is a possible source (currently playing) music object and each column a destination (next) music object; every cell defines the rules for moving between that source-destination pair.", "plain_english": "A transition matrix is a grid that tells game music how to move from one piece to another. Each box sets the rules for going from the music playing now to the music that plays next.", "purpose_function": "It lets a sound designer control musical transitions between game states smoothly, setting exit and entry points, fades, and optional bridging segments so the score changes without jarring the player.", "practical_application": "A game-audio implementer fills the matrix cells to choose where the current cue exits (immediately, on the next bar, or at an exit cue), which transition segment plays, and where the next cue enters, then tests it in-game.", "category": "Interactive Music", "related_terms": ["Transition segment", "Stealth music", "Victory music", "Stinger", "Music switch container"], "common_mistakes": ["Assuming it is a mathematical Markov table; here it is a Wwise-style grid of musical transition rules.", "Leaving cells at abrupt defaults, so the music cuts harshly between states.", "Forgetting to set entry and exit cues, which breaks musical timing during transitions."], "scenario_contexts": ["Moving smoothly from exploration to combat music when an enemy appears.", "Bridging two cues with a short transition segment on a beat boundary.", "Returning to calm music with a musical fade after a fight ends."]}, "6491fd0e-518e-4bbc-b15a-fe92460b2bdc": {"definition": "A short passage of audio that connects two main sections of a song or program, such as the link between a verse and a chorus or the join between two cues, where the arrangement and mix are shaped to lead smoothly from one part into the next.", "plain_english": "A short bit of music that links two bigger parts of a song. It works like a hallway between two rooms, helping the listener move from one section to the next.", "purpose_function": "It exists to keep an arrangement flowing, giving the ear a smooth handoff between sections instead of an abrupt jump, and it is where fills, risers, and level moves are often placed.", "practical_application": "A mixer shapes the transition segment with automation, filters, risers, or reverb throws so energy builds or resolves as the track moves from one section into the next.", "category": "Arrangement", "related_terms": ["Arrangement", "Automation", "Riser", "Crossfade", "Fill", "Bridge"], "common_mistakes": ["Leaving the transition flat with no automation or effect move, so the sections feel disconnected.", "Overloading the transition with risers and effects until it distracts from the song.", "Forgetting to match levels across the join, so the next section jumps up or drops in volume."], "scenario_contexts": ["Adding a filter sweep and reverb throw to lead from a verse into a chorus.", "Smoothing the join between two scenes or cues in a broadcast or theatre mix.", "Automating a build across the bars before a drop in an electronic track."]}, "f676e9d2-8c96-415e-b2dc-ce0fab9d747f": {"definition": "The practice of adjusting a mix or master so its tonal balance, levels, and stereo image hold up consistently across many playback systems and environments, from studio monitors to earbuds, phone speakers, and car stereos, rather than sounding right on only one system.", "plain_english": "Making a mix sound good on all kinds of speakers, not just the ones you mixed on. It is like checking that a photo still looks right on a phone, a laptop, and a printout.", "purpose_function": "It exists because listeners use very different playback systems, so the goal is a mix whose balance and impact survive on small or cheap speakers as well as on full studio monitors.", "practical_application": "An engineer checks the mix on several playback systems, compares it to reference tracks, and mixes at times in mono or on small speakers, then fixes balance problems that only show up outside the main monitors.", "category": "Mix Fundamentals", "related_terms": ["Translation", "Reference monitor", "Reference track", "Mono compatibility", "Tonal balance", "Room correction"], "common_mistakes": ["Judging the mix only on one flattering set of speakers, so it falls apart elsewhere.", "Skipping a mono check, then finding parts vanish on phone and club systems.", "Chasing a perfect sound on headphones while ignoring how it plays on small speakers."], "scenario_contexts": ["Checking a finished mix on phone, laptop, and car speakers before release.", "Comparing a mix against commercial reference tracks on the same system.", "Mixing bass and vocals in mono to keep them solid on small speakers."]}, "b2b75f84-a24b-47a5-ae6b-09764872e744": {"definition": "A global timeline track in a DAW that applies real-time pitch transposition to MIDI parts across sections of the project, shifting them by a set number of semitones without changing the recorded notes; in Steinberg Cubase this is the Transpose Track.", "plain_english": "A special lane in music software that shifts the key of your parts over the song. You set how many steps to move each section up or down, and it changes the pitch without rewriting the notes.", "purpose_function": "It exists to let you try a song in a different key or add key changes quickly, keeping the original MIDI intact so the change stays non-destructive and easy to undo.", "practical_application": "A producer draws transpose values on the track to move a chorus up two semitones or to test a whole song in a higher key before committing to it.", "category": "MIDI Editing", "related_terms": ["Transposition track", "MIDI", "Semitone", "Key change", "Global tracks", "Pitch shift"], "common_mistakes": ["Expecting the transpose track to move recorded audio, when it acts on MIDI parts.", "Forgetting the track is still active, so a part later plays in the wrong key.", "Confusing this real-time transpose with permanently rewriting the MIDI notes."], "scenario_contexts": ["Testing a full song a few semitones higher to suit a singer's range.", "Adding a key change to the final chorus without editing every note.", "Auditioning a chord progression in several keys quickly."]}, "31c0d7df-e56b-4bde-b886-e303cf3c8468": {"definition": "A dedicated global track in some DAWs that stores pitch transposition or key-change values along the project timeline and applies them to the associated material, so the key of parts follows the transposition events without altering the original recorded notes.", "plain_english": "A timeline lane that holds the key changes for a song. As the song plays, it shifts the parts to the right key at each point, without changing the notes you recorded.", "purpose_function": "It exists to manage key and pitch changes in one place across a project, keeping transposition non-destructive and consistent for every part that follows it.", "practical_application": "An engineer enters transposition values at each section so the arrangement moves through its key changes, then prints or exports with those changes applied.", "category": "MIDI Editing", "related_terms": ["Transpose track", "Global tracks", "Key change", "Semitone", "MIDI", "Pitch shift"], "common_mistakes": ["Assuming every DAW names and implements this feature the same way, when hosts differ.", "Leaving old transposition events in place, so a later edit plays in the wrong key.", "Expecting it to retune audio the same way it retunes MIDI parts."], "scenario_contexts": ["Mapping out a song's key changes on one global track.", "Shifting a whole section up a step to fit a vocal range.", "Keeping transposition consistent across many MIDI parts at once."]}, "b73be02a-9c09-4b55-a238-11140da4c40c": {"definition": "An editing tool in a DAW used to adjust the start or end boundary of a clip or region by dragging its edge, revealing or hiding material without moving the clip in time; in Pro Tools it is one of the main Edit tools and includes variants such as TCE and Loop trim.", "plain_english": "A tool in music software that shortens or lengthens a clip by dragging its edge. It is like sliding the edge of a sticky note to show more or less of what is underneath.", "purpose_function": "It exists to set exactly where a clip starts and ends, so a technician can tighten edits, remove unwanted audio at the edges, or extend a clip to reveal more of the take.", "practical_application": "An editor selects the Trim tool and drags a clip's edge to cut off a noisy breath before a vocal line or to open up the tail of a reverb.", "category": "Editing", "related_terms": ["Clip", "Fade", "Crossfade", "Grabber tool", "Selector tool", "Edit window"], "common_mistakes": ["Trimming past the recorded material and getting silence at the clip edge.", "Confusing the Trim tool with time-compression trim, which changes the audio speed.", "Trimming without a fade, leaving a click at the new clip boundary."], "scenario_contexts": ["Cutting a noisy breath from the front of a vocal clip.", "Extending a guitar clip's end to keep its natural ring.", "Tightening the edges of drum clips during editing."]}, "5715cf76-2cd6-422a-b86f-b9a20bfd9531": {"definition": "The practice of controlling the true-peak level of audio, the maximum inter-sample peak reconstructed by a digital-to-analog converter measured in dBTP per ITU-R BS.1770, so it stays below a set ceiling (commonly -1 dBTP) to avoid clipping and distortion after conversion or lossy encoding.", "plain_english": "Keeping the real loudest points of digital audio under a safe limit. Hidden peaks can appear between the digital samples, so you leave a little room to stop distortion when the sound is played back.", "purpose_function": "It exists because peaks can rise between digital samples and overload a converter or encoder even when the sample values look safe, so managing true peak prevents audible clipping on playback and after MP3 or AAC encoding.", "practical_application": "A mastering engineer sets a true-peak limiter to a ceiling such as -1 dBTP and watches a true-peak meter so the final file meets a platform's delivery spec without inter-sample clipping.", "category": "Loudness", "related_terms": ["True peak", "dBTP", "Inter-sample peak", "Loudness normalization", "Limiter", "Headroom"], "common_mistakes": ["Trusting the sample-peak meter and assuming 0 dBFS is safe, missing higher true peaks.", "Setting the ceiling at 0 dBTP, leaving no room for encoding to add distortion.", "Ignoring true-peak limits until a streaming platform rejects or distorts the file."], "scenario_contexts": ["Setting a -1 dBTP ceiling before exporting a master for streaming.", "Checking true-peak levels after MP3 or AAC encoding.", "Meeting a broadcast delivery spec that limits true peaks."]}, "0b65a145-3a08-4b1c-b086-a3b6980f023b": {"definition": "The process of measuring and verifying that a finished audio file's true-peak levels, in dBTP per ITU-R BS.1770, comply with a target ceiling required by a delivery or broadcast specification, using a compliant true-peak meter to confirm the file passes before delivery.", "plain_english": "Checking a finished file to prove its loudest hidden peaks stay under the required limit. It is a final pass-or-fail test before you hand the file over.", "purpose_function": "It exists to confirm a deliverable meets a platform or broadcaster's true-peak rule, catching over-ceiling peaks before the file is rejected or distorts on playback.", "practical_application": "Before delivery, an engineer runs the mix through a true-peak meter or loudness-compliance tool and confirms the reading sits at or below the required ceiling, such as -1 dBTP.", "category": "Loudness", "related_terms": ["True peak", "True-peak management", "dBTP", "Loudness normalization", "Delivery spec", "Metering"], "common_mistakes": ["Validating loudness but forgetting to check true peak against the spec.", "Measuring with a meter that is not true-peak compliant, so the reading is wrong.", "Checking peaks before final encoding instead of on the delivered file."], "scenario_contexts": ["Confirming a master meets a streaming service's -1 dBTP limit before upload.", "Verifying a broadcast file passes its loudness and true-peak spec.", "Re-checking true peak after a format or codec change."]}, "f858689b-fdfc-4acf-9750-e94c0b210158": {"definition": "An approach to building a signal path so that gain stages pass signal at unity gain (no net boost or cut, a gain of one) wherever possible, keeping levels consistent from input to output and preserving healthy headroom and signal-to-noise ratio throughout the chain.", "plain_english": "A way of setting levels so each step passes the sound through without making it louder or quieter. Keeping everything at this no-change point keeps the signal clean and avoids noise or distortion.", "purpose_function": "It exists to keep good gain structure across a system, so no stage is pushed too hot or run too low, which protects headroom and keeps noise and distortion down.", "practical_application": "An engineer builds a session with faders and sends at unity and matches plugin input and output levels, so bypassing a processor does not change the volume, then rides balance from that neutral starting point.", "category": "Gain Structure", "related_terms": ["Unity gain", "Gain structure", "Gain staging", "Headroom", "Signal-to-noise ratio", "Fader"], "common_mistakes": ["Boosting makeup gain on plugins until the mix is far louder than the bypassed level.", "Running channels very hot early, then pulling the master down to fix it.", "Confusing a fader at unity (0 dB) with the channel being off."], "scenario_contexts": ["Matching a plugin's output to its input so bypass does not change level.", "Setting console and DAW faders to unity as a mixing starting point.", "Keeping gain consistent when moving signal between analog and digital gear."]}, "5785088f-2f0b-4449-93a2-424eb9d4c814": {"definition": "A display mode on a lighting control console or DMX software that shows the live output values of all 512 slots (channels) of a single DMX512 universe, letting the operator monitor or check each channel's level. A DMX universe is one independent stream of 512 control channels as defined by the DMX512 standard.", "plain_english": "A screen on a lighting desk that shows all 512 control channels in one DMX group at once. It is like a dashboard where you watch the level being sent to every light.", "purpose_function": "It lets a technician see the raw output on every channel of a universe, so they can confirm a fixture is receiving the right level or find an addressing or patch problem.", "practical_application": "When a moving light misbehaves, an operator opens the universe view to see whether the console is actually sending values to that fixture's address.", "category": "Lighting Control", "related_terms": ["DMX512", "DMX universe", "Channel", "Patch", "Address"], "common_mistakes": ["Confusing a channel number in the console with the raw DMX address shown in the universe view.", "Assuming a blank value in the view means a broken cable, when the fixture may simply be unpatched.", "Forgetting that one universe holds only 512 channels, so large rigs need several universes."], "scenario_contexts": ["Checking that a dimmer is receiving output during a rig check.", "Diagnosing an unresponsive fixture by watching its address in the universe view.", "Verifying DMX values while troubleshooting an addressing conflict."]}, "871e41e5-8b29-48b7-92dc-76466c1dba9c": {"definition": "In the Avid VENUE live-sound platform, a V-Rack is a self-contained rackmount chassis that houses a DSP mix engine plus I/O and option cards, adding inputs, outputs, and processing to a VENUE system or running as a standalone engine without a control-surface console attached.", "plain_english": "A box in the Avid VENUE mixing system that adds more inputs, outputs, and processing power. It can work on its own, without a fader surface plugged into it.", "purpose_function": "It exists to expand a VENUE system's channel count, connections, and effects, or to act as a standalone engine for tasks like recording or virtual soundcheck.", "practical_application": "A touring engineer adds a V-Rack to gain extra outputs for more monitor mixes, or to run virtual soundcheck playback while the band is off the stage.", "category": "Live Sound", "related_terms": ["Stage rack", "Mix engine", "Virtual soundcheck", "DSP", "I/O card"], "common_mistakes": ["Thinking a V-Rack is only I/O, when it also carries the DSP mix engine and processing.", "Assuming it needs a console surface to function, when it can run standalone.", "Under-planning card slots and running out of I/O or plug-in capacity mid-show."], "scenario_contexts": ["Expanding output count for extra monitor mixes on a large stage.", "Running virtual soundcheck from a V-Rack while musicians are away.", "Adding plug-in processing capacity to a VENUE rig."]}, "49e410af-94aa-47ff-a9bb-ea658f83de60": {"definition": "A tempo map in which the project's tempo changes across the timeline through programmed tempo events or a tempo curve, rather than staying at one fixed value, so the sequencer's beat grid follows tempo shifts such as ritardando, accelerando, or section changes.", "plain_english": "A set of tempo changes written into a song's timeline, so the speed can rise and fall instead of staying fixed. It lets the software's beat grid follow music that speeds up or slows down.", "purpose_function": "It lets a DAW keep its bars-and-beats grid aligned with music that does not hold one steady tempo, which is needed for editing, quantizing, and syncing to free or changing performances.", "practical_application": "An engineer builds a variable tempo map by matching bar lines to a live drummer's shifting tempo so that loops, MIDI, and edits line up with the recording.", "category": "Sequencing", "related_terms": ["Tempo map", "Beat grid", "Quantize", "Bars and beats", "Tempo track"], "common_mistakes": ["Recording MIDI against a fixed tempo when the audio actually drifts, so nothing lines up later.", "Forgetting to build the tempo map before quantizing, which shifts notes to the wrong grid.", "Confusing tempo changes with time-signature changes."], "scenario_contexts": ["Mapping tempo to a live band recording that speeds up in the chorus.", "Programming a ritardando at the end of a song.", "Aligning samples and MIDI to a rubato piano take."]}, "60a2f228-c92d-4d8d-9460-b3a0f3dd5511": {"definition": "A dedicated track or master fader that remotely controls the gain of a group of assigned channels together without combining their audio into one signal path; moving the VCA fader offsets every member channel's level while each keeps its own fader and routing. The name derives from the voltage-controlled amplifier used for this on analog consoles.", "plain_english": "A single fader that turns a whole group of channels up or down at once, without mixing them into one signal. It is like a master remote that nudges every assigned track while each track keeps its own fader.", "purpose_function": "It lets an engineer ride the overall level of many related channels, such as all the drums, with one fader while preserving the internal balance and each channel's direct routing to the mix.", "practical_application": "A mixer assigns every drum channel to a VCA fader, then rides that one fader to raise the whole kit in the chorus without re-balancing the individual drum faders.", "category": "Mix Control", "related_terms": ["VCA group", "Subgroup", "Bus", "Fader automation", "Mix bus"], "common_mistakes": ["Confusing a VCA with an audio subgroup; a VCA controls level but does not sum the audio to a bus.", "Expecting to insert a bus processor on a VCA, when a VCA carries no audio to process.", "Forgetting that muting a VCA mutes all of its assigned member channels."], "scenario_contexts": ["Riding all drum channels with one fader during a mix.", "Controlling a group of background vocals together while keeping their blend.", "Grouping a horn section under one VCA for quick level moves."]}, "d78d22aa-a04e-4fbd-90ac-4d2b00072352": {"definition": "The process of introducing small, often randomized variations to the velocity values of MIDI notes so that a programmed part sounds less mechanically uniform and closer to a human performance, in which each note is struck with slightly different force.", "plain_english": "Slightly changing how hard each MIDI note is played so a programmed part does not sound stiff. Real players never hit every note at the same strength, and this copies that natural unevenness.", "purpose_function": "It exists to make step-entered or copied MIDI parts feel more natural and expressive by breaking up the identical dynamics that make programming sound robotic.", "practical_application": "After drawing in a hi-hat pattern, a producer applies velocity humanization so the repeated hits vary in loudness and the groove feels played rather than typed.", "category": "MIDI Sequencing", "related_terms": ["Velocity", "MIDI", "Quantize", "Humanize", "Groove"], "common_mistakes": ["Applying so much random variation that some notes nearly disappear or jump out unnaturally.", "Humanizing velocity but leaving timing perfectly quantized, which still sounds stiff.", "Assuming every instrument's samples respond to velocity, when some map velocity only to volume."], "scenario_contexts": ["Loosening a programmed drum pattern so it feels human.", "Varying the dynamics of a repeated synth arpeggio.", "Adding life to a copied-and-pasted MIDI phrase."]}, "6b3bbcc7-c337-46b1-b09b-cf8d7d41dafa": {"definition": "In a sampler or virtual instrument, a velocity zone is a defined range of MIDI note-on velocity values that triggers a particular sample or layer, so that different playing strengths call up different recordings mapped across the velocity axis.", "plain_english": "A range of how-hard-you-play values that triggers one particular sound in a sampler. Play softly and you fall in one zone; hit harder and you cross into a zone that plays a different recording.", "purpose_function": "It lets an instrument switch between samples captured at different dynamics, so soft and hard notes use recordings that actually sound soft or hard rather than just changing in volume.", "practical_application": "When building a sampled piano, a sound designer assigns quiet recordings to low velocity zones and loud recordings to high ones so dynamics change the tone, not just the level.", "category": "Sampling", "related_terms": ["Velocity", "Velocity layer", "Key zone", "Sample mapping", "Velocity switching"], "common_mistakes": ["Leaving gaps between zones so some velocities trigger no sample at all.", "Setting hard zone edges that cause an audible jump between samples instead of a crossfade.", "Confusing a velocity zone with a key zone, which maps by pitch rather than by force."], "scenario_contexts": ["Mapping soft and hard drum hits to different recordings.", "Building a multisampled instrument that changes tone with dynamics.", "Setting a velocity threshold so a hard hit triggers an accent sample."]}, "9977f300-7e01-4c72-9cec-30afb106f0e6": {"definition": "A sampled drum instrument in which each drum is represented by several recordings captured at different striking strengths, mapped to velocity ranges so that note-on velocity selects the layer whose loudness and tone match how hard the pad or key was played.", "plain_english": "A sampled drum that holds several recordings of the same drum, each hit at a different strength. How hard you play picks which recording sounds, so soft and hard hits differ in tone, not just volume.", "purpose_function": "It exists to make sampled drums respond realistically to playing dynamics, because a real drum changes tone as well as loudness when struck harder or softer.", "practical_application": "A producer playing a velocity-layered kit on pads gets brighter, harder snare tones on strong hits and softer, duller tones on light hits, so the part breathes like a live drummer.", "category": "Sampling", "related_terms": ["Velocity layer", "Velocity zone", "Velocity", "Round robin", "Sample library"], "common_mistakes": ["Programming every hit at the same velocity, which defeats the layering and sounds like a machine gun.", "Assuming more layers always sound better, when poorly matched layers cause audible steps.", "Ignoring round-robin needs, so repeated same-velocity hits still sound identical."], "scenario_contexts": ["Playing expressive drum parts from a pad controller.", "Programming dynamics into a sampled kit.", "Choosing a drum library with enough layers for realistic fills."]}, "77b4f563-d987-4c2f-9955-2a8b4f4cb54a": {"definition": "An adaptive-music technique in which a piece is built from several musical layers that play simultaneously in sync, and the game or application adds or removes layers in real time to raise or lower intensity while the underlying music keeps playing.", "plain_english": "A way of writing game music as stacked parts that all play together in time. The game switches parts on or off to make the music feel calmer or more intense without stopping it.", "purpose_function": "It lets a score react to gameplay smoothly by changing how full the music sounds, avoiding hard stops and giving a sense of rising or falling tension.", "practical_application": "A game composer stems a cue into rhythm, harmony, and lead layers, then has the audio engine fade the lead and rhythm layers in as combat starts.", "category": "Adaptive Music", "related_terms": ["Vertical remixing", "Horizontal resequencing", "Adaptive music", "Stem", "Interactive music"], "common_mistakes": ["Writing layers that do not share the same tempo and key, so they clash when combined.", "Layering parts that sound wrong when heard alone or in some combinations.", "Switching layers abruptly instead of fading, which draws attention to the change."], "scenario_contexts": ["Building tension as a player nears an enemy.", "Fading extra parts in during a game's combat state.", "Scoring an open-world area that shifts mood with player action."]}, "8db18048-c46e-4fc0-a995-1159ff23d091": {"definition": "A form of adaptive music, closely related to vertical layering, in which a single synchronized piece is divided into simultaneous stems whose individual volumes are raised, lowered, muted, or unmuted in real time to remix the arrangement on the fly in response to gameplay, without changing the underlying timeline.", "plain_english": "Changing a game track on the fly by turning its separate parts up, down, or off while it keeps playing in time. It is like a live mixer that adds or drops instruments to match what the player is doing.", "purpose_function": "It exists to vary the mood and energy of a continuous cue by re-mixing which parts are heard, so the music adapts to the action without a jarring cut to a new piece.", "practical_application": "A composer delivers a cue as separate stems and sets rules so the engine mutes the drums during exploration and unmutes them in a chase, remixing the same piece live.", "category": "Adaptive Music", "related_terms": ["Vertical layering", "Horizontal resequencing", "Adaptive music", "Stem", "Interactive music"], "common_mistakes": ["Treating vertical remixing as writing new sections, when it only re-mixes stems of the same piece.", "Muting stems with hard cuts instead of smooth fades, which sounds abrupt.", "Building stems that do not work in every on/off combination the game can call."], "scenario_contexts": ["Dropping and adding instrument stems as game intensity changes.", "Muting the melody during dialogue and restoring it afterward.", "Remixing a looping cue live to follow player choices."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"64eeabd7-d42a-4552-a79a-61397affbe7f": {"definition": "In Logic Pro's Flex Pitch, the Vibrato control is the upper-middle hotspot on a detected note that increases or reduces the depth of the note's natural pitch vibrato. Dragging it up exaggerates the wobble; dragging down flattens it toward a steady pitch, without changing the note's center pitch.", "plain_english": "Flex Pitch lets you edit sung notes in Logic Pro. The Vibrato control changes how much a note wobbles up and down in pitch. Drag it up for more wobble, or down to make the note steadier.", "purpose_function": "It lets an engineer shape the expressive pitch wobble of a recorded vocal or instrument note after the fact, so a take can be fixed or enhanced without re-recording it.", "practical_application": "When tuning a lead vocal in Logic, you drag a note's Vibrato hotspot down to calm an over-wide wobble on a held note, or up to add life to a flat, lifeless one.", "category": "Pitch Editing", "related_terms": ["Flex Pitch", "Pitch correction", "Formant shift", "Fine pitch", "Vocal tuning", "Automation"], "common_mistakes": ["Confusing the Vibrato hotspot with overall pitch; it changes wobble depth, not the note's center pitch.", "Removing all vibrato so the vocal sounds robotic and lifeless.", "Editing vibrato on a note that Flex Pitch detected poorly, which creates glitches instead of a fix."], "scenario_contexts": ["Taming an unstable, wide vibrato on a sustained note in a pop lead vocal.", "Adding gentle vibrato to a flat-sounding held vocal or synth note.", "Cleaning up a take before printing a tuned vocal comp."]}, "cef9722a-a9a6-45a8-91a3-19115541c891": {"definition": "Victory music is a short, triumphant cue, often a fanfare or upbeat stinger, played to mark a win, level completion, boss defeat, or successful outcome in games, film, sports, and other media.", "plain_english": "Victory music is the happy, triumphant music that plays when you win or finish something, like a level in a game. It tells you that you succeeded.", "purpose_function": "It rewards and signals success to the audience or player, providing clear emotional payoff and closure at the end of a challenge.", "practical_application": "A game-audio implementer triggers a victory stinger when a win condition is met, ducking or stopping the current music so the fanfare lands cleanly.", "category": "Score Cue Type", "related_terms": ["Suspense music", "Stealth music", "Stinger", "Transition matrix", "Underscore"], "common_mistakes": ["Letting the previous cue clash with the victory stinger instead of ducking or stopping it.", "Making the cue too long, so it drags past the moment of triumph.", "Reusing the same victory cue so often that it loses its impact."], "scenario_contexts": ["Playing a fanfare when the player defeats a boss.", "Marking level completion in a mobile game.", "Underscoring a team's win in a sports broadcast."]}, "71090753-d9a2-42e5-9a69-c4f6e94ba5ed": {"definition": "Vocal Assistant is an assistive feature in iZotope Nectar that analyzes a solo vocal recording and automatically builds a starting processing chain, setting EQ, compression, de-essing, pitch and reverb based on the voice. Its Unmask function can also adjust other plugins to reduce frequency clashes with the vocal.", "plain_english": "Vocal Assistant is a smart tool in iZotope Nectar. You play part of a vocal and it listens, then sets up a good starting mix for that voice by itself. You still fine-tune it, but you do not start from zero.", "purpose_function": "It gives beginners and busy engineers a fast, sensible starting point for vocal processing instead of dialing every setting by hand.", "practical_application": "A technician loads Nectar on a lead vocal, runs Vocal Assistant over a loud, sustained phrase, then tweaks the suggested EQ and compression to taste.", "category": "Assistive Tools", "related_terms": ["Equalization", "Compression", "De-esser", "Vocal chain", "Reverb", "Masking"], "common_mistakes": ["Treating the Assistant's result as finished instead of a starting point to refine.", "Running it over a quiet or noisy section, which gives a poor analysis.", "Using it on a bus with several instruments instead of an isolated vocal."], "scenario_contexts": ["Quickly setting up a vocal chain during a fast-turnaround mix.", "Helping a beginner learn what settings a vocal usually needs.", "Using Unmask to carve space so the vocal sits over a busy instrumental."]}, "647f09a2-26d1-472b-9f99-b68043170ed7": {"definition": "A voice choke (choke group) is a setting in a sampler or drum instrument that lets one sound instantly silence another when triggered, so only one voice in the group sounds at a time. The classic use is a closed hi-hat choking a ringing open hi-hat, mimicking a real drummer.", "plain_english": "Voice choke makes one drum sound cut off another. The most common example is hi-hats: hitting the closed hat stops the open hat from ringing. It copies how a real drummer closes the cymbals with a foot.", "purpose_function": "It recreates natural instrument behavior where two related sounds cannot ring at once, keeping programmed drums tight and believable.", "practical_application": "In a drum rack or sampler, a producer assigns the open and closed hi-hats to the same choke group so triggering the closed hat cuts off the open one.", "category": "Drum Programming", "related_terms": ["Choke group", "Sampler", "Drum Rack", "Polyphony", "Monophonic", "Hi-hat"], "common_mistakes": ["Assuming choke just lowers volume; it fully cuts off the other voice.", "Forgetting to also add the open hi-hat to the group, so it keeps ringing.", "Placing sounds that should overlap, like kick and snare, in the same choke group by mistake."], "scenario_contexts": ["Programming realistic hi-hats from separate open and closed samples.", "Setting a bass or 808 patch so a new note cuts off the previous one.", "Building a kit where certain percussion hits should never overlap."]}, "b4c3b4f3-0861-41ba-96bb-4e14887192b7": {"definition": "A volume automation pass is a dedicated run through a mix in which the engineer writes or refines volume (fader) automation, recording level moves over time so each part sits at the right loudness through the song. It is usually done as a focused stage after the static balance is set.", "plain_english": "A volume automation pass is when you go through the whole song and record fader moves. This makes each part louder or quieter at the right moments, like turning a quiet word up so you can hear it. You focus only on volume during this pass.", "purpose_function": "It keeps every element audible and balanced from section to section, fixing spots where one fixed fader level is too loud or too soft.", "practical_application": "After the rough balance, an engineer arms volume automation and rides the vocal fader up on quiet words and down on loud ones across the track.", "category": "Automation", "related_terms": ["Automation", "Fader", "Gain riding", "Mixing", "Breakpoint", "Volume View"], "common_mistakes": ["Writing detailed automation before setting a solid static balance first.", "Making moves so large the mix sounds jumpy and unnatural.", "Forgetting to set automation to a write or touch mode, so nothing is recorded."], "scenario_contexts": ["Riding a lead vocal so every word stays clear over the band.", "Lifting a guitar solo in the chorus and lowering it afterward.", "Smoothing level jumps between a quiet verse and a loud chorus."]}, "28e44e70-c537-4501-a770-295a0e1e3d3b": {"definition": "In Pro Tools, Volume view is a track display mode that shows a track's volume automation as an editable breakpoint line drawn over the audio, instead of the waveform. Choosing it lets you draw and edit fader-level automation directly in the Edit window.", "plain_english": "Volume View is a way to look at a track in Pro Tools. Instead of the sound wave, it shows a line for the track's volume. You drag points on that line to make parts louder or quieter over time.", "purpose_function": "It gives a clear, hands-on way to see and edit level changes across a track right on the clip, without opening a separate automation lane.", "practical_application": "An engineer switches an audio track to Volume view, then clicks and drags breakpoints on the line to ride the level of a phrase.", "category": "Track Views", "related_terms": ["Waveform View", "Volume automation pass", "Automation", "Breakpoint", "Track View", "Fader"], "common_mistakes": ["Trying to edit the audio while in Volume view and moving automation points by accident.", "Confusing the volume line with the audio waveform.", "Leaving a track in Volume view and forgetting why the display looks different."], "scenario_contexts": ["Drawing precise volume automation on a vocal in Pro Tools.", "Fixing a single loud breath by pulling down one breakpoint.", "Toggling to Volume view to check existing level moves."]}, "7c1b61e7-2dde-46f1-8a27-38f8ae671338": {"definition": "To walk the room is to physically move through the listening area or venue while audio plays, checking tonal balance, level and coverage at different positions rather than judging the sound only from the mix position. It is a standard check in live sound and studio work.", "plain_english": "Walking the room means moving around the space while music plays. You listen from different spots, not just where the mixing desk is. This tells you if the sound is good and even for everyone, not only at your seat.", "purpose_function": "It reveals how the audience actually hears the system, exposing dead spots, harsh areas or bass buildup that are not obvious at the console.", "practical_application": "During soundcheck, a live engineer walks front to back and side to side, noting where the vocal gets buried or the low end piles up, then adjusts EQ or system tuning.", "category": "Monitoring", "related_terms": ["Coverage", "System tuning", "Soundcheck", "Front of house", "Room acoustics", "Reference monitoring"], "common_mistakes": ["Mixing only from the sweet spot and never checking the rest of the room.", "Walking the room with no music or a poor reference track, so problems stay hidden.", "Changing settings for one bad spot in a way that harms the main seating area."], "scenario_contexts": ["Checking coverage across a venue during soundcheck.", "Finding a feedback-prone or boomy zone before doors open.", "Verifying that a studio mix holds up around the control room."]}, "9fac0d31-ef75-415b-b18d-09e71bb2b652": {"definition": "Waveform view is a track display mode that shows recorded audio as a time-domain amplitude waveform, drawing the signal's level over time. It is the default view for audio tracks and gives the visual detail needed for accurate editing.", "plain_english": "Waveform View shows a sound as a wavy shape on screen. Taller parts are louder and flatter parts are quieter. Seeing this shape helps you find beats and edit audio at the right spot.", "purpose_function": "It lets an engineer see where sounds start, stop and peak, so edits like cuts, fades and alignment can be placed precisely.", "practical_application": "An editor uses Waveform view to find the exact start of a drum hit before cutting or nudging the clip into time.", "category": "Track Views", "related_terms": ["Waveform Zoom", "Volume View", "Transient", "Editing", "Zero crossing", "Clip"], "common_mistakes": ["Thinking a tall waveform always means distortion; height shows level, not clipping.", "Editing between beats without zooming in enough to see the transient.", "Confusing the waveform display with volume automation shown in Volume view."], "scenario_contexts": ["Cutting a clip cleanly at a silent point.", "Lining up a double-tracked vocal to the main take.", "Spotting a loud pop or click to edit out."]}, "3746dd04-384b-4364-ba0c-b844211198c4": {"definition": "Waveform Zoom is the adjustment of how magnified the waveform display appears, horizontally in time and/or vertically in amplitude. Zooming in reveals fine detail for precise edits, while zooming out shows more of the timeline at once.", "plain_english": "Waveform Zoom makes the sound wave look bigger or smaller on screen. Zoom in to see tiny details, like the exact start of a note. Zoom out to see the whole song at once.", "purpose_function": "It lets an engineer move between a wide overview of the arrangement and a close-up needed for sample-accurate editing.", "practical_application": "Before making a tight cut, an editor zooms in horizontally to see individual waveform cycles, then zooms back out to check the edit in context.", "category": "Editing", "related_terms": ["Waveform View", "Zoom", "Editing", "Transient", "Nudge", "Zero crossing"], "common_mistakes": ["Editing while zoomed too far out, causing sloppy, off-beat cuts.", "Confusing vertical zoom (a display change) with an actual gain change; it only changes how the waveform looks.", "Zooming so far in that you lose track of where you are in the song."], "scenario_contexts": ["Zooming in to place a fade exactly at a zero crossing.", "Zooming out to view the whole session for arrangement.", "Getting close on a waveform to remove a single click."]}, "dd2053d3-24ab-406b-a19b-5850976c2d64": {"definition": "In a DAW media browser (notably Avid Pro Tools' Workspace), a catalog is a saved, user-defined collection of references to volumes, folders, and media files, letting you organize and quickly recall assets without physically moving or copying them on disk.", "plain_english": "A catalog is like a saved list of shortcuts to your sound files. It points to where the files live so you can find them fast, but it does not move or copy the real files.", "purpose_function": "It exists to speed up finding and reusing media across drives and projects by grouping links to files in one searchable place.", "practical_application": "A technician builds a catalog of go-to sound effects or loops so they can drag them into any session without hunting through folders.", "category": "Session Management", "related_terms": ["Workspace preset", "Session", "Import Audio", "Region", "Sample rate"], "common_mistakes": ["Assuming a catalog stores the actual audio, then deleting the source files and breaking every reference.", "Confusing a catalog of saved references with importing or copying media into the session.", "Forgetting that a catalog only points to files, so moving or renaming the originals makes them go offline."], "scenario_contexts": ["Building a reusable library of sound effects for a post-production suite.", "Organizing sample and loop folders across several drives for quick recall.", "Locating a specific take stored on an external volume without importing it first."]}, "df86d015-5a7e-481b-93e0-a585c1e6a860": {"definition": "A saved configuration of a DAW's on-screen layout, including window sizes and positions, visible panels, editors, and toolbars, that can be recalled instantly to restore a preferred working arrangement.", "plain_english": "A workspace preset saves how your screen is set up. Load it and all your windows and panels jump back to where you like them.", "purpose_function": "It lets you switch quickly between task-specific layouts, such as recording, editing, and mixing, and keep a consistent setup across sessions and machines.", "practical_application": "An engineer keeps one preset for tracking and another for mixing, switching with a key command as the session moves between stages.", "category": "Session Management", "related_terms": ["Workspace Catalog", "Session", "Window configuration", "Edit window", "Mix window"], "common_mistakes": ["Confusing a window-layout preset with a session template, which also stores tracks and routing.", "Expecting a preset to save audio or mix settings when it only stores the screen layout.", "Overwriting a saved preset by accident instead of creating a new one."], "scenario_contexts": ["Switching from a tracking layout to a mixing layout during a session.", "Restoring a familiar window setup after opening a colleague's session.", "Setting up matching layouts on a studio rig and a laptop rig."]}, "f8c36dab-253b-4ee7-a52a-6d717d8b0875": {"definition": "An automation mode in which the DAW records (writes) new automation data for a parameter across the whole pass, overwriting any existing automation for that parameter for as long as the transport runs, whether or not the control is touched.", "plain_english": "Write mode records every move of a fader or knob as the song plays. It also erases the old moves it passes over, even ones you do not touch, so use it with care.", "purpose_function": "It exists to lay down an initial automation pass or to completely replace existing moves for a parameter.", "practical_application": "A mixer uses Write mode to record a first volume ride, then switches to Touch or Latch so the next pass does not wipe the good moves already recorded.", "category": "Automation", "related_terms": ["Touch automation mode", "Latch automation mode", "Read automation mode", "Trim automation mode", "Automation lane"], "common_mistakes": ["Leaving a track in Write mode during playback, which erases existing automation as the playhead passes over it.", "Confusing Write with Touch or Latch, so parameters get overwritten unintentionally.", "Not switching out of Write after the first pass, wiping good automation on the next play."], "scenario_contexts": ["Recording a first volume ride on a lead vocal.", "Erasing and re-recording a pan automation pass that went wrong.", "Setting static automation levels at the start of a mix."]}, "cff83ef9-61e4-4a2b-935a-e799b4b533d1": {"definition": "A Pro Tools editing command that switches between the current view and a stored, user-defined zoom state, including horizontal and vertical zoom, track height, track view, and grid settings, letting you jump instantly to a detailed edit view and back.", "plain_english": "Zoom Toggle is a one-key jump between your normal view and a close-up edit view. Press it to zoom in on a spot, then press again to pop back out.", "purpose_function": "It exists to give editors instant, one-key access to a preferred detailed edit view without manually re-zooming each time.", "practical_application": "An editor stores a tight zoom and track height, then toggles into it to fix a click and toggles back out to the full session.", "category": "Editing", "related_terms": ["Zoom Tool", "Edit window", "Track height", "Grid", "Selector tool"], "common_mistakes": ["Confusing Zoom Toggle with the Zoom tool; Toggle recalls a stored view, while the tool zooms manually.", "Not setting the zoom-toggle preferences, so the recalled view is not what you expected.", "Pressing it twice and losing your place because it returns to the previous zoom."], "scenario_contexts": ["Jumping to a close-up view to fix a vocal edit, then back to the full arrangement.", "Toggling to a detailed grid view for tight drum edits.", "Quickly checking a crossfade up close during editing."]}, "5f061147-c9e2-4f23-8c33-1959a44ac9ef": {"definition": "A DAW edit-window tool, usually shown as a magnifying-glass cursor, used to zoom the timeline view in or out by clicking or dragging over a region to enlarge it horizontally, and sometimes vertically, for detailed editing.", "plain_english": "The Zoom tool is a magnifying glass for your timeline. Click or drag over part of a track to get a closer look for fine editing.", "purpose_function": "It lets you change how much of the timeline you see so you can work at the right level of detail for the task.", "practical_application": "A technician grabs the Zoom tool to drag over a snare hit, enlarge it, and trim the edit precisely.", "category": "Editing", "related_terms": ["Zoom Toggle", "Selector tool", "Grabber tool", "Trim tool", "Edit window"], "common_mistakes": ["Zooming in so far that you lose track of the wider arrangement and place edits in the wrong spot.", "Confusing the Zoom tool with Zoom Toggle or keyboard zoom commands.", "Forgetting that horizontal and vertical zoom are separate, so tracks look too short to edit."], "scenario_contexts": ["Zooming in to place an edit exactly on a transient.", "Enlarging a quiet section to see the waveform for a clean cut.", "Zooming out to see the whole song arrangement."]}, "ea4a6a39-74b7-4451-a197-886bb609a27a": {"definition": "A creative effect that captures short slices of an audio signal and retriggers them in rhythmic subdivisions synced to the track's tempo, producing stutters, rolls, and glitch patterns. It is implemented as a dedicated device or plug-in that samples incoming audio into a buffer and replays it at set note values, often with pitch, gating, and filtering options.", "plain_english": "Beat repeat grabs a tiny piece of the sound and plays it again and again very fast, in time with the beat. It is like a skipping record used on purpose to make a stutter.", "purpose_function": "It adds rhythmic movement and energy by turning a plain sound into fast repeated bursts, and is used for fills, transitions, and glitch textures.", "practical_application": "A producer inserts a beat repeat device on drums or a vocal, sets a note value so a slice retriggers on cue, and automates it to punch up a fill before a drop.", "category": "Rhythmic Effects", "related_terms": ["Buffer repeat", "Glitch edit", "Chopped vocal", "Gated rhythm effect", "Pitch-stutter effect"], "common_mistakes": ["Setting repeat rates off the tempo grid so the stutters clash with the beat.", "Applying it across a whole part instead of automating short bursts, which becomes tiring to hear.", "Not controlling the level, so loud repeats overload the mix bus."], "scenario_contexts": ["Building a drum fill that stutters just before a chorus drop.", "Adding glitch repeats to a vocal ad-lib in an electronic track.", "Creating a rhythmic riser from a sustained synth by retriggering slices."]}, "258d2da6-c430-4b84-abd4-722aa4f9ebcc": {"definition": "A glitch effect that continuously records incoming audio into a short memory buffer and replays a captured segment as a loop, retriggering it at rhythmic intervals to create stutter and roll artifacts. Because the buffer holds whatever audio was last present rather than a fixed sample, the repeated fragment changes with the performance.", "plain_english": "This effect keeps a very short recording of the sound in memory and plays that snippet over and over. It is like holding down a copy button so the last moment of audio keeps looping.", "purpose_function": "It lets a technician freeze and repeat a live slice of audio for stutter and glitch effects without pre-slicing the file, keeping the repeats tied to what just played.", "practical_application": "A producer places a buffer effect on a channel and triggers it during playback so the last fraction of a second loops, then releases it to return to normal audio.", "category": "Glitch Effects", "related_terms": ["Beat repeat", "Glitch edit", "Creative resampling", "Pitch-stutter effect", "Chopped vocal"], "common_mistakes": ["Confusing it with a delay; the buffer loops a captured slice rather than echoing the signal.", "Using long buffer lengths that blur the rhythmic effect.", "Leaving it engaged too long so the loop becomes monotonous."], "scenario_contexts": ["Freezing a vocal word into a stutter loop for a breakdown.", "Adding glitch rolls to a drum loop in real time.", "Creating a tension build by looping the tail of a synth chord."]}, "f0fed69f-2caa-4675-871c-650709ea8e95": {"definition": "A vocal recording that has been sliced into short segments and rearranged, retriggered, or gated to create new rhythmic or melodic phrases from the original take. The technique may reorder syllables, repeat fragments, or trigger slices from a sampler or MIDI pattern.", "plain_english": "A chopped vocal is a sung part cut into little pieces that are then rearranged or replayed in a new order. It is like cutting up a sentence and taping the words back in a different pattern.", "purpose_function": "It turns an ordinary vocal take into a rhythmic or hook-like element, adding movement and originality without needing a new performance.", "practical_application": "A producer slices a vocal phrase at transient points, maps the slices to a sampler or clips, and retriggers them in a pattern to build a chopped hook.", "category": "Vocal Processing", "related_terms": ["Beat repeat", "Glitch edit", "Creative resampling", "Formant-shifted vocal", "Pitch-stutter effect"], "common_mistakes": ["Cutting slices away from zero crossings or transients, which causes clicks.", "Chopping so heavily that the lyric becomes unintelligible when it should stay clear.", "Forgetting to crossfade edits, which leaves audible gaps."], "scenario_contexts": ["Building a stuttered vocal hook in a pop or EDM track.", "Rearranging a sampled phrase into a new rhythmic line.", "Creating a call-and-response effect from a single vocal take."]}, "58198997-1fb2-4936-9c9b-fe10bd4a92bd": {"definition": "The technique of bouncing or rendering already-processed audio to a new file and then treating that file as fresh source material for further slicing, pitching, and effects. Resampling captures the combined result of prior processing so it can be manipulated as a single new sound.", "plain_english": "Creative resampling means recording your processed sound back into a new audio clip, then messing with that clip again. It is like taking a photo of a drawing so you can cut up and reuse the copy.", "purpose_function": "It lets a producer lock in complex processing and then reshape the result in ways that are hard to do on the live signal chain, encouraging new textures and happy accidents.", "practical_application": "A producer renders a heavily effected synth to audio, then chops, reverses, and pitches the bounce to create a new lead or texture.", "category": "Creative Processing", "related_terms": ["Chopped vocal", "Glitch edit", "Buffer repeat", "Beat repeat", "Pitch-stutter effect"], "common_mistakes": ["Resampling at too low a level and losing headroom or detail.", "Forgetting to note the tempo or key, which makes the bounce hard to reuse.", "Baking in effects too early, removing the ability to tweak them later."], "scenario_contexts": ["Bouncing a granular synth patch to audio for further chopping.", "Rendering a full drum bus to resample into a new one-shot.", "Reversing and pitching a resampled chord to make a riser."]}, "399d6fa2-2793-4f5f-9eb9-6a9e880ee218": {"definition": "A creative effect in which the audio is briefly and deliberately silenced or heavily reduced, then restored, creating a momentary gap or cut in the mix. It may be produced by muting, gating, volume automation, or by emulating tape and signal dropouts.", "plain_english": "A dropout effect is when the sound suddenly cuts out for a moment and then comes back. It is like someone briefly pressing mute to leave a hole in the music.", "purpose_function": "It creates surprise, tension, or emphasis by removing sound where the ear expects it, making the return of the audio feel stronger.", "practical_application": "An engineer automates a short mute or gate on a stem or the master so the track drops to silence for a beat before the chorus lands.", "category": "Creative Processing", "related_terms": ["Gated rhythm effect", "Glitch edit", "Beat repeat", "Chopped vocal", "Buffer repeat"], "common_mistakes": ["Cutting the audio without a fast fade, which causes a click at the edit.", "Making the drop too long so the energy of the track stalls.", "Dropping out the wrong element so the groove loses its anchor."], "scenario_contexts": ["Silencing the mix for one beat right before a drop.", "Adding rhythmic gaps to a synth to imply a stutter.", "Emulating a tape dropout for a lo-fi, worn feel."]}, "ec248c1c-f76f-45e1-bf79-2aa3ceede6a8": {"definition": "A vocal processed to move its formant frequencies, the resonant peaks of the vocal tract, up or down independently of pitch, altering the perceived size and character of the voice without changing the notes sung. Raising formants suggests a smaller, brighter voice, while lowering them suggests a larger, darker one.", "plain_english": "A formant-shifted vocal has its tone colour changed so the singer sounds smaller or bigger, without changing the actual notes. It is like making a voice sound cartoonish or monstrous while it still sings the same tune.", "purpose_function": "It reshapes vocal character for creative effect or disguise, letting one singer sound like a different person or adding harmony layers with contrasting timbres.", "practical_application": "A producer uses a pitch and formant tool to shift only the formants of a doubled vocal, creating a chipmunk or deep-voice layer that sits under the lead.", "category": "Vocal Processing", "related_terms": ["Chopped vocal", "Pitch-stutter effect", "Creative resampling", "Glitch edit", "Gated rhythm effect"], "common_mistakes": ["Confusing formant shift with pitch shift; formant shift changes the tone, not the note.", "Shifting formants too far, making the vocal sound unnatural when a subtle change was wanted.", "Applying it to a poorly recorded take, which exaggerates artifacts."], "scenario_contexts": ["Creating a deep or high alter-ego voice for a rap or hook.", "Blending doubled vocals with different formant characters.", "Disguising a voice for a creative or anonymity effect."]}, "8d7c9ac1-dc7c-4f43-94ad-c02942f69e36": {"definition": "A rhythmic effect created by using a noise gate, often driven by a repeating pattern, LFO, or sidechain key, to open and close a sustained sound in time with the tempo, chopping it into pulses. The classic trance gate cuts a held synth chord or pad into a staccato rhythmic pattern.", "plain_english": "A gated rhythm effect uses a gate to switch a steady sound on and off quickly in time with the beat. It is like flicking a light switch fast so a long note turns into a chopped, pulsing pattern.", "purpose_function": "It adds rhythm and motion to sustained pads, chords, or noise, turning a static sound into a driving pattern that locks to the groove.", "practical_application": "A producer routes a pad through a gate sequencer and draws a step pattern, so the pad pulses in eighth or sixteenth notes under the track.", "category": "Rhythmic Effects", "related_terms": ["Beat repeat", "Dropout effect", "Glitch edit", "Buffer repeat", "Pitch-stutter effect"], "common_mistakes": ["Setting attack and release too slow, which blurs the rhythmic edges.", "Not syncing the gate to tempo, so the pattern drifts against the beat.", "Gating a sound with no sustain, which leaves little for the gate to shape."], "scenario_contexts": ["Turning a held synth chord into a trance-gate pattern.", "Pulsing a pad in time with the hi-hats.", "Chopping a noise sweep into rhythmic bursts for a build."]}, "edec8899-f1fa-4cf0-bf36-ead49aab19dd": {"definition": "An editing technique that deliberately introduces digital artifacts, such as stutters, buffer repeats, clicks, pitch jumps, and hard cuts, as an aesthetic element, often on drums, vocals, or synths. It can be performed by hand-editing on the timeline or with dedicated glitch and multi-effect plug-ins.", "plain_english": "A glitch edit adds broken, stuttery digital sounds on purpose, like errors you would normally avoid. It is like making the music sound as if it is skipping or breaking up as a style.", "purpose_function": "It brings energy, surprise, and a modern electronic character to a part, and is used for fills, transitions, and ear-catching detail.", "practical_application": "An editor slices a drum loop and applies repeats, reverses, and hard cuts across a bar, or drops a glitch plug-in on the bus to generate randomized artifacts.", "category": "Glitch Effects", "related_terms": ["Beat repeat", "Buffer repeat", "Chopped vocal", "Pitch-stutter effect", "Creative resampling"], "common_mistakes": ["Overusing glitches so they distract from the song rather than support it.", "Not controlling levels, so glitch bursts spike louder than the mix.", "Placing edits off the grid so they fight the groove."], "scenario_contexts": ["Adding a glitchy fill in the last bar before a chorus.", "Breaking up a repeated section so it stays interesting.", "Creating an IDM-style stutter pattern on a vocal chop."]}, "5a959668-2151-4b33-bc4f-8281be550e32": {"definition": "A stutter effect in which each repeated slice of audio is played back at a different pitch, combining rapid retriggering with pitch changes to create melodic or rising and falling stutter patterns. Stutter and multi-effect plug-ins let the pitch step, glide, or randomize across the repeats.", "plain_english": "A pitch-stutter effect repeats a tiny piece of sound very fast while also changing its pitch each time. It is like a fast stutter that also climbs or jumps up and down in notes.", "purpose_function": "It turns a simple repeat into a musical gesture, adding melodic movement and excitement to fills and transitions.", "practical_application": "A producer triggers a stutter effect on a vocal or synth and sets the pitch to rise across the repeats, building a glitchy riser into a drop.", "category": "Glitch Effects", "related_terms": ["Beat repeat", "Buffer repeat", "Glitch edit", "Chopped vocal", "Formant-shifted vocal"], "common_mistakes": ["Confusing pitch stutter with a plain stutter; here the pitch changes on each repeat.", "Letting pitched repeats clash with the song's key.", "Overlong stutters that lose rhythmic tightness."], "scenario_contexts": ["Building a pitched-up stutter riser before a drop.", "Adding a melodic glitch to a vocal chop.", "Creating an arpeggio-like stutter from a single synth note."]}, "991ee0ea-94fd-4d2f-87d6-bc36ef484013": {"definition": "An edit in which a short segment of audio is copied and played back several times in immediate succession, producing a rhythmic repetition or roll. It is commonly applied to a single beat, syllable, or transient to build fills, build-ups, or glitch patterns from existing material.", "plain_english": "You take a tiny piece of sound and play it over and over, fast. It is like a skipping record that repeats one beat to make a cool roll.", "purpose_function": "It adds rhythmic movement and energy to a part without recording anything new, letting an engineer build fills, transitions, and glitch textures from audio that is already there.", "practical_application": "In a DAW an engineer chops a drum hit or vocal word, then duplicates it across a bar to create a stutter roll that leads into a chorus.", "category": "Creative Editing", "related_terms": ["Stutter edit", "Slice rearrangement", "Time-stutter effect", "Rhythmic mute", "Reverse edit"], "common_mistakes": ["Repeating a segment that is not trimmed to a zero crossing, causing clicks between repeats.", "Setting the repeat length off the tempo grid so the roll sounds out of time.", "Overusing repeats until they lose impact and clutter the mix."], "scenario_contexts": ["Building a drum roll into a chorus by repeating the last snare hit.", "Creating a glitch fill from a single vocal syllable.", "Filling a gap in an arrangement with a repeated synth stab."]}, "16c49089-3757-4c4f-b515-2fd9217f307d": {"definition": "An edit in which a segment of audio is played backwards, reversing its waveform in time so that a natural decay becomes a rising swell. It is commonly applied to cymbals, reverb tails, vocals, or whole phrases for creative effect.", "plain_english": "You flip a piece of sound so it plays backwards. A cymbal crash then turns into a sound that grows louder and rushes up to the next beat.", "purpose_function": "Reversing audio creates a rising, anticipatory sound that draws the ear toward the next event, adding surprise and motion that forward audio cannot give.", "practical_application": "An engineer reverses a cymbal or a snare's reverb tail so it swells up into the downbeat of a new section.", "category": "Creative Editing", "related_terms": ["Reverse transition", "Repeat edit", "Slice rearrangement", "Tape-stop effect", "Stutter edit"], "common_mistakes": ["Forgetting to render or bounce the reversed clip so playback reverts to normal audio.", "Not aligning the swell's peak with the downbeat, so the build lands early or late.", "Reversing a clip with a hard start that creates an abrupt click."], "scenario_contexts": ["Reversing a cymbal to lead into a chorus.", "Flipping a vocal phrase for an intro texture.", "Reversing a reverb tail to create a rising swell before a drop."]}, "4fcd5720-387f-411c-8639-957c8cd17cd8": {"definition": "A transition technique that uses reversed audio, such as a reversed cymbal, reverb swell, or synth, to lead from one section of a song into the next, building anticipation as the reversed sound rises toward the downbeat.", "plain_english": "This uses a backwards sound to join two parts of a song. The backwards sound gets louder and pulls you into the next part, like a run-up before a jump.", "purpose_function": "It signals and smooths the move between sections, giving the listener a rising cue that a change is coming and making the arrival feel bigger.", "practical_application": "Before a chorus or drop, an engineer places a reversed cymbal or reverse-reverb swell that crescendos into the first beat of the new section.", "category": "Transition Effects", "related_terms": ["Reverse edit", "Tape-stop effect", "Repeat edit", "Riser", "Stutter edit"], "common_mistakes": ["Letting the swell peak before the downbeat so the transition loses its punch.", "Making the reversed element too loud so it buries the following section.", "Using a reversed sound whose length does not match the bar, throwing off the timing."], "scenario_contexts": ["Leading into a chorus with a reversed cymbal swell.", "Building tension before an electronic-dance drop.", "Bridging a verse and a breakdown with a reverse-reverb rise."]}, "0968ccf7-879e-4ba2-b42a-0fca56f6235d": {"definition": "The rhythmic muting and unmuting of a track or group in time with the tempo, creating gaps that chop a sustained sound into a pattern. It can be performed by automating a mute, drawing volume steps, or using a tempo-synced gate.", "plain_english": "You quickly turn a sound off and on in time with the beat. A held pad then becomes a chopped, pulsing pattern, like flicking a light switch to the music.", "purpose_function": "It turns a static or sustained part into a rhythmic element, adding groove and movement and helping a busy section breathe.", "practical_application": "An engineer automates the mute on a pad or guitar so it drops out on certain beats, creating a stuttering rhythmic pattern in sync with the drums.", "category": "Rhythmic Effects", "related_terms": ["Trance-gate effect", "Stutter edit", "Repeat edit", "Slice rearrangement", "Time-stutter effect"], "common_mistakes": ["Placing mute points off the grid so the pattern sounds sloppy.", "Muting without a short fade, causing clicks at each cut.", "Chopping so hard that the part loses its musical role."], "scenario_contexts": ["Chopping a sustained pad into an eighth-note pattern.", "Muting a vocal on off-beats for a rhythmic hook.", "Gating a guitar chord in time with the kick."]}, "b62032c5-44c2-49d8-8685-fd7b3d4bb21f": {"definition": "An editing technique in which a passage of audio is cut into smaller slices, often at transients or beat divisions, and those slices are reordered, repeated, or removed to create a new rhythmic pattern. It is a core method of breakbeat and glitch editing.", "plain_english": "You cut a loop into small pieces and put them back in a new order. It is like cutting up a sentence and rearranging the words to make a new one.", "purpose_function": "It lets an engineer build fresh grooves and fills from existing audio, changing rhythm and feel without recording a new performance.", "practical_application": "A producer slices a drum break at each hit, then drags the slices into a new order to make a unique beat or a fill.", "category": "Creative Editing", "related_terms": ["Stutter edit", "Repeat edit", "Time-stutter effect", "Reverse edit", "Rhythmic mute"], "common_mistakes": ["Cutting between transients so slices start with clicks or clipped hits.", "Not snapping slices to the grid, making the new pattern drift off time.", "Leaving gaps or overlaps between slices that create unwanted silence or flams."], "scenario_contexts": ["Rearranging a drum break into a new groove.", "Building a fill by reordering slices of a vocal chop.", "Chopping a sampled loop to fit a new tempo and pattern."]}, "2c082195-0d7e-40cc-8109-54004c560a99": {"definition": "An edit that rapidly repeats a very short slice of audio, often with changing rate, pitch, or volume, to produce a stuttering or glitching effect. It can be performed by hand in a DAW or with dedicated plugins built for the purpose.", "plain_english": "You repeat a tiny bit of sound very fast so it seems to trip or stumble. It sounds like a word or beat getting stuck and repeating in quick bursts.", "purpose_function": "It adds a burst of rhythmic, glitchy excitement, useful for fills, build-ups, and grabbing attention at transition points.", "practical_application": "An engineer applies a stutter to the last beat before a drop, repeating a slice at a fast tempo-synced rate to create tension.", "category": "Rhythmic Effects", "related_terms": ["Repeat edit", "Time-stutter effect", "Slice rearrangement", "Trance-gate effect", "Rhythmic mute"], "common_mistakes": ["Choosing a stutter rate not synced to tempo, so it clashes with the groove.", "Repeating a slice that has a click at its edges.", "Stuttering too long so it feels gimmicky and stalls the energy."], "scenario_contexts": ["Adding a stutter fill before a chorus.", "Glitching a vocal word for a hook.", "Building tension on the final beat before a drop."]}, "26f55ec5-d78e-43d3-b558-c130a12ffe0f": {"definition": "An effect that simulates an analog tape machine or turntable being switched off, where pitch and speed drop rapidly to zero as the medium slows to a stop. It produces a characteristic downward pitch-and-tempo glide.", "plain_english": "It copies the sound of a tape or record slowing down and stopping. The pitch drops and the sound bends downward until it dies away.", "purpose_function": "It creates a dramatic stop or hand-off between sections, giving a sudden, recognizable winding-down moment that grabs attention.", "practical_application": "A producer places a tape-stop at the end of a section so the music appears to grind to a halt before the next part begins.", "category": "Transition Effects", "related_terms": ["Reverse transition", "Time-stutter effect", "Reverse edit", "Riser", "Rhythmic mute"], "common_mistakes": ["Setting the slow-down time so the stop does not land on the beat.", "Using it so often that it loses its dramatic impact.", "Forgetting that the pitch drop can clash with a sustained note underneath."], "scenario_contexts": ["Ending a section with a dramatic wind-down.", "Transitioning into a breakdown.", "Creating a DJ-style stop before a drop."]}, "bec2e464-f6f8-4d32-b42e-4f5b94b0cc4e": {"definition": "A time-based effect that repeats and re-triggers short slices of audio in rapid succession, often varying the repeat rate to create rolling or accelerating stutters. It manipulates playback timing rather than the source itself, producing glitch and roll textures.", "plain_english": "This chops a sound into fast repeats and can speed them up or slow them down. It makes a rolling, stuttering pattern, like a drum roll built from one hit.", "purpose_function": "It adds rhythmic, glitchy motion and build-up energy, letting an engineer create rolls and fills from a single sound by re-triggering it in time.", "practical_application": "An engineer uses a time-stutter on a snare or synth to create an accelerating roll that builds into a new section.", "category": "Rhythmic Effects", "related_terms": ["Stutter edit", "Repeat edit", "Slice rearrangement", "Trance-gate effect", "Rhythmic mute"], "common_mistakes": ["Leaving the repeat rate off the tempo grid so rolls feel unsteady.", "Stuttering slices that have clicky edges.", "Overusing the effect until it distracts from the song."], "scenario_contexts": ["Building an accelerating drum roll into a drop.", "Adding a glitch fill on a synth stab.", "Creating tension in a breakdown with re-triggered slices."]}, "d10ad1ed-ad93-45c2-9cd5-d172249056cf": {"definition": "A rhythmic effect in which a tempo-synced gate or amplitude modulation rapidly opens and closes on a sustained sound, chopping it into a pulsing pattern of on and off steps. It is typically driven by a step sequencer or LFO and is a staple of trance and electronic dance music.", "plain_english": "It quickly turns a held sound off and on in a set pattern, in time with the beat. A long pad becomes a chopping, pulsing rhythm, like a strobe light for sound.", "purpose_function": "It turns a sustained pad or chord into a rhythmic, driving element, adding energy and movement locked to the tempo.", "practical_application": "An engineer feeds a pad through a tempo-synced gate with a programmed step pattern so it pulses in time with the track.", "category": "Rhythmic Effects", "related_terms": ["Rhythmic mute", "Stutter edit", "Time-stutter effect", "Repeat edit", "Reverse transition"], "common_mistakes": ["Running the gate free rather than synced to tempo, so the pulse drifts off beat.", "Using instant open and close with no fade, causing clicks on each step.", "Gating a part with little sustain, so the effect is barely audible."], "scenario_contexts": ["Turning a pad into a rhythmic pulse in a trance track.", "Adding movement to a sustained chord in a breakdown.", "Creating a pumping synth rhythm synced to the tempo."]}, "5715f143-8a4b-456c-a283-050a4a20efe6": {"definition": "A transition effect that emulates a vinyl record or turntable being abruptly braked to a standstill, produced by rapidly sweeping the playback speed, and therefore the pitch, of audio down to zero over a short time. It is typically applied to a full mix or a single element at the end of a phrase or before a drop.", "plain_english": "It makes a sound slow down and drop in pitch, like a record player switched off while the record is still spinning. Producers use it to end a section with a dramatic wind-down.", "purpose_function": "It provides a dramatic, instantly recognisable transition or ending gesture that signals the close of a phrase or section by mimicking a turntable losing power. This adds energy and a sense of release without changing the arrangement itself.", "practical_application": "A technician automates a tape/vinyl-stop plugin or draws a downward pitch or varispeed automation curve on a track or the master bus, timed to hit on the last beat before a breakdown or drop.", "category": "Transition Effect", "related_terms": ["Tape-stop effect", "Varispeed", "Pitch automation", "Riser", "Filter sweep", "Automation"], "common_mistakes": ["Confusing it with a true tape-stop, which follows a different slow-down curve than a spinning platter losing momentum", "Making the effect too long so the wind-down drags and loses impact", "Not lining the effect up to the beat grid, so the return into the next section feels loose"], "scenario_contexts": ["Ending an EDM section right before a drop or breakdown", "Closing out the final bar of a track for a dramatic finish", "Emulating a DJ-style turntable brake inside a DAW mix"]}, "513e6c25-ac92-470f-b30d-6f33b0939362": {"definition": "A production technique in which a vocal recording is sliced into short fragments that are rearranged, re-pitched and re-triggered, often mapped across a sampler and played melodically, to create a rhythmic or melodic hook. The result is a new phrase built from pieces of the original performance.", "plain_english": "It is when you cut a singing recording into tiny pieces. You rearrange the pieces like blocks to build a new catchy, rhythmic tune.", "purpose_function": "It turns an existing vocal recording into a playable instrument or hook, letting a producer add a human-sounding melodic element without recording a new performance. This gives a track a distinctive, memorable motif.", "practical_application": "A technician slices a vocal in a sampler or DAW, maps the slices across a keyboard or pad grid, then plays a fresh melodic or rhythmic pattern, often adding pitch and formant correction to keep it natural.", "category": "Sampling Technique", "related_terms": ["Sampler", "Time-stretching", "Formant shift", "Warping", "Granular synthesis", "Rhythmic gating"], "common_mistakes": ["Leaving clicks or pops at slice edit points instead of adding short fades or crossfades", "Re-pitching slices far up or down without formant control, giving an unnatural chipmunk sound", "Reusing a copyrighted vocal without clearing sample rights"], "scenario_contexts": ["Building a melodic hook for a future bass, pop or EDM track", "Turning a full vocal take into a rhythmic stutter pattern", "Creating a new topline for a remix from an acapella"]}, "ce04d3aa-caf8-40fe-842c-3b62f5b06ca8": {"definition": "A 5.1-channel version of an immersive (object-based) master produced by the renderer, which folds the objects and beds of the immersive mix down into the six channels of the standard 5.1 layout (L, C, R, Ls, Rs, LFE). It is one of several channel-based re-renders derived from a single ADM/immersive master.", "plain_english": "A 5.1 surround copy made from an Atmos mix. The tool takes the moving sounds and fits them into six speakers. That way, people without Atmos still get surround sound.", "purpose_function": "It lets one immersive master serve older 5.1 delivery targets such as broadcast, Blu-ray and streaming without a separate manual mix, keeping every format matched to the immersive source.", "practical_application": "In the Dolby Atmos Renderer a mastering engineer selects the 5.1 re-render output, then checks its balance, dialogue level and LFE before delivering it alongside the ADM master.", "category": "Immersive Deliverable", "related_terms": ["7.1 re-render", "ADM BWF master", "Binaural render", "Downmix", "Bed (immersive audio)", "Dolby Atmos Renderer"], "common_mistakes": ["Assuming the 5.1 re-render sounds identical to the immersive mix, when overhead objects collapse down into the surround plane.", "Not re-checking dialogue and LFE level after re-rendering, so the fold-down clips or the center is too quiet.", "Delivering the re-render at the wrong loudness or bit depth for the target platform."], "scenario_contexts": ["Creating a 5.1 broadcast deliverable from a Dolby Atmos music or film master.", "Producing a surround version for Blu-ray from an object-based master.", "QC-ing a batch of re-renders against the immersive reference before delivery."]}, "c9561968-f295-4279-a42e-e833c494372c": {"definition": "A 7.1-channel version of an immersive (object-based) master produced by the renderer, which folds the objects and beds of the immersive mix down into the eight channels of the 7.1 layout (L, C, R, Lss, Rss, Lrs, Rrs, LFE). It is one of several channel-based re-renders derived from a single ADM/immersive master.", "plain_english": "A 7.1 surround copy made from an Atmos mix. It spreads the sounds across eight speaker feeds instead of six. This gives more speakers around the room than a 5.1 copy.", "purpose_function": "It provides a 7.1-compatible deliverable from the immersive master for cinema and home-theater targets that use side and rear surrounds, without remixing the program.", "practical_application": "A mastering engineer generates the 7.1 re-render in the renderer, confirms the surround channel mapping is correct, and delivers it with the ADM master and other re-renders.", "category": "Immersive Deliverable", "related_terms": ["5.1 re-render", "ADM BWF master", "Binaural render", "Downmix", "Bed (immersive audio)", "Dolby Atmos Renderer"], "common_mistakes": ["Confusing the 7.1 surround channel order with the 7.1.2/7.1.4 bed order, so channels are mislabeled.", "Assuming height information survives, when a 7.1 re-render has no dedicated overhead speakers.", "Skipping a level and balance check after the fold-down."], "scenario_contexts": ["Delivering a 7.1 home-theater version from a Dolby Atmos master.", "Supplying a 7.1 cinema-compatible fold from an object-based mix.", "Comparing 5.1 and 7.1 re-renders against the immersive reference during QC."]}, "d91ec217-3903-4b5b-b682-91a76ff79919": {"definition": "The cellulose acetate film substrate used as the flexible backing of magnetic recording tape from the mid-1930s until the early 1970s, onto which the magnetic oxide coating was bound. It was progressively replaced by more stable polyester (PET) base, and is prone to embrittlement and hydrolysis (vinegar syndrome) with age.", "plain_english": "The clear plastic backing that older recording tape was built on. It holds the coating that stores the sound. Over time it turns brittle and can smell like vinegar.", "purpose_function": "The base carries the fragile magnetic coating on a flexible, stable carrier so tape can be wound, run past the heads and stored; identifying the base type tells an archivist how a reel will age and how to handle it.", "practical_application": "When transferring old reels, a technician spots acetate base (it is translucent when held to light and may smell of vinegar) and handles it gently, because it can snap under normal playback tension.", "category": "Archive & Preservation", "related_terms": ["Polyester tape base", "Vinegar syndrome", "Magnetic tape", "Print-through", "Oxide shedding", "Archive media migration"], "common_mistakes": ["Confusing brittle acetate with polyester base, when acetate snaps cleanly and polyester stretches and distorts.", "Applying higher tension to a brittle acetate reel to improve head contact, which breaks it.", "Storing acetate tapes in warm, humid conditions, which speeds up vinegar syndrome (hydrolysis)."], "scenario_contexts": ["Assessing an old reel-to-reel master before digital transfer.", "Identifying vinegar syndrome by smell and warping in an archive.", "Prioritising fragile acetate holdings for urgent migration."]}, "e2ea50a7-2b16-4780-aa06-242ae0e281d8": {"definition": "A Broadcast Wave Format (BWF) file that carries Audio Definition Model (ADM) metadata, per ITU-R BS.2076 and EBU Tech 3364, describing the channels, objects and their spatial positions of an immersive mix. It serves as the open, self-contained interchange master for object-based programs such as Dolby Atmos.", "plain_english": "One file that holds an Atmos mix plus a map of where each sound sits in 3D space. It is the master copy studios hand off. Any system can use it to rebuild the mix the right way.", "purpose_function": "It bundles all audio and spatial metadata into one open, standardized file, so an immersive master can be delivered, archived and re-rendered without a proprietary session.", "practical_application": "A mastering engineer exports the ADM BWF from the renderer or DAW as the primary immersive deliverable, then generates channel re-renders and a stereo master from it.", "category": "Immersive Deliverable", "related_terms": ["ADM validation", "5.1 re-render", "7.1 re-render", "Audio Definition Model", "Broadcast Wave Format", "Dolby Atmos Renderer"], "common_mistakes": ["Treating the ADM BWF as an ordinary WAV and stripping its metadata chunk during editing or conversion.", "Delivering at the wrong sample rate or bit depth, when immersive masters are typically 48 kHz / 24-bit.", "Assuming any player reads it, when non-ADM software ignores the object metadata and plays only the raw audio."], "scenario_contexts": ["Delivering a Dolby Atmos music master to a distributor.", "Archiving an object-based film mix as a single interchange file.", "Importing an ADM BWF into a renderer to generate re-renders."]}, "cfd30a85-39df-4fe6-87cd-f720e8a4b7d7": {"definition": "The process of checking that an ADM BWF file conforms to the Audio Definition Model specification (ITU-R BS.2076 / EBU Tech 3364) and to any required delivery profile, such as the Dolby Atmos ADM profile. It verifies that the XML metadata is well-formed and complete, that references resolve, and that channel/object counts, layout and sample rate meet requirements.", "plain_english": "A check that makes sure an Atmos master file is built by the rules before you send it. It is like a spell-check for the file's sound map. It catches missing or mislabeled parts early.", "purpose_function": "It catches metadata errors before delivery, so a distributor or broadcaster does not reject the master or play it back incorrectly.", "practical_application": "Before delivery, an engineer runs the file through an ADM validator, such as the EBU tool or a distributor's QC check, and fixes any flagged metadata or profile violations.", "category": "Immersive Deliverable", "related_terms": ["ADM BWF master", "Audio Definition Model", "Broadcast Wave Format", "Dolby Atmos Renderer", "Loudness metering", "Quality control (QC)"], "common_mistakes": ["Confirming only that the file plays, and skipping metadata validation entirely.", "Validating against the generic ADM spec but not the stricter delivery profile the distributor requires.", "Ignoring warnings about unresolved object references or mismatched channel counts."], "scenario_contexts": ["QC-ing an ADM BWF before uploading to a streaming distributor.", "Debugging why a delivered Atmos file was rejected.", "Confirming a renderer export meets the Dolby Atmos ADM profile."]}, "ce10ccd4-9bf4-4b83-a593-be24e90092cc": {"definition": "A version of a program's final soundtrack in which the musical score is substituted or re-balanced while the dialogue and sound effects stay the same, produced as a deliverable when a title needs different music for a territory, edit or rights reason.", "plain_english": "A second version of a finished soundtrack that uses different music. It keeps the same speech and sound effects. Studios make it when a show needs new music for another country or a re-edit.", "purpose_function": "It lets the same picture ship with different music without remixing the whole soundtrack, covering rights, regional or creative needs.", "practical_application": "In post, a re-recording mixer swaps the score stem into the final mix, then re-checks balance and loudness before delivering the alternate version.", "category": "Mix Deliverable", "related_terms": ["M&E mix", "Music stem", "Dialogue stem", "Final mix", "Stem (mixing)", "Deliverables"], "common_mistakes": ["Confusing the alternate score mix with an M&E (music-and-effects) mix, which removes dialogue.", "Forgetting to re-check loudness and balance after swapping the score.", "Delivering the alternate without matching the technical specs of the original mix."], "scenario_contexts": ["Preparing a version with replacement music for a foreign territory.", "Delivering a re-edited cut that needs a different score.", "Supplying a cleared-music alternate to replace a temp score."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"39999617-5626-4648-ac44-3c8a12c801c6": {"definition": "The scheduled transfer of archived audio content from one storage medium or format to a newer one (for example from one LTO tape generation to the next, or from aging analog tape to file-based storage) to prevent loss from media degradation and from hardware or format obsolescence.", "plain_english": "Copying stored recordings onto newer media before the old media wears out. It is like moving photos off old floppy disks onto a new drive. You do it so the files are never lost.", "purpose_function": "It keeps preserved audio accessible over decades by staying ahead of media decay and the obsolescence of the drives and formats needed to read it.", "practical_application": "An archivist migrates data every few years, for example off an older LTO generation whose drives are no longer sold, and verifies checksums so nothing is corrupted in the copy.", "category": "Archive & Preservation", "related_terms": ["Archive storage container", "Archive retrieval system", "Checksum", "LTO (Linear Tape-Open)", "Format obsolescence", "Acetate tape base"], "common_mistakes": ["Waiting until drives are already obsolete or the media has degraded before migrating.", "Migrating without verifying checksums, so silent data corruption is copied forward.", "Keeping only one copy after migration instead of multiple, geographically separate copies."], "scenario_contexts": ["Moving a master library from an older LTO generation to a current one.", "Transferring aging analog tape masters to file-based digital storage.", "Refreshing a digital archive on a fixed migration schedule."]}, "1dfd3e49-7c91-4033-ae48-24c2059487bd": {"definition": "The catalog, database and storage infrastructure, such as a media asset management system paired with an LTO tape library or nearline storage, used to locate, request and restore archived audio masters and their metadata on demand.", "plain_english": "The system an archive uses to find and pull back a stored recording. It works like a library catalog joined to the shelves. You look up a title and the system fetches it.", "purpose_function": "It makes a large archive usable by letting staff search metadata and restore the exact master they need, instead of hunting manually through shelves of media.", "practical_application": "To reissue an album, an engineer searches the retrieval system by title or ID, requests the master, and the system restores it from the tape library to online storage.", "category": "Archive & Preservation", "related_terms": ["Media asset management (MAM)", "Metadata", "Archive storage container", "Archive media migration", "LTO (Linear Tape-Open)", "Nearline storage"], "common_mistakes": ["Relying on filenames alone instead of proper catalog metadata, so assets become unfindable.", "Not testing restores, so a needed master turns out to be unreadable when finally requested.", "Failing to update the catalog when media is migrated or physically moved."], "scenario_contexts": ["Recalling an original master for a remaster or reissue.", "Pulling archived stems for a sync licensing request.", "Auditing which titles are stored on which media."]}, "b51728fe-c0d4-4415-9491-5064843f3431": {"definition": "A standardized file container (wrapper) format used to bundle archived audio essence with its metadata for long-term preservation, for example Broadcast Wave (BWF) for audio-only or MXF for wrapped audio with video. Open, well-documented containers are chosen so the content stays readable across technology cycles.", "plain_english": "A file format that wraps a recording together with its notes in one package. Think of it as a labeled box holding both the sound and its paperwork. That keeps them from getting split up.", "purpose_function": "It keeps the audio and its metadata together in one open, documented file, so archived content stays intact and readable when systems and software change.", "practical_application": "When archiving a master, a technician wraps the audio as a BWF (or MXF for audio-with-picture) so future users can open it and read its embedded metadata without proprietary tools.", "category": "Archive & Preservation", "related_terms": ["Broadcast Wave Format", "MXF (Material Exchange Format)", "Wrapper format", "Metadata", "Archive media migration", "Archive retrieval system"], "common_mistakes": ["Choosing a proprietary or poorly documented container that may become unreadable later.", "Confusing the container (wrapper) with the codec, when the container holds the audio and the codec encodes it.", "Storing metadata in a separate file that gets lost from the audio during migration."], "scenario_contexts": ["Wrapping a preservation master as BWF for deposit in an archive.", "Choosing MXF to archive an audio-with-picture program.", "Keeping embedded metadata with the essence during a format migration."]}, "bd15ea07-6678-4e70-8723-cab0bfb62ce8": {"definition": "The final creative and technical stage of audio production, in which a completed mix is prepared and transferred to a master used for reproduction. Mastering optimizes overall level, tonal balance, and dynamics, ensures consistency across a program such as an album, and encodes format-specific delivery data before duplication or streaming.", "plain_english": "Mastering is the last step in making a record. An engineer takes the finished mix and polishes its volume, tone, and balance. This makes every song sound clear and even on any speaker or set of headphones. It is like the final coat of polish before the music goes out to the world.", "purpose_function": "It gives a release a consistent, competitive sound that translates well across all playback systems, and produces a technically correct master for each delivery format. It exists to bridge the gap between an approved mix and the many formats listeners actually use.", "practical_application": "A mastering engineer loads the stereo mix onto a calibrated system, adjusts EQ, compression, and limiting, matches loudness and tone between tracks, and exports masters that meet each distributor's specifications. They also handle track spacing, fades, and embedded codes for the final release.", "category": "Mastering process", "related_terms": ["Mixing", "Stem mastering", "Loudness normalization", "Brickwall limiter", "Dithering", "DDP image"], "common_mistakes": ["Treating mastering as a way to fix a flawed mix instead of returning to correct the problems in the mix itself", "Pushing loudness so hard with the limiter that the master becomes distorted and lifeless", "Making tonal decisions while monitoring too loud or on an uncalibrated system"], "scenario_contexts": ["Preparing an album so all tracks share consistent loudness and tone before release", "Creating format-specific masters for streaming, CD, and vinyl from one approved mix", "Matching a new single to the tonal character of earlier tracks in a catalog"]}, "4947ee9c-f842-47dd-af0b-af70fd34290a": {"definition": "Magnetic recording tape that carries a thin, nonmagnetic layer of conductive carbon black on the reverse side of the base film, opposite the oxide coating. The back coat reduces static charge buildup, improves frictional behavior, and produces a smoother, more even tape pack during winding.", "plain_english": "Back-coated tape is reel-to-reel tape with a dull, dark layer on its back side. This coating cuts down on static and helps the tape wind smoothly and evenly. Think of it like a non-slip backing that keeps the tape roll neat and clean.", "purpose_function": "The back coat exists to control static and dust, steady tape tension and handling, and prevent winding faults such as cinching, uneven stacking, and edge damage. This helps keep the recorded signal clean and the reel physically stable over time.", "practical_application": "A technician restoring or transferring older recordings identifies back-coated stock by its matte back side and watches for formulations prone to sticky-shed syndrome, which may need baking before a safe playback transfer.", "category": "Analog tape media", "related_terms": ["Analog tape recording", "Tape bias", "Sticky-shed syndrome", "Reel-to-reel", "Tape baking"], "common_mistakes": ["Assuming all back-coated tape is high quality, when some binder formulations suffer sticky-shed and must be baked before playback", "Confusing the matte back coat with the glossy oxide side and threading the tape so the wrong side faces the heads"], "scenario_contexts": ["Restoring archival multitrack recordings originally captured on back-coated tape", "Selecting tape stock for an analog session where smooth winding and low static matter"]}, "134ce59c-58c6-4bd3-93b6-6f3a83479d76": {"definition": "In immersive audio masters such as Dolby Atmos, the set of metadata that describes the channel-based bed, the foundation of sounds anchored to fixed loudspeaker positions rather than to moving objects. It records the bed's speaker-layout assignment and channel configuration so a renderer can reproduce the bed correctly across different playback systems.", "plain_english": "In surround and Dolby Atmos sound, the bed is the layer tied to fixed speaker spots. Its metadata package is the bundle of notes that says what that layer is and where its channels belong. It is like a label on a box that lists what is inside and where each part goes.", "purpose_function": "It lets an immersive master carry a stable, speaker-anchored foundation alongside the moving objects, so playback systems know how to route and reproduce the bed. This keeps the core surround field consistent while objects move around it.", "practical_application": "When exporting an Atmos master, an engineer confirms the bed configuration, such as 7.1.2, is written correctly so the bed and its metadata travel with the object audio into the ADM BWF or Dolby Atmos master file.", "category": "Immersive metadata", "related_terms": ["Dolby Atmos", "Audio object", "ADM BWF", "Binaural metadata", "Immersive master"], "common_mistakes": ["Confusing the bed with objects; the bed is fixed to speaker positions and does not carry per-object positional trajectories", "Assuming the bed metadata alone is enough, when the objects and their metadata must also be exported for a complete immersive master"], "scenario_contexts": ["Exporting a Dolby Atmos master where the 7.1.2 bed and its metadata accompany the objects", "Troubleshooting an immersive deliverable that plays back with the wrong speaker layout"]}, "4a05b055-7006-4736-aec2-e822d8c52acb": {"definition": "Metadata carried in an immersive master, notably Dolby Atmos, that assigns each object or bed a binaural render mode, Off, Near, Mid, or Far. These settings tell the binaural renderer how much distance and space to apply to each element when the mix is folded down to two-channel headphone playback.", "plain_english": "Binaural metadata is a small set of instructions saved with an Atmos mix. It tells the headphone rendering how near or far each sound should feel. Think of it as a note that says make this sound close or make this one far away when you listen on headphones.", "purpose_function": "It exists so the mixer can control the sense of depth and space heard on headphones without changing the loudspeaker mix. This gives immersive releases a convincing 3D feel for the large audience listening on earbuds and headphones.", "practical_application": "In the Dolby Atmos renderer, an engineer assigns near, mid, or far to objects to shape headphone depth, then verifies these settings are saved in the master before it is delivered to a streaming service.", "category": "Immersive metadata", "related_terms": ["Binaural render mode", "Binaural re-render", "Dolby Atmos", "Audio object", "Spatial audio"], "common_mistakes": ["Thinking the binaural render settings change the speaker mix, when they only affect the headphone render", "Leaving every element on the same near, mid, or far setting, which flattens the sense of depth on headphones"], "scenario_contexts": ["Setting objects to near, mid, or far so an Atmos mix has depth on headphones", "Confirming binaural render settings are saved in the master before delivery to a streaming service"]}, "78add2c2-73cb-45ad-b92c-8e3c78481cf7": {"definition": "A two-channel headphone version produced from an immersive mix by processing it through head-related transfer functions so surround and height cues are simulated over ordinary stereo headphones. The re-render honors the binaural render-mode metadata assigned to each object and bed in the master.", "plain_english": "A binaural re-render turns a surround or Atmos mix into a normal two-channel headphone mix. It uses facts about how our ears hear direction to fake a 3D space over plain headphones. It is how one immersive mix can still sound wide and deep in your earbuds.", "purpose_function": "It exists to deliver the immersive experience to the huge audience listening on headphones, where real surround and height speakers are not available. It also lets engineers audition how headphone listeners will hear the immersive mix.", "practical_application": "An engineer auditions the binaural re-render in the Dolby Atmos renderer to check headphone translation, and may deliver a binaural stereo file alongside the immersive master for headphone-based streaming.", "category": "Immersive rendering", "related_terms": ["Binaural metadata", "Dolby Atmos", "HRTF", "Spatial audio", "Downmix"], "common_mistakes": ["Assuming the binaural re-render will sound identical to the speaker mix, when HRTF processing changes timbre and space", "Judging the whole immersive mix only by the binaural re-render instead of monitoring on the full speaker system"], "scenario_contexts": ["Auditioning how an Atmos mix will sound to headphone listeners on a streaming service", "Delivering a binaural stereo version alongside the immersive master"]}, "28b7d29e-9329-4f27-8643-fc5a1aaf1f8c": {"definition": "The measurement of Block Error Rate on a Compact Disc, defined as the number of erroneous data blocks per second entering the C1 stage of the CIRC error-correction decoder, averaged over a period such as ten seconds. The Red Book specification sets a maximum average BLER of 220 per second for a conforming disc.", "plain_english": "BLER measurement counts how many small data errors show up on a CD each second as it plays. A low count means the disc was made well and should play reliably. It is like checking a printed page for smudges before you send it off to be copied.", "purpose_function": "It gives a quantitative check of manufacturing and burn quality so a disc can be judged fit for replication or archiving. Keeping BLER low leaves error correction with enough headroom to hide the remaining errors during playback.", "practical_application": "A technician runs error analysis on a glass master or reference CD-R with a suitable drive and software, checking BLER along with E22 and E32 error counts before approving a disc for replication.", "category": "Disc quality control", "related_terms": ["Red Book", "CIRC error correction", "C1/C2 errors", "DDP image", "Glass master"], "common_mistakes": ["Believing a low BLER guarantees a perfect disc, when uncorrectable E32 or CU errors matter more for playback failures", "Skipping error analysis on a burned reference disc and then sending a faulty master for replication"], "scenario_contexts": ["Running an error analysis on a glass master or reference CD-R before replication", "Assessing the condition of an archival CD to decide whether it should be re-ripped"]}, "24e4165a-d0a8-435b-ad78-d83b985ca18f": {"definition": "A mastering plugin from Brainworx, distributed by Plugin Alliance, that presents a complete analog-style mastering chain in a single interface. It combines volume and loudness metering, compression, a four-band tone stack, harmonic and stereo tools, and a true-peak limiter so a user can produce a finished master from one window.", "plain_english": "bx_masterdesk is a mastering plugin that puts a whole mastering chain in one window. You turn a few simple knobs to set loudness, tone, and balance, and it handles the rest. It is made to help people master tracks without years of training.", "purpose_function": "It exists to make competitive, loudness-aware mastering accessible to users without a full outboard chain or deep mastering expertise. It bundles the usual mastering stages into guided controls with metering that shows loudness and peak levels.", "practical_application": "A producer places bx_masterdesk on the stereo mix bus, raises the volume control to drive the chain, shapes the tone stack and compression, then sets the limiter to reach a target loudness while watching the true-peak meter.", "category": "Mastering software", "related_terms": ["Mastering chain", "Brickwall limiter", "True peak", "Loudness normalization", "Bus compression"], "common_mistakes": ["Relying on presets and loud output without checking true-peak levels and translation on other systems", "Pushing the chain for maximum loudness, which crushes dynamics and adds audible distortion"], "scenario_contexts": ["Producing a quick, competitive master of a demo without a full outboard chain", "Setting a loudness and true-peak target for a self-released single"]}, "8ab7ea52-6ce7-48dd-9a33-b66ef49a9d51": {"definition": "A stem containing the combined submix of all brass instruments, such as trumpets, trombones, and horns, bounced as a single mono, stereo, or multichannel file. It is delivered so the brass can be balanced or processed as one group without returning to the full multitrack session.", "plain_english": "A brass stem is a single mixed track that holds all the brass instruments together, like trumpets and trombones. Keeping brass on its own stem lets an engineer change just the horns without touching the rest of the song. It is like putting all the brass players on one slider.", "purpose_function": "It exists to give mastering, re-mixing, and post-production stages control over the brass section as a unit while preserving the balance made within it. Stems let sections be adjusted or re-versioned without a full remix.", "practical_application": "An engineer receives the brass stem among a set of stems, and nudges its level or tone during stem mastering or a film re-recording mix while the other stems stay untouched.", "category": "Stems", "related_terms": ["Stem mastering", "Submix", "Stem mixing", "Group bus", "Mixdown"], "common_mistakes": ["Processing the full mix when only the brass stem needed adjustment", "Delivering stems that do not sum back to the original mix because levels or effects were changed after the mix was approved"], "scenario_contexts": ["Delivering separate brass, strings, and rhythm stems for a film re-recording mix", "Stem mastering a song so the brass level can be nudged without a full remix"]}, "56666112-8a90-4bdf-b483-84e9baf282db": {"definition": "The preparation of a master that conforms to the loudness and level rules of broadcast delivery, using loudness normalization to standards such as EBU R128 and ATSC A/85 with measurement defined by ITU-R BS.1770. Targets typically include an integrated loudness such as -23 LUFS or -24 LKFS and a true-peak ceiling such as -1 dBTP.", "plain_english": "Broadcast mastering prepares a mix to meet the strict loudness and level rules used by TV and radio. It sets the volume to a fixed target so shows and ads do not jump louder or softer. It is like making sure every clip fits the same volume speed limit before it airs.", "purpose_function": "It exists to give consistent perceived loudness across programs and channels and to stop peaks from clipping after transmission encoding. This meets legal and network requirements and spares listeners jarring jumps in volume.", "practical_application": "A mastering engineer measures the program with a compliant loudness meter, normalizes it to the required integrated target, and limits true peaks below the specified ceiling before delivering the file to the broadcaster.", "category": "Mastering process", "related_terms": ["Loudness normalization", "EBU R128", "LUFS", "True peak", "Dialnorm"], "common_mistakes": ["Mastering to streaming loudness targets and assuming the file also meets broadcast specs, which differ", "Exceeding the true-peak ceiling such as -1 dBTP, which causes clipping after lossy encoding"], "scenario_contexts": ["Preparing a program master to -23 LUFS with a -1 dBTP ceiling for European broadcast", "Delivering a commercial that complies with the US CALM Act loudness rules"]}, "9e867aec-8e90-458c-9fa7-382470249509": {"definition": "The rate of first-stage (C1) errors in a CD's CIRC error correction, counted as the number of blocks per second containing errors at the input of the C1 decoder (BLER, block error rate). Under the Red Book (IEC 60908) the averaged BLER must not exceed 220 per second over any ten-second window.", "plain_english": "This counts how many small read errors a CD player finds and fixes at the first stage each second. A good disc keeps this number low, so the music plays cleanly. If it climbs too high, the disc is close to failing.", "purpose_function": "It measures how readable a pressed or burned CD is, because a low C1 rate shows the data can be recovered with the first layer of error correction to spare. It is the main go/no-go quality metric for CD manufacturing.", "practical_application": "A QC or mastering engineer scans a finished disc on an analyzer and checks that peak and average BLER stay within Red Book limits before approving a glass master or a pressing run.", "category": "Disc Quality Control", "related_terms": ["C2 error rate", "BLER", "CIRC", "Red Book", "Compact Disc master", "CD mastering"], "common_mistakes": ["Confusing C1 errors with real failures: C1 errors are normal and fully corrected, whereas uncorrectable (E32/CU) errors are the actual problem.", "Assuming a low C1 rate alone guarantees good audio, when burst errors and downstream C2/E32 counts also matter.", "Reading BLER as a fixed lifetime spec rather than a snapshot that can worsen as a disc ages or is mishandled."], "scenario_contexts": ["Quality-checking a glass master before a replication run", "Comparing burn quality across CD-R brands and write speeds", "Diagnosing playback dropouts on returned or archived discs"]}, "ec5ce2aa-c818-425b-82a3-f96a1019b87f": {"definition": "The rate of second-stage (C2) errors in a CD's CIRC error correction, counting blocks the first (C1) stage could not fix that are passed to the C2 decoder. C2 errors that remain uncorrectable (E32) force interpolation or muting and indicate serious data loss.", "plain_english": "This counts the read errors that slip past the first fix stage and need a deeper repair. Many of these mean a disc is in poor shape. If even the second stage cannot fix them, the player has to guess or mute the sound.", "purpose_function": "It flags discs whose errors are severe enough to threaten the audio, because C2 activity, especially uncorrectable E32 errors, is where real, audible data loss begins. It is a stricter health check than C1 alone.", "practical_application": "During disc QC an engineer confirms corrected C2 (E22) errors are rare and that there are zero uncorrectable E32 errors before signing off, since any E32 means the master or pressing is rejected.", "category": "Disc Quality Control", "related_terms": ["C1 error rate", "BLER", "CIRC", "Red Book", "Compact Disc master"], "common_mistakes": ["Treating every C2 error as fatal: corrected E22 errors may be within tolerance, but uncorrectable E32 errors are not.", "Relying on whether a disc 'plays fine' on one drive instead of measuring C2 and E32 on an analyzer.", "Confusing the C2 error rate with C1 (BLER); C2 sits downstream and reflects more serious damage."], "scenario_contexts": ["Rejecting a glass master that shows uncorrectable E32 errors", "Grading the long-term readability of archival CD-R media", "Investigating audible clicks or dropouts traced to disc errors"]}, "1b25b56d-c05a-418c-9eed-6d08fa8ed5c1": {"definition": "The final preparation of finished stereo mixes into a Red Book (IEC 60908) compliant CD master, covering level and tonal balance, track sequencing, gaps and fades, PQ/subcode coding, ISRC and UPC embedding, and delivery as a DDP fileset, PMCD, or verified disc.", "plain_english": "This is the last step that turns finished songs into the exact disc a factory will copy. The engineer sets a matching volume and tone across the tracks and puts them in order. The result is a master that meets the CD standard.", "purpose_function": "It makes an album sound consistent and translate well across playback systems while meeting the technical rules a plant needs to press error-free discs. It is the bridge between mixing and manufacturing.", "practical_application": "A mastering engineer loads mixes into an editor such as WaveLab, Sequoia, SADiE, or Pyramix, applies EQ, compression and limiting, builds the PQ sheet, and exports a DDP image for replication.", "category": "CD Mastering", "related_terms": ["Compact Disc master", "Red Book", "DDP", "PQ coding", "ISRC", "CD-Text authoring"], "common_mistakes": ["Setting inter-track gaps or track start IDs wrongly so songs run together or start clipped on the pressed disc.", "Exceeding 0 dBFS or creating inter-sample peaks that distort on consumer players.", "Skipping ISRC, UPC, or CD-Text entry and then having to re-cut the master.", "Delivering audio that is not exactly 16-bit / 44.1 kHz, which is out of Red Book spec."], "scenario_contexts": ["Preparing an album for CD replication", "Creating a reference disc for an artist to approve", "Assembling and sequencing a compilation from multiple sessions"]}, "c7bf691e-3369-47b6-ab04-794072dd6edb": {"definition": "The process of entering and encoding disc and track metadata, such as album title, track titles, performer, songwriter, composer, and arranger, into the R-W subcode channels of a Red Book CD so compatible players can display it. It is added during premastering and written into the DDP or disc master.", "plain_english": "This is adding the album name, song titles, and artist so a CD player can show them on screen. The text rides along in a spare data lane on the disc. The engineer types it in while building the master.", "purpose_function": "It lets standard CD players show readable title and artist information with no internet lookup, since the text travels on the disc itself. This improves the listener experience.", "practical_application": "In mastering software the engineer fills in the CD-Text fields for the disc and each track, then confirms it is included in the exported DDP fileset sent to the plant.", "category": "Disc Authoring", "related_terms": ["CD mastering", "Compact Disc master", "Red Book", "ISRC", "PQ coding", "DDP"], "common_mistakes": ["Confusing CD-Text (stored on the disc) with CDDB/Gracenote lookup (fetched online); they are different systems.", "Exceeding the CD-Text character limits so titles are truncated on players.", "Using characters outside the supported set, causing garbled display.", "Forgetting to embed CD-Text in the final DDP, so it is missing from pressed discs."], "scenario_contexts": ["Adding album and track titles to a commercial CD master", "Preparing a promo disc that displays artist and track names", "Matching CD-Text to the printed booklet and PQ log"]}, "9aec6885-66e7-4aa0-9eb8-cc6fa848473b": {"definition": "A deliverable made by rendering an object- and bed-based immersive mix, such as Dolby Atmos, down to a fixed channel layout like 5.1, 7.1.4, stereo, or binaural. The renderer resolves object positions and bed channels into the target speaker feeds for monitoring or delivery.", "plain_english": "An immersive mix places sounds as movable objects in a 3D space. A channel-based re-render turns that mix into a normal set of fixed speaker feeds, like 5.1 surround or plain stereo. It lets people without an immersive setup hear a matching version.", "purpose_function": "It produces the flat, speaker-specific versions that distributors and older systems need from a single immersive master, so one mix can serve many formats while staying consistent with the original.", "practical_application": "In the Dolby Atmos Renderer or a DAW's built-in renderer, the engineer prints re-renders such as 2.0, 5.1, 7.1.4, and binaural from the master, checking levels and downmix balance on each.", "category": "Immersive Delivery", "related_terms": ["Dolby Atmos", "ADM BWF", "Binaural rendering", "Downmix", "Bed", "Object-based audio"], "common_mistakes": ["Assuming a re-render is a simple downmix, when object positions and renderer settings change the result.", "Not checking loudness and clipping on each re-render, since folding channels together can raise levels.", "Forgetting that binaural re-renders depend on per-object distance settings that must be set in the mix."], "scenario_contexts": ["Delivering 5.1 and stereo versions alongside a Dolby Atmos master", "Creating a binaural headphone version for streaming", "Providing a stereo re-render for broadcast from an immersive session"]}, "12250777-c613-4b93-ab4a-396c766b3cca": {"definition": "A stem consisting of the mixed and processed choir (vocal ensemble) tracks bounced together as one submix, kept separate from other instrument groups. It carries the full choir at its final balance for use in mastering, re-mixing, or delivery.", "plain_english": "A stem is one track that holds a whole group of related sounds mixed together. A choir stem is that single track for just the choir voices. Keeping it separate lets someone change the choir later without touching the rest.", "purpose_function": "It lets a mastering engineer, film mixer, or remixer control the choir's level and tone on its own after the mix is done, without returning to every individual voice track. It also supports stem delivery and archiving.", "practical_application": "An engineer receiving a set of stems can raise or gently EQ the choir stem during stem mastering, or supply it to a film re-recording mixer who needs the choir on its own fader.", "category": "Stems & Sources", "related_terms": ["Stem", "Stem mastering", "Submix", "Bus", "Vocal stem"], "common_mistakes": ["Bouncing the choir stem with different plugins or timing than the full mix, so the stems no longer sum to the original.", "Not matching sample rate, bit depth, and start time across stems, causing sync or level problems.", "Treating a stem as a finished solo mix rather than a component that must recombine with the others."], "scenario_contexts": ["Delivering stems for stem mastering", "Supplying a choir stem to a film or TV re-recording mixer", "Creating an instrumental or a cappella version by muting or soloing stems"]}, "d5c1d3f2-6151-4bdc-8df4-e47a66f56ae1": {"definition": "A magnetic recording layer made of chromium dioxide (CrO2) used on Type II ('chrome'/high-bias) cassette and some open-reel tapes. Its higher coercivity and needle-shaped particles give better high-frequency response and lower noise than standard ferric-oxide tape, and it uses the 70 microsecond replay equalization time constant.", "plain_english": "This is a special coating on some cassette tapes made from a chromium compound. It holds magnetic signals more firmly than common brown tape, so it captures crisp high notes with less hiss. Decks have a 'chrome' or 'high bias' setting made to match it.", "purpose_function": "It exists to raise cassette recording quality, giving cleaner treble and a better signal-to-noise ratio than Type I ferric tape. Matching the recorder's bias and equalization to it is what unlocks that improvement.", "practical_application": "When dubbing to a Type II chrome cassette, an engineer selects the deck's high-bias / 70 microsecond setting, or relies on the shell's auto-detect notch, so the recording is correctly biased and equalized.", "category": "Magnetic Media", "related_terms": ["Tape bias", "Ferric oxide tape", "Type II cassette", "Tape equalization", "Noise reduction"], "common_mistakes": ["Recording chrome tape on a Type I (normal bias) setting, giving a dull or mistracked result.", "Assuming high-bias tape is always better, when the deck must actually support and be aligned for it.", "Confusing the 70 microsecond playback EQ of Type II with the 120 microsecond used for Type I."], "scenario_contexts": ["Dubbing a master to high-bias cassette for distribution", "Aligning a cassette deck's bias and EQ for chrome tape", "Archiving or transferring vintage Type II recordings"]}, "a5100053-7fc9-45fa-92ed-106b178b1cc7": {"definition": "A mastering session in which the client (artist, producer, or label representative) is physically present in the mastering room, listening on the studio monitoring and giving feedback in real time as decisions are made, as opposed to an unattended session delivered remotely.", "plain_english": "This is a mastering session where the artist or producer sits in the room while the engineer works. They hear each change on the studio speakers and give feedback right away. It is the opposite of sending files and waiting for the result.", "purpose_function": "It lets creative decisions be approved on the spot on trusted monitoring, cutting revision rounds and giving the client confidence in the final sound. It also books the room and engineer's time exclusively.", "practical_application": "A studio schedules attended time at a higher rate; the engineer prepares the session beforehand, then makes tonal and level moves live while the client approves each track.", "category": "Session Workflow", "related_terms": ["Unattended mastering", "Mastering", "Reference monitor", "Revision", "CD mastering"], "common_mistakes": ["Expecting a client's laptop or headphones to match the mastering room, then chasing changes that only 'fix' unfamiliar monitoring.", "Letting a room full of opinions push level or brightness too far from a translatable master.", "Not preparing and gain-staging the session beforehand, wasting paid attended time."], "scenario_contexts": ["An artist attending to approve final tonal balance and sequencing", "A label rep signing off on a single before release", "Comparing masters against references in the room with the client present"]}, "87f9231d-793d-42ee-b039-940a0c92fc22": {"definition": "The final, Red Book (IEC 60908) compliant master from which CDs are replicated, delivered as a DDP fileset, a PMCD (Pre-Master CD), or an approved verified disc, containing the audio plus PQ subcode, ISRC/UPC, and any CD-Text. It defines exactly what the pressing plant reproduces.", "plain_english": "This is the finished, approved version of a disc that a factory copies exactly. It holds the audio plus hidden data like track marks, gaps, and codes. Whatever is on this master ends up on every pressed CD.", "purpose_function": "It is the single authoritative source for CD manufacturing, so every pressed copy matches the approved audio and metadata. Delivering it in a checked format keeps errors out of the run.", "practical_application": "After mastering, the engineer exports a DDP image with a checksum, or cuts and verifies a PMCD, and sends it to the replicator as the reference for the glass master.", "category": "Master Formats", "related_terms": ["DDP", "PMCD", "Glass master", "Red Book", "CD mastering", "PQ coding"], "common_mistakes": ["Sending a plain burned audio CD-R with no checksum as a 'master', risking undetected read errors on the copy.", "Assuming a plain data copy preserves PQ, ISRC, and CD-Text; only proper master formats (DDP/PMCD) do.", "Not verifying the master's checksum, so a corrupted transfer is pressed unnoticed."], "scenario_contexts": ["Delivering a DDP fileset to a replication plant", "Cutting and verifying a PMCD for a small run", "Archiving the approved master for future repressings"]}, "5060e207-faeb-479b-acf7-6172109302f1": {"definition": "Cross-interleaved Reed-Solomon coding (CIRC) is the two-stage error-correction scheme used on audio Compact Discs, defined in the Red Book standard (IEC 60908). It pairs two Reed-Solomon codes (called C1 and C2) with an interleave that spreads each block of audio across many code words, so burst errors from scratches or dust are broken up and can be corrected or, failing that, concealed.", "plain_english": "CIRC is the safety net a CD uses to fix reading errors. It spreads each bit of the music across the disc. So a scratch harms many tiny pieces, not one whole chunk, and the damage is easy to repair. It works like copying your notes in a few places so one spill never wipes out a full page.", "purpose_function": "It exists to make optical-disc playback robust: because CDs get handled, scratched, and dusty, CIRC lets the player recover the original samples exactly, or briefly hide the loss, so the listener still hears clean audio.", "practical_application": "A mastering or QC engineer leans on CIRC when checking a disc's error rates; low C1/C2 counts show that a glass master or replicated disc will play reliably.", "category": "Optical Disc Coding", "related_terms": ["CU error rate", "Block error rate (BLER)", "Red Book standard", "Interleaving", "Error concealment", "Glass master"], "common_mistakes": ["Thinking CIRC makes CDs error-proof; it only corrects or conceals errors up to a limit, after which audible dropouts or muting occur.", "Confusing correction with concealment: CIRC first tries to rebuild the data exactly, and only interpolates (conceals) when correction fails.", "Assuming a disc that plays fine has low error rates; playback can succeed while error correction is working hard, hiding a disc that is near failure."], "scenario_contexts": ["Verifying error rates on a CD glass master before authorizing replication.", "Diagnosing why a burned CD-R plays with dropouts on some players.", "Explaining why a scratch running across the disc is worse than a single radial scratch."]}, "732e9606-1a83-457b-8345-e0d91e94cfd9": {"definition": "The CU (uncorrectable) error rate is a Compact Disc quality measurement counting the errors that the disc's C2 (second Reed-Solomon) decoder cannot correct, per unit of time. A nonzero CU rate means the CIRC system had to conceal (interpolate) or mute samples rather than recover them exactly, so by professional standards the disc is defective.", "plain_english": "The CU error rate counts the reading mistakes a CD's built-in repair system cannot fix. When it is above zero, the player has to guess or mute part of the sound instead of reading it correctly. For a finished disc this number should be zero, the way a printed book should have no missing letters.", "purpose_function": "It is a pass/fail health check: a good disc has zero uncorrectable errors, so measuring the CU rate tells an engineer whether a master or replicated disc meets the standard before it is duplicated or shipped.", "practical_application": "In QC, a technician runs a disc analyzer, watches the error report, and rejects any master or batch showing CU (uncorrectable) errors, since these cause audible clicks or muting.", "category": "Optical Disc Testing", "related_terms": ["Cross-interleaved Reed-Solomon coding", "Block error rate (BLER)", "C1/C2 errors", "Error concealment", "Glass master", "Disc replication"], "common_mistakes": ["Treating a low but nonzero CU rate as acceptable; for a finished CD the target is zero uncorrectable errors.", "Confusing CU (uncorrectable, C2) errors with ordinary C1 errors, which are common and fully corrected.", "Judging a disc only by whether it plays; a player can mute over CU errors so briefly that the listener misses it."], "scenario_contexts": ["Final QC of a glass master before mass replication.", "Screening burned CD-Rs used as reference or production masters.", "Investigating intermittent clicks reported on a duplicated disc run."]}, "b6afa3f8-562e-4702-9752-0548193b6b5f": {"definition": "Cue-by-cue export is the practice of bouncing a film or television score to disk as one separate audio file (or set of stems) per musical cue, rather than as a single continuous file. Each cue is exported at its scene's timecode so it drops into the re-recording (dub) session in sync.", "plain_english": "In film music, a 'cue' is one short piece of score written for a scene. Cue-by-cue export means saving each of those pieces as its own audio file instead of one long track. That way the mixing team can place, move, and balance each piece of music on its own. It is like handing over a stack of labeled clips instead of one giant recording.", "purpose_function": "It exists so the mixer and music editor can position, level, and edit each piece of score independently against picture, and so a change to one scene does not require re-delivering the whole score.", "practical_application": "A composer or score mixer bounces each cue to timecode-stamped files (often as stems), names them by cue number, and hands them to the music editor for the dub stage.", "category": "Score Delivery", "related_terms": ["Delay-only score stem", "Stems", "Timecode", "Music editor", "Bounce/export", "Re-recording mix"], "common_mistakes": ["Exporting one continuous file instead of separate cues, which makes it hard for the dub stage to place and revise individual cues.", "Not aligning or embedding timecode, so the exported cues do not drop into the mix in sync.", "Inconsistent naming or missing cue numbers, causing cues to be misfiled at the dub stage."], "scenario_contexts": ["Delivering a completed score to the re-recording mixer for a film's final dub.", "Sending revised music for a single scene without re-exporting the entire score.", "Preparing score stems for a TV episode's music-and-effects (M&E) delivery."]}, "add17eb2-1c78-430d-b910-dbdcfc48b8fc": {"definition": "Cutter-head cooling refers to the methods used to remove heat from the electromagnetic drive coils of a disc-cutting head, which dissipate significant power when cutting loud or high-frequency material. On lathes such as the Neumann SX-74, helium gas is fed around the coils to conduct heat away, and protection circuits mute the head if coil current or temperature exceeds safe limits.", "plain_english": "The cutting head that carves a record's groove has coils that get very hot. Loud, bright music makes them hotter still. Cutter-head cooling stops those coils from burning out. It usually feeds helium gas around them to carry the heat away. It works like the fan that keeps a computer chip from cooking itself.", "purpose_function": "It exists to protect an expensive, hard-to-replace cutter head from heat damage, letting the engineer cut loud programs without burning out the drive coils.", "practical_application": "A cutting engineer keeps the helium supply flowing and watches the head's temperature and protection meters, easing off level or high frequencies if the coils approach their limit.", "category": "Disc Cutting", "related_terms": ["Cutter-head heating", "Cutting level optimization", "Disc-cutting lathe", "Cutting stylus", "Cutter-head protection", "Variable pitch"], "common_mistakes": ["UNSAFE: Cutting very loud, high-frequency material without adequate cooling or heed of the protection meters, which can burn out the costly drive coils.", "Forgetting to turn on or refill the helium supply before a cutting session.", "Assuming cooling lets you ignore level limits; it raises the safe ceiling but does not remove it."], "scenario_contexts": ["Cutting a loud, bright master where coil heating is a real risk.", "Pre-session checks on a Neumann lathe's helium cooling supply.", "Troubleshooting a cutter head that keeps tripping its thermal protection."]}, "210217b7-8c06-4363-812a-d84ce504f4e7": {"definition": "Cutter-head heating (the 'hot stylus' technique) is the deliberate warming of the cutting stylus by a small heater coil during disc cutting. Heating softens the lacquer at the point of cut, which reduces cutting friction and surface (groove) noise and improves high-frequency detail and groove-wall finish. It is distinct from unwanted overheating of the drive coils, which the cooling system prevents.", "plain_english": "A record groove is carved by a sharp stylus cutting into a soft lacquer disc. Heating the stylus with a tiny built-in heater makes it slice more cleanly, which lowers background hiss and sharpens the high notes. It is like warming a knife before cutting so it glides through smoothly instead of tearing.", "purpose_function": "It exists to lower groove-surface noise and clean up high-frequency cutting, giving a quieter, more detailed record.", "practical_application": "The cutting engineer adjusts the stylus heat while listening to a test cut, dialing it for the lowest surface noise without over-heating, which would distort or scorch the lacquer.", "category": "Disc Cutting", "related_terms": ["Cutter-head cooling", "Cutting stylus", "Lacquer", "Surface noise", "Disc-cutting lathe", "Cutting level optimization"], "common_mistakes": ["Using too much stylus heat, which distorts the groove and can raise noise or damage the stylus.", "Using too little heat, leaving audible surface noise and dull high frequencies.", "Confusing deliberate stylus heating with coil overheating; the first is a wanted adjustment, the second is a fault the cooling system guards against."], "scenario_contexts": ["Dialing in stylus heat at the start of a lacquer cutting session for lowest surface noise.", "Cutting a quiet, delicate passage where groove noise would be exposed.", "Diagnosing excess surface noise traced to an incorrectly set stylus heater."]}, "3d813cfa-df16-4eb4-9bfd-3c99e5ac502f": {"definition": "Cutting level optimization is the process of setting the level fed to a disc-cutting lathe as high as the medium allows while still fitting the required playing time and cutting a groove that plays back cleanly. It trades a hotter level (better signal-to-noise and impact) against groove width, side length, and safe tracking on consumer turntables.", "plain_english": "When making a vinyl record, louder grooves sound better but take up more space, so each side holds less music. Cutting level optimization is finding the highest level that still fits the whole side and plays back without skipping. It is like choosing the biggest, clearest handwriting that still fits your whole essay on one page.", "purpose_function": "It exists to get the best loudness and signal-to-noise from vinyl's limited space without overrunning a side or cutting grooves too wide or deep to track reliably.", "practical_application": "The cutting engineer sets overall level, often with variable pitch and depth driven by a preview signal, to fit the side length while keeping grooves loud but trackable, watching bass level and sibilance.", "category": "Disc Cutting", "related_terms": ["Cutting preview system", "Variable pitch", "Cutter-head cooling", "Groove spacing", "Playing time", "Cutting stylus"], "common_mistakes": ["Cutting too hot for a long side, so the grooves overrun the space and run into the label.", "Ignoring heavy or out-of-phase bass, which forces very wide grooves and can make the stylus jump.", "Assuming louder is always better; over-cut grooves mistrack on many consumer turntables."], "scenario_contexts": ["Deciding cutting level for a long (20+ minute) LP side.", "Balancing loudness against surface noise on a quiet classical record.", "Setting level and pitch for a bass-heavy dance record so it still tracks."]}, "c68d67fb-696e-4f96-912e-04394ce6872e": {"definition": "The cutting preview system feeds the disc-cutting lathe's automatic groove-spacing (variable pitch and depth) control with the program audio a fixed time ahead, typically one disc revolution, of the audio being cut. Originally a second 'preview' head on a tape machine (or a matched delay on the program signal), it lets the pitch computer widen groove spacing just before loud passages and tighten it during quiet ones.", "plain_english": "A record lathe needs to know what is coming so it can space the grooves correctly: wide for loud parts, tight for quiet parts. The preview system feeds it the sound slightly early, one turn of the disc ahead, using a special tape head or a delay. It is like a driver seeing the road ahead so they steer before the curve, not during it.", "purpose_function": "It exists to make automatic variable pitch and depth possible: by hearing each passage in advance, the lathe packs the most music onto a side while leaving room for loud grooves so they never cut into their neighbors.", "practical_application": "When cutting from tape, the engineer uses a preview head set ahead of the program head (or a matching delay on a digital source) so the lathe's pitch computer gets the advance signal that drives groove spacing.", "category": "Disc Cutting", "related_terms": ["Variable pitch", "Cutting level optimization", "Disc-cutting lathe", "Preview head", "Groove spacing", "Cutter-head cooling"], "common_mistakes": ["Setting the preview time wrong, so groove spacing changes too early or too late and grooves overrun or waste space.", "Forgetting the preview delay when cutting from a digital source, so variable pitch cannot work.", "Confusing the preview (advance) signal with the actual program feed to the cutter head."], "scenario_contexts": ["Cutting a dynamic master from a preview-head tape machine.", "Configuring the delay offset when cutting from a digital file source.", "Troubleshooting grooves that run together on loud passages due to a mis-set preview."]}, "fa366925-a4ed-484d-84aa-d04813f5f5eb": {"definition": "The dead wax is the smooth, essentially ungrooved area on a vinyl record between the end of the recorded (modulated) grooves and the label. It carries the run-out groove and any etched matrix, catalogue and stamper identifiers, and it is where the tonearm lifts or parks at the end of a side.", "plain_english": "The dead wax is the shiny blank ring near the middle of a record, just past where the music stops and before the paper label. No sound is cut there, but you can often find scratched-in codes that identify the master and pressing. It is like the blank margin and printer's marks at the edge of a printed page.", "purpose_function": "It provides a safe run-out for the stylus at the end of a side and a place to inscribe the matrix, stamper and mastering marks used to trace and match parts through pressing.", "practical_application": "Engineers and QC staff read the dead-wax matrix numbers to confirm the correct master or stamper was used and to identify a pressing; the mastering engineer's initials or stamp may also appear there.", "category": "Vinyl Record", "related_terms": ["Matrix number", "Run-out groove", "Lacquer", "Stamper", "Disc-cutting lathe", "Lead-out groove"], "common_mistakes": ["Thinking the dead wax is a defect or empty waste; it is a deliberate, standard part of the record used for run-out and identification.", "Misreading or ignoring matrix and stamper codes when matching parts, leading to a wrong or mismatched pressing.", "Confusing the lead-out (run-out) groove with the locked concentric groove that finally stops the stylus."], "scenario_contexts": ["Reading matrix numbers in the dead wax to verify the correct stamper.", "Identifying a pressing or cut from etched dead-wax codes.", "Explaining where a mastering engineer stamps or signs a lacquer."]}, "81596854-a3e8-4f69-94a2-ebc2f5af23f4": {"definition": "A delay-only score stem is a score delivery stem that contains only the output of the delay (echo) effects, that is, the delayed 'wet' repeats with the dry source removed. Delivered alongside the dry stems, it lets the re-recording mixer adjust or remove the score's delay effect independently during the final mix.", "plain_english": "In film music, a stem is one part of the mix delivered on its own. A delay-only stem holds just the echoes from the music, with the original notes taken out. Handing it over separately lets the mixing team turn the echo up, down, or off without touching the rest of the music. It is like getting the shadow of a picture on its own clear sheet.", "purpose_function": "It exists to give the final mixer control over time-based effects: keeping the delay on its own stem means the echo can be balanced against dialogue and effects, or removed, without re-rendering the score.", "practical_application": "The score mixer routes the delay returns to a separate bus and bounces them as their own stem, labeled and time-aligned with the dry cue, for delivery to the dub stage.", "category": "Score Delivery", "related_terms": ["Cue-by-cue export", "Stems", "Wet/dry signal", "Reverb return", "Re-recording mix", "Bus"], "common_mistakes": ["Baking the delay into the main (dry) stem, so the dub mixer cannot reduce or remove it if it clashes with dialogue.", "Failing to time-align the delay stem with its dry cue, causing timing or phase problems when they are recombined.", "Including dry signal in the 'delay-only' stem, which defeats the purpose of an isolated effect stem."], "scenario_contexts": ["Delivering score stems for a dub where the mixer may need to pull echo out from under dialogue.", "Providing separate wet (delay/reverb) stems for a Dolby Atmos score mix.", "Re-balancing a delay effect on the score during the final re-recording mix."]}, "0ad2d233-e4f2-4cb1-a8f4-e9f2d68758fb": {"definition": "A film or TV music mix balanced and spectrally shaped so the musical score supports the picture without masking or reducing the intelligibility of spoken dialogue. It is achieved by controlling the music's level and dynamics and by carving competing midrange frequencies relative to the dialogue.", "plain_english": "A way of mixing background music so it never covers up the talking. The music is kept a bit quieter and pulled out of the voice's range. It is like a band playing softly behind a speaker so you still hear every word.", "purpose_function": "It exists so the audience can always follow the story: dialogue is the priority element, and the score is shaped to add emotion while staying out of its way.", "practical_application": "A re-recording or music mixer rides the music level under dialogue, uses EQ to open space around 1-4 kHz, and may duck the score during lines so the words stay clear.", "category": "Post-Production Mixing", "related_terms": ["Dialogue intelligibility", "Ducking", "Stem mixing", "Loudness normalization", "Frequency masking", "Re-recording mix"], "common_mistakes": ["Setting the music by feel in a quiet room, then finding it buries dialogue on small TV speakers", "Using only a level ride instead of also carving the competing midrange frequencies", "Ignoring dialogue-anchored loudness standards, so the delivered mix fails broadcast targets"], "scenario_contexts": ["Mixing a documentary where narration must stay clear over a music bed", "Balancing an orchestral cue under an emotional dialogue scene in a film", "Preparing a TV episode mix to meet broadcast dialogue-anchored loudness specs"]}, "b6904c32-2ab9-4b86-8c76-57b8b16fe9a3": {"definition": "A quality-control check that measures a disc's residual mechanical (dynamic) imbalance, the uneven distribution of mass about its rotational axis, to confirm it stays within specification so the disc spins without excessive vibration at high playback speeds.", "plain_english": "A test that checks the disc's weight is spread evenly around its center. If one side is heavier, the disc wobbles when it spins fast, just like a lopsided wheel on a car. This test makes sure it stays smooth.", "purpose_function": "It exists to catch discs whose off-center mass would cause vibration, tracking errors, or read failures in high-speed drives, protecting playback reliability.", "practical_application": "In manufacturing QC, a technician spins sample discs on a balance analyzer and compares the measured residual imbalance against the standard's limit before releasing a production run.", "category": "Disc Quality Control", "related_terms": ["Disc eccentricity test", "Disc reflectivity measurement", "Disc compatibility test", "Radial runout", "Residual imbalance"], "common_mistakes": ["Confusing mechanical mass imbalance with left/right audio channel balance, which is unrelated", "Assuming imbalance only matters for data discs, when high-speed audio and video playback is affected too", "Skipping balance checks on thin or warped stock that is most likely to fail at speed"], "scenario_contexts": ["Batch QC of pressed CDs or DVDs before shipment", "Diagnosing a disc that vibrates or fails to read at high drive speeds", "Qualifying a new stamper or moulding run for consistent disc flatness and balance"]}, "4e473d49-e759-4365-96d5-36fda07313ba": {"definition": "A verification step confirming that a finished or premaster disc conforms to its format standard (such as Red Book) and plays back correctly across a representative range of drives and players, not only on the machine that wrote it.", "plain_english": "A check that makes sure a disc really plays in lots of different players, not just the one that made it. It is like testing a house key in every door it should open, so you know it works everywhere before you hand it out.", "purpose_function": "It exists to catch format or writing errors that would make a disc unreadable or cause it to be rejected at the pressing plant, ensuring the master is safe to replicate.", "practical_application": "A mastering engineer plays the finished CD-R or DDP master on several drives and an analyzer, checking for E32 uncorrectable errors and standard compliance before sending it for replication.", "category": "Disc Quality Control", "related_terms": ["Disc-at-once mastering", "Disc image verification", "Red Book standard", "Block error rate (BLER)", "DDP"], "common_mistakes": ["Delivering a Track-At-Once CD-R whose run-out sectors read as uncorrectable E32 errors and get rejected by the plant", "Testing only on the burner's own drive and assuming universal compatibility", "Ignoring high block-error-rate warnings on a master that still happens to play on one machine"], "scenario_contexts": ["Checking a CD master on multiple players before replication", "Troubleshooting a disc that plays on a computer but not on standalone players", "Pre-flighting a delivery to meet a plant's error-rate acceptance criteria"]}, "f3bf9e0e-bad4-429b-ac40-f625133a458e": {"definition": "A measurement of how far a disc's recorded track spiral or centre hole deviates from being concentric with the rotational axis, expressed as radial runout, verifying the deviation stays within the format standard's limits.", "plain_english": "A test that checks the disc's grooves and center hole sit truly in the middle. If they are off-center, the disc reads unevenly as it spins, like a record with an off-center hole that makes the pitch wobble. This keeps it centered.", "purpose_function": "It exists to ensure the read or cutting mechanism can track the spiral smoothly; too much eccentricity causes tracking errors, speed wobble, or read failures.", "practical_application": "In QC, a technician measures the track's radial runout and hub concentricity against the standard's limits, such as those in ECMA-130, to accept or reject discs or a moulding run.", "category": "Disc Quality Control", "related_terms": ["Disc balance verification", "Radial runout", "Disc reflectivity measurement", "Tracking error", "Centre hole concentricity"], "common_mistakes": ["Confusing eccentricity (off-center) with warp or axial deviation (up-and-down); both are checked but are different", "Assuming a slightly off-center printed label means the recorded track itself is eccentric", "Overlooking hub and centre-hole concentricity, which sets how well any player can center the disc"], "scenario_contexts": ["QC of pressed optical discs against standard runout limits", "Diagnosing tracking errors or audible wow on a disc", "Setting up a cutting lathe or mastering system so the master is cut concentrically"]}, "d07ea4e2-31f1-43f5-9c83-14246b159457": {"definition": "A standardized code that uniquely identifies an optical disc or its release. On audio CDs the primary example is the Media Catalog Number (MCN), a 13-digit UPC/EAN encoded in the disc's Q-subchannel per IEC 60908 (Red Book), complemented by source and matrix codes molded into the disc that identify its manufacturing origin.", "plain_english": "A code stored on a disc that tells machines exactly which disc it is, like a barcode on a grocery item. On a CD it is a hidden number that names the whole release, so software and players can look it up.", "purpose_function": "It exists so a disc and its release can be recognized, catalogued, and tracked automatically by players, software, and the manufacturing chain.", "practical_application": "During CD mastering, the engineer enters the MCN, and the per-track ISRC codes, so they are written into the subcode; QC then reads them back to confirm they are present and correct.", "category": "Disc Metadata", "related_terms": ["ISRC", "Media Catalog Number", "Subcode (Q channel)", "Disc image verification", "Matrix number"], "common_mistakes": ["Confusing the MCN, which identifies the whole disc, with the ISRC, which identifies each individual track", "Leaving the MCN blank or reusing another release's number", "Assuming the catalogue number printed on the artwork is the same as the encoded MCN"], "scenario_contexts": ["Entering MCN and ISRC codes during CD premastering", "Verifying encoded identifiers on a master before replication", "Identifying a pressed disc's origin from its matrix and source codes"]}, "e670034e-20d3-4fb4-8fce-f681512158e7": {"definition": "The process of confirming that a disc image, the complete premaster file set describing a disc's content and most commonly a DDP (Disc Description Protocol) image, is intact and matches its source, typically by comparing MD5 checksums before the image is replicated.", "plain_english": "A check that makes sure the disc's master files arrived complete and unchanged. It compares a digital fingerprint, called a checksum, taken at both ends. If the fingerprints match, nothing got corrupted along the way.", "purpose_function": "It exists to guarantee the exact audio and data the engineer approved are what get pressed, preventing a corrupted transfer from being turned into thousands of faulty discs.", "practical_application": "A mastering engineer generates an MD5 checksum for the DDP image and sends it with the files; the plant recomputes the checksum on receipt to confirm the image is bit-for-bit identical.", "category": "Disc Quality Control", "related_terms": ["DDP", "MD5 checksum", "Disc compatibility test", "Disc-at-once mastering", "Red Book standard"], "common_mistakes": ["Delivering a DDP with no checksum, so a corrupted transfer can go undetected", "Assuming a file that opens correctly is automatically bit-perfect", "Editing files inside the DDP folder after the checksum was generated, which invalidates it"], "scenario_contexts": ["Sending a DDP master to a replication plant with an MD5 file", "A plant verifying a received image before starting a pressing run", "Confirming an archived disc image is still intact years later"]}, "0dbb2292-6dc5-40be-afda-becdd9ad6639": {"definition": "A measurement of the fraction of incident laser light reflected from a disc's information surface, used to verify the disc meets the format standard's minimum reflectance; for CD this is at least 70% under normal incidence per ECMA-130 and IEC 60908, so players can reliably read it.", "plain_english": "A test of how well a disc bounces the player's laser back. If the surface does not reflect enough light, the player cannot read the data, like trying to read a mirror that has gone dull. The test makes sure it is shiny enough.", "purpose_function": "It exists to confirm the reflective layer and substrate return enough signal for stable reading; low reflectivity causes read errors, skipping, or unplayable discs.", "practical_application": "In QC, a technician measures reflectance on unrecorded and recorded areas with an analyzer and compares it to the standard's minimum before accepting the batch.", "category": "Disc Quality Control", "related_terms": ["Block error rate (BLER)", "Disc eccentricity test", "Disc compatibility test", "Red Book standard", "Reflective layer"], "common_mistakes": ["Assuming any dye or metal layer meets spec without actually measuring reflectance", "Confusing shininess to the eye with the laser-wavelength reflectance that actually matters", "Ignoring reflectance variation across the disc, which the standard also limits"], "scenario_contexts": ["QC of pressed or burned discs against the 70% minimum", "Diagnosing discs that skip or are unreadable in some drives", "Qualifying a new reflective-layer or dye formulation in manufacturing"]}, "617f84ae-c621-407e-b64e-c7d950867176": {"definition": "A CD writing method in which the entire disc, including lead-in, all tracks, and lead-out, is written in a single continuous pass without the laser switching off between tracks, producing a gapless, Red Book-compliant master suitable for replication.", "plain_english": "A way of burning a whole CD in one non-stop pass, from start to finish, without stopping between songs. Because the laser never pauses, there are no glitchy gaps, which is why factories want masters made this way. It is like writing a letter without lifting your pen.", "purpose_function": "It exists to create clean, glitch-free masters with controllable gaps and no run-out errors, meeting the requirements for commercial CD replication.", "practical_application": "When creating a final CD master or DDP, the engineer selects disc-at-once so the plant does not reject the disc for Track-At-Once run-out (E32) errors.", "category": "Disc Mastering", "related_terms": ["Track-at-once", "DDP", "Disc image verification", "Red Book standard", "Disc compatibility test"], "common_mistakes": ["Delivering a Track-At-Once CD-R for replication, whose run-out sectors can read as E32 errors and be rejected", "Thinking disc-at-once and track-at-once sound different; the difference is gaps and errors, not audio quality", "Adding or trimming tracks after finalizing, which requires re-burning the whole disc"], "scenario_contexts": ["Burning a final CD-R master for a pressing plant", "Creating a gapless live-album or DJ-mix CD", "Producing a Red Book master alongside a DDP for delivery"]}, "2c4c9691-891a-4607-a2b8-5af78e2e77ea": {"definition": "A specialist mastering engineer who transfers audio to a physical disc master by operating a cutting lathe, driving a cutter head that engraves the modulated groove into a lacquer (or copper/DMM) blank from which vinyl records are subsequently manufactured.", "plain_english": "The engineer who carves the sound into a master disc used to make vinyl records. Using a machine called a cutting lathe, they turn the audio into a real groove, a bit like a very precise needle drawing a spiral. Their choices affect how the record sounds.", "purpose_function": "They exist to translate a finished audio master into a groove a record can reproduce, managing level, bass, and stereo width so the cut plays back cleanly without skipping.", "practical_application": "The cutting engineer sets the lathe's pitch and depth, applies any EQ or limiting the medium needs, and cuts the lacquer master that goes to the plating and pressing plant.", "category": "Disc Mastering", "related_terms": ["Cutting lathe", "Lacquer master", "Vinyl mastering", "RIAA equalization", "Direct Metal Mastering (DMM)"], "common_mistakes": ["Assuming a digital master needs no changes for vinyl; excessive bass, out-of-phase low end, or sibilance can make a groove unplayable", "Confusing the cutting engineer with the pressing plant; cutting makes the master, pressing makes the copies", "Cutting levels too hot or sides too long, reducing groove space and lowering volume or causing skips"], "scenario_contexts": ["Cutting a lacquer master for a vinyl release", "Adjusting a master's low end and sibilance so it can be cut safely", "Deciding cut level versus side length to fit a long album on one side"]}, "a28d7a65-7445-4f10-b46a-0d747e5c7919": {"definition": "The final, approved audio master prepared and formatted for a specific delivery channel or medium, such as a DDP image for CD replication, a high-resolution PCM file for streaming and download stores, or a dedicated cut master for vinyl. It is derived from the mastering session's production master and carries the exact program, track order, spacing, and metadata that will be reproduced.", "plain_english": "The finished version of a record, saved in the exact form a shop or streaming service needs. There can be one for CDs, one for streaming, and another for vinyl. It is like exporting the same photo in the right size for a poster, a phone, and a website.", "purpose_function": "It exists to hand distributors and pressing plants a ready-to-use, format-correct copy of the finished music so it is reproduced exactly as approved.", "practical_application": "A mastering engineer exports a separate distribution master per outlet: a DDP for the CD plant, high-resolution WAVs for streaming, and a dedicated cut for vinyl, each meeting that outlet's spec.", "category": "Mastering Deliverables", "related_terms": ["Production master", "DDP", "Premaster", "Delivery specification", "Red Book standard", "Loudness normalization"], "common_mistakes": ["Sending one generic file to every outlet instead of a format-correct master for each", "Confusing the distribution master with the production master it is derived from", "Ignoring an outlet's spec for sample rate, headroom, or metadata, so the file is rejected"], "scenario_contexts": ["Exporting a DDP distribution master for a CD pressing plant", "Delivering high-resolution WAV masters to a streaming aggregator", "Preparing a separate cut master for vinyl alongside the digital masters"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"64674906-ae30-43a5-ac88-4cffa57a6486": {"definition": "A software equalizer plug-in from DMG Audio offering up to 32 bands of shelving, filter, notch, and peaking EQ that can run in series or in parallel. It provides linear-phase, minimum-phase, analogue-modelled, and free-phase modes, per-band dynamic (level-dependent) EQ, plus mid-side and multichannel operation, aimed at mixing and mastering.", "plain_english": "A very flexible tone-shaping plug-in for a computer. It can boost or cut many exact frequency ranges, copy the sound of classic hardware, and even react to how loud a sound is. It is like a huge set of tone dials with a lot of extra options.", "purpose_function": "It exists to give engineers precise, adaptable control over tone and balance, from surgical fixes to gentle mastering shaping, all in one plug-in.", "practical_application": "A mastering engineer might use a linear-phase band for a clean broad lift, a dynamic band to tame a resonance only when it peaks, and mid-side bands to widen or focus the stereo image.", "category": "Mastering Software", "related_terms": ["Parametric equalizer", "Linear-phase EQ", "Dynamic EQ", "Mid-side processing", "Mastering chain", "DMG Audio Limitless"], "common_mistakes": ["Defaulting to linear-phase everywhere, ignoring its pre-ring and added latency trade-offs", "Adding many bands when a couple of well-placed moves would do", "Confusing minimum-phase and linear-phase modes and their differing effect on transients"], "scenario_contexts": ["Broad tonal shaping across a master bus", "Notching a narrow resonance with a dynamic band", "Mid-side EQ to open the top end without widening the bass"]}, "d3f1fb24-d5f1-4d2c-a493-55202d777758": {"definition": "A mastering peak-limiter plug-in from DMG Audio that splits the signal into up to five user-editable frequency bands and separates transients from sustained material, processing each with dedicated limiting routines. It includes true-peak-aware limiting and a multi-algorithm clipping stage, aiming for loud, transparent masters.", "plain_english": "A loudness tool for finishing a track. It gently holds back the loudest peaks so the whole song can be turned up without distorting. It splits the sound into separate frequency zones and treats sudden hits differently from steady sounds to stay clean.", "purpose_function": "It exists to raise a master's overall loudness while controlling peaks, doing so with fewer audible artifacts than a single wide-band limiter.", "practical_application": "At the end of the mastering chain, an engineer sets the output ceiling and gain, then tunes the bands and transient handling so the master hits its loudness target without pumping or distortion.", "category": "Mastering Software", "related_terms": ["Brickwall limiter", "True peak", "Loudness normalization", "Multiband processing", "Mastering chain", "DMG Audio Equilibrium"], "common_mistakes": ["Pushing gain until the master pumps or distorts, chasing loudness over quality", "Setting a 0 dBFS ceiling and getting true-peak overs after lossy encoding", "Leaving it in the most complex mode without understanding each band's job"], "scenario_contexts": ["Final limiting stage of a mastering chain", "Meeting a streaming loudness and true-peak target", "Controlling peaks on a dynamic mix without audible squashing"]}, "554eff6d-8860-4ced-99e0-f1ff029f77b1": {"definition": "The primary Dolby Atmos deliverable that stores a complete immersive mix as channel-based beds plus individual audio objects together with their three-dimensional positional (spatial) metadata. It exists as the Dolby Atmos Master File set (an .atmos file with companion audio and metadata files) or as an interchange ADM BWF (.wav) file, from which the Dolby renderer produces speaker-array and binaural outputs.", "plain_english": "One special file that holds a full surround-and-height mix. Instead of fixed speaker tracks, it stores the sounds plus notes on where each one should sit in the room. A playback system then places those sounds on whatever speakers or headphones the listener has.", "purpose_function": "It exists to carry a finished Atmos mix in a device-independent way, so the same file can be rendered correctly to many different playback setups.", "practical_application": "A mixer exports the Atmos master, often as an ADM BWF, from the Dolby renderer, then masters or delivers it to streaming platforms, which re-render it to formats like 5.1, 7.1, and binaural.", "category": "Immersive Audio", "related_terms": ["ADM BWF", "Audio object", "Dolby Atmos Renderer", "Bed (channel-based audio)", "Binaural rendering", "Downmix metadata"], "common_mistakes": ["Thinking it is a fixed speaker mix rather than objects plus positional metadata", "Confusing the .atmos master file set with the single-file ADM BWF export", "Assuming the master already contains final 5.1 or stereo mixes instead of re-renders made from it"], "scenario_contexts": ["Delivering an Atmos music master as ADM BWF to a streaming service", "Archiving a film or music Atmos mix as a master file set", "Re-rendering the master to 5.1 and binaural for other outlets"]}, "2a832871-fd59-46b7-aeb4-5f8af5a523df": {"definition": "Encoded parameters that tell a consumer decoder how to fold a multichannel program, such as 5.1, down to fewer channels, most commonly to stereo. It selects the downmix mode, Lt/Rt for matrix-surround compatibility or Lo/Ro for conventional stereo, and sets the centre and surround downmix levels that control how much those channels contribute to the two-channel result.", "plain_english": "Instructions saved with surround audio that tell a TV or player how to fold it into stereo. They set how loud the centre and rear channels should be in that stereo mix. The centre channel is the one that carries voices. It is like a recipe for shrinking six speakers down to two without losing the important parts.", "purpose_function": "It exists so a single surround delivery plays back correctly and predictably on stereo systems, keeping dialogue and balance right without needing a separate stereo mix.", "practical_application": "A broadcast or mastering engineer sets the Lo/Ro and Lt/Rt levels in the Dolby metadata so the encoded stream folds down cleanly, then auditions the resulting stereo downmix on the encoder.", "category": "Delivery Metadata", "related_terms": ["Dialnorm", "Lt/Rt", "Lo/Ro", "Dolby E", "Broadcast metadata", "Downmix"], "common_mistakes": ["Confusing downmix metadata with dialnorm; dialnorm sets a reference level, not the fold-down", "Never auditioning the stereo downmix, so it clips or buries dialogue", "Assuming default levels suit every program regardless of its surround balance"], "scenario_contexts": ["Setting Dolby metadata for a 5.1 broadcast delivery", "Checking a surround master's stereo fold-down before encoding", "Ensuring dialogue stays clear when a home receiver downmixes to two speakers"]}, "d63b4bea-b47b-4788-9a87-5bfea24afceb": {"definition": "A submix (stem) of a film or television musical score printed without added time-based effects such as reverb or delay, that is, the music in its dry form. It is delivered so the re-recording mixer can add or match ambience and place the score within the final soundtrack.", "plain_english": "A version of the movie's music saved with no echo or reverb added, just the plain, close sound. The final mixer can then add their own room sound so the music fits the scene. It is like getting a clean vocal so you can add your own echo later.", "purpose_function": "It exists to give the final dubbing stage full control over the music's space and blend, rather than baking in effects that cannot be undone later.", "practical_application": "The score mixer delivers dry, and often separate wet, music stems; on the dub stage the re-recording mixer adds reverb to seat the score with dialogue and effects.", "category": "Post-Production Mixing", "related_terms": ["Stem mixing", "Wet/dry signal", "Re-recording mix", "Reverb", "Effects-friendly score mix", "Dialogue-friendly score mix"], "common_mistakes": ["Printing the stem with reverb already added, removing the dub stage's control", "Confusing a dry stem with a rough or unfinished mix; dry only means no effects", "Delivering only a wet stem, leaving no clean version to reshape"], "scenario_contexts": ["Delivering music stems to a film dub stage", "Matching score ambience to a scene at the final mix", "Repurposing a cue for a trailer that needs different reverb"]}, "8dff32e3-ce2b-47cc-8ea1-dcabe3e332ff": {"definition": "A film or television music mix arranged and balanced so the score leaves sonic room for sound effects in the final dub, controlling the music's density and frequency content so score and effects can coexist without masking each other.", "plain_english": "A way of mixing a film's music so it does not fight with the sound effects, like explosions or footsteps. The music is shaped to leave gaps for those sounds. It is like a band leaving space so you can still hear the crowd and the action.", "purpose_function": "It exists so the score and the sound-effects track both stay clear in the finished soundtrack, instead of clashing and cluttering the mix.", "practical_application": "The score mixer thins busy arrangements and carves competing frequencies during effects-heavy scenes so the re-recording mixer can sit music and effects together easily.", "category": "Post-Production Mixing", "related_terms": ["Dialogue-friendly score mix", "Frequency masking", "Stem mixing", "Re-recording mix", "Sound effects (SFX)", "Dry score stem"], "common_mistakes": ["Mixing the score dense and full-range, so it masks key effects", "Judging balance in isolation instead of against the effects track", "Assuming level automation alone fixes clashes, without carving competing frequencies"], "scenario_contexts": ["Scoring an action scene with heavy sound effects", "Preparing music stems for a busy dub", "Leaving spectral room so effects and score both read clearly"]}, "17fb9cf7-49e4-4e70-938e-01a4dac31312": {"definition": "The channel-coding scheme used to record data on Compact Disc, defined in IEC 60908 (the Red Book). Each 8-bit data byte is translated by a fixed lookup table into a 14-bit channel pattern, and 3 merging bits are inserted between patterns, so that ones are always separated by at least 2 and at most 10 zeros; this run-length constraint keeps pit and land lengths readable and limits low-frequency (DC) content.", "plain_english": "A code used on CDs that turns each group of 8 data bits into a longer 14-bit pattern before it is burned as pits. The rule keeps the marks from being too short or too long, so the player's laser can read them reliably. It is like re-spelling words so a machine never trips over them.", "purpose_function": "It exists to shape the recorded signal so the pits and lands are always a readable length and the data stream stays easy to clock and free of drifting DC, giving reliable CD playback.", "practical_application": "A technician rarely sets EFM by hand but understands that it underlies CD encoding, and that trouble here, seen as a high block-error rate, points to an unreliable disc.", "category": "Disc Encoding", "related_terms": ["Red Book standard", "Cross-Interleaved Reed-Solomon Code (CIRC)", "Block error rate (BLER)", "Subcode (Q channel)", "Pit and land", "Run-length-limited coding"], "common_mistakes": ["Thinking EFM stores audio directly, when it is a channel code applied after error-correction encoding", "Confusing EFM with error correction (CIRC); they do different jobs", "Assuming the 14-bit patterns add data, when they only reshape it for reliable reading"], "scenario_contexts": ["Understanding how audio data is physically encoded on a CD", "Explaining why CD pits have limited minimum and maximum lengths", "Tracing a high-error disc back to its channel coding and readability"]}, "a7161568-eb67-41c3-bb26-4355106ef7f7": {"definition": "A stereo processor used chiefly in disc (vinyl) cutting that progressively sums low-frequency content to mono below a chosen crossover frequency, reducing the out-of-phase (vertical) component of the groove modulation. This narrows the low end toward the centre so the cutter head and the playback stylus are not driven out of the groove by out-of-phase bass.", "plain_english": "A tool used when making vinyl that makes the deep bass come from the centre instead of spreading it left and right. Out-of-phase bass makes the record needle jump, so this keeps the low end centred and steady. It is like tucking the heavy bass into the middle so the groove stays smooth.", "purpose_function": "It exists to keep low-frequency energy in phase and centred so a record can be cut and played back without the stylus mistracking or skipping.", "practical_application": "A cutting engineer sets the elliptical EQ's crossover, often around a couple of hundred hertz, so bass below it collapses to mono, allowing a louder, more stable groove.", "category": "Disc Mastering", "related_terms": ["Disc-cutting engineer", "Cutting lathe", "Vinyl mastering", "Mid-side processing", "Bass mono", "RIAA equalization"], "common_mistakes": ["Confusing it with a tone EQ; it controls the stereo width of the bass, not overall tone", "Setting the crossover too high, collapsing musical stereo information to mono", "Assuming it is only for vinyl, when centred bass also helps club and streaming masters"], "scenario_contexts": ["Preparing a stereo master for vinyl cutting", "Taming out-of-phase bass that would make a groove skip", "Focusing the low end to mono for a punchier, more stable master"]}, "0bfa5940-1e18-4525-b5ba-ed84dd772eb4": {"definition": "The quantitative measurement of how often data errors occur when digital media is read back, used to judge the physical quality of a disc, tape, or transfer. For a manufactured CD it is typically expressed as the Block Error Rate (BLER) — the number of data blocks per second flagged at the C1 stage of error correction — with an industry-recommended maximum average around 220 per second.", "plain_english": "Every disc or tape has tiny flaws that cause read errors. Error-rate measurement counts how many of these errors show up each second when the media is played back. A lower count means a healthier copy that should last longer and play back more reliably.", "purpose_function": "It verifies that a finished master or manufactured copy is physically sound and will read back reliably, catching pressing, burning, or media faults before a product is shipped.", "practical_application": "A mastering or QC engineer runs a manufactured CD or DVD through a disc analyzer and confirms that BLER (for CD) or PI/PO errors (for DVD) stay within accepted limits before approving the run.", "category": "Quality Control", "related_terms": ["Final replication package", "DDP image", "C1/C2 error correction", "Red Book (CD-DA) standard", "Jitter"], "common_mistakes": ["Assuming a disc that plays fine has a low error rate; clean playback can still hide high, correctable error counts that shorten disc life.", "Confusing correctable errors (C1 / BLER) with uncorrectable errors (C2 / E22), which are the truly serious faults.", "Judging quality from one fast read instead of a proper analyzer scan at a controlled speed."], "scenario_contexts": ["Approving a glass master or test pressing before a CD replication run.", "Checking archival optical discs for rising error rates that signal disc rot.", "Comparing burn quality across blank media brands and write speeds for short-run CD-R masters."]}, "83c7915f-7144-40dc-aa19-f551dd70725b": {"definition": "A software brickwall peak limiter plug-in made by FabFilter, used mainly on the mastering bus to raise perceived loudness while preventing the signal from exceeding a chosen output ceiling. The current version, Pro-L 2, offers several limiting algorithms, true peak (inter-sample) limiting, oversampling up to 32x, and integrated loudness metering to EBU R128 / ITU-R BS.1770 (LUFS).", "plain_english": "FabFilter Pro-L is a computer plug-in that acts like a safety wall for volume. It makes a track sound louder but stops the sound from ever going past a level you set, so it does not clip or distort. Mastering engineers use it as the final loudness step.", "purpose_function": "It maximizes loudness and guarantees a safe output ceiling, letting engineers hit streaming and broadcast loudness targets without clipping or inter-sample overshoots.", "practical_application": "An engineer places Pro-L 2 last in the mastering chain, sets an output ceiling (commonly around -1 dBTP), enables true peak limiting, and adjusts gain and limiting style while watching the LUFS meters to reach a delivery target.", "category": "Mastering Plug-in", "related_terms": ["Brickwall limiter", "True peak (dBTP)", "LUFS / integrated loudness", "Oversampling", "Inter-sample peak", "FabFilter Pro-Q"], "common_mistakes": ["Pushing gain far into heavy limiting to chase loudness, which crushes transients and adds distortion and pumping.", "Leaving the ceiling at 0 dBFS, allowing inter-sample true-peak overs that distort after lossy encoding; a ceiling near -1 dBTP is safer.", "Disabling oversampling or true peak limiting and trusting the sample-peak meter to tell the whole story."], "scenario_contexts": ["Setting final loudness and ceiling on a master before export for streaming.", "Comparing limiting algorithms to find the most transparent one for a delicate acoustic mix.", "A/B testing loudness against a reference track while watching integrated LUFS."]}, "046fbf78-ebe1-45a2-88b8-f325b40d640a": {"definition": "A software parametric equalizer plug-in made by FabFilter, used to shape tone by boosting or cutting selected frequency bands. The current version, Pro-Q 4, provides many EQ bands, dynamic EQ, selectable zero-latency, natural-phase and linear-phase processing, mid/side operation, and a real-time spectrum analyzer for precise, frequency-specific control.", "plain_english": "FabFilter Pro-Q is a computer plug-in that lets you turn different pitch ranges of a sound up or down. Think of it as a very precise set of tone controls, from deep bass to high treble. Engineers use it to fix problem frequencies and to polish the overall tone.", "purpose_function": "It gives precise tonal control across the whole frequency range so engineers can correct imbalances, remove resonances, and match tonal targets while mixing and mastering.", "practical_application": "A mastering engineer uses Pro-Q 4 for gentle, wide broadband moves and narrow surgical cuts, often in linear-phase mode on the master bus, and uses dynamic bands to tame resonances only when they spike.", "category": "Mastering Plug-in", "related_terms": ["Parametric equalizer", "Dynamic EQ", "Linear phase", "Mid/side processing", "Q (bandwidth)", "FabFilter Pro-L"], "common_mistakes": ["Making large boosts with a very narrow Q, which sounds unnatural and can ring; mastering EQ moves are usually small and wide.", "Using linear-phase mode everywhere without accounting for its added latency and possible pre-ringing on transients.", "Trusting the spectrum analyzer's shape over the ears and over-correcting toward a flat curve."], "scenario_contexts": ["Applying a broad high-shelf lift to add air to a finished master.", "Using a dynamic band to control a harsh resonance that only appears in loud sections.", "Matching the tonal balance of a mix to a reference using the EQ match feature."]}, "116f1f52-a188-45f1-91f9-a243fe251e2b": {"definition": "In the Dolby Atmos binaural render mode, Far is the setting that renders an object or bed with the greatest amount of binaural (HRTF-based) processing, so it is perceived as the most distant from the listener when the mix is folded down to a binaural headphone stream.", "plain_english": "The Far setting makes a sound feel far away from you when you listen on headphones. It adds the most space processing so the sound seems distant.", "purpose_function": "It lets the mixer assign a distant spatial impression to specific objects in a binaural headphone render, adding depth and separation between near and far sounds.", "practical_application": "In the Dolby Atmos Renderer, a mixer sets ambience, reverb returns, or background elements to Far so they sit back in the binaural image while close elements stay nearer.", "category": "Binaural Render Mode", "related_terms": ["Near binaural setting", "Mid binaural setting", "Binaural render mode", "HRTF", "Dolby Atmos"], "common_mistakes": ["Assuming Far changes level or panning; it only sets the perceived binaural distance for the headphone folddown.", "Expecting the setting to affect the loudspeaker (multichannel) render, when it applies to the binaural stream.", "Forgetting that binaural render mode is set per object and is not automatable during the mix."], "scenario_contexts": ["Placing reverb and ambience beds far back in a binaural music mix.", "Pushing crowd or room tone into the distance on a headphone render.", "Contrasting a close lead vocal (Near) against distant instruments (Far)."]}, "0a012a67-197e-4b04-abb0-8087d16126c8": {"definition": "A featured-score mix is a version of the score mix in which the music is brought forward as a featured, foreground element of the soundtrack, mixed to sit prominently rather than as subtle background underscore, for moments or deliverables where the score is meant to be the focus.", "plain_english": "A featured-score mix is a version where the music is turned up front and center, not kept quietly in the background. It is used when the score is meant to stand out.", "purpose_function": "It gives the dub or picture editor a version with the score foregrounded, so music-led moments land with full impact without rebalancing from scratch.", "practical_application": "A scoring mixer supplies a featured-score mix for montage or music-driven sequences, where the re-recording mixer wants the score prominent over reduced dialogue and effects.", "category": "Score Deliverable", "related_terms": ["Full score mix", "Music stem", "Underscore", "Music-only master", "Theatrical printmaster"], "common_mistakes": ["Confusing a featured-score mix (score foregrounded) with a full score mix (all elements combined at standard balance).", "Pushing the score so far forward that it buries essential dialogue.", "Assuming every scene wants a featured balance, when most underscore should sit under dialogue."], "scenario_contexts": ["Mixing a music-led montage where the score carries the scene.", "Providing a score-forward version for a trailer or promo.", "Featuring the main theme prominently during an emotional climax."]}, "a70f147a-3b52-467b-bbbf-01416fe5ef3b": {"definition": "The magnetic recording layer on analog tape (and early data media) formed from needle-shaped gamma ferric oxide (gamma-Fe2O3) particles suspended in a binder and coated onto a plastic base film. It was the original and most common magnetic pigment, giving standard 'ferric' (Type I) tapes their relatively low coercivity of roughly 300 to 360 oersteds.", "plain_english": "Ferric oxide coating is the brown magnetic layer painted onto recording tape. It is basically a form of rust, made of tiny iron-oxide particles held in glue on a thin plastic ribbon. The recorder magnetizes these particles to store the sound.", "purpose_function": "The coating stores audio (or data) as patterns of magnetization; the particles' magnetic properties set the tape's sensitivity, output level, and noise floor.", "practical_application": "Technicians meet ferric oxide tape when transferring or restoring older reels and Type I cassettes, choosing the correct bias and playback EQ and watching for oxide shedding or level loss on aged stock.", "category": "Recording Media", "related_terms": ["Magnetic tape", "Coercivity", "Bias (tape recording)", "Chromium dioxide (Type II)", "Print-through", "Tape hiss"], "common_mistakes": ["Setting a deck to Type II (chrome) bias and EQ for a ferric tape, which mismatches bias current and skews the tone.", "Assuming all tape hiss is a machine fault when ferric formulations naturally have a higher noise floor than chrome or metal.", "Confusing the plain iron-oxide 'ferric' pigment with later cobalt-doped or metal-particle tapes, which need different settings and handling."], "scenario_contexts": ["Transferring a 1970s ferric reel-to-reel master to digital for a reissue.", "Selecting Type I bias and EQ when dubbing an old ferric cassette.", "Assessing an archival ferric tape for oxide shedding and level loss before playback."]}, "8d0a707d-7846-4888-84c4-f502dd448901": {"definition": "The complete, finalized set of master files and manufacturing instructions delivered to a disc replication plant to press a title. For a CD it typically centers on a verified DDP 2.0 image (with checksum) or a PMCD, together with the PQ/track log, ISRC and UPC/EAN codes, and any label and artwork files the plant needs to build the glass master and packaging.", "plain_english": "The final replication package is everything a factory needs to mass-produce a disc. It holds the finished audio master and the track and timing list. It also holds the ID codes and the artwork. Think of it as a complete recipe kit for the pressing plant.", "purpose_function": "It gives the plant a single, unambiguous, verified source so every pressed copy matches the approved master exactly, with the correct track order, codes, and artwork.", "practical_application": "After a master is approved, the engineer assembles and checksums the DDP image, confirms the ISRC/UPC and PQ data, sends this package to the plant, and keeps an identical verified copy for reference.", "category": "Mastering Deliverable", "related_terms": ["DDP image", "PMCD", "ISRC", "UPC/EAN barcode", "PQ codes", "Error-rate measurement"], "common_mistakes": ["Sending an audio-only file set with no ISRC/UPC or PQ sheet, forcing the plant to guess track IDs and gaps.", "Delivering a DDP image without its checksum, so a corrupted transfer can go undetected.", "Assuming a burned CD-R master is as reliable as a DDP image for replication, when CD-R can introduce read errors."], "scenario_contexts": ["Handing a finished album master to a CD pressing plant.", "Preparing a DDP image plus metadata for a manufacturer's upload portal.", "Archiving the exact approved package so a future repress matches the original."]}, "283e4ef7-4202-4a7a-bea6-9d98b4ffda2d": {"definition": "Data carried alongside a multichannel program that tells a decoder how to combine (fold down) surround or immersive channels into stereo or mono for listeners without full playback systems. In Dolby Digital (AC-3), this includes parameters such as the center and surround mix levels and the choice between Lo/Ro and Lt/Rt downmix coefficients, as defined in the ATSC A/52 standard.", "plain_english": "Not everyone hears a film in full surround sound; many people listen in plain stereo. Fold-down metadata is a set of hidden instructions that tells the player how to squeeze the extra speaker channels down into two. It keeps the dialogue clear and the balance right on smaller systems.", "purpose_function": "It ensures a surround or immersive mix still sounds correct and intelligible when it is automatically collapsed to stereo or mono, giving the creator control over the downmix instead of leaving it to chance.", "practical_application": "A mastering or post engineer sets downmix parameters (for example Lt/Rt versus Lo/Ro and the center/surround levels) when encoding Dolby Digital or preparing streaming deliverables, then checks the folded-down result for level and dialogue balance.", "category": "Metadata", "related_terms": ["Downmix (fold-down)", "Dolby Digital (AC-3)", "Lo/Ro and Lt/Rt", "Dialnorm", "LFE channel", "Surround / immersive mixing"], "common_mistakes": ["Checking only the full surround mix and ignoring the stereo fold-down, so stereo listeners get buried dialogue or a phasey balance.", "Confusing fold-down/downmix metadata with dialnorm (loudness) metadata; they control different things.", "Assuming Lt/Rt and Lo/Ro give the same result, when Lt/Rt is matrix-surround compatible and Lo/Ro is a plain stereo sum."], "scenario_contexts": ["Encoding a 5.1 broadcast mix to Dolby Digital and setting its stereo downmix behavior.", "Checking that a surround film mix still has clear dialogue on a stereo TV.", "Preparing immersive masters so the required stereo fold-downs meet a platform's delivery spec."]}, "c508a9da-73fc-4ac2-8b5b-7113941ef015": {"definition": "A full score mix is the complete, balanced mix of a musical score or cue containing all of its instrument groups together (for example strings, brass, percussion, choir, and soloists), as opposed to individual stems or reduced alternate versions.", "plain_english": "A full score mix is the whole piece of music mixed together with every instrument included. It is the complete version, not a stripped-down one.", "purpose_function": "It serves as the primary, reference version of the music for the dub or final mix, giving editors and re-recording mixers the composer's intended balance in a single stereo or multichannel file.", "practical_application": "A composer or scoring mixer delivers the full score mix alongside stems and alternate mixes, and the re-recording mixer places it under picture, adjusting level against dialogue and effects.", "category": "Score Deliverable", "related_terms": ["Featured-score mix", "Music stem", "Music-only master", "Theatrical printmaster", "Stem"], "common_mistakes": ["Confusing the full score mix (everything combined) with individual score stems (separate element groups).", "Delivering only the full mix when the dub also needs stems and alternates for flexibility.", "Assuming the full-mix level is final, when it is still balanced against dialogue and effects at the dub."], "scenario_contexts": ["Delivering the composer's complete cue for the final dub.", "Referencing the intended balance before rebalancing stems.", "Supplying a full mix for a soundtrack album master."]}, "62062160-f5d7-4665-b95a-1170315f0d22": {"definition": "In disc (vinyl) cutting, the lateral and/or vertical displacement of the modulated groove away from its unmodulated centerline; the peak excursion determines how far the groove swings and thus how much lacquer space each groove turn needs.", "plain_english": "When a record is cut, the audio makes the groove wiggle from side to side. Groove excursion is how far that wiggle swings out from the middle. Louder, deeper sounds swing it wider, so they take up more room.", "purpose_function": "It measures the physical size of the cut modulation, which decides whether adjacent grooves stay clear of each other and how loud a side can be cut.", "practical_application": "A cutting engineer watches groove excursion through the microscope, meters, and the pitch computer to stop adjacent grooves from overlapping and to keep bass and level within cuttable limits.", "category": "Disc Cutting", "related_terms": ["Groove modulation", "Groove velocity", "Groove-pitch control", "Groove-spacing computer", "Groove-depth control"], "common_mistakes": ["Confusing groove excursion (how far the groove swings sideways) with groove depth (how deep it is cut).", "Assuming heavy low-frequency or wide stereo content can be cut at any level, when large excursions force wider spacing and shorten playing time.", "Thinking excursion only limits loudness, when excessive excursion also causes mistracking on playback."], "scenario_contexts": ["Cutting a bass-heavy dance track where large low-frequency excursions threaten to make adjacent grooves collide.", "Setting the lathe's preview system so groove spacing widens automatically when excursion increases.", "Diagnosing why a test lacquer skips and tracing it to excessive groove excursion at high level."]}, "27e94fca-89b4-413f-8463-157dfa5bcffa": {"definition": "The adjustment of a groove's physical shape and layout during disc cutting - its depth, pitch (spacing), width, and wall angle - to maximize playing time and playback quality while keeping the groove reliably trackable.", "plain_english": "A record's groove has a shape and spacing that can be fine-tuned. Optimizing groove geometry means setting the depth and spacing so the music fits, stays loud, and plays cleanly. It is like packing a suitcase so everything fits without getting crushed.", "purpose_function": "It balances competing needs - loudness, playing time, and clean tracking - by shaping and spacing grooves to suit the specific program material.", "practical_application": "Engineers use variable pitch and depth control, often driven by the lathe's computer, to reshape groove geometry passage by passage across a side.", "category": "Disc Cutting", "related_terms": ["Groove-pitch control", "Groove-depth control", "Groove-spacing computer", "Groove excursion", "Groove modulation"], "common_mistakes": ["Maximizing loudness with no regard to playing time, so grooves crowd and quality suffers.", "Believing geometry tweaks can rescue a mix with excess bass or out-of-phase low end that is simply uncuttable.", "Treating one fixed pitch and depth setting as ideal for a whole side instead of varying it with the program."], "scenario_contexts": ["Fitting a long album side onto a 12-inch disc by tightening groove spacing during quiet passages.", "Cutting a loud single with wide spacing so high modulation does not cause groove collisions.", "Preparing a reference lacquer and trading a little level for more playing time by adjusting pitch and depth."]}, "b0ac34f3-6b67-46e3-8e60-5c1d9845b942": {"definition": "A raised ridge molded into a phonograph record - pioneered by RCA Victor - that lifts the outer edge and label area slightly above the grooved playing surface, so stacked or slipped discs contact each other only at the ridge and not on the grooves.", "plain_english": "On many records the outer rim and the area around the label sit a little higher than the grooves. This raised ridge, called a groove guard, keeps stacked records from rubbing their grooves together. It works like a raised frame that keeps a picture off the glass.", "purpose_function": "It protects the delicate grooves from scuffs and wear when records are stacked, slid, or handled, by keeping the playing surface off other surfaces.", "practical_application": "Technicians and archivists recognize the groove-guard ridge when handling and storing LPs, which is why stacked discs rest on their rims rather than on their grooves.", "category": "Vinyl Records", "related_terms": ["Lacquer", "Pressing", "Stylus", "Groove modulation", "Warp"], "common_mistakes": ["Mistaking the raised groove-guard ridge for a manufacturing defect or a warp.", "Assuming the groove guard makes stacking records safe, when stacking still risks warping and scratches.", "Confusing the molded groove-guard ridge on the disc with anti-static inner sleeves sold under similar names."], "scenario_contexts": ["Inspecting an LP and noticing the outer rim and label area sit higher than the grooves.", "Explaining to a client why some pressings resist groove-to-groove contact when slipped from a sleeve.", "Archiving records and relying on the groove-guard ridge to reduce surface wear in storage."]}, "fbdd7c20-42c9-4444-bd11-fdc2848a4326": {"definition": "The variation impressed on the groove walls during cutting that encodes the audio signal; in mono lateral cutting the groove swings side to side, while in 45/45 stereo each of the two groove walls carries one channel.", "plain_english": "The audio is stored as tiny wiggles carved into the groove walls. That patterned wiggle is the groove modulation. On stereo records, each of the two walls carries one side of the sound.", "purpose_function": "It is the mechanism that physically records sound onto a disc and reads it back - the stylus follows the modulation and turns it into an electrical signal.", "practical_application": "When cutting, engineers monitor modulation level and phase to keep it trackable; on playback, the cartridge stylus traces the modulation to recover the audio.", "category": "Disc Cutting", "related_terms": ["Groove excursion", "Groove velocity", "Groove-pitch control", "Stylus", "Cutter head"], "common_mistakes": ["Confusing groove modulation (the encoded wiggle) with groove pitch (the spacing between turns).", "Cutting heavy out-of-phase low frequency, which in stereo makes large vertical modulation that lifts the stylus and causes skipping.", "Assuming louder modulation is always better, ignoring that over-modulation causes distortion and mistracking."], "scenario_contexts": ["Checking modulation level and phase on the console before committing a cut to lacquer.", "Troubleshooting a pressing that skips because of excessive vertical modulation from out-of-phase bass.", "Explaining how a cartridge stylus reads the two groove walls of a stereo record."]}, "60e93167-c1ed-4b3e-be99-ffe74bcd01fa": {"definition": "In disc recording, the instantaneous velocity (rate of displacement) of the groove modulation - the lateral or vertical speed at which the groove wall moves the stylus; disc systems are essentially constant-velocity above the turnover frequency, so cutting levels are specified as peak velocity in cm/s.", "plain_english": "A record stores sound as a moving groove wall. Groove velocity is how fast that wall pushes the stylus sideways, not just how far. It matters because the pickup reacts to the speed of the motion, so cutting levels are measured in centimeters per second.", "purpose_function": "It is the quantity that magnetic pickups and the RIAA cutting and playback curve are built around, so it sets recorded level and helps define safe cutting limits.", "practical_application": "Engineers reference peak groove velocity in cm/s when setting cutting levels and reading test records, since high-frequency energy at high velocity can overload the cutter head and cause mistracking.", "category": "Disc Cutting", "related_terms": ["Groove modulation", "Groove excursion", "RIAA equalization", "Cutter head", "Groove-pitch control"], "common_mistakes": ["Confusing groove velocity (the speed of the groove modulation) with the disc's linear surface speed under the stylus.", "Ignoring that a given amplitude produces higher velocity at higher frequencies, so bright content can overload the cutter.", "Assuming inner-groove tracks sound the same as outer ones, when lower linear velocity near the center raises distortion."], "scenario_contexts": ["Setting cutting level to a target peak velocity in cm/s while reading the lathe's meters.", "Checking a test record whose bands are specified at known recorded velocities.", "Deciding to place bright, high-level material earlier on a side to avoid inner-groove trouble."]}, "0e2c3eef-665c-46f5-a7c1-8a777e90a2f2": {"definition": "On a disc-cutting lathe, control of how deeply the cutting stylus penetrates the lacquer; variable-depth systems reduce cut depth in quiet passages and increase it for louder modulation, working with pitch control to conserve space.", "plain_english": "When a record is cut, the stylus can dig shallower or deeper into the blank. Groove-depth control sets that depth, cutting shallower in quiet parts so less material is carved out. It is like scooping a shallower channel where the sound is soft.", "purpose_function": "It keeps the groove deep enough to hold the stylus and carry modulation, while shaving unused depth in quiet parts so more program fits on a side.", "practical_application": "Engineers set a safe minimum depth for reliable tracking and let the lathe increase depth automatically as modulation grows, coordinated with pitch to avoid groove collisions.", "category": "Disc Cutting", "related_terms": ["Groove-pitch control", "Groove-spacing computer", "Groove excursion", "Groove modulation", "Lacquer"], "common_mistakes": ["Cutting too shallow to save space, so the stylus mistracks or the groove is too weak to hold it.", "Confusing depth control (the vertical cut) with pitch control (the horizontal spacing between grooves).", "Forgetting that deeper cuts remove more lacquer and place more demand on the cutting stylus."], "scenario_contexts": ["Setting a minimum groove depth so a quiet classical passage still tracks reliably.", "Letting depth rise automatically during a loud chorus while spacing widens to match.", "Trimming cut depth in quiet intros to help a long side fit the disc."]}, "716bca86-08c2-4788-87d1-a4c55098bdd6": {"definition": "On a disc-cutting lathe, control of pitch - the number of groove turns per inch, i.e., the spacing between adjacent grooves; variable-pitch systems widen the spacing for loud, large-excursion passages and narrow it for quiet passages to maximize playing time.", "plain_english": "A record is one long spiral groove. Groove-pitch control sets how close together the spiral turns are. Loud parts need wider spacing, while quiet parts can be packed tight to fit more music on a side.", "purpose_function": "It trades playing time against modulation room, spacing grooves just far enough apart to avoid collisions while packing them tightly where the signal is small.", "practical_application": "Engineers rely on variable pitch, usually driven by the preview computer, to fit long sides without adjacent grooves cutting into one another.", "category": "Disc Cutting", "related_terms": ["Groove-depth control", "Groove-spacing computer", "Groove excursion", "Groove modulation", "Lacquer"], "common_mistakes": ["Confusing groove pitch (the spacing between grooves) with musical pitch or with groove depth.", "Setting too tight a fixed pitch for a loud program, so adjacent grooves overlap (overcutting).", "Assuming maximum playing time is free, when very tight pitch lowers achievable level and safety margin."], "scenario_contexts": ["Widening pitch through a loud, bass-heavy chorus to keep grooves from colliding.", "Tightening pitch during quiet passages to squeeze a long side onto the disc.", "Setting up the lathe so pitch tracks the preview signal automatically during the cut."]}, "3f0564b9-0c66-4209-a415-26be3daf1b18": {"definition": "The preview-driven automatic pitch-and-depth control system on a disc-cutting lathe (Neumann branded it the \"computer\") that reads the program about one revolution ahead, via a tape preview head or delay, and continuously sets groove spacing and depth so grooves never collide while playing time is maximized.", "plain_english": "A cutting lathe gets a sneak preview of the audio a moment early. A small computer uses that preview to decide how far apart to space each groove turn. This lets loud parts spread out and quiet parts pack tight automatically.", "purpose_function": "It automates variable pitch and depth, using advance knowledge of the signal to prevent adjacent-groove collisions while fitting the longest possible program on a side.", "practical_application": "The engineer feeds the lathe a preview signal from a tape preview head or digital delay and sets minimum and maximum limits, and the computer then manages groove spacing in real time during the cut.", "category": "Disc Cutting", "related_terms": ["Groove-pitch control", "Groove-depth control", "Groove excursion", "Groove modulation", "Cutter head"], "common_mistakes": ["Cutting without the correct preview delay, so the computer spaces grooves for the wrong moment and grooves collide.", "Assuming the computer can fix an uncuttable master, when it only manages spacing and cannot remove excess bass or level.", "Confusing the pitch and depth computer with playback equalization or level automation."], "scenario_contexts": ["Aligning the preview delay so the computer spaces grooves for the correct upcoming passage.", "Setting minimum and maximum pitch limits before starting an automatic cut.", "Relying on the computer to fit a long side while keeping loud sections collision-free."]}, "e1fc5d81-5fb6-4211-a03b-e501a93de3f8": {"definition": "In stem mastering, a stem (submix bounce) containing the harmonic or tonal instruments of a track - such as chords from keys, guitars, and pads - kept separate from vocals, bass, and drums so the mastering engineer can process it independently.", "plain_english": "A song's parts can be grouped and bounced out as separate files. The harmonic music stem is the group holding the chord instruments, like keys, guitars, and pads. It lets the mastering engineer tweak those sounds without touching the vocals or drums.", "purpose_function": "It gives the mastering engineer separate control over the song's harmony layer, allowing balance and tone changes that a single stereo mix would not allow.", "practical_application": "When a client sends stems, the engineer loads the harmonic stem alongside the vocal, drum, and bass stems and adjusts its level and EQ to fit the master.", "category": "Stem Mastering", "related_terms": ["Stem mastering", "Submix", "Vocal stem", "Drum stem", "Mixdown"], "common_mistakes": ["Overlapping content between stems, such as the same guitar appearing in two stems, so they no longer sum back to the intended mix.", "Adding heavy master-bus processing to individual stems before export, which limits what the mastering engineer can do.", "Confusing a harmonic stem (a group of instruments) with individual multitrack files or with a full mixdown."], "scenario_contexts": ["A client delivers vocal, drum, bass, and harmonic stems for stem mastering instead of one stereo mix.", "Lowering a busy harmonic stem slightly so the vocals sit forward in the final master.", "EQing the harmonic stem to reduce midrange buildup without affecting the drum or bass stems."]}, "69b8620c-33ad-45f1-aaf9-c52555c734ff": {"definition": "A binaural, two-channel version of an immersive object-based master, generated by the immersive renderer, that folds the 3D mix down for headphone playback using head-related processing so listeners perceive height and surround cues over ordinary headphones.", "plain_english": "A headphone version made from a 3D surround mix. Special software squeezes all the sounds placed around and above you into two channels for your earbuds. It uses facts about how ears hear direction, so the mix still feels like it wraps around your head.", "purpose_function": "It exists so an immersive mix can be heard on everyday headphones, which is how most people hear spatial music on streaming services, without needing a room full of speakers.", "practical_application": "In an Atmos session the engineer sets each object's binaural distance mode, then exports the headphone re-render from the renderer and checks it against the speaker mix before delivery.", "category": "Immersive Mastering", "related_terms": ["Binaural rendering", "Dolby Atmos", "ADM BWF", "Object-based audio", "Immersive distribution master", "Stereo fold-down"], "common_mistakes": ["Assuming the headphone re-render sounds identical to the speaker mix, when binaural processing changes tone and space", "Leaving object binaural distance settings at default, so height and depth cues are wrong", "Delivering only the immersive master and forgetting to QC the headphone render, a common cause of rejection"], "scenario_contexts": ["Exporting a binaural headphone mix from a Dolby Atmos session for streaming", "Checking how an immersive master translates to earbuds before release", "Comparing the headphone re-render to the speaker layout to fix collapsed imaging"]}, "a452bcbe-1114-4184-a03d-255c134cb382": {"definition": "A piece of audio deliberately placed on a release so it is not shown in the tracklist, typically concealed either in the pregap before the first track or after an extended silence following the last listed track, exploiting the disc's index and pause structure.", "plain_english": "A secret song an album does not list. It is often tucked before the first track or after a long silence at the very end. You find it by rewinding past the start or letting the last track keep playing.", "purpose_function": "It exists as a creative or bonus surprise for listeners, rewarding people who explore the whole disc rather than stopping at the last named song.", "practical_application": "When assembling a CD master, the engineer places the hidden audio in the pregap of track one or adds a long silent gap and then the extra track, setting the index and PQ codes so players handle it correctly.", "category": "CD Mastering", "related_terms": ["Pregap", "PQ codes", "Red Book standard", "Track indexing", "Disc-at-once mastering", "Lead-out"], "common_mistakes": ["Placing a hidden track in the pregap without testing, since many players and rippers cannot access negative-index audio", "Using a very long silent gap that some players skip or that fails plant QC", "Forgetting that streaming and downloads have no pregap, so the trick does not transfer"], "scenario_contexts": ["Hiding a bonus track in the pregap before track one of a CD", "Adding a secret song after minutes of silence on the final track", "Explaining to a client why a CD hidden track will not survive digital distribution"]}, "7bc3e29a-961c-4453-a976-0050b1960ebf": {"definition": "Magnetic tape, notably IEC Type II cassette tape, using higher-coercivity particles such as chromium dioxide or cobalt-modified ferric oxide, which require a stronger recording bias current and use 70-microsecond playback equalization, giving improved high-frequency response and lower noise than standard ferric Type I tape.", "plain_english": "A better-quality tape that needs a stronger hidden helper signal, called bias, while recording. Its magnetic coating holds sound more firmly, so it captures bright treble and hisses less. Cassette decks have a high-bias or chrome switch for it.", "purpose_function": "It exists to extend high-frequency range and reduce hiss, letting a cassette or tape store more detail and a wider dynamic range than basic ferric tape.", "practical_application": "A technician sets the deck to the Type II high-bias position, or lets it auto-detect the cassette's keying notches, so bias and EQ match the tape and the recording plays back flat.", "category": "Recording Media", "related_terms": ["Type II tape", "Tape bias", "Chromium dioxide", "High-output tape", "Tape equalization", "Coercivity"], "common_mistakes": ["Recording high-bias tape on a deck set to normal bias, which over-brightens and distorts the sound", "Confusing higher bias with higher output, which are separate tape properties", "Assuming all Type II tape is chrome, when many are cobalt-doped ferric so-called pseudo-chrome"], "scenario_contexts": ["Selecting the high-bias setting when recording a chrome cassette", "Calibrating a cassette deck's bias and EQ for Type II tape", "Restoring or transferring an old chrome cassette with the correct 70-microsecond EQ"]}, "00e861d0-1f52-46b3-ae1d-200f790480ff": {"definition": "A stem, meaning a grouped submix bounced as a separate file, that carries the high-frequency portion of a production's music, whether the naturally bright high-register instruments grouped together or the treble band of a frequency-split music mix, kept separate so it can be balanced or processed on its own.", "plain_english": "A separate music mix that holds just the bright, high-pitched sounds, like cymbals, hi-hats, and airy synths. Keeping the treble part on its own track lets an engineer turn it up, down, or reshape it without touching the rest. It is like putting all the sparkly sounds in their own bucket.", "purpose_function": "It exists so the top end of the music can be adjusted on its own during mastering, re-mixing, or re-versioning without reopening the full session.", "practical_application": "A mastering or dubbing engineer receives the high-frequency music stem alongside other stems and rides or EQs it to fix a dull or harsh top end without disturbing the low and mid content.", "category": "Stem Mastering", "related_terms": ["Stem mastering", "Submix", "Multiband processing", "Frequency splitting", "Music stem", "Bus"], "common_mistakes": ["Assuming a stem is a single instrument, when it is a grouped submix of related content", "Boosting the high-frequency stem without checking for added hiss or sibilance", "Summing stems that were processed on the master bus, so the recombined mix no longer matches the original"], "scenario_contexts": ["Delivering frequency-split music stems for flexible mastering", "Brightening only the top-end music without affecting bass in a remaster", "Rebalancing airy elements for a broadcast or instrumental version"]}, "594e1301-038d-4671-8f05-fedd4d8b7a0b": {"definition": "Analog magnetic tape whose formulation, using finer and more densely packed magnetic particles, yields a higher maximum output level before saturation, allowing recording at an elevated operating level or reference fluxivity for a better signal-to-noise ratio; classic examples include Ampex/Quantegy 456, 499/GP9 and 3M 250.", "plain_english": "A tape that can be recorded louder before it distorts. Because it takes a hotter signal, the music sits further above the tape's background hiss, so recordings sound cleaner. Engineers set their machines to a higher reference level to use it.", "purpose_function": "It exists to raise the level a tape can hold cleanly, improving dynamic range and reducing audible hiss on masters and multitrack recordings.", "practical_application": "An engineer calibrates the tape machine to the higher operating level the tape is rated for, for example +6 or +9 over the 185 nWb/m standard, so the extra headroom and lower noise are actually realized.", "category": "Recording Media", "related_terms": ["Operating level", "Reference fluxivity", "Tape bias", "Signal-to-noise ratio", "High-bias tape", "Tape saturation"], "common_mistakes": ["Running high-output tape at a low reference level, wasting the headroom it was made for", "Confusing high output with high bias, since output is level capacity and bias is a recording adjustment", "Playing a high-output master on a machine calibrated to a lower fluxivity, so levels read wrong"], "scenario_contexts": ["Choosing high-output tape for a low-noise master", "Calibrating a multitrack to a tape's elevated operating level", "Transferring an archived high-output master with the correct reference fluxivity"]}, "0140e6c1-72aa-45d0-a1e4-7915ea4eec7d": {"definition": "A line of professional audio processing plugins from the German company HOFA, comprising feature-rich tools for mixing and mastering, including an EQ, compressor, true-peak limiter, de-esser, transient shaper, reverb and spectrum analyser, noted for dynamic, mid/side and linear-phase processing and detailed visual metering.", "plain_english": "A set of studio software tools made by a company called HOFA. It includes an EQ, a compressor, a loudness limiter, and more, each with a clear visual display. Engineers use them to polish and finalize songs.", "purpose_function": "It exists to give mixing and mastering engineers a matched, high-quality toolkit with modern features like true-peak limiting and mid/side control across one plugin family.", "practical_application": "A mastering engineer might shape tone with the IQ-Series EQ, control dynamics with the IQ-Series Comp, and set final loudness and true-peak ceiling with the IQ-Series Limiter before export.", "category": "Mastering Software", "related_terms": ["True peak limiter", "Mid-side processing", "Linear-phase EQ", "De-esser", "Spectrum analyzer", "Mastering chain"], "common_mistakes": ["Treating the intelligent automatic settings as final instead of adjusting them by ear", "Stacking linear-phase EQ without noticing the added latency or pre-ringing", "Pushing the limiter for loudness until true-peak overs and distortion appear"], "scenario_contexts": ["Assembling a mastering chain from the IQ-Series plugins", "Setting a true-peak safe loudness target for streaming with the IQ-Series Limiter", "Using mid/side EQ to widen a mix during mastering"]}, "efea973e-24ca-4771-9333-a3894a47d898": {"definition": "The preservation-grade master of an immersive object-based mix retained for long-term archiving, typically the full-resolution Dolby Atmos master (DAMF file set or ADM BWF) that holds all audio objects, beds and 3D metadata so any future deliverable or re-render can be regenerated from it.", "plain_english": "The keeper copy of a 3D surround mix, saved for the future. It stores every sound, its position in space, and all the extra data, at full quality. Because nothing is thrown away, new versions can be made from it later.", "purpose_function": "It exists so the complete immersive mix, with all its spatial information intact, is preserved and can be re-rendered into new formats years later without remixing.", "practical_application": "After a session the engineer archives the ADM BWF or Atmos master file set as the source of truth, from which distribution masters and re-renders are produced now and in the future.", "category": "Immersive Mastering", "related_terms": ["ADM BWF", "Dolby Atmos", "Immersive distribution master", "Object-based audio", "Re-render", "Master archiving"], "common_mistakes": ["Archiving only a stereo or binaural render, which cannot rebuild the full immersive mix", "Saving the master without its metadata, so object positions are lost", "Assuming the distribution master and the archive master are always the same file"], "scenario_contexts": ["Storing the full-resolution Atmos master for long-term preservation", "Regenerating a new re-render years later from the archived immersive master", "Delivering an archive master to a label's asset library"]}, "8db77e0e-bbef-41ea-9cb4-8f35d0e1b650": {"definition": "The verification stage for immersive audio deliverables, in which the master and its re-renders such as binaural, 5.1 and stereo are checked for correct loudness and true-peak levels, valid spatial metadata and object settings, format conformance and clean playback before the files are submitted for distribution.", "plain_english": "The final checking of a 3D mix before it is sent out. The engineer confirms the loudness is right, the sound positions are correct, and every version plays properly. It is like proofreading a document before you hand it in.", "purpose_function": "It exists to catch metadata, loudness, and format errors that would otherwise get the immersive files rejected by a platform or sound wrong to listeners.", "practical_application": "Before delivery the engineer meters integrated loudness and true peak in the renderer, audits the binaural and surround re-renders, and checks file naming and metadata against the platform's specification.", "category": "Immersive Mastering", "related_terms": ["Loudness normalization", "True peak", "ADM BWF", "Headphone re-render", "Immersive distribution master", "Metadata validation"], "common_mistakes": ["Skipping the binaural re-render check, a leading cause of platform rejection", "Meeting the loudness target but missing an over-the-limit true peak", "Trusting default metadata instead of verifying object and binaural settings"], "scenario_contexts": ["QC of an Atmos master and its re-renders before uploading to a streaming platform", "Catching a true-peak overshoot on the binaural render during final checks", "Verifying metadata and file naming against a distributor's delivery spec"]}, "d97135c3-664f-4eee-a20c-e5a7bca2ecaf": {"definition": "The immersive master prepared and formatted for distribution to streaming platforms or broadcasters, most commonly the ADM BWF Dolby Atmos file meeting the target platform's specification such as 48 kHz/24-bit with defined loudness and true-peak limits, from which the service encodes its consumer immersive stream.", "plain_english": "The version of a 3D mix that is actually sent to streaming services. It is packaged in the exact format and loudness a platform requires, so the service can turn it into what listeners stream. Think of it as the ready-to-ship copy.", "purpose_function": "It exists to hand distributors a conformed, spec-compliant immersive file they can ingest and encode, keeping the release consistent across platforms.", "practical_application": "The engineer exports an ADM BWF from the renderer at the required sample rate, loudness and true-peak targets, names it per the platform's rules, and uploads it as the immersive deliverable.", "category": "Immersive Mastering", "related_terms": ["ADM BWF", "Dolby Atmos", "Immersive archive master", "Headphone re-render", "Loudness normalization", "Immersive delivery quality control"], "common_mistakes": ["Delivering the raw archive master without conforming it to the platform's loudness and format spec", "Exporting from the DAW instead of the renderer, producing an invalid ADM file", "Forgetting the stereo fallback that platforms require alongside the immersive master"], "scenario_contexts": ["Exporting an ADM BWF distribution master for Apple Music or Tidal", "Conforming an immersive mix to a platform's loudness and true-peak spec", "Uploading the immersive deliverable plus its stereo fallback to a distributor"]}, "ad543a93-c4c3-43c5-9b1c-09dc6759b692": {"definition": "A finished master delivered in an immersive, three-dimensional audio format—channel-based (such as 7.1.4) or object-based (such as Dolby Atmos)—that positions sounds around and above the listener rather than only left-to-right as in stereo.", "plain_english": "It is the final version of a song made for surround sound that wraps around you. Instead of sound coming only from the left and right, it can also seem to come from the sides, behind you, and above your head.", "purpose_function": "It exists so listeners on surround or headphone systems can hear music with height and space, giving the mastering engineer a spatial deliverable beyond traditional stereo.", "practical_application": "A mastering engineer prepares and checks the immersive render, confirming loudness, true-peak limits, and the binaural fold-down before delivering it to a label or streaming platform.", "category": "Immersive Mastering", "related_terms": ["Stereo master", "Dolby Atmos", "Binaural render", "Immersive stem export", "Immersive streaming master", "True peak"], "common_mistakes": ["Assuming a good stereo master automatically translates to immersive without a dedicated immersive mix.", "Ignoring the binaural fold-down, so headphone listeners hear a poor version.", "Delivering above the platform's loudness or true-peak targets, causing rejection or clipping.", "Confusing channel-based (fixed-speaker) formats with object-based formats like Dolby Atmos."], "scenario_contexts": ["Mastering a Dolby Atmos Music version of an album for Apple Music, Tidal, or Amazon Music.", "Preparing a 7.1.4 channel-based master for a film or live event.", "Checking the binaural render so headphone listeners get a usable mix.", "Delivering both a stereo and an immersive master of the same release."]}, "c7623b9d-0eb6-4137-afcb-ae4b0723e953": {"definition": "The complete set of deliverable files for an immersive release, typically including the object-based master file (such as an ADM BWF or Dolby Atmos master file), a binaural render, any required re-renders (for example 5.1 or 7.1.4), and the associated metadata.", "plain_english": "It is the full bundle of files you hand over for a surround-sound release. It holds the main immersive file plus extra versions and notes, so the label or streaming service has all it needs.", "purpose_function": "It gathers every file and specification a platform or client needs, so an immersive release can be checked, stored, and distributed without missing parts.", "practical_application": "A mastering engineer assembles the package to a platform's delivery spec, naming files correctly and including the ADM BWF, binaural render, and metadata before upload or handoff.", "category": "Immersive Mastering", "related_terms": ["Immersive master", "ADM BWF", "Binaural render", "Immersive stem export", "Delivery specification", "Metadata"], "common_mistakes": ["Delivering only the master file and forgetting required re-renders or the binaural version.", "Using wrong file names or folder structure that fails the platform's automated checks.", "Leaving out or mislabeling metadata such as the title, ISRC, or loudness values.", "Assuming one package fits every platform when the specs differ."], "scenario_contexts": ["Assembling a Dolby Atmos delivery package for Apple Music.", "Handing a client all immersive files and re-renders for archiving.", "Passing QC by matching a platform's exact folder and naming spec.", "Including a binaural render so headphone playback is covered."]}, "2f46027a-33a2-4b82-ace4-b6b8fa282d10": {"definition": "The process of rendering grouped sub-mixes (stems)—such as drums, bass, vocals, and music beds—out of an immersive session while preserving their spatial or object positioning, so they can be recombined or re-mixed later.", "plain_english": "It means saving a surround-sound project as a few grouped tracks instead of one file. Each group, like drums or vocals, keeps its place in the 3D space, so someone can rebuild or tweak the mix later.", "purpose_function": "It provides editable spatial building blocks for remixing, re-versioning, archiving, or handing a project to another engineer without the original session.", "practical_application": "An engineer exports immersive stems to a client's or platform's spec so a track can be re-mixed, used in a trailer, or updated without opening the full immersive session.", "category": "Immersive Mastering", "related_terms": ["Stem", "Immersive master", "Immersive mix package", "ADM BWF", "Object-based audio", "Re-render"], "common_mistakes": ["Exporting stems that no longer sum back to the reference mix because of master-bus processing.", "Losing object or height information by folding down to a flat channel layout.", "Inconsistent start times or sample rates between stems.", "Forgetting to document the speaker layout or object mapping each stem uses."], "scenario_contexts": ["Delivering immersive stems for a remix or trailer edit.", "Archiving a project as spatial stems for future re-versioning.", "Handing stems to another studio that lacks the original session.", "Rebuilding an immersive mix from stems when the source project is unavailable."]}, "1a98f5bb-0fc4-4c17-bc99-55b63834f11c": {"definition": "An immersive master prepared specifically for streaming delivery, conformed to a streaming platform's technical specification—commonly an ADM BWF Dolby Atmos master meeting the service's loudness, true-peak, and metadata requirements.", "plain_english": "It is a surround-sound version made to fit the exact rules of a streaming service. It follows their limits for loudness and peaks, so it plays back correctly on phones, speakers, and headphones.", "purpose_function": "It ensures an immersive release meets a streaming platform's playback and loudness rules, so it is accepted and sounds consistent across devices.", "practical_application": "A mastering engineer conforms the immersive master to a platform's Dolby Atmos spec—checking integrated loudness, true-peak ceiling, and metadata—before delivering the streaming version.", "category": "Immersive Mastering", "related_terms": ["Immersive master", "ADM BWF", "Loudness normalization", "True peak", "Binaural render", "Delivery specification"], "common_mistakes": ["Exceeding the platform's loudness or true-peak targets and getting the file rejected.", "Skipping the binaural render check that headphone playback relies on.", "Mismatched or missing metadata causing failed ingestion.", "Assuming stereo streaming targets and immersive targets are the same."], "scenario_contexts": ["Delivering a Dolby Atmos Music master to Apple Music, Amazon Music, or Tidal.", "Meeting a streaming service's loudness spec so the immersive version matches the catalog.", "QC checking true-peak before upload to avoid clipping on consumer devices.", "Re-delivering after a platform rejects a master for spec violations."]}, "d67997b5-3468-4984-8ff0-1ed275209fcf": {"definition": "In the Compact Disc (Red Book / IEC 60908) subcode standard, INDEX 01 is the index point that marks the true start of a track's program audio; playback and track-time counting begin here, immediately after any pre-gap marked by INDEX 00.", "plain_english": "On a CD, Index 01 is the spot where a song actually starts playing. It sits just after the short silent gap before the track, and it is where the timer starts counting the song.", "purpose_function": "It defines the exact audio start of each track for players and for the disc's timing, separating the counted program material from the silent pre-gap.", "practical_application": "During CD mastering (PQ editing), the engineer places INDEX 01 markers at each song's start so track times, spacing, and pre-gaps are correct on the final disc and DDP.", "category": "CD Mastering", "related_terms": ["Index zero", "Red Book", "PQ codes", "Track marker", "Pre-gap", "DDP"], "common_mistakes": ["Placing INDEX 01 late so the very start of the song is cut off or delayed.", "Confusing INDEX 00 (pre-gap) with INDEX 01 (track start).", "Leaving inconsistent pre-gaps between tracks on an album.", "Assuming index points are audible edits rather than subcode timing markers."], "scenario_contexts": ["Setting track starts during CD PQ editing before making a DDP.", "Adjusting a pre-gap so a live album flows without unwanted silence.", "Troubleshooting a disc where a player skips past the first moment of a song.", "Matching index points to a client's track list and timing sheet."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"19c79b98-d21f-43f6-84ab-e8c52772b587": {"definition": "In the Compact Disc (Red Book / IEC 60908) subcode standard, INDEX 00 marks a track's pre-gap—the transitional region (often silent) between the previous track and the start of program audio at INDEX 01; time within it typically counts down to the track start.", "plain_english": "On a CD, Index 00 is the short gap right before a song begins. It is usually silence, and its timer counts down to the moment the song starts.", "purpose_function": "It defines the pause or lead-in before each track, letting the disc hold silence or run-in audio that is separate from the counted program material.", "practical_application": "In PQ editing the engineer sets INDEX 00 to control the gap before each song, choosing standard pre-gaps or hidden lead-in audio as the project needs.", "category": "CD Mastering", "related_terms": ["Index one", "Red Book", "PQ codes", "Pre-gap", "Track marker", "DDP"], "common_mistakes": ["Confusing INDEX 00 (pre-gap) with INDEX 01 (song start).", "Setting an unwanted gap that breaks the flow between continuous tracks.", "Forgetting that pre-gap time usually counts down, not up.", "Assuming every track needs a two-second gap when live or continuous albums may not."], "scenario_contexts": ["Creating gapless transitions on a live or concept album.", "Placing a standard pre-gap between separate songs.", "Hiding a lead-in or count-in inside the pre-gap region.", "Diagnosing an unexpected silence a listener hears before a track."]}, "22de5431-a312-4ad5-ad07-1ce1eeaa57ee": {"definition": "The metering and audio-analysis functionality of iZotope Insight, a software suite used in mixing, mastering, and post production that provides loudness metering to broadcast standards (ITU-R BS.1770 / EBU R128), true-peak metering, spectral analysis (spectrogram), and stereo-imaging displays.", "plain_english": "It is a software tool that shows clear meters and graphs of your sound. It measures loudness, peaks, and the balance across pitches and between left and right, so you can see problems your ears might miss.", "purpose_function": "It gives engineers accurate, standards-based visual feedback on loudness, peaks, spectrum, and stereo balance, so a master can be checked against delivery targets rather than judged by ear alone.", "practical_application": "A mastering engineer places it on the master bus to confirm integrated loudness and true-peak against a platform's spec and to spot tonal or imaging issues while working.", "category": "Metering", "related_terms": ["Loudness metering", "True peak", "LUFS", "Spectrogram", "EBU R128", "Vectorscope"], "common_mistakes": ["Reading momentary or short-term loudness when the platform target is integrated (program) loudness.", "Trusting sample-peak instead of true-peak, allowing inter-sample overs.", "Chasing a number on the meter while ignoring how the master actually sounds.", "Forgetting to set the meter to the correct loudness standard for the target platform."], "scenario_contexts": ["Checking a master's integrated loudness and true-peak before delivery.", "Diagnosing a harsh frequency buildup on the spectrogram.", "Verifying mono compatibility and stereo width on the imaging display.", "Matching loudness to a streaming platform's normalization target."]}, "6e060830-36e0-453b-bb44-91312f94cfab": {"definition": "Magnetic tape manufactured for instrumentation (data) recorders rather than audio program—used to record measurement, telemetry, and multichannel scientific or engineering signals, typically to Inter-Range Instrumentation Group (IRIG) standards with tighter tolerances on coating uniformity, dropout, and dimensional stability than consumer audio tape.", "plain_english": "It is a special magnetic tape made to store data, not music. Engineers used it to record signals such as sensor readings. It had to be very steady and even from end to end.", "purpose_function": "It exists to store analog or FM-encoded measurement data accurately over many channels, where dropouts or level errors could corrupt the recorded signals.", "practical_application": "A technician loads instrumentation tape on a data or telemetry recorder to log test signals for later analysis; in audio work it is mainly encountered when identifying or transferring legacy reels.", "category": "Recording Media", "related_terms": ["Magnetic tape", "Analog tape", "Tape recorder", "Telemetry", "Dropout", "FM recording"], "common_mistakes": ["Assuming instrumentation tape and audio tape are interchangeable despite different specs and formats.", "Overlooking that many instrumentation recordings use FM encoding rather than direct audio.", "Playing back at the wrong speed or on an incompatible transport and misreading the signal.", "Confusing instrumentation recording with multitrack studio recording."], "scenario_contexts": ["Recording multichannel telemetry or test-bench data on a legacy instrumentation recorder.", "Transferring archived instrumentation tapes to a digital system for analysis.", "Identifying an unlabeled reel as instrumentation rather than audio tape.", "Servicing or aligning a data recorder that uses instrumentation tape."]}, "45cf5ed9-8beb-44dd-be22-9e69b40d760e": {"definition": "A deliverable stem containing only the music portion of a production, supplied so a program or song can be localized for foreign markets—vocals or dialogue in the original language can be replaced while the music is retained. In broadcast and film it forms the music component of the Music and Effects (M&E) deliverables.", "plain_english": "It is a version of the track that has only the music and no lead vocals. It lets a team add singing or speech in another language for foreign listeners, using the same backing music.", "purpose_function": "It separates the music from the language-specific vocals or dialogue, so the same production can be re-voiced for different countries without remaking the music.", "practical_application": "An engineer delivers the international music stem alongside the full mix so a client can produce foreign-language versions or use the instrumental for broadcast and sync.", "category": "Deliverables", "related_terms": ["Stem", "Instrumental version", "Music and effects", "TV mix", "Stem export", "A cappella"], "common_mistakes": ["Leaving background vocals or ad-libs in the music stem when they should sit with the vocal.", "Delivering a music stem that does not sum back to match the main mix.", "Inconsistent length, sample rate, or level versus the other deliverables.", "Confusing an instrumental music stem with a full M&E track that also includes effects."], "scenario_contexts": ["Providing an instrumental/music stem for a foreign-language cover or dub.", "Supplying the music component of M&E deliverables for a TV broadcast.", "Delivering an instrumental for a live TV performance or sync license.", "Preparing localized versions of a single for international release."]}, "07d62ed3-e876-4cfa-b47f-e3cabae3c5e5": {"definition": "A software plug-in suite for audio mastering developed by iZotope that combines mastering-chain modules such as an equalizer, multiband dynamics, stereo imager, harmonic exciter, and a peak-limiting maximizer, together with metering and assistant/analysis tools, in a single instance. It is used on a stereo mix bus or standalone to apply the final tonal, dynamic, and loudness processing of a master.", "plain_english": "Ozone is a software toolbox for the last step of making a track, called mastering. It puts tools like an equalizer, a compressor, and a loudness limiter in one window so you can polish a whole song at once.", "purpose_function": "It gathers the common mastering processors into one controllable signal chain so an engineer can shape overall tone, dynamics, stereo width, and final loudness on a finished mix. Its metering and assistant features exist to help judge and hit modern delivery and loudness targets.", "practical_application": "A technician loads Ozone on the master output, arranges modules in a chosen order, and uses its EQ, dynamics, and maximizer while watching LUFS and true-peak meters to prepare a master for streaming, CD, or file delivery. The Master Assistant can suggest a starting chain that the engineer then refines by ear.", "category": "Mastering software", "related_terms": ["Maximizer", "Multiband compression", "True-peak limiting", "LUFS", "Mastering chain", "Stereo imaging"], "common_mistakes": ["Accepting a Master Assistant preset as finished without critical listening and manual adjustment", "Pushing the maximizer for maximum loudness until the master clips or distorts", "Treating it as a mixing fix and using it to rescue balance problems that belong in the mix"], "scenario_contexts": ["Applying the final tonal balance and loudness pass to a finished stereo mix", "Metering a master to a target integrated loudness and true-peak ceiling for streaming delivery", "Using multiband dynamics and imaging to tighten and widen a master before export"]}, "0d63fa4b-79c5-43b6-b84f-21d03d917f3c": {"definition": "A disc-cutting session in which mastered program audio is transferred to a lacquer master disc on a cutting lathe, where a heated stylus cuts the modulated groove into the nitrocellulose-coated aluminum blank. The resulting lacquer is the source from which metal stampers are electroformed to press vinyl records.", "plain_english": "This is the studio session where a finished song is cut into a soft, coated disc called a lacquer. That disc is the first step used to make the metal parts that press vinyl records.", "purpose_function": "It converts a final digital or analog master into a physical cut groove that a record plant can plate and press, bridging the mastering stage and vinyl manufacturing. The session exists because vinyl production requires a mechanically cut master rather than a file.", "practical_application": "A cutting engineer plays the master into the lathe, applies RIAA pre-emphasis and any low-frequency mono and de-essing needed to keep grooves cuttable, and sets level and groove pitch so the program fits the side with clean playback. The finished lacquer is shipped quickly to a plating plant before its soft surface degrades.", "category": "Disc cutting", "related_terms": ["Cutting lathe", "Lead-in groove", "Lead-out groove", "Lateral modulation control", "RIAA equalization", "Stamper"], "common_mistakes": ["Confusing the soft lacquer master with the finished vinyl record", "Assuming any mix can be cut without controlling low-frequency and out-of-phase energy that widens or destabilizes grooves", "Not accounting for lacquers being fragile and time-sensitive, so plating must happen soon after cutting"], "scenario_contexts": ["Cutting a lacquer master for a vinyl release from a supplied master file", "Preparing program with mono bass and de-essing so the lathe can cut it cleanly", "Sending finished lacquers to a plating plant to make stampers"]}, "d2e0f213-ee31-49df-84d9-bfa421b69c51": {"definition": "On a disc-cutting lathe, the management of the side-to-side (lateral) movement of the cutting stylus that encodes audio into the groove walls; in the standard 45/45 stereo system lateral modulation carries the in-phase sum (mono) component. Controlling its amplitude keeps groove excursions within spacing and geometry limits so adjacent grooves do not overcut.", "plain_english": "A record groove wiggles side to side to hold the sound. This control sets how far the cutter swings sideways, so the grooves stay small enough not to crash into each other.", "purpose_function": "It limits the horizontal swing of the cut groove so loud, low, and in-phase content does not create excursions wider than the available groove pitch. This exists to protect playability and prevent grooves from cutting into one another on the disc.", "practical_application": "A cutting engineer manages lateral modulation by controlling program level, keeping low frequencies mono, and letting variable groove pitch widen spacing during loud lateral passages. This lets a loud, bass-heavy program still fit the side and track without skipping.", "category": "Disc cutting", "related_terms": ["Vertical modulation", "Variable groove pitch", "Cutting lathe", "Lacquer mastering session", "Mono bass", "Elliptical equalization"], "common_mistakes": ["Confusing lateral (side-to-side, mono) modulation with vertical (up-and-down, difference) modulation", "Assuming heavy low-frequency mono energy is always safe, when excessive lateral bass swings widen grooves and cause skipping", "Ignoring groove pitch and level trade-offs that lateral modulation forces on long, loud sides"], "scenario_contexts": ["Setting cutting level and pitch so loud lateral passages fit the disc side", "Applying mono bass to keep low-frequency lateral excursions controlled", "Diagnosing groove overcut or skipping traced to excessive lateral modulation"]}, "58e62875-aa57-4849-b343-2b91f3727ca5": {"definition": "The smooth, unmodulated spiral groove cut at the outer edge of a record that guides the playback stylus from the disc edge inward to the first modulated groove of the program. It carries no audio and provides a quiet run into the start of the recording.", "plain_english": "This is the smooth groove at the outer edge of a record. It has no sound and just guides the needle inward until the music starts.", "purpose_function": "It gives the stylus a stable, silent path from the dropped-needle point to the beginning of the program, so playback starts cleanly at the right place. It exists to absorb needle-drop position error and settle the stylus before audio begins.", "practical_application": "A cutting engineer sets the lead-in width and length on the lathe so the tonearm lands reliably and reaches the first note quickly without excess silence. Listeners hear it as the short, quiet moment after the needle drops before the track plays.", "category": "Disc cutting", "related_terms": ["Lead-out groove", "Locked groove", "Lacquer mastering session", "Cutting lathe", "Variable groove pitch", "Spiral"], "common_mistakes": ["Confusing the lead-in at the outer edge with the lead-out and run-out near the label", "Thinking the lead-in groove carries recorded audio", "Assuming its length does not matter, when a mis-sized lead-in causes late starts or unreliable needle landing"], "scenario_contexts": ["Setting the lead-in when cutting a lacquer so the stylus lands and reaches the first track cleanly", "Explaining the quiet gap heard right after the needle drops", "Troubleshooting a stylus that lands unreliably at the start of a side"]}, "877fdae8-0229-481e-aa1e-172e83846215": {"definition": "The smooth, unmodulated spiral groove cut after the last program material on a record side that carries the stylus inward toward the label. It typically ends in a locked (endless) groove or run-out area and provides a quiet exit that can trigger a turntable's auto-lift or return mechanism.", "plain_english": "This is the smooth groove after the music ends. It carries the needle toward the middle so the song does not just stop in place.", "purpose_function": "It gives the stylus a silent path away from the last note toward the label and to a stopping point, so the side ends cleanly. It exists to hold the stylus quietly and to work with tonearm auto-stop or lift systems.", "practical_application": "A cutting engineer cuts the lead-out after the final track and usually ends it in a locked groove so the stylus does not ride into the label. On playback it is the quiet moment after the last song before the arm lifts or the record loops.", "category": "Disc cutting", "related_terms": ["Lead-in groove", "Locked groove", "Run-out groove", "Lacquer mastering session", "Cutting lathe", "Tonearm"], "common_mistakes": ["Confusing the lead-out with the lead-in groove at the outer edge", "Assuming the lead-out carries audio", "Forgetting to terminate it in a locked groove, so the stylus drifts into the label area"], "scenario_contexts": ["Cutting the quiet exit after the last track on a side", "Ending a side in a locked groove so the stylus stops safely", "Explaining the silent passage before a turntable auto-lifts the arm"]}, "791c96ae-d012-4319-9cb7-965e61367138": {"definition": "A concentric, closed groove cut at the end of a record's spiral in which the stylus circulates on a single endless circle instead of moving inward. The record then repeats the same short segment, or silence, indefinitely until the stylus is lifted.", "plain_english": "This is a closed loop groove at the very end of a record. The needle keeps going around the same tiny circle forever until you lift it off.", "purpose_function": "It stops the stylus from drifting into the label by trapping it in an endless circle, and it can be used deliberately to loop a short sound. It exists both as a safe end-of-side stop and as a creative repeating effect.", "practical_application": "A cutting engineer ends most sides with a silent locked groove so the stylus parks instead of riding into the label, and can cut a short audio loop into a locked groove for a repeating end effect. On playback a locked groove either sits quietly or loops the same fraction of a second until lifted.", "category": "Disc cutting", "related_terms": ["Lead-out groove", "Lead-in groove", "Run-out groove", "Lacquer mastering session", "Cutting lathe", "Groove pitch"], "common_mistakes": ["Confusing a locked groove with the lead-out or run-out spiral, which still moves inward", "Assuming a stuck or skipping worn groove is the same as a deliberately cut locked groove", "Cutting a locked-groove loop without matching its length to one exact revolution, so the loop clicks or drifts"], "scenario_contexts": ["Ending a record side so the stylus parks instead of hitting the label", "Cutting a short repeating sound loop as an end-of-side effect", "Identifying whether an endlessly repeating passage is a designed locked groove or a defect"]}, "0be65465-c76b-4b2a-a84d-3923e28be008": {"definition": "The degree to which a recording medium retains its stored audio and physical integrity over long time spans without degradation such as binder breakdown, oxide shedding, magnetic decay, print-through, dye fade, or delamination. It determines a medium's archival life and the preservation strategy needed to keep content accessible.", "plain_english": "This is how well a tape, disc, or drive holds onto its sound over many years. Media that breaks down or fades has low stability, so archives must copy it before it dies.", "purpose_function": "It tells an engineer or archivist how soon a recording must be transferred or migrated to remain playable, guiding storage conditions and backup schedules. The concept exists because every physical medium ages and eventually fails, threatening the recordings on it.", "practical_application": "A technician stores masters in controlled temperature and humidity, monitors known failure modes for each format, and migrates content to fresh media before degradation makes transfer impossible. For example, older tapes may be baked before a one-time safe transfer to a stable digital archive.", "category": "Archiving and preservation", "related_terms": ["Sticky-shed syndrome", "Print-through", "Baking (tape restoration)", "Archival migration", "Low-noise tape", "Optical disc rot"], "common_mistakes": ["Assuming digital files are permanent and skipping redundant backups and periodic migration", "Storing tape or disc masters in heat and humidity that speed up decay", "Waiting until a medium already fails before attempting transfer, when early migration is far safer"], "scenario_contexts": ["Planning storage conditions and migration schedules for a tape or disc archive", "Deciding to transfer aging masters to a stable digital format before they degrade", "Assessing which formats in a collection are most at risk of loss"]}, "c95383f0-9e92-41b9-9f2d-545fab156a79": {"definition": "A stem, meaning a submixed group bounced as its own audio file, that contains the low-frequency musical elements of a mix, typically bass instruments and the low content of the kick drum. It lets the low end be handled, checked, or re-balanced separately from the rest of the mix in mastering or re-mixing.", "plain_english": "A stem is one part of a mix saved as its own file. A low-end stem holds just the deep, low sounds like bass, so they can be worked on or fixed on their own later.", "purpose_function": "It isolates the low-frequency musical content so an engineer can adjust its level, tone, or mono compatibility without disturbing vocals and other elements. It exists to give mastering and re-mix stages targeted control over the often-troublesome bass region.", "practical_application": "A mixing engineer delivers a low-end stem alongside other stems so the mastering engineer can nudge bass level, tighten it, or sum it to mono for vinyl without a full remix. It is common in stem mastering and in preparing masters for formats sensitive to low-frequency energy.", "category": "Stems and delivery", "related_terms": ["Stem", "Stem mastering", "Mono bass", "Bass management", "Multiband compression", "Mixdown"], "common_mistakes": ["Confusing a stem with a single instrument track, when a stem is a submixed group", "Letting low-end stems overlap the same bass content in other stems, so summing them changes the balance", "Exporting stems at inconsistent levels or without matching processing, which breaks the intended mix when recombined"], "scenario_contexts": ["Delivering a low-end stem for stem mastering so bass can be balanced separately", "Summing the low-end stem to mono when preparing a vinyl cut", "Re-balancing bass level for a remix without returning to the full session"]}, "82f12a72-afc5-4d91-adfb-77f003abb915": {"definition": "Magnetic recording tape formulated with finer, more uniform magnetic particles and improved coatings to produce a lower inherent noise floor (tape hiss) and higher signal-to-noise ratio than standard tape at a given output level. It reduces audible background noise without relying on an external noise-reduction system.", "plain_english": "This is recording tape made to be quieter than normal tape. It has less of the soft background hiss you hear on many older recordings.", "purpose_function": "It lowers the constant hiss inherent to magnetic tape so quiet passages and low-level detail stay cleaner, widening the usable dynamic range. It exists to improve recording quality at the media level rather than through processing.", "practical_application": "An engineer chooses low-noise tape stock, sets bias and level correctly for that formulation, and can further improve the noise floor by adding a companding noise-reduction system. Choosing and aligning to the right tape formulation is part of preparing a machine before tracking or mastering.", "category": "Recording media", "related_terms": ["Tape hiss", "Bias", "Signal-to-noise ratio", "Noise reduction", "Print-through", "Long-term media stability"], "common_mistakes": ["Confusing low-noise tape with an electronic noise-reduction system such as a companding encoder", "Assuming low-noise tape removes hiss entirely rather than lowering it", "Running low-noise stock without aligning bias and level to that formulation, which loses its noise and headroom benefit"], "scenario_contexts": ["Selecting tape stock to get the cleanest possible noise floor for a session", "Aligning a tape machine's bias and level to a chosen low-noise formulation", "Combining low-noise tape with a noise-reduction system to maximize dynamic range"]}, "352779ce-3a07-42c7-94d5-6eaced6c5363": {"definition": "Magnetic recording tape whose formulation delivers a lower playback signal (output flux) for a given recorded level than standard or high-output stock, leaving less headroom before saturation and a poorer signal-to-noise ratio at a fixed reference fluxivity.", "plain_english": "A kind of recording tape that gives back a weaker signal than newer, hotter tapes. Because the signal is weak, you must turn it up more, so you also hear more hiss and get less room before the sound distorts.", "purpose_function": "Like any tape it stores recorded audio, but its lower sensitivity forces more playback gain that raises the noise floor, so recognizing it guides level, calibration, and noise-reduction choices during a transfer.", "practical_application": "When transferring an older archive reel, a mastering engineer calibrates the machine to the tape's own reference level and applies extra make-up gain while watching the raised hiss floor.", "category": "Analog Media", "related_terms": ["Reference fluxivity", "Tape saturation", "Signal-to-noise ratio", "Noise reduction", "Calibration tone", "Tape bias"], "common_mistakes": ["Assuming every reel has the same output and skipping calibration to the tape's own reference level", "Adding heavy playback gain without accounting for the noise floor it raises", "Mistaking a naturally low-output formulation for a worn or degraded tape"], "scenario_contexts": ["Transferring a vintage archive reel that reads several dB below a modern reference tape", "Setting playback and calibration levels before digitizing an old master", "Deciding how much noise reduction a hissy low-output transfer needs"]}, "9707cb45-a1d9-4f36-92dd-664e5f442fac": {"definition": "The formal sign-off step in which a reference produced by the replication or duplication plant — such as a vinyl test pressing, a CD check disc, or a verified DDP image — is evaluated and accepted before full mass production begins.", "plain_english": "The last 'yes, go ahead' check before a factory makes thousands of copies. Someone plays a sample made by the plant and confirms it sounds right before the full run starts.", "purpose_function": "It catches errors the plant may add, such as clicks, wrong track order, or level faults, before the cost of a full run, protecting release quality and budget.", "practical_application": "A mastering engineer or label representative auditions the plant's test pressing or check disc against the approved master, then signs off or requests a new one before the run.", "category": "Manufacturing", "related_terms": ["Test pressing", "Check disc", "Manufacturing master", "DDP", "Master approval", "Replication"], "common_mistakes": ["Approving from the studio master instead of the plant's actual reference copy", "Skipping a full front-to-back listen and missing clicks or track-order errors", "Confusing manufacturing approval with the client's earlier master approval"], "scenario_contexts": ["Auditioning a vinyl test pressing before authorizing the pressing run", "Verifying a CD check disc against the DDP before glass mastering", "Rejecting a test pressing for surface noise and requesting a recut"]}, "3dc4970e-6fb7-414a-be36-25a02ac19f36": {"definition": "The final, production-ready deliverable handed to a replication or duplication plant as the exact source for making copies — for CD a DDP image or PMCD, for vinyl a cut lacquer or approved digital cut file, and for digital release the encoded delivery files.", "plain_english": "The finished copy of the audio that the factory uses to make every disc. It is the exact master template that all copies are stamped from.", "purpose_function": "It gives the plant one authoritative, error-checked source so every manufactured copy matches the approved master exactly.", "practical_application": "After mastering and approval, the engineer builds the manufacturing master, such as a DDP fileset with checksums, and delivers it to the plant for replication.", "category": "Manufacturing", "related_terms": ["DDP", "PMCD", "Master for duplication", "Manufacturing approval", "Red Book", "Lacquer"], "common_mistakes": ["Sending a rough or unapproved bounce instead of the final approved master", "Omitting checksums so the plant cannot verify the delivered image", "Confusing the manufacturing master with a personal reference or listening copy"], "scenario_contexts": ["Rendering a DDP image with checksums for a CD pressing plant", "Delivering an approved digital cut file to a vinyl cutting house", "Supplying encoded delivery files to a distributor for digital release"]}, "8a256640-b397-436f-9f08-13b70468b5a2": {"definition": "The stage at which the client — artist, producer, or label — reviews the completed master and formally accepts it as final before it proceeds to manufacturing or release.", "plain_english": "When the artist or label listens to the finished master and agrees it is done. Nothing goes to the factory until they give this approval.", "purpose_function": "It confirms the master meets the client's creative and technical expectations and creates a clear point of agreement before any costly manufacturing steps.", "practical_application": "The mastering engineer sends reference files, collects feedback, makes any revisions, and only releases the master for manufacturing once the client signs off.", "category": "Mastering Workflow", "related_terms": ["Mastering revision", "Manufacturing approval", "Reference file", "Manufacturing master", "Mastering session", "Master for duplication"], "common_mistakes": ["Sending a master to the plant before the client has approved it", "Treating vague verbal comments as formal approval", "Confusing the client's master approval with the plant's manufacturing approval"], "scenario_contexts": ["Emailing reference MP3s and awaiting the artist's sign-off before delivery", "Holding manufacturing until label approval is confirmed in writing", "Booking a revision when the client withholds approval over a level concern"]}, "f64facb6-13b8-43b7-83bf-ca20d21c033f": {"definition": "A finished master prepared and formatted specifically to serve as the source for making copies, with the track order, spacing, metadata, and format required by the copying process in place.", "plain_english": "A finished master set up so it can be copied cleanly. All the track order, gaps, and file details are ready for the copying stage.", "purpose_function": "It ensures the copying stage starts from a correctly formatted, error-checked source so every copy is faithful to the approved master.", "practical_application": "Before delivery, the engineer sequences the songs, sets gaps and fades, embeds metadata, and exports the master in the format the copy house requires.", "category": "Manufacturing", "related_terms": ["Manufacturing master", "DDP", "Master approval", "Manufacturing approval", "Red Book", "Duplication"], "common_mistakes": ["Leaving track spacing, fades, or metadata unset before delivery", "Delivering in a format the copy house cannot accept", "Confusing simple duplication with pressed replication from a glass master"], "scenario_contexts": ["Sequencing and gapping an album before exporting a delivery fileset", "Embedding ISRC and title metadata into a CD master", "Preparing a verified fileset for a short-run CD-R duplication order"]}, "d9e7a705-331f-4161-ae59-4de27ba5cc8e": {"definition": "The ordered series of processing stages a mix passes through during mastering — typically some combination of equalization, dynamics processing such as compression, harmonic or stereo-width processing, metering, and final peak limiting with dithering.", "plain_english": "The line-up of tools the finished mix runs through in order during mastering. Each tool, such as EQ or a limiter, does one job before passing the sound to the next.", "purpose_function": "It shapes tone, controls dynamics, and sets final loudness in a deliberate order so the finished master translates well across playback systems.", "practical_application": "An engineer arranges processors so, for example, corrective EQ precedes compression and a limiter sits last, then tunes each stage while listening to the whole chain.", "category": "Mastering Workflow", "related_terms": ["Mastering signal path", "Equalization", "Compression", "Limiter", "Dither", "Gain staging"], "common_mistakes": ["Placing the limiter early so later processing overshoots the ceiling", "Stacking heavy processing at every stage and crushing the dynamics", "Ignoring gain staging so levels drift between devices in the chain"], "scenario_contexts": ["Ordering EQ, compression, and a limiter for an album master", "Comparing an analog outboard chain against an in-the-box plugin chain", "Adjusting one stage in the chain while auditioning the full path"]}, "24d1733c-feee-4607-8a7c-6c9f770d627a": {"definition": "A new version of a master produced after the client requests changes, adjusting elements such as level, tone, spacing, or fades in response to feedback on a prior version.", "plain_english": "An updated version of the master made after the artist or label asks for changes. The engineer tweaks things like loudness or tone and sends a fresh version.", "purpose_function": "It lets the master be refined toward the client's goals through feedback while keeping earlier versions on record for comparison.", "practical_application": "After a client notes a track is too bright, the engineer recalls the session, adjusts the EQ, exports a new labeled version, and sends it for review.", "category": "Mastering Workflow", "related_terms": ["Master approval", "Mastering session", "Reference file", "Recall", "Revision control", "Mastering chain"], "common_mistakes": ["Overwriting the previous version instead of saving a new labeled one", "Making broad changes when only a small targeted tweak was requested", "Losing track of which revision was actually approved"], "scenario_contexts": ["Brightening or darkening a track after client feedback", "Rebalancing the level of one song relative to the album", "Delivering a labeled version 2 master for a second round of review"]}, "3c066c3a-a62a-4837-bda4-dbe54909c2f0": {"definition": "The working session in which a mastering engineer processes, sequences, and assembles final program material, along with the saved project file that stores its settings, edits, and track layout.", "plain_english": "The work session where the engineer polishes and lines up the finished songs. It is also the saved project file that remembers all the settings and edits.", "purpose_function": "It holds all processing, sequencing, and edit decisions in one recallable place so work can be reviewed, revised, and reproduced later.", "practical_application": "The engineer loads mixes into the session, sets processing and song order, exports the master, and saves the session so revisions can be recalled exactly.", "category": "Mastering Workflow", "related_terms": ["Mastering chain", "Mastering revision", "Recall", "Sequencing", "Master approval", "DDP"], "common_mistakes": ["Not saving the session, so a later revision cannot be recalled", "Mislabeling versions and losing track of the approved state", "Leaving mixes at inconsistent levels before starting to process"], "scenario_contexts": ["Assembling and sequencing an album in one session", "Recalling a saved session to make a requested revision", "Exporting the final master and DDP from the session"]}, "19bf49c5-2644-46a1-b7e3-8f28917afd93": {"definition": "The complete route audio takes through a mastering system, from the playback source through converters, patching, and the processing devices to the capture or output stage, including the monitoring feed used to judge it.", "plain_english": "The full path the sound travels through the mastering gear, from the source, through the converters and processors, to where it is captured. It also covers the feed to the speakers you judge it on.", "purpose_function": "It defines every point the signal passes so the engineer can keep the path clean, correctly leveled, and free of unwanted conversion or noise.", "practical_application": "An engineer traces the path from converter to processors to capture, checking gain staging and connections so nothing adds noise or overload along the way.", "category": "Mastering Workflow", "related_terms": ["Mastering chain", "Gain staging", "Converter", "Monitoring", "Patchbay", "Signal-to-noise ratio"], "common_mistakes": ["Confusing the whole signal path with just the processing chain", "Overlooking a gain-staging error where the path crosses converters", "Leaving an unused device inline that adds noise to the path"], "scenario_contexts": ["Tracing audio from the DAC through outboard gear back to capture", "Diagnosing added noise by checking each point in the path", "Verifying the monitoring feed matches the processed path being captured"]}, "cc57a1af-8f80-401b-82b2-8c9db51e86ff": {"definition": "A specialized production facility, acoustically designed and equipped for audio mastering, where a mastering engineer applies final processing and quality control to finished mixes and produces the distribution master. It provides accurate, calibrated full-range monitoring and a neutral, low-coloration listening environment.", "plain_english": "A room built and tuned for the very last step of making a record. It has very accurate speakers and a neutral sound, so the engineer can hear tiny problems and fix them before a song is released. Think of it like a photo studio with perfect lighting, but for sound.", "purpose_function": "It gives the mastering engineer a trustworthy, repeatable listening space so that final tone, level, and loudness choices translate well across phones, cars, and other playback systems.", "practical_application": "A technician sends approved mixes to a mastering studio, or works in one, to have them EQ'd, leveled, sequenced, and turned into delivery masters for streaming, CD, or vinyl.", "category": "Mastering environment", "related_terms": ["Mastering workflow", "Music delivery master", "Reference monitor", "Monitor calibration", "Room acoustics", "Loudness normalization"], "common_mistakes": ["Assuming any home room with nice speakers equals a proper mastering studio, ignoring acoustic treatment and monitor calibration", "Expecting mastering to fix a poor mix rather than treating it as final polish", "Making tonal decisions on uncalibrated or nearfield speakers, then finding they do not translate", "UNSAFE: Monitoring for long periods at very high SPL risks permanent hearing loss; follow OSHA 1910.95 exposure limits and take breaks"], "scenario_contexts": ["Booking an album for a mastering session at a dedicated studio", "Calibrating and acoustically treating a mastering room before critical work", "Comparing a mix on accurate mastering monitors versus consumer earbuds"]}, "794a43e7-1014-4eeb-ac96-f92ec760dcf7": {"definition": "The ordered sequence of steps a mastering engineer follows to turn approved mixes into finished, delivery-ready masters: importing and evaluating each mix, corrective and tonal processing (EQ, dynamics, limiting), matching level and loudness across a project, sequencing and spacing, quality control, and generating format-specific delivery files.", "plain_english": "The step-by-step order of jobs used to finish songs for release. The engineer listens, fixes the tone and loudness, puts the tracks in order, checks for errors, then makes the files each store needs. It is like a checklist you follow the same way every time so nothing gets missed.", "purpose_function": "A consistent workflow makes sure every release meets its loudness, tonal, and technical delivery targets and cuts down on errors before distribution.", "practical_application": "An engineer follows the workflow to process an album, keep song-to-song loudness even, run a final quality check, and export the masters plus a DDP set for duplication or upload.", "category": "Mastering process", "related_terms": ["Mastering studio", "Music-stem preparation", "Music delivery master", "Loudness normalization", "DDP image", "Quality control"], "common_mistakes": ["Skipping the final quality-control and error-check pass before delivery", "Over-limiting to chase loudness and crushing the dynamics", "Not comparing against reference tracks during the session", "Leaving inconsistent levels between tracks on an album"], "scenario_contexts": ["Mastering a full album so every song sits at a consistent loudness", "Preparing a single to meet a streaming platform's loudness target", "Running a final QC pass before sending a master to a pressing plant"]}, "02afe610-800c-43ce-9c64-2fdfa80d2893": {"definition": "A stem, or submixed group, containing the pitched, melodic musical elements of a production, such as lead and backing instruments, synths, and harmony parts, rendered as one stereo or multichannel file separate from the rhythm, percussion, and vocal stems.", "plain_english": "One combined track that holds the tuneful instruments of a song, like guitars, keys, and synths, kept apart from the drums and vocals. It lets someone adjust just those parts later without touching the rest. Think of it as one labeled bag holding all the melody pieces.", "purpose_function": "Grouping the melodic instruments into one stem lets a mixing or mastering engineer change their balance, tone, or level as a single unit and supports remixing and re-versioning.", "practical_application": "An engineer receives a melodic music stem alongside drum, bass, and vocal stems to fine-tune the instrumental balance during stem mastering or to build an alternate mix.", "category": "Stems", "related_terms": ["Music-edit stem", "Music-stem preparation", "Music-only master", "Stem mastering", "Submix", "Vocal stem"], "common_mistakes": ["Confusing a stem with a single raw track or the full multitrack session", "Letting content overlap between stems so they do not sum back to the original mix", "Printing stems at mismatched levels, sample rate, or start points so they will not recombine cleanly"], "scenario_contexts": ["Delivering grouped stems for a stem-mastering session", "Providing stems to a remixer who needs only the instruments", "Building an immersive or alternate mix from grouped stems"]}, "d99a1764-a0d1-42dc-844f-0dc8505a146a": {"definition": "A magnetic recording tape whose coating uses pure metal (iron) particles rather than a metal-oxide pigment, giving high coercivity (up to roughly 1500 Oe) and high remanence. Classified as IEC Type IV in the compact cassette, it delivers greater output and extended high-frequency response but requires higher record bias and erase levels.", "plain_english": "A recording tape coated with tiny bits of pure metal instead of a rust-like oxide. The metal holds a stronger magnetic signal, so it records louder, cleaner sound with brighter highs. In cassettes this is the top Type IV, or Metal, grade.", "purpose_function": "Its high coercivity stores a stronger, higher-frequency signal for better output and headroom, at the cost of needing more bias and erase current from the recorder.", "practical_application": "An engineer picks metal-particle (Type IV) tape and sets the deck to the matching bias and EQ position for the highest-fidelity cassette, DAT, or digital-video recordings; fully erasing it needs a machine rated for metal tape.", "category": "Recording media", "related_terms": ["Coercivity", "Tape bias", "Ferric-oxide tape", "IEC tape type", "Chromium-dioxide tape", "Analog recording"], "common_mistakes": ["Recording metal tape on a deck set for Type I or Type II bias, giving dull, distorted sound", "Assuming any deck can properly bias or fully erase metal tape when it is not rated for it", "Confusing metal-particle (MP) tape with the rarer metal-evaporated (ME) tape"], "scenario_contexts": ["Choosing tape for a high-fidelity cassette dub", "Transferring or archiving old Type IV cassettes and DAT masters", "Setting the correct bias and EQ position on a cassette deck before recording"]}, "d5bde576-7fb9-4c30-9314-9616303014f0": {"definition": "In the Dolby Atmos binaural render mode, Mid is the middle setting between Near and Far: it renders an object or bed with a moderate amount of binaural (HRTF-based) processing, giving a medium perceived distance from the listener in the binaural headphone folddown.", "plain_english": "The Mid setting makes a sound feel a medium distance away on headphones, not right next to you and not far off. It adds a middle amount of space processing.", "purpose_function": "It offers an intermediate distance option so the mixer can place elements between the close Near sound and the distant Far sound in the binaural image.", "practical_application": "In the Dolby Atmos Renderer, a mixer assigns Mid to supporting instruments or backing elements that should sit behind the lead but in front of far ambience in the headphone render.", "category": "Binaural Render Mode", "related_terms": ["Near binaural setting", "Far binaural setting", "Binaural render mode", "HRTF", "Dolby Atmos"], "common_mistakes": ["Thinking Mid is a level or pan control rather than a perceived-distance setting for headphones.", "Expecting it to affect the loudspeaker render, when it applies to the binaural folddown.", "Using one distance for everything, which loses the depth that Near/Mid/Far contrast provides."], "scenario_contexts": ["Placing rhythm instruments at a middle depth behind the lead vocal.", "Giving backing vocals a moderate distance in a binaural music mix.", "Balancing depth across a mix using Near, Mid, and Far together."]}, "91684592-3158-495b-898f-090accb68c76": {"definition": "The final, approved master of a music program prepared specifically for distribution, conformed to the file format, sample rate and bit depth, loudness, and metadata required by the target channel, such as streaming, a CD/DDP image, or a vinyl pre-master.", "plain_english": "The finished song file made ready to hand off for release. It is set to the exact format, loudness, and details a store or streaming service asks for. Think of it as the final print you send out, not a rough copy.", "purpose_function": "It provides a distribution-ready, specification-compliant version of the master so a release plays back correctly and consistently on the intended platform.", "practical_application": "After mastering, the engineer exports a music delivery master, for example a 24-bit WAV at the platform's loudness target or a DDP image for replication, and checks it against the distributor's spec before upload.", "category": "Deliverables", "related_terms": ["Mastering workflow", "Music-only master", "DDP image", "Loudness normalization", "Delivery specification", "Production master"], "common_mistakes": ["Delivering the wrong sample rate, bit depth, or file format for the target platform", "Ignoring the platform's loudness target so the release is turned down or sounds off", "Missing or incorrect metadata such as ISRC codes or track IDs", "Sending a clipped or over-limited file as the final master"], "scenario_contexts": ["Uploading a release to a streaming distributor or aggregator", "Sending a master to a vinyl cutting house or CD plant", "Meeting a record label's written delivery specification"]}, "371e8fcb-3e23-4a46-9c80-2db1198e6a77": {"definition": "In audio post-production, a stem containing the edited and mixed music elements of a program, delivered separately from the dialogue and effects stems. It carries the final music as prepared by the music editor and mixer so it can be balanced, re-versioned, or replaced without affecting other elements.", "plain_english": "In film and TV sound, one track that holds only the finished music, kept apart from the talking and the sound effects. Keeping music on its own lets editors change or swap it later without touching the voices. It is like keeping the music on its own labeled layer.", "purpose_function": "Isolating the music into its own stem lets a re-recording mixer adjust music level or content on its own and supports foreign-language and music-and-effects versions.", "practical_application": "A post engineer delivers the music-edit stem alongside the dialogue and effects stems so the mix can be re-balanced for broadcast, or the music muted and replaced for a music-and-effects version.", "category": "Stems", "related_terms": ["Music-only master", "Melodic music stem", "Music-stem preparation", "M&E (music and effects)", "Dialogue stem", "Re-recording mix"], "common_mistakes": ["Bouncing the music stem at a different level or reference than the final mix so it will not sum correctly", "Leaving dialogue or effects bleed inside the music stem", "Mismatched sample rate, timecode, or start point across the stem set"], "scenario_contexts": ["Delivering broadcast or streaming audio stems for a show", "Building a music-and-effects version for foreign dubbing", "Re-balancing music level under narration during a mix"]}, "4971ce8c-8d15-4ec1-95ba-af2155e0e59b": {"definition": "A master version of a program containing only the music, with dialogue and sound effects removed. It is supplied as a component of a deliverables package for re-versioning, foreign-language production, or licensing where the music must stand alone.", "plain_english": "A finished version of the audio that has the music but no talking or sound effects. It is handed over so the music can be reused on its own, such as for a different-language dub or a licensing deal. It is the music-only copy.", "purpose_function": "It supplies an isolated music version so a program can be re-voiced in other languages or its music reused and licensed without any other audio.", "practical_application": "A post or mastering engineer prepares a music-only master as part of the deliverables so a distributor can create foreign dubs or license the score separately.", "category": "Deliverables", "related_terms": ["Music-edit stem", "Music delivery master", "M&E (music and effects)", "Stem mastering", "Dialogue stem", "Re-versioning"], "common_mistakes": ["Confusing a music-only master with a full M&E, which also includes the sound effects", "Leaving reverb tails or effects bleed from other elements inside the music", "Level or format mismatch between the music-only master and the main master"], "scenario_contexts": ["Assembling a delivery package for international distribution", "Supplying music on its own for a trailer or promo", "Licensing a program's music separately from the full soundtrack"]}, "cadbd2c6-dcd9-47d6-b57c-3b7a235bba1d": {"definition": "The process of readying music stems for mixing, mastering, or delivery: bouncing consistent, time-aligned files that sum back to the reference mix, with matched sample rate and bit depth, correct start points and headroom, and clear labeling.", "plain_english": "Getting the music stems ready before the next step. You bounce each group as a clean, matching file that lines up in time and adds back up to the full song. Good prep means clear names, the right settings, and no surprises for the next engineer.", "purpose_function": "Careful preparation makes sure the stems sum correctly to the intended mix and meet the technical specs of the mastering or post-production workflow, which prevents rework.", "practical_application": "Before stem mastering or hand-off, an engineer exports each music stem from the same start point at a common sample rate and bit depth, checks that the stems sum to the mix, and labels the files clearly.", "category": "Stems", "related_terms": ["Melodic music stem", "Music-edit stem", "Music delivery master", "Stem mastering", "Submix", "Mastering workflow"], "common_mistakes": ["Exporting stems from different start points so they drift out of sync", "Using mismatched sample rate, bit depth, or levels so stems will not sum to the mix", "Applying the master-bus limiter to each stem so the sum is over-processed", "Poor or missing file labeling that confuses the next engineer"], "scenario_contexts": ["Preparing stems to send to a stem-mastering engineer", "Bouncing stems for a remix or re-version", "Checking that exported stems sum back to the approved mix before hand-off"]}, "ea44279a-5a8b-4f29-bdd0-970ca90a9860": {"definition": "In the Dolby Atmos binaural render mode, Near is the setting that renders an object or bed with the least amount of binaural (HRTF-based) processing, so it is perceived as the closest to the listener in the binaural headphone folddown.", "plain_english": "The Near setting makes a sound feel close to you on headphones. It uses the least space processing, so the sound seems right up front.", "purpose_function": "It lets the mixer keep chosen objects intimate and up-front in a binaural render, which helps lead elements stay clear and present.", "practical_application": "In the Dolby Atmos Renderer, a mixer sets lead vocals or close instruments to Near so they stay forward in the binaural image, contrasted against Mid and Far elements.", "category": "Binaural Render Mode", "related_terms": ["Mid binaural setting", "Far binaural setting", "Binaural render mode", "HRTF", "Dolby Atmos"], "common_mistakes": ["Assuming Near boosts level; it sets perceived closeness for the binaural render, not gain.", "Expecting it to change the loudspeaker render rather than the headphone folddown.", "Setting everything to Near, which flattens depth and crowds the image."], "scenario_contexts": ["Keeping a lead vocal close and present in a binaural music mix.", "Placing a narrator up front on a headphone render.", "Contrasting a Near lead against Far ambience for depth."]}, "24cba83c-f0aa-4e77-a178-dacd1b7cbc82": {"definition": "An alternate version of a film or television score mixdown delivered with the choir (vocal ensemble) elements muted or removed while the rest of the orchestration remains, so the choir can be controlled, lowered, or replaced independently at the final dub.", "plain_english": "It is a copy of the movie's music mix with the singing choir taken out but everything else kept in. The team saves this version so they can lower or swap the choir later without redoing the whole score.", "purpose_function": "It lets the re-recording mixer or music editor drop, lower, or swap the choir without touching the rest of the score, for example when the choir clashes with a line of dialogue.", "practical_application": "It is delivered alongside the full score mix and stems, and on the dub stage the mixer switches to it whenever the choir needs to sit back under dialogue or be replaced.", "category": "Score Deliverables", "related_terms": ["Score mix", "Stems", "Alternate mix", "Re-recording mix", "No-percussion score mix", "No-soloist score mix"], "common_mistakes": ["Thinking it is a completely separate recording rather than the same score mix with one element muted.", "Confusing it with a stem; a no-choir mix is a full alternate mix, while a stem is one isolated group.", "Letting its level or processing drift so the versions no longer swap cleanly with the main mix."], "scenario_contexts": ["The choir overpowers dialogue in a key scene, so the dub mixer switches to the no-choir version there.", "A studio note asks to remove the choir from a cue after the score is already mixed.", "A trailer editor needs the score without choir to fit a different picture edit."]}, "0858b1de-ef38-40e8-b228-f3f43f10c701": {"definition": "An alternate version of a film or television score mixdown delivered with the percussion elements muted or removed while the rest of the orchestration remains, so percussion can be controlled, lowered, or replaced separately at the final dub.", "plain_english": "It is a copy of the movie's music mix with the drums and percussion taken out but the rest kept in. The team saves it so they can change or lower the percussion later without remixing everything.", "purpose_function": "It lets the re-recording mixer or music editor lower, cut, or swap percussion without touching the rest of the score, for example when musical hits collide with sound effects.", "practical_application": "It is delivered with the main score mix, and on the dub stage the mixer uses it when percussion competes with effects such as gunshots or footsteps.", "category": "Score Deliverables", "related_terms": ["Score mix", "Stems", "Alternate mix", "Re-recording mix", "No-choir score mix", "No-soloist score mix"], "common_mistakes": ["Assuming it removes only drum kit when it usually removes all tuned and untuned percussion in the mix.", "Confusing the alternate mix with an isolated percussion stem.", "Changing its level or EQ so it no longer matches the full mix."], "scenario_contexts": ["Percussion hits clash with sound effects, so the mixer drops to the no-percussion version.", "A director wants a softer, less rhythmic feel in a particular scene.", "Effects editors need room in the low end that the percussion was filling."]}, "68f293b5-a97b-489c-b0c5-ae8a876c5f53": {"definition": "An alternate version of a film or television score mixdown delivered with the featured solo instrument or solo voice muted or removed while the accompaniment remains, so the soloist can be controlled, lowered, or replaced separately at the final dub.", "plain_english": "It is a copy of the movie's music mix with the main solo part, like a solo singer or violin, taken out but the backing music left in. The team keeps it so they can adjust or replace the solo later.", "purpose_function": "It lets the re-recording mixer or music editor lower, cut, or re-record the featured soloist without redoing the accompaniment, for example when the solo distracts from dialogue.", "practical_application": "It ships with the main score mix, and the dub mixer chooses it when the soloist must step back under dialogue or when a new solo take is dropped in.", "category": "Score Deliverables", "related_terms": ["Score mix", "Stems", "Alternate mix", "Re-recording mix", "No-choir score mix", "No-percussion score mix"], "common_mistakes": ["Thinking it removes all melody rather than just the featured solo line.", "Confusing the alternate mix with a soloed or isolated stem.", "Letting the version drift in level so it cannot swap cleanly with the main mix."], "scenario_contexts": ["A solo vocal competes with dialogue, so the mixer uses the no-soloist version there.", "The director asks to replace the original soloist with a new performance.", "A cue is reused in a scene where the featured solo does not fit."]}, "313f1801-ac8b-41fc-96d0-00fabf66663c": {"definition": "Analog magnetic recording tape manufactured without the matte, usually carbon-loaded back coating applied to the non-oxide side of the base film, so it relies only on the base film and oxide layers for its winding and handling behavior.", "plain_english": "It is reel-to-reel tape with no extra rough, dark layer on its back. That back layer normally helps the tape wind evenly and drains static, so tape without it can be more slippery and pick up more static.", "purpose_function": "The distinction matters because the back coating controls static build-up, friction, and how evenly the tape packs on the reel; non-back-coated stock lacks that help and can wind less smoothly and hold more charge.", "practical_application": "A mastering or archive engineer identifies non-back-coated stock, often earlier tapes, because it may wind unevenly, attract more dust and static, and needs careful handling and storage during transfer.", "category": "Tape Media", "related_terms": ["Back coating", "Print-through", "Tape baking", "Oxide shedding", "Reel-to-reel tape", "Analog mastering"], "common_mistakes": ["Assuming all analog tape has a back coating; many early formulations did not.", "Confusing the dull back coating with the glossy oxide (recording) side of the tape.", "Blaming poor winding or static only on the machine when the tape simply lacks a back coat."], "scenario_contexts": ["Transferring an older archival reel that winds unevenly because it has no back coating.", "Identifying tape stock and its era during a mastering transfer.", "Managing extra static and dust attraction when handling non-back-coated tape."]}, "2fc7a3d6-aaa3-4bc6-a8f1-b062b21c4831": {"definition": "NUGEN MasterCheck is a metering plug-in that measures a master against streaming and broadcast loudness targets, displaying integrated loudness (LUFS), true-peak (dBTP) and peak-to-loudness ratio (PLR/dynamics), and, in the Pro version, auditions how lossy codecs and platform loudness normalization will alter the delivered audio.", "plain_english": "It is a plug-in that checks how loud and how dynamic your final mix is, using the same rules streaming sites like Spotify use. It can also play a preview of how the song will sound after those sites squeeze and re-level it.", "purpose_function": "It exists so engineers master to specific loudness targets instead of just chasing maximum level, and can catch true-peak overs or codec distortion before a platform turns the track down or damages it.", "practical_application": "A mastering engineer runs it on the master bus to hit a platform's LUFS target, watch true-peak headroom, and A/B the codec preview so the release still sounds right after Spotify, Apple Music, or YouTube process it.", "category": "Loudness Metering", "related_terms": ["LUFS", "True peak", "Loudness normalization", "Peak-to-loudness ratio", "Codec", "Loudness metering"], "common_mistakes": ["Treating its loudness reading as a level to hit by over-limiting, which defeats the point of normalization.", "Ignoring the true-peak warning and delivering inter-sample peaks that clip after codec encoding.", "Assuming the codec preview is the exact platform result rather than a close estimate."], "scenario_contexts": ["Preparing a master to meet Spotify or Apple Music loudness targets.", "Checking true-peak headroom before lossy codec encoding.", "Comparing a mix's loudness and dynamics against commercial reference tracks."]}, "b53d2b32-6a30-4660-a4e9-d9593d2fcc3f": {"definition": "In object-based audio, the metadata that records the time-varying values of an audio object's parameters, most often position but also gain and related controls, so the renderer can move and change the object over time; in the Audio Definition Model this is carried by a sequence of audioBlockFormat blocks, each with a start time and duration.", "plain_english": "It is the saved instructions that tell the system how a single sound should move and change over time, like sliding a voice from left to right. The sound is treated as a movable object, and this data is its recorded path and settings.", "purpose_function": "It exists so an object's motion and parameter changes travel with the mix as data, letting each playback system, whether speakers or headphones, recreate the movement correctly for its own layout.", "practical_application": "When a mixer automates a sound's position or level in a Dolby Atmos or ADM session, that automation is stored as object metadata and rendered live, so the same file adapts from a cinema array to a soundbar.", "category": "Object Metadata", "related_terms": ["Audio object", "Dolby Atmos", "Audio Definition Model", "Object gain metadata", "Object divergence metadata", "Renderer"], "common_mistakes": ["Thinking the object's movement is baked into fixed channels rather than stored as separate metadata.", "Confusing the object metadata with the audio itself; the two travel together but are distinct.", "Assuming automation plays back identically on every system when the renderer adapts it to each layout."], "scenario_contexts": ["Automating a flyover sound to move overhead in a Dolby Atmos mix.", "Delivering an ADM BWF master where object motion is stored as metadata.", "Re-rendering the same immersive mix for cinema, home, and headphones."]}, "ff296754-4b47-42f7-9ced-5855d13fc1b5": {"definition": "In object-based audio, the metadata parameter that spreads an audio object's energy from a single point toward two symmetric positions offset around its stated location, trading a tight point source for a wider, more diffuse image; in the Audio Definition Model it is the objectDivergence value with an associated azimuth range, where 0 means no spread.", "plain_english": "It is a setting that tells the system how wide or spread out a sound object should feel. At zero the sound comes from one exact spot, and as you raise it the sound fans out to feel bigger and less pinpointed.", "purpose_function": "It exists so a mixer can control how focused or enveloping an object sounds without changing its core position, helping objects feel larger or blend across nearby speakers.", "practical_application": "In a Dolby Atmos or ADM mix, an engineer raises divergence on an object such as ambience or a pad so it spreads across speakers instead of stabbing from one point.", "category": "Object Metadata", "related_terms": ["Audio object", "Dolby Atmos", "Audio Definition Model", "Object gain metadata", "Object automation metadata", "Renderer"], "common_mistakes": ["Confusing divergence, the spread of one object, with panning, which moves its position.", "Assuming high divergence means louder; it changes spread, not just level.", "Expecting the same spread on every layout when the renderer adapts it to the room's speakers."], "scenario_contexts": ["Spreading an ambience or pad object so it envelops the room.", "Softening a hard point source that feels too pinpointed.", "Making a large on-screen sound feel wider in a cinema mix."]}, "54e9dd8b-d210-4950-bb52-f99ff44ee241": {"definition": "In object-based audio, the metadata parameter that sets an audio object's level as a linear multiplier applied by the renderer; in the Audio Definition Model a gain of 1.0 leaves the object's signal unchanged, and the value can vary over time to automate the object's level.", "plain_english": "It is the saved volume setting for a single sound object, telling the system how loud to play it. A value of one means leave it as is, higher makes it louder, and lower makes it quieter.", "purpose_function": "It exists so each object's level is stored as data and applied at playback, letting the renderer balance objects correctly for whatever speaker or headphone system is used.", "practical_application": "A mixer sets or automates an object's gain in a Dolby Atmos or ADM session, and that value rides with the file so the object stays balanced when re-rendered for different systems.", "category": "Object Metadata", "related_terms": ["Audio object", "Dolby Atmos", "Audio Definition Model", "Object automation metadata", "Object divergence metadata", "Renderer"], "common_mistakes": ["Confusing object gain, applied at render, with printing the level into the audio file.", "Assuming a gain of 1.0 boosts the signal when it actually leaves it unchanged.", "Forgetting that object gain interacts with the final render and monitoring level."], "scenario_contexts": ["Balancing an object against the bed in a Dolby Atmos mix.", "Automating an object's level to fade it in or out.", "Adjusting object gain so the mix translates across cinema, home, and headphones."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"5792b0db-69e8-427a-bff4-7556b53ef742": {"definition": "In object-based immersive audio (e.g., Dolby Atmos, or ADM per ITU-R BS.2076), the complete set of descriptive metadata carried with a single audio object - its position, size, gain, and related parameters - that travels alongside the object's audio essence and tells the renderer how to reproduce it.", "plain_english": "An audio object is one sound, like a single voice, that can move around the room. The metadata package is the set of instructions that rides along with it. It tells the player where to put the sound, how big it is, and how loud. Think of it like a shipping label stuck to a box.", "purpose_function": "It lets one master play back correctly on any speaker layout, because the renderer reads each object's metadata and places the sound live instead of relying on fixed channels.", "practical_application": "A mastering engineer checks that every object's metadata package is complete and valid before exporting the ADM BWF master, since missing or wrong values change how the mix renders.", "category": "Immersive Audio Metadata", "related_terms": ["Object position metadata", "Object size metadata", "Object mute metadata", "Object-based re-render", "Off binaural setting"], "common_mistakes": ["Confusing the metadata package with the audio itself - the metadata describes the object, but the sound lives in a separate audio track.", "Assuming metadata carries over when bouncing to a channel-based file - a flat stereo or 5.1 render discards the object metadata.", "Editing object levels only in the DAW while ignoring gain stored in the object metadata."], "scenario_contexts": ["Preparing a Dolby Atmos music master and validating each object's metadata before delivery.", "Troubleshooting an object that plays in the wrong location because its position metadata was set incorrectly.", "Handing off an ADM BWF file so a streaming platform's renderer can rebuild the mix for the listener's device."]}, "3ca059b9-64fd-444a-b057-1efdf3f37de3": {"definition": "A metadata parameter attached to an audio object that flags it as muted, instructing the renderer to silence that object during playback while its audio essence and other metadata remain intact; in ADM (ITU-R BS.2076) this is a mute flag on the audioObject element.", "plain_english": "This is a simple on/off switch stored with a sound object that says keep this one silent. The sound is still in the file, but the player is told not to play it. It is like leaving a track in a project but pressing its mute button. Nothing is deleted; it just stays quiet.", "purpose_function": "It lets an object be silenced without deleting it, so alternate versions or checks can be made non-destructively and the object can be un-muted later.", "practical_application": "An engineer uses mute metadata to audition a mix with a specific object removed, or to deliver a version where an element is silenced without re-editing the audio.", "category": "Immersive Audio Metadata", "related_terms": ["Object metadata package", "Object position metadata", "Object size metadata", "Object-based re-render", "Off binaural setting"], "common_mistakes": ["Thinking muting an object deletes it - the audio and metadata remain, only playback is silenced.", "Leaving an object muted by accident in the exported master, so an element goes missing on playback.", "Confusing object mute with pulling gain to minus infinity; mute is a distinct flag."], "scenario_contexts": ["Delivering an instrumental version by muting the vocal object rather than removing it.", "Checking a mix by temporarily muting a single object during quality control."]}, "f41965a4-fd83-4ace-8922-50ef797f4436": {"definition": "The metadata that specifies where an audio object sits in three-dimensional space, expressed as azimuth/elevation/distance (polar) or X/Y/Z (Cartesian) coordinates per ADM (ITU-R BS.2076); the renderer uses it to place the sound across the available speakers.", "plain_english": "This is the set of coordinates that tells the system where a sound should appear in the room. It can point left or right, high or low, near or far. The player reads those numbers and steers the sound to the right spot. It works like GPS coordinates for a sound.", "purpose_function": "It frees a sound from fixed channels, letting the renderer place or move it accurately on any speaker layout, which is the core idea of object-based audio.", "practical_application": "Engineers automate position metadata to pan objects through a scene and verify the coordinates so sounds land where intended on every playback system.", "category": "Immersive Audio Metadata", "related_terms": ["Object metadata package", "Object size metadata", "Object mute metadata", "Object-based re-render", "Off binaural setting"], "common_mistakes": ["Assuming position is fixed - it is automated over time, and stale keyframes can misplace a sound.", "Mixing up coordinate systems (polar vs. Cartesian) and entering values in the wrong one.", "Judging position only on your own speaker setup, forgetting the renderer remaps it for other layouts."], "scenario_contexts": ["Automating a helicopter object to fly overhead in a Dolby Atmos mix.", "Correcting an object that appears in the wrong spot by editing its position coordinates."]}, "0d09e77a-6529-44e5-8f30-c00a1fc7f71c": {"definition": "The metadata that defines an object's spatial extent - how large or diffuse it appears - via width, height, and depth parameters (ADM, ITU-R BS.2076) or the renderer's size control; larger values spread the object across more speakers rather than as a point source.", "plain_english": "This tells the system how big a sound should feel. A small value makes a tight point, like one speaker. A big value spreads it wide, like a wash of sound all around you. It is the difference between a single dripping tap and steady rain everywhere. The player uses it to decide how many speakers share the sound.", "purpose_function": "It lets a sound be a pinpoint or a broad, enveloping source, giving the mix a sense of scale and space beyond simple position.", "practical_application": "Engineers increase object size to make pads, ambiences, or reverbs feel wide and immersive, and reduce it to keep effects tight and localized.", "category": "Immersive Audio Metadata", "related_terms": ["Object metadata package", "Object position metadata", "Object mute metadata", "Object-based re-render", "Off binaural setting"], "common_mistakes": ["Confusing size with loudness - size changes spread and localization, not level.", "Setting size very large on everything, which smears the image and loses clarity.", "Expecting the same spread on all systems; small speaker layouts render size differently."], "scenario_contexts": ["Widening a synth pad by increasing its object size so it surrounds the listener.", "Keeping a lead vocal tight by using a small object size for precise placement."]}, "1f348546-d9ee-4700-88b3-81ceed0e2e34": {"definition": "The process by which a renderer takes an object-based master (e.g., Dolby Atmos) and produces a channel-based output - such as 7.1, 5.1, stereo, or binaural - by rendering each object's metadata to that specific speaker layout; the resulting fixed-channel file is called a re-render.", "plain_english": "This turns a flexible object mix into a normal fixed-speaker version. The system reads where every sound should go and bakes it into set channels, like 5.1 or stereo. Think of it like flattening the layers in a photo into one image. You get a ready-to-play file for a specific setup.", "purpose_function": "It creates deliverables for systems that cannot decode objects, ensuring the immersive mix translates to standard stereo and surround formats.", "practical_application": "From one Atmos master an engineer generates re-renders - stereo, 5.1, 7.1, binaural - as delivery files or reference bounces for clients and platforms.", "category": "Object-Based Audio", "related_terms": ["Object metadata package", "Object position metadata", "Object size metadata", "Object mute metadata", "Off binaural setting"], "common_mistakes": ["Treating a re-render as reversible - a channel-based re-render loses the object metadata and cannot be turned back into objects.", "Not checking loudness and balance on each re-render; a good Atmos mix can fold down poorly.", "Forgetting the renderer's limit on how many re-renders can be created at once."], "scenario_contexts": ["Bouncing a stereo re-render from an Atmos master for a client reference.", "Generating 5.1 and 7.1 re-renders as broadcast deliverables from one immersive master."]}, "859e636e-c592-48dd-9c24-9f20cf1a7a38": {"definition": "In the Dolby Atmos Renderer's binaural (headphone) monitoring path, a per-bed or per-object setting of Off that applies no spatial distance processing to that element, so it is rendered without the near/mid/far head-related cues used to push a sound away from and outside the listener's head; Near, Mid, and Far apply progressively greater simulated distance.", "plain_english": "When mixing Atmos for headphones, each sound can be pushed to feel near, middle, or far away. Setting it to Off turns that distance effect off for that one sound. The sound then stays plain and close, without being pushed back. You use it to keep things like a lead vocal clear and up front.", "purpose_function": "It gives the engineer per-element control over headphone depth, letting some sounds stay dry and forward while others are pushed back for a sense of space.", "practical_application": "An engineer sets a lead vocal or kick to Off so it stays punchy and present in the binaural render, while reverbs or ambience are set to Far.", "category": "Immersive Monitoring", "related_terms": ["Object metadata package", "Object position metadata", "Object-based re-render", "Object size metadata", "Object mute metadata"], "common_mistakes": ["Assuming Off disables binaural entirely - it only removes distance processing for that one element, not the whole mix.", "Leaving everything on Off, which makes the headphone mix sound flat and stuck inside the head.", "Forgetting binaural settings only affect the binaural/headphone render, not the speaker output."], "scenario_contexts": ["Keeping a vocal forward by setting its binaural mode to Off while ambiences are set to Far.", "Fixing a headphone mix that feels distant by switching key elements to Off."]}, "3b5c3dc7-9a47-4401-a999-556e454ed69b": {"definition": "A master copy of a finished program stored on optical media (such as CD-R, DVD, Blu-ray, or archival-grade disc) for long-term preservation, kept separate from working copies so the definitive version can be retrieved unchanged.", "plain_english": "This is the keeper copy of a finished project, burned onto a disc for safe storage. It is not the copy you work from day to day. It sits safely so the original can be found later exactly as it was. Think of it like a photo negative you lock in a drawer.", "purpose_function": "It preserves the definitive final version on stable media so the work can be recovered years later if working files are lost or corrupted.", "practical_application": "After a master is approved, an engineer burns and labels an optical archive master, stores it safely, and often keeps a second copy in another location.", "category": "Archival & Delivery", "related_terms": ["Optical verification", "Object metadata package", "Object-based re-render", "Orchestra stem preparation"], "common_mistakes": ["Relying on a single disc - optical media can degrade, so keep multiple copies and verify them.", "Treating a burned disc as permanent; discs should be checked periodically and migrated over time.", "Skipping clear labeling, so the archive master cannot be identified later."], "scenario_contexts": ["Burning an archive master to disc after a mastering session is signed off.", "Retrieving an old optical archive master to make a new deliverable years later."]}, "8de58af9-a058-48bc-8287-ef362d145336": {"definition": "A quality-control step in which data written to an optical disc is read back and compared against the source (by checksum or bit-for-bit comparison) to confirm the burn is accurate and error-free before the disc is trusted as a master or deliverable.", "plain_english": "After burning a disc, you read it back to make sure every bit copied correctly. The system compares the disc to the original to catch any errors. It is like proofreading a printout against the file it came from. If they match, the disc can be trusted.", "purpose_function": "It catches burn errors and bad media before a faulty disc is delivered or archived, protecting the integrity of the master.", "practical_application": "An engineer runs verification after burning a master or DDP disc, and re-burns if the comparison reports mismatches or read errors.", "category": "Archival & Delivery", "related_terms": ["Optical archive master", "Object metadata package", "Object-based re-render", "Orchestra stem preparation"], "common_mistakes": ["Skipping verification and assuming a burn is good because no error popped up while writing.", "Verifying only on the same drive that burned the disc, without testing read-back on another drive.", "Ignoring rising read errors that warn a disc or drive is failing."], "scenario_contexts": ["Verifying a DDP master disc before shipping it to a replication plant.", "Reading back an archive disc to confirm it is still error-free."]}, "1db92a4d-0399-4f7a-a669-3aacadb65c73": {"definition": "The task of grouping a large orchestral mix into a set of stems - submixes such as strings, brass, woodwinds, and percussion - bounced as separate, time-aligned files so the material can be balanced, mixed, or re-used later without returning to the full session.", "plain_english": "An orchestra has many players and tracks. Stem preparation means bundling them into a few grouped mixes, like one for strings and one for brass. These bounced files line up in time and are easy to rebalance later. It is like sorting laundry into a few labeled baskets instead of one huge pile.", "purpose_function": "Stems let a mixer or mastering engineer adjust sections independently and reuse the music (for trailers, edits, or foreign versions) without the original multitrack session.", "practical_application": "A scoring or mastering engineer bounces orchestral stems by section, keeping levels and start times consistent so they sum back to the approved full mix.", "category": "Stem Preparation", "related_terms": ["Object-based re-render", "Optical archive master", "Object metadata package", "Optical verification"], "common_mistakes": ["Bouncing stems that do not sum back to the full mix because of processing left on the master bus.", "Misaligned start times, so stems drift out of sync when combined.", "Inconsistent levels or naming, making the stems hard to recombine."], "scenario_contexts": ["Delivering orchestral stems (strings, brass, woodwinds, percussion) to a film re-recording mixer.", "Preparing section stems so a trailer editor can rebalance the music."]}, "fec988f1-970c-4d54-a934-c2c722412435": {"definition": "The audio quality achievable in the outer (largest-diameter) grooves of a disc record, where the higher linear groove velocity at constant rotational speed gives greater high-frequency headroom and lower tracing distortion than the smaller inner grooves.", "plain_english": "A record spins at one steady speed. But the outer edge moves past the needle faster than the middle does. That extra speed gives the needle more room to trace loud, bright sounds cleanly. So songs near the outer edge often sound their best.", "purpose_function": "It describes why groove position affects sound quality on a disc, which guides how a side is sequenced so loud or bright passages land where fidelity is highest.", "practical_application": "A cutting or mastering engineer places the loudest and most high-frequency-heavy tracks toward the start of a side and leaves quieter material for the inner grooves to avoid inner-groove distortion.", "category": "Vinyl Mastering", "related_terms": ["Inner-groove distortion", "Lacquer cutting", "Linear groove velocity", "Side sequencing", "Disc cutting"], "common_mistakes": ["Assuming every point on a record reproduces sound equally well regardless of radius", "Placing the brightest or loudest track at the end of a side, where the inner groove has the least high-frequency headroom", "Confusing the outer groove's linear-velocity advantage with rotational speed (RPM), which is constant across the whole disc"], "scenario_contexts": ["Sequencing an album for vinyl so the most demanding tracks fall on the outer grooves", "Reviewing a test pressing for inner-groove distortion versus clean outer-groove passages", "Deciding how much program time to cut per side to keep grooves at a favorable radius"]}, "c974bc8d-8d21-4870-ad84-129671d19a51": {"definition": "The transparent polyethylene terephthalate (PET, trade name Mylar) film used as the flexible backing onto which the magnetic oxide coating of recording tape is applied; from the 1950s-60s it replaced cellulose acetate as the standard base for professional audio tape.", "plain_english": "Recording tape is a thin plastic ribbon with a magnetic coat on it. The plastic underneath is called the base. Modern tape uses a strong, steady plastic called polyester. This helps the tape keep its shape and not snap or dry out.", "purpose_function": "The base provides a strong, dimensionally stable carrier for the magnetic coating; polyester's strength and chemical stability keep tape playable for decades and resist the brittleness and vinegar syndrome that affect older acetate tape.", "practical_application": "When transferring legacy tapes, a technician identifies a polyester base (it tends to stretch rather than snap and does not smell of vinegar) to judge handling risks and whether the binder needs baking.", "category": "Magnetic Tape", "related_terms": ["Cellulose acetate base", "Sticky-shed syndrome", "Tape baking", "Magnetic tape", "Preservation transfer plan", "Binder"], "common_mistakes": ["Assuming a polyester base cannot fail, when its binder can still suffer sticky-shed syndrome even though the base itself is stable", "Confusing the base film with the magnetic oxide coating carried on top of it", "Believing polyester tape breaks cleanly like acetate; under stress it tends to stretch permanently, deforming the recording"], "scenario_contexts": ["Identifying tape base type before transferring an archival reel", "Diagnosing why an old acetate tape is brittle while a polyester tape has stretched", "Choosing storage and handling procedures based on the base material"]}, "f820f0b6-212c-45d5-a0e8-ee7bd215f390": {"definition": "The CD premastering process of placing and adjusting the P and Q subcode data-track starts (Index 1), pauses and pre-gaps (Index 0), index points, and timing offsets-so a Red Book (IEC 60908) disc plays back with correct track boundaries, timing, and cueing.", "plain_english": "A CD has hidden markers. They tell the player where each track starts and stops. PQ editing is the step where the engineer sets those markers. This makes tracks begin, end, and gap in the right place.", "purpose_function": "It defines the disc's navigation-track numbers, start points, and gaps-so players and rippers see the intended layout; without it the audio would play as one undivided stream.", "practical_application": "In mastering software the engineer drops track-start markers between songs, sets pre-gap lengths, enters ISRC and UPC codes, and nudges start and end offsets before exporting a DDP image.", "category": "CD Premastering", "related_terms": ["PQ subcode", "PQ sheet", "Pre-gap audio", "DDP image", "Red Book", "ISRC"], "common_mistakes": ["Placing a track-start marker exactly on the first sample so playback clips the attack instead of allowing a small start offset", "Ignoring the Red Book minimum gap and track-length rules", "Forgetting to enter ISRC or UPC/EAN codes during PQ editing"], "scenario_contexts": ["Setting track IDs for a live album with continuous audio between songs", "Adding a hidden track in the pre-gap before track 1", "Preparing a DDP for a pressing plant with correct track times and codes"]}, "3083c110-6533-48b8-864f-3f7fadacc0c7": {"definition": "A document generated during CD premastering that lists every track's start and end times, index points, pause/pre-gap durations, ISRC codes, and the disc's UPC/EAN (MCN); it is a human-readable record of the PQ subcode used by the pressing plant and for quality control.", "plain_english": "A PQ sheet is like a track list for a CD. It writes down where each song starts and ends. It also notes the gap lengths and the ID codes. The factory and the engineer use it to check everything is right.", "purpose_function": "It documents the intended track layout and metadata so the plant can verify the master and the client can approve timings and codes before replication.", "practical_application": "A mastering engineer exports the PQ sheet alongside the DDP image and checks it against the client's track list and supplied ISRC codes before delivery.", "category": "CD Premastering", "related_terms": ["PQ subcode", "PQ editing", "DDP image", "ISRC", "Pre-gap audio", "Premaster image"], "common_mistakes": ["Treating the PQ sheet as the master itself rather than a reference document describing it", "Not cross-checking ISRC and UPC codes on the sheet against the client's supplied codes", "Overlooking the pre-gap lengths listed on the sheet when approving track spacing"], "scenario_contexts": ["Sending track times and codes to a pressing plant for verification", "Client review of track order and gaps before manufacturing", "QC comparison of the PQ sheet against the finished reference disc"]}, "c051c2dc-c7b0-40c0-a61b-197425eb3a45": {"definition": "The P and Q channels of CD subcode-control and timing data interleaved with the audio at one subcode frame per 588 samples (75 frames per second) under the Red Book (IEC 60908); the P channel flags track and pause boundaries while the Q channel carries track/index numbers, running times, and codes such as ISRC and UPC/EAN.", "plain_english": "Along with the music, a CD carries a stream of hidden data. The PQ part tells the player which track you are on and the time. It also marks where tracks and gaps begin. This is what makes the display and skip buttons work.", "purpose_function": "It provides the navigation and timing layer of the CD standard, letting players locate tracks, show elapsed and remaining time, and mark pauses without interrupting the audio data.", "practical_application": "When an engineer sets track markers and codes in mastering software, they are writing PQ subcode that a CD player later reads to build its track menu and time display.", "category": "CD Premastering", "related_terms": ["PQ editing", "PQ sheet", "Red Book", "Pre-gap audio", "ISRC", "DDP image"], "common_mistakes": ["Confusing the eight subcode channels (P through W); only P and Q carry the basic track and timing data", "Assuming subcode is part of the audio samples rather than separate interleaved data", "Thinking ISRC lives in the audio when it is actually stored in the Q subcode"], "scenario_contexts": ["Troubleshooting a disc whose track times display incorrectly", "Embedding ISRC codes into the Q channel during mastering", "Verifying track and index navigation on a burned reference disc"]}, "52c0e91f-dfd9-4963-be90-d4d9e7b0dce8": {"definition": "Audio placed in the pause/pre-gap region (Index 0) that precedes a track's Index 1 start point on a CD, used for hidden tracks before track 1 or for continuous audio that runs through the gap between tracks, in place of the Red Book default of silence.", "plain_english": "The short gap before a CD track is usually silent. But you can hide sound there instead. That is pre-gap audio. It is like the secret song some albums tuck in before track 1.", "purpose_function": "It lets engineers use the pause region creatively-hidden intros, count-ins, or seamless transitions-while keeping standard track navigation intact.", "practical_application": "To create a hidden track, an engineer lengthens the pre-gap before track 1 and places audio there; for a live album they let applause run through the pre-gaps so tracks flow without silence.", "category": "CD Premastering", "related_terms": ["Pre-gap", "PQ editing", "PQ subcode", "Index point", "Red Book", "Hidden track"], "common_mistakes": ["Assuming a pre-gap must always be silent, when audio can be placed there instead", "Hiding important audio in the pre-gap before track 1, which some players and rippers will not access", "Confusing pre-gap audio at Index 0 with the actual track start at Index 1"], "scenario_contexts": ["Adding a hidden bonus track before track 1", "Keeping crowd noise continuous across tracks on a live album", "Setting gap lengths so seamless transitions are not broken by silence"]}, "7ba30c0d-bf29-40b3-b16d-3f9ba4bd41b9": {"definition": "The final, assembled digital image of a disc-complete with audio, PQ subcode, and metadata-delivered to a replication plant as the production master, most commonly a DDP (Disc Description Protocol) image or, historically, a PMCD.", "plain_english": "A premaster image is the finished, ready-to-copy version of a whole disc. It is one set of files. The factory uses it to stamp out every copy. So it has to be exactly right.", "purpose_function": "It packages everything the plant needs-audio, track markers, and codes-into one verifiable deliverable so every pressed copy matches the approved master.", "practical_application": "After PQ editing, the engineer exports a DDP premaster image, verifies its checksum, and uploads it to the pressing plant instead of mailing a physical disc.", "category": "Delivery & QC", "related_terms": ["DDP image", "PQ sheet", "PQ editing", "Pressing approval", "Red Book", "Checksum"], "common_mistakes": ["Sending a burned audio CD-R instead of a verified DDP premaster image", "Not verifying the image's checksum before delivery", "Editing audio after the premaster image is approved without regenerating and re-verifying the image"], "scenario_contexts": ["Delivering a finished album to a CD or vinyl plant", "Archiving the exact production master for a future repressing", "Verifying a premaster image's integrity with checksums before manufacturing"]}, "8549dd4e-feee-4ccf-bea6-aa1931a2a82a": {"definition": "A documented plan governing the transfer of legacy audio recordings to archival digital form, specifying source-media assessment and handling, playback equipment and signal chain, target file formats and sampling parameters, metadata capture, and quality control, in line with recognized archival practice such as IASA-TC 04.", "plain_english": "Old tapes and records do not last forever. So archives copy them to digital files before they fail. A preservation transfer plan is the written game plan for that work. It keeps the copying careful and the same for every item.", "purpose_function": "It ensures transfers are done consistently, safely, and at archival quality so the digital copy faithfully preserves the original and stays usable long after the source media decays.", "practical_application": "Before digitizing a collection of reel-to-reel tapes, an archivist writes a plan covering tape inspection, whether baking is needed, playback deck and A/D settings, target file format such as high-resolution PCM, and the metadata to log for each item.", "category": "Archival Transfer", "related_terms": ["Polyester tape base", "Sticky-shed syndrome", "Tape baking", "Magnetic tape", "Sample rate", "Metadata"], "common_mistakes": ["Starting transfers with no documented plan, leading to inconsistent formats and missing metadata", "Playing fragile or sticky-shed tapes without inspection or baking, which sheds oxide onto the head and can damage both tape and machine", "Choosing lossy or low-resolution target files that fail archival preservation standards"], "scenario_contexts": ["Planning digitization of a radio station's tape archive", "Setting standard file formats and metadata for a preservation project", "Assessing at-risk acetate and polyester tapes before transfer"]}, "aa69b7da-74fd-453f-9a6d-254a6e32fcc4": {"definition": "The quality-control step in which a test pressing (vinyl) or reference/check disc (CD) made from the master is critically auditioned and inspected and then formally approved before the plant proceeds with the full manufacturing run.", "plain_english": "Before a factory makes thousands of records, it makes a few sample copies first. Pressing approval is when someone listens to a sample. They check it for problems. If it sounds right, they give the green light for the full run.", "purpose_function": "It catches defects-noise, distortion, skips, wrong levels, or manufacturing faults-while only a few copies exist, preventing a whole flawed production run.", "practical_application": "The plant sends test pressings; the engineer and client audition them on a good system, check for ticks, warps, and inner-groove distortion, and either sign off or request a recut before mass pressing.", "category": "Delivery & QC", "related_terms": ["Test pressing", "Premaster image", "Inner-groove distortion", "Lacquer cutting", "Reference disc", "PQ sheet"], "common_mistakes": ["Approving a test pressing after only a quick or partial listen instead of auditioning every side in full", "Judging a test pressing on a poor playback system that hides defects", "Confusing normal source-material qualities with pressing faults, or the reverse, when deciding whether to approve"], "scenario_contexts": ["Auditioning vinyl test pressings before a full production run", "Checking a CD reference disc against the approved master", "Deciding whether to approve or request a recut after finding a defect"]}, "e2f8752e-435a-46d2-8508-ce4b37a9ebdc": {"definition": "In disc mastering, an arrangement that supplies the lathe's automatic pitch and depth control with an advance (preview) copy of the audio, timed roughly one groove revolution ahead of the signal being cut, so groove spacing can be adjusted before loud or bass-heavy passages arrive. It is implemented either with a separate preview (advance) head on the master tape machine or, for digital sources, with a delay line that delays the cutting feed while the undelayed feed drives the pitch computer.", "plain_english": "When a record is cut, the machine must space the grooves out before a loud part so they do not overlap. A preview-delay system lets the machine 'hear' the music a moment early, giving it time to make room. It works like reading a line just ahead of when you say it out loud.", "purpose_function": "It gives the lathe's variable pitch and depth system look-ahead, so it can widen groove spacing for loud or low passages and pack quiet passages tightly, fitting the most program time on a side without grooves cutting into each other.", "practical_application": "A disc-mastering engineer sets the preview time to one platter revolution (about 1.8 seconds at 33 1/3 rpm) and feeds the preview signal to the pitch computer while the delayed program feeds the cutter head.", "category": "Disc Mastering", "related_terms": ["Cutting lathe", "Variable pitch", "Lacquer master", "Reference lacquer", "Groove spacing"], "common_mistakes": ["Setting the preview delay to the wrong time, so the pitch control opens up too early or too late and wastes side length or overcuts adjacent grooves.", "Assuming the preview signal is heard on the finished record, when it only drives the automatic spacing and is not part of the cut audio.", "Forgetting that a digital preview delay must match the platter speed, so a 45 rpm cut needs a different delay time than a 33 1/3 rpm cut."], "scenario_contexts": ["Cutting a loud, bass-heavy master to a 12-inch lacquer where wide groove spacing is needed to keep adjacent grooves from cutting into each other.", "Fitting a long album side onto one lacquer by letting the automatic pitch pack quiet passages tightly.", "Setting up a lathe to cut from a digital file rather than a tape machine that has a physical preview head."]}, "9e9f1086-8bcf-4101-8265-06a7bce06c51": {"definition": "The final, approved master from which all consumer copies of a release are manufactured, for example a DDP fileset or PMCD for CD, a cutting master for vinyl, or an encoded master for digital distribution. It is the last stage of the mastering chain and is not altered further; every replicated or distributed copy derives from it.", "plain_english": "This is the final, finished version of a recording that a factory or store copies to make every disc or download. Nothing is changed after it, so every copy people get comes from it. It is like the master stamp used to press identical coins.", "purpose_function": "It locks the finished, approved sound and metadata into one authoritative source, so that every manufactured or distributed copy is identical and matches what the artist and label signed off on.", "practical_application": "A mastering engineer delivers the production master as a DDP image, PMCD, or distribution-ready file set, checks it against the approved reference, and sends it to the replication plant or distributor.", "category": "Master Deliverables", "related_terms": ["Reference master", "DDP fileset", "PMCD", "Cutting master", "Remastering"], "common_mistakes": ["Confusing the production master with a rough or reference mix and sending an unapproved version for manufacture.", "Editing or re-rendering the master after approval, so pressed or streamed copies no longer match the signed-off reference.", "Delivering the wrong sample rate or bit depth for the target format, forcing the plant to re-encode and change the sound."], "scenario_contexts": ["Sending a DDP fileset to a CD plant for glass-master and disc replication.", "Uploading a distribution master to a streaming aggregator.", "Handing a vinyl cutting master to a lathe engineer for lacquer cutting."]}, "fce34dc6-3ded-495d-8e28-acb3541a3703": {"definition": "A stem containing only the musical elements of a program or track, prepared and delivered for promotional material such as on-air promos, trailers, or advertisements, so the music can be reused or re-balanced independently of dialogue and effects.", "plain_english": "A stem is a mix that holds just one group of sounds. A promo music stem holds only the music, given to the team that makes ads and trailers so they can use the music by itself. It is like getting only the drum part of a song so you can add it to something new.", "purpose_function": "It lets promo and marketing editors drop in, loop, or re-level the music without dialogue and effects, keeping promotional versions clean and giving flexibility for shorter cutdowns.", "practical_application": "A mix engineer bounces a music-only stem alongside the dialogue and effects stems and includes it in the promo package so a network's promo department can build trailers and spots.", "category": "Stem Delivery", "related_terms": ["Stem", "M&E", "Dialogue stem", "Effects stem", "Full mix"], "common_mistakes": ["Baking effects or dialogue into the music stem, so it is no longer clean music-only.", "Delivering the stem at a different level or sync than the full mix, so it does not line up when recombined.", "Assuming one stem covers all promo needs when different cutdown lengths or alternate mixes are required."], "scenario_contexts": ["Supplying a network's promo team with a show's music so they can cut a trailer.", "Building a 30-second ad that reuses a track's music bed without the vocal or effects.", "Delivering stems so an international promo can be re-voiced over the same music."]}, "1af80f9b-ba0e-43dd-9f8e-0203f403fac0": {"definition": "An alternate mix of a musical cue built from a reduced version of the score, using fewer instruments or a condensed arrangement, supplied so a thinner, less busy version of the music is available, for instance to sit beneath dialogue or narration or for simpler placements.", "plain_english": "A full score can have many instruments playing at once. A reduced score mix is the same music played by fewer instruments and mixed as its own version. It gives a lighter, less busy option, handy when someone is talking over the music.", "purpose_function": "It provides a thinner alternate of a cue so the music can support speech or a quiet scene without crowding the mix, while still matching the full version.", "practical_application": "A score mixer prints a reduced version alongside the full mix so the dubbing stage can choose the lighter cue where dialogue or effects need room.", "category": "Music Delivery", "related_terms": ["Score mix", "Underscore", "Full mix", "Stem", "Cue"], "common_mistakes": ["Treating the reduced mix as a stem, when it is a complete alternate mix rather than a single element group.", "Letting the reduced version drift out of sync or tuning with the full mix, so the two cannot be swapped.", "Stripping out so much that the reduced mix no longer reads as the same cue."], "scenario_contexts": ["Delivering a lighter version of a cue to sit under heavy dialogue on a dubbing stage.", "Offering a simpler arrangement of a theme for a quiet scene.", "Providing an alternate mix for a promo that needs less instrumentation."]}, "4374072e-8d3c-4656-8ea9-555c98d9facb": {"definition": "A lacquer-coated disc, commonly called an acetate, cut as a temporary reference so a recording can be auditioned on an ordinary turntable before committing to a production lacquer and pressing. It is a soft, short-lived cut used only for evaluation and approval, not for mass manufacture.", "plain_english": "This is a one-off record cut so people can play a mix on a normal turntable and check it before the real records are made. It wears out fast, so it is only for listening and approval. Think of it as a rough draft you can actually play.", "purpose_function": "It lets the artist, label, or engineer hear how a master will sound as a played-back disc and approve it before the costlier, one-way steps of production cutting and plating.", "practical_application": "A cutting engineer cuts a reference acetate from the master, sends it out for approval, and only cuts the production lacquer once the acetate is signed off.", "category": "Disc Mastering", "related_terms": ["Reference lacquer", "Lacquer master", "Dubplate", "Reference pressing", "Cutting lathe"], "common_mistakes": ["Calling it 'acetate' and thinking it is made of acetate, when the coating is actually nitrocellulose lacquer over a metal or glass base.", "Playing a reference acetate many times, not realizing each play wears the soft groove and dulls the sound.", "Judging final quality from an acetate, which does not sound identical to the finished pressing."], "scenario_contexts": ["Cutting a quick reference disc so a band can hear their master on a home turntable.", "Checking that a bass-heavy master tracks cleanly under a stylus before production.", "Sending an acetate to a label for sign-off before plating begins."]}, "668bac2d-9517-4806-9d32-612003f4c5c7": {"definition": "A lacquer (acetate) disc cut for listening and approval, as distinct from the production lacquer that is silvered and electroplated to make stampers. It lets the cut be checked on a turntable before the one-way plating and pressing process begins.", "plain_english": "A lacquer is the soft disc a record is first cut onto. A reference lacquer is one cut just so people can play it and approve the sound, not the one used to make the factory stampers. It is a playable check before the point of no return.", "purpose_function": "It gives a listenable version of the cut for sign-off, guarding against sending a flawed cut into the irreversible plating and pressing chain.", "practical_application": "An engineer cuts a reference lacquer for the client to approve, then cuts a separate production lacquer for plating once the sound and levels are confirmed.", "category": "Disc Mastering", "related_terms": ["Reference acetate", "Lacquer master", "Reference pressing", "Cutting lathe", "Stamper"], "common_mistakes": ["Confusing the reference lacquer with the production lacquer that goes into the plating bath.", "Expecting a lacquer to survive many plays, when it is soft and degrades with use.", "Assuming the lacquer's sound equals the final pressing, which is shaped further by plating and pressing."], "scenario_contexts": ["Cutting a lacquer for client approval before committing to plating.", "Comparing two cutting levels on lacquers to choose the best side length.", "Auditioning a lacquer to confirm sibilance and bass track cleanly."]}, "cb8a1262-9c21-4c55-8a22-5d7efa43b63c": {"definition": "An approved master used as the sonic reference against which later copies, transfers, or manufactured products are checked. It defines the target sound and level that a production master or pressing must match.", "plain_english": "This is the approved 'sounds right' version everyone compares against. When a copy or pressing is made, engineers check it against the reference master to be sure it matches. It is like the answer key you check your work against.", "purpose_function": "It sets the agreed sonic target so that production masters, transfers, and manufactured copies can be verified as faithful before release.", "practical_application": "A mastering engineer keeps the approved reference master on hand and A/Bs it against test pressings or new transfers to confirm they match.", "category": "Master Deliverables", "related_terms": ["Production master", "Reference pressing", "Remastering", "Reference lacquer", "Cutting master"], "common_mistakes": ["Mixing up the reference master with the production master, when one is the target and the other is what gets manufactured.", "Not documenting the reference master's level and format, making later matching guesswork.", "Assuming any early mix is the reference, when only the approved version counts."], "scenario_contexts": ["Checking a vinyl test pressing against the approved reference master.", "Verifying a new digital transfer matches the reference before release.", "Confirming a plant's copy has not drifted from the approved sound."]}, "17d65a8f-917b-48aa-9c64-5dbb887ed6cd": {"definition": "A record pressed from the finished stampers and sent to the artist, label, or engineer for approval before the full production run, commonly called a test pressing. It is checked for surface noise, defects, level, and overall sound.", "plain_english": "Before a factory presses thousands of records, it makes a few from the finished parts and sends them out to be checked. This reference pressing lets people catch problems like noise or skips before the big run. It is like a proof copy before printing a whole book run.", "purpose_function": "It provides a real, playable sample from the actual stampers so faults can be caught and the sound approved before committing to a costly full pressing run.", "practical_application": "The artist or mastering engineer plays the reference pressing on a good turntable, listens for clicks, distortion, and level, and either approves the run or asks for a re-cut.", "category": "Disc Mastering", "related_terms": ["Test pressing", "Reference lacquer", "Reference master", "Stamper", "Cutting master"], "common_mistakes": ["Approving a reference pressing after only a quick listen, missing defects that show up later in the run.", "Judging it on a poor turntable, so real problems are hidden or false ones imagined.", "Assuming every production copy will sound identical, when stamper wear can change later pressings."], "scenario_contexts": ["Reviewing a test pressing for surface noise before greenlighting a run.", "Comparing the pressing against the reference master to confirm the sound.", "Catching a skip or non-fill defect before thousands of copies are made."]}, "d335abfc-7f86-4b51-a977-172ac4441f71": {"definition": "The process of creating a new master from an existing recording, typically the original master tapes or files, to improve quality or adapt it to a new format, loudness target, or medium, without re-recording the performance or remixing from the multitrack.", "plain_english": "Remastering means making a fresh, improved master from a recording that already exists. The performance is not redone; the engineer cleans it up and re-balances it for today's formats. It is like restoring an old photo without taking a new one.", "purpose_function": "It brings older or format-limited recordings up to current quality and delivery standards, or prepares a catalog title for a new release format.", "practical_application": "An engineer transfers the original tapes at high resolution, then corrects level, tone, and noise to produce a new master for CD, streaming, or a vinyl reissue.", "category": "Mastering Process", "related_terms": ["Production master", "Reference master", "Restoration", "Loudness normalization", "Reissue"], "common_mistakes": ["Confusing remastering with remixing, when remastering works from the finished mix rather than the multitrack.", "Over-compressing a remaster to sound louder, sacrificing the dynamics of the original.", "Assuming a remaster always sounds better, when a poor one can harm a well-regarded original."], "scenario_contexts": ["Preparing a 1970s album from its original tapes for a streaming reissue.", "Bringing an old low-level master up to current loudness targets.", "Cleaning tape hiss and re-balancing tone for a remastered CD edition."]}, "1bd1d89c-4175-44f4-91b6-1b4c21f6d70d": {"definition": "A verification step in object-based/immersive audio finishing that confirms a program's audio and accompanying metadata decode and render correctly across the target renderers and playback configurations — for example different speaker layouts and binaural or stereo downmix outputs — so the delivered mix translates as intended.", "plain_english": "A test that makes sure an immersive mix plays back well on every system it reaches. It checks the mix still sounds right on many speakers, a soundbar, or plain headphones.", "purpose_function": "It exists to catch translation and metadata errors before delivery, so the mix stays consistent across every renderer and speaker layout the audience might use.", "practical_application": "An engineer auditions the master through the renderer's binaural and downmix outputs and on different speaker configurations, confirming object positions, levels, and metadata behave correctly before sign-off.", "category": "Immersive Audio", "related_terms": ["Renderer metadata", "Object audio", "Bed channel", "Binaural render", "Downmix", "Immersive master"], "common_mistakes": ["Checking only the full speaker layout and never auditioning the binaural or stereo downmix that most listeners actually hear", "Assuming a mix that sounds correct in one DAW renderer will render identically in every decoder", "Ignoring metadata errors such as wrong object positions or trim settings because the beds sound fine"], "scenario_contexts": ["Finishing a Dolby Atmos music master before delivery to a streaming service", "Preparing an immersive film mix for both cinema and home-theatre decoders", "Confirming a soundbar downmix of an object-based program matches the reference mix"]}, "3a262916-cfe3-4e6e-a9b9-3dab0c19be19": {"definition": "The descriptive data carried alongside object-based/immersive audio that tells the renderer how to reproduce each element — parameters such as object x/y/z position, size, gain, and bed/channel assignment — rather than the audio being fixed to specific speaker feeds.", "plain_english": "Instructions that travel with immersive audio and tell the playback system where each sound should go. Instead of locking a sound to one speaker, the metadata says place it here, and the system picks the speakers.", "purpose_function": "It lets one master adapt to many speaker layouts, because the renderer uses the metadata to place each sound correctly for whatever playback system is present.", "practical_application": "Engineers set and automate object positions, sizes, and gains in the renderer, and that metadata is embedded in the deliverable so decoders can recreate the intended spatial mix on any system.", "category": "Immersive Audio", "related_terms": ["Renderer compatibility check", "Object audio", "Bed channel", "Audio Definition Model", "Binaural render", "Downmix"], "common_mistakes": ["Confusing metadata-driven object positions with fixed channel assignments", "Forgetting that incorrect metadata can ruin the spatial image even when the audio itself is clean", "Not checking that authored metadata survives the export or encode to the delivery format"], "scenario_contexts": ["Automating an instrument's position around the room in an Atmos music mix", "Delivering an ADM BWF master where object metadata must stay intact", "Troubleshooting why a program collapses to the front speakers on playback"]}, "f00bde6f-f3a0-4c7c-b310-f6e7eab2a313": {"definition": "The final, quality-control-approved production master supplied to a disc-manufacturing plant as the exact source for replication (mass-pressing of discs from a glass master and stampers), as distinct from duplication (burning individual discs); for CD it is typically a verified DDP image or approved premaster.", "plain_english": "The final, checked master a factory uses to mass-produce pressed discs. Every copy is stamped from this one approved source, so it must have no errors.", "purpose_function": "It gives the pressing plant a single verified reference so that every replicated disc is an exact copy of the approved master.", "practical_application": "A mastering engineer exports and error-checks a DDP image or supplies approved parts, then sends this replication master to the plant, which cuts the glass master and stampers from it.", "category": "Disc Mastering", "related_terms": ["DDP", "Glass master", "Premaster", "Duplication", "PQ codes", "Run-out groove"], "common_mistakes": ["Confusing replication (pressing from a stamper) with duplication (burning individual discs)", "Sending a master without verifying the DDP checksum, so any error gets pressed into every copy", "Assuming last-minute changes are still possible after the glass master has been cut"], "scenario_contexts": ["Delivering a CD album to a pressing plant as a verified DDP image", "Supplying approved parts for a vinyl or optical-disc pressing run", "Archiving the exact source used to manufacture a commercial release"]}, "2264dd96-6d38-4375-8eef-2afe7246fb3b": {"definition": "A score stem — a submixed group of a film, TV, or game musical score — that contains only the reverb and other wet effect returns, with the dry direct signals routed to separate stems, so the score's ambience can be balanced or removed independently in the final mix.", "plain_english": "A separate track that holds only the echo and room sound of the music, not the dry instruments. Keeping it apart lets the mixer turn the music's space up or down on its own.", "purpose_function": "It gives the re-recording mixer independent control over the score's ambience, so reverb can be adjusted against dialogue and effects without touching the dry music.", "practical_application": "A composer or music editor delivers the wet reverb returns as their own stem so the dub stage can dial the score's space in or out for clarity under dialogue.", "category": "Stem Delivery", "related_terms": ["Score stem preparation", "Rhythmic music stem", "Score printmaster", "Reverb return", "Stem mixing", "Score-stem quality control"], "common_mistakes": ["Baking the reverb into the dry music stem, which removes the mixer's ability to adjust ambience", "Delivering the reverb stem at a different sample rate or length than the other score stems", "Assuming the reverb stem alone is a usable mix — it must sum with the dry stems"], "scenario_contexts": ["Delivering film score stems so the dub stage can reduce music reverb under dialogue", "Rebalancing a game's musical ambience for a drier in-game mix", "Recreating a score's original space when re-mixing for a new format"]}, "a25571e6-db2f-4c84-812e-f3d2c83ca3a0": {"definition": "A music stem containing the rhythmic elements of a piece — such as drums, percussion, and other timekeeping or groove parts — grouped together so they can be balanced or muted independently of the melodic and harmonic stems.", "plain_english": "A single track that holds all the beat and percussion parts of the music, kept apart from the melodies. The mixer can then push the groove up or pull it back on its own.", "purpose_function": "It lets a mixer control the energy and drive of a cue independently, for example lowering the beat under dialogue or emphasizing it in an action scene.", "practical_application": "A composer stems the drums and percussion into one rhythmic stem so the final mix can adjust the groove's level without affecting the melody or pads.", "category": "Stem Delivery", "related_terms": ["Reverb-only score stem", "Score stem preparation", "Stem mixing", "Music stem", "Dialogue stem", "Score printmaster"], "common_mistakes": ["Including melodic parts in the rhythmic stem, which defeats the point of separating the groove", "Delivering stems that do not sum back to the approved full mix", "Mismatched start times or lengths between the rhythmic stem and the other stems"], "scenario_contexts": ["Lowering the drum groove under dialogue on a film dub stage", "Giving a game's interactive system a separate rhythm layer to fade in and out", "Rebalancing a song's beat for a TV promo edit"]}, "a2efe7b1-b5c4-4ca3-bf49-cc2a2cd4b852": {"definition": "The section of groove at the very end of a phonograph record side, after the recorded program — comprising the lead-out (run-off) spiral that guides the stylus inward and terminating in a locked, concentric groove that keeps the stylus in place; the surrounding blank land often carries matrix and run-out etchings.", "plain_english": "The groove at the end of a record side, after the music stops. Its spiral guides the needle inward to a closed loop that stops it drifting off, and the blank ring there often has hand-etched codes.", "purpose_function": "It safely parks the stylus after playback by way of a locked groove and provides blank land where the cutting engineer etches matrix and identification codes.", "practical_application": "When cutting a lacquer, the mastering engineer sets the lead-out and locked groove and scribes matrix numbers into the run-out; plants and collectors later read those etchings to identify the pressing.", "category": "Vinyl Mastering", "related_terms": ["Lead-in groove", "Locked groove", "Lacquer cutting", "Matrix number", "Replication master", "Stylus"], "common_mistakes": ["Confusing the run-out groove at the end of the side with the lead-in groove at the start", "Thinking the run-out etchings are pressing defects rather than intentional matrix codes", "Assuming every record has a locked groove — some run off toward the label instead"], "scenario_contexts": ["Reading matrix numbers in a record's run-out to identify the pressing plant", "Cutting a lacquer and scribing identification codes into the run-out area", "Diagnosing a stylus that will not lift because a record lacks a proper locked groove"]}, "72f445c2-b190-4aaa-a5c7-a879cad28237": {"definition": "The final, print-ready master of a production's mixed musical score — a fully balanced, format-conformed rendering of the music used for lay-back to picture and as the source for the music element in the final re-recording mix, from which delivery stems are derived.", "plain_english": "The finished, ready-to-use master of a film's music. Everything in the score is already mixed and balanced, so it can drop straight into the movie.", "purpose_function": "It provides a single approved music master the dub stage can place against dialogue and effects, delivering the score in its final, format-correct form.", "practical_application": "After the scoring mix is approved, the engineer prints the score printmaster in the required format, sample rate, and frame rate so the re-recording mixer can integrate it into the final mix.", "category": "Score Delivery", "related_terms": ["Score stem preparation", "Score-stem quality control", "Reverb-only score stem", "Rhythmic music stem", "Stem mixing", "Final mix"], "common_mistakes": ["Confusing the score printmaster (music only) with the full-mix printmaster that also includes dialogue and effects", "Printing at the wrong sample rate or frame rate so it will not conform to picture", "Delivering without checking sync against the locked cut"], "scenario_contexts": ["Printing the final scoring mix for lay-back to a feature film", "Delivering the music master for a TV episode's final dub", "Archiving the approved score master for future re-use or remixing"]}, "0022ffeb-457f-448a-8fcd-7b9269ccdfa9": {"definition": "The process of organizing and rendering a musical score into its component stems — submixed groups such as strings, brass, percussion, and reverb returns that sum to the approved full score — conformed to the required format, sample rate, level, and length for delivery.", "plain_english": "Getting the music ready by splitting it into grouped tracks that add back up to the full score. Each group, such as strings or drums, is exported cleanly so a mixer can adjust it later.", "purpose_function": "It gives the final mix flexible, independent control over parts of the score and provides broadcasters and archives with the separated elements they require.", "practical_application": "A music editor bounces the score into agreed stem groups, checks they null against the full mix, and labels and formats them to the delivery spec.", "category": "Score Delivery", "related_terms": ["Score-stem quality control", "Score printmaster", "Reverb-only score stem", "Rhythmic music stem", "Stem mixing", "Null test"], "common_mistakes": ["Creating stems that do not sum back to the approved full mix", "Leaving processing on the master bus so the stems do not null correctly", "Inconsistent naming, levels, or lengths across the stem set"], "scenario_contexts": ["Preparing score stems for a film's final re-recording mix", "Delivering separated music elements for international and M&E versions", "Bouncing stems so a game engine can recombine them interactively"]}, "16a0f464-5dbb-4480-8536-e6328a8ccd2c": {"definition": "The verification stage in which delivered score stems are checked for technical and musical correctness — confirming they sum (null) to the approved full mix, share matching format, sample rate, start time and length, and are free of clicks, dropouts, clipping, and labeling errors before delivery.", "plain_english": "A final check of the music stems before they go out. You make sure they add back up to the full mix and have no clicks, wrong lengths, or mislabels.", "purpose_function": "It catches errors before delivery, so the mix stage or client receives stems that are correct, in sync, and reassemble into the intended score.", "practical_application": "An engineer sums the stems and null-tests them against the printmaster, then scans each stem for clipping, dropouts, sync, and naming errors before sign-off.", "category": "Score Delivery", "related_terms": ["Score stem preparation", "Score printmaster", "Reverb-only score stem", "Null test", "Clipping", "Dropout"], "common_mistakes": ["Skipping the null test, so stems that do not sum to the full mix slip through", "Missing clicks, dropouts, or clipping because only levels were checked", "Overlooking mismatched start times that break sync when stems are recombined"], "scenario_contexts": ["QC of score stems before delivery to a film's dub stage", "Verifying broadcast music stems meet a network's delivery spec", "Catching a clipped or misnamed stem before it ships to the client"]}, "a64b94d5-fc9c-41dc-902c-4663484a754b": {"definition": "A CD-writing method in which each session — a self-contained group of tracks with its own lead-in and lead-out — is recorded in a single continuous pass while the disc is left open so further sessions can be added. In mastering it is used mainly for Enhanced or mixed-mode CDs that combine an audio session with a data session, whereas a replication-ready Red Book audio master requires Disc-At-Once instead.", "plain_english": "A way of burning a CD where a whole batch of tracks is written in one go, but the disc stays open so you can add more later. It is used for discs that hold both music and computer files. For normal music CDs sent to a factory, engineers use Disc-At-Once instead.", "purpose_function": "It lets one disc carry more than a single session — for example an audio session plus a data session — by finishing each session on its own while keeping the disc writable. This supports Enhanced CD formats that a single Disc-At-Once write cannot create.", "practical_application": "An authoring engineer chooses Session-At-Once when building a mixed-mode or Enhanced CD, but switches to Disc-At-Once for any audio master going to a pressing plant, because run-out sectors left by other modes can be read as uncorrectable errors.", "category": "CD Mastering", "related_terms": ["Disc-At-Once", "Track-At-Once", "Red Book", "DDP", "Enhanced CD"], "common_mistakes": ["Using Session-At-Once for an audio master meant for replication, when Disc-At-Once is required.", "Assuming any burned CD-R is Red Book compliant no matter which write mode was used.", "Confusing sessions with tracks — one session can hold many tracks."], "scenario_contexts": ["Authoring an Enhanced CD that pairs an audio album with bonus video or data files.", "Preparing a mixed-mode disc for a promotional release.", "Deciding on a write mode before sending a master to a pressing plant."]}, "78da7d4e-baa3-45e2-9633-03fc105906f7": {"definition": "In vinyl mastering, the practice of arranging program length, cutting level and low-frequency content so each side of a record can be cut cleanly. Because a longer side forces grooves closer together, the engineer trades playing time against maximum level, bass energy and groove spacing to keep tracking reliable and quality high.", "plain_english": "On a record, the more music you fit on one side, the quieter and thinner it must be cut. This work balances how long each side runs against how loud and how much bass it can hold. Short sides can be loud and full; long sides must be tamed.", "purpose_function": "It exists because a lacquer has limited space, so packing grooves tighter for a longer side lowers the level that can be cut and risks mistracking. Managing side length protects loudness, low end and reliable playback.", "practical_application": "A vinyl mastering engineer checks each side's total time, then sets track order, cutting level and how much bass to keep in mono, often splitting an album so no single side runs over-length.", "category": "Vinyl Mastering", "related_terms": ["Lacquer cutting", "Groove spacing", "Bass mono", "RIAA equalization", "Cutting lathe"], "common_mistakes": ["Cramming too much time onto one side, then wondering why it plays back quiet or distorted.", "Ignoring heavy bass content, which widens grooves and uses up space fast.", "Placing the loudest track at the inner grooves, where cutting quality is lowest."], "scenario_contexts": ["Splitting a long album across sides so neither one runs over-length.", "Deciding whether a loud, bass-heavy single fits on one 7-inch side at 45 rpm.", "Advising a client to trim runtime so the record can stay loud."]}, "fdafa565-5fb9-491f-a887-e78ac7055ff8": {"definition": "The mastering of a single — a standalone release built around one lead track, sometimes with a remix or B-side — rather than a full album or EP. It applies the usual finishing process of level, tone, dynamics and format masters, but focuses on making that one track competitive and consistent across release outlets.", "plain_english": "Getting one song ready for release on its own, instead of as part of an album. The engineer polishes its loudness and tone so it holds up next to other hits. It may also include a remix or two.", "purpose_function": "It exists so a track released on its own sounds finished and competitive on streaming, radio and other outlets. With no album around it, the single has to stand fully by itself.", "practical_application": "A mastering engineer sets the single's loudness and tone to modern targets, delivers the format masters each outlet needs, and compares it against reference tracks in the same genre.", "category": "Mastering Workflow", "related_terms": ["Album mastering", "Loudness normalization", "Reference track", "Streaming master", "Sequencing"], "common_mistakes": ["Mastering a single much louder than the artist's album, so the catalogue sounds inconsistent.", "Sending one file everywhere instead of the correct format masters.", "Ignoring streaming loudness targets and getting turned down on playback."], "scenario_contexts": ["Preparing a lead single ahead of an album campaign.", "Mastering a one-off track for a playlist pitch.", "Delivering a single with both clean and explicit versions."]}, "429b0891-1006-40d5-b8be-0b67aa52ed51": {"definition": "A stem — a grouped submix bounced as its own audio file — that carries the featured soloist, such as a lead vocal or solo instrument, kept separate from the rest of the mix. It lets a mastering or re-mix engineer adjust the soloist's level and tone independently of the backing.", "plain_english": "A separate audio file that holds just the star part, like the lead singer or a solo guitar. Keeping it on its own lets the engineer turn it up or down without touching the rest of the music. It is one of several grouped files handed over for mastering.", "purpose_function": "It exists to give control over the most important element after mixing is finished, so the soloist can be lifted, brightened or dipped without a full remix. This helps in stem mastering and when making alternate versions.", "practical_application": "In stem mastering the engineer receives the soloist stem alongside the music and other stems, and nudges its level or EQ so the lead sits right before combining everything into the final master.", "category": "Stem Mastering", "related_terms": ["Stem mastering", "Lead vocal", "Submix", "Music stem", "Stem"], "common_mistakes": ["Delivering the soloist stem with print effects baked in, so it can no longer be adjusted cleanly.", "Stems that do not add back up to the original mix because levels or routing changed.", "Confusing a stem with a single track — a stem can hold several grouped parts."], "scenario_contexts": ["Raising a quiet lead vocal during stem mastering without going back to a remix.", "Creating an instrumental version by muting the soloist stem.", "Delivering stems for a film or streaming remix."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"9cb16b2b-162d-4d99-8f29-c6af4b159123": {"definition": "A stem that carries the sound-design elements of a music production — risers, impacts, textures, drones and other designed effects — grouped as a single audio file separate from the drum, bass, melodic and vocal stems. It lets these atmospheric or transitional sounds be balanced on their own during stem mastering or re-mixing.", "plain_english": "A separate file that holds the special-effect sounds in a track, like whooshes, booms and background textures. Keeping them apart lets the engineer set how loud these effects sit without changing the drums or vocals. It is one of the grouped files handed over for mastering.", "purpose_function": "It exists so designed, non-instrumental sounds can be controlled on their own, since they often need a different level or brightness than the musical parts. This helps in stem mastering and when adapting a track for picture or games.", "practical_application": "A stem mastering engineer receives the sound-design stem with the other stems and adjusts its level and tone so risers and impacts add energy without swamping the mix.", "category": "Stem Mastering", "related_terms": ["Stem mastering", "Music stem", "Riser", "Submix", "Soloist stem"], "common_mistakes": ["Burying transitional effects so low that they lose their build-up impact.", "Letting loud impacts trigger the master limiter and pump the whole mix.", "Bouncing the stem with different processing than the reference mix, breaking the sum."], "scenario_contexts": ["Balancing risers and impacts in an electronic track during stem mastering.", "Adapting a song's effects layer for a trailer or game.", "Muting the sound-design stem to make a cleaner instrumental."]}, "8037d916-7922-4d71-872f-364caf2e88d4": {"definition": "In immersive, object-based audio such as Dolby Atmos, a re-render is a channel-based bounce of the master made for a specific speaker layout — for example 7.1.4, 5.1, stereo or binaural — produced by the renderer from the same object mix. It provides ready deliverables for playback systems that are not object-capable.", "plain_english": "Immersive mixes store sounds that can move anywhere in the room. A speaker re-render turns that master into a fixed version made for one speaker setup, such as 5.1 surround or plain stereo. It lets the mix play back right on systems that cannot handle the moving-sound format.", "purpose_function": "It exists because listeners do not all have the same speakers, so one object-based master is folded down into set channel layouts for delivery. This gives a controlled result on stereo, surround and headphone playback.", "practical_application": "Working in the Dolby Atmos Renderer, an engineer sets up re-renders for the layouts a label needs and bounces them alongside the master, delivering stereo, 5.1 and binaural versions from one session.", "category": "Immersive Mastering", "related_terms": ["Dolby Atmos", "Binaural render", "Downmix", "Object-based audio", "ADM BWF"], "common_mistakes": ["Assuming the stereo re-render will match a separately made stereo master — fold-down levels can differ.", "Forgetting to render every deliverable layout the distributor requires.", "Not checking the binaural re-render on headphones before delivery."], "scenario_contexts": ["Bouncing 5.1 and stereo deliverables from a Dolby Atmos music master.", "Creating a binaural version for headphone streaming.", "Supplying multiple speaker layouts for a film mix."]}, "807c6d13-2396-429c-90ae-f010f88ee131": {"definition": "In vinyl manufacturing, the electroforming step that produces the metal stamper used to press records. The cut lacquer is silvered and electroplated to grow a metal 'father'; from it a 'mother' is grown, and from the mother the negative 'stampers' are formed and mounted in the press.", "plain_english": "The step that turns a freshly cut master disc into the metal mould that stamps out records. The soft lacquer is coated in metal and copied in stages to make a tough, reversed plate. That plate presses the grooves into every copy.", "purpose_function": "It exists because the delicate lacquer cannot survive pressing thousands of records, so a hard metal negative is grown from it. The stamper is the durable tool that shapes the hot vinyl in the press.", "practical_application": "A plating technician silvers and electroforms the lacquer and produces a stamper for each side; the mastering engineer's cut quality directly sets how good those stampers, and the finished records, turn out.", "category": "Disc Manufacturing", "related_terms": ["Lacquer cutting", "Mother", "Electroforming", "Test pressing", "Pressing"], "common_mistakes": ["Thinking the stamper is a positive copy — it is a negative, mirror image of the record.", "Assuming plating can fix a noisy or poorly cut lacquer.", "Handling or storing lacquers carelessly before plating, which adds clicks and dropouts."], "scenario_contexts": ["A pressing plant plating a lacquer to begin a record run.", "Growing extra stampers to press a large order.", "Tracing surface noise back to the plating stage."]}, "f7d1bc8f-8a5b-413e-942b-3af0f5a44539": {"definition": "A mastering approach in which the engineer works from a small set of grouped submixes (stems) — such as drums, bass, music and vocals — instead of a single stereo mixdown. Processing the stems individually gives more control over balance and tone than stereo mastering, placing the work between mixing and traditional mastering.", "plain_english": "Instead of one finished stereo file, the engineer gets a few grouped tracks — like drums, bass, music and vocals — bounced separately. Working on these gives more control to fix the balance while mastering. It sits partway between mixing and normal mastering.", "purpose_function": "It exists to let a mastering engineer solve balance problems — a too-loud vocal or a weak low end — that a single stereo file cannot fix. It offers more reach than stereo mastering without a full remix.", "practical_application": "The engineer imports the stems, checks they add back up to the original mix, then processes and balances them together to reach the final master, usually when the mix needs more help than stereo mastering allows.", "category": "Mastering Workflow", "related_terms": ["Stereo mastering", "Stem", "Submix", "Mixdown", "Soloist stem"], "common_mistakes": ["Treating stem mastering as a chance to remix instead of to finish the record.", "Stems that do not add back up to the approved mix because of level or effect changes.", "Charging stereo-master rates for stem work, which takes much longer."], "scenario_contexts": ["Rescuing a mix with a buried vocal without reopening the mix session.", "A label wanting balance tweaks late in the schedule.", "Mastering a track whose low end needs separate control."]}, "aa5a76b6-a90e-4bc3-b60b-a3946394259e": {"definition": "The standard mastering process carried out on a finished two-channel stereo mixdown — a single stereo file per song — applying level, equalization, dynamics, stereo and other processing to prepare it for release. It contrasts with stem mastering, which works from grouped submixes, and with immersive mastering, which works from objects or multichannel beds.", "plain_english": "The usual way of mastering, working from one finished stereo file for each song. The engineer adjusts loudness, tone and dynamics to get it ready for release. It is the most common method and the one most engineers learn first.", "purpose_function": "It exists to give a mixed song its final polish and a consistent loudness and tone across a release, using the single stereo file the mix engineer approved. It is the baseline mastering format for most music.", "practical_application": "A mastering engineer loads the stereo mixdown, sets tone and loudness against reference tracks and release targets, then delivers the format masters for streaming, CD or vinyl.", "category": "Mastering Workflow", "related_terms": ["Stem mastering", "Mixdown", "Loudness normalization", "Mastering chain", "Reference track"], "common_mistakes": ["Over-limiting a stereo master while chasing loudness and crushing the dynamics.", "Mastering without reference tracks, so tone and level drift off target.", "Expecting stereo mastering to fix a serious mix balance problem it cannot reach."], "scenario_contexts": ["Mastering an album from approved stereo mixdowns.", "Finishing a single from one stereo bounce.", "Setting a consistent loudness across a stereo release."]}, "ce5b2333-5be7-4bf4-95a7-5e3ba209cbfa": {"definition": "The act of bouncing or exporting a two-channel (left/right) mix or master again to produce a fresh stereo audio file, typically after edits, format changes, or corrections have been made to the session or processing chain.", "plain_english": "Making a new stereo (left and right) sound file from your project after you change something. It is like re-printing a photo once you have fixed how it looks.", "purpose_function": "It captures the current state of the mix or master into a new file so later steps like further mastering, encoding, or replication use the updated audio instead of an old bounce.", "practical_application": "A mastering engineer re-renders the stereo master after tweaking EQ or fixing a bad edit, then checks the new file's peaks and loudness before delivery.", "category": "Master Delivery", "related_terms": ["Bounce/mixdown", "Stereo master", "Sample rate conversion", "Dither", "True peak", "Master bus"], "common_mistakes": ["Re-rendering with a different plugin state or gain than the approved version, giving an inconsistent master.", "Forgetting to set the correct dither or sample-rate options on the new render.", "Delivering the old bounce by mistake after changes were made."], "scenario_contexts": ["Fixing a small edit late in mastering and re-rendering the stereo file for delivery.", "Producing a corrected stereo master after a client revision.", "Re-rendering at a new sample rate for a different distribution format."]}, "bbdee0ed-4361-47f8-ad96-e260d1a27a06": {"definition": "The practice of preparing and mastering a track so it translates well after streaming services apply loudness normalization, typically targeting an integrated loudness near the platform reference (about -14 LUFS for Spotify per ITU-R BS.1770) while keeping true-peak headroom (commonly -1 dBTP) to avoid encoder distortion.", "plain_english": "Getting a song ready so it sounds good on apps like Spotify, which set every track to a similar volume. You aim for their loudness level and leave a little headroom so it does not distort.", "purpose_function": "It makes sure a release keeps its intended tone, dynamics, and clean peaks after a streaming service turns its volume up or down to match other tracks, instead of being hurt for being too loud.", "practical_application": "The engineer meters integrated LUFS and true peak, sets the limiter so the master lands near the target loudness, and checks how it will sound after normalization on each platform.", "category": "Streaming Delivery", "related_terms": ["LUFS", "Loudness normalization", "True peak", "ITU-R BS.1770", "Limiter", "Dynamic range"], "common_mistakes": ["Pushing loudness far past the streaming target, which only gets turned back down and loses dynamics.", "Ignoring true-peak limits so the lossy encoder clips.", "Assuming every platform uses the same target and the same true-peak rule."], "scenario_contexts": ["Mastering a single for release across Spotify, Apple Music, and YouTube.", "Deciding how hard to limit a loud pop track knowing it will be normalized.", "Setting a -1 dBTP true-peak ceiling before delivery to avoid AAC or Ogg distortion."]}, "f549f9f5-b0f7-4112-a32e-de200b467856": {"definition": "A stem consisting of all string-section parts (for example violins, violas, cellos, basses, or synthesized strings) combined and rendered as a single grouped audio file for use in stem mixing or stem mastering.", "plain_english": "One sound file that holds all the string instruments mixed together, like violins and cellos. It lets someone change the whole string group at once instead of each part.", "purpose_function": "It lets a mix or mastering engineer balance and process the whole string group as a unit while keeping it separate from vocals, drums, and other stems for finer control.", "practical_application": "During stem mastering the engineer gets a strings stem and can gently raise or EQ it if the strings feel too quiet or too harsh in the full mix.", "category": "Stem Mastering", "related_terms": ["Stem mastering", "Submix", "Bus", "Synthesizer stem", "Mixdown", "Master bus"], "common_mistakes": ["Printing the strings stem with different plugins or automation than the final mix, so the stems do not sum back to the mix.", "Rendering the stem too hot so it clips on its own output.", "Leaving master-bus processing on the stem so it gets processed twice later."], "scenario_contexts": ["Delivering separate stems such as drums, bass, vocals, and strings to a mastering engineer.", "Boosting the strings stem slightly during stem mastering for a fuller sound.", "Recalling a mix by re-importing stems, including the strings group."]}, "de440404-d1c4-4ef4-9625-082174319d1d": {"definition": "Professional analog magnetic tape used to record the final two-track master mix in a studio, typically 1/4-inch or 1/2-inch tape run at 15 or 30 ips, often serving as the source medium from which lacquers or digital masters are made.", "plain_english": "The reel of analog tape that holds the finished stereo mix in a studio. It is the master copy that other formats, like records or digital files, are made from.", "purpose_function": "It holds a high-quality master recording of the final mix, giving a warm analog sound and a stable source for transfer to other formats.", "practical_application": "An engineer aligns the tape machine (bias, level, azimuth) to a reference tone, records the mix at 30 ips, and later transfers the tape to digital or cuts a lacquer from it.", "category": "Analog Media", "related_terms": ["Analog tape", "Tape machine", "Bias", "Reference level", "Two-track master", "Lacquer"], "common_mistakes": ["Not printing alignment tones at the head of the tape, so playback level and EQ become guesswork.", "Storing the reel heads-out and near heat or magnetic fields, which worsens print-through and damage.", "Setting the wrong reference flux level so later transfers come out too hot or too quiet."], "scenario_contexts": ["Mixing to a 1/2-inch analog master at 30 ips for a warm, high-headroom master.", "Transferring an archived studio mastering tape to digital for a reissue.", "Cutting a vinyl lacquer directly from the analog mastering tape."]}, "02bb7588-39ca-49f7-b743-62913ebd333f": {"definition": "In disc mastering, the controlled electrical heating of the cutting stylus on a lathe (via a small heater coil adjustable in amperes) that warms and slightly softens the lacquer at the cutting point, reducing friction-induced surface noise and high-frequency cutting distortion to yield quieter grooves and cleaner high-frequency reproduction.", "plain_english": "Warming the sharp tool that carves the groove into a record master. The heat softens the surface so it cuts smoother, giving quieter, cleaner grooves, much like a warm knife slicing more neatly.", "purpose_function": "It improves groove quality by letting the stylus carve softened lacquer with less noise and distortion, especially in the high frequencies, so the cut master sounds cleaner.", "practical_application": "A disc-cutting engineer adjusts the stylus heat current while cutting a test lacquer, listening for the lowest surface noise and cleanest highs without overheating the lacquer.", "category": "Disc Mastering", "related_terms": ["Cutting lathe", "Cutting stylus", "Lacquer", "Disc mastering", "Cutter head", "Direct metal mastering"], "common_mistakes": ["Using too much heat, which can deform the groove or overheat and burn the lacquer.", "Using too little heat, leaving excess surface noise and high-frequency distortion.", "Assuming stylus heat can fix a bad cut when the real problem is level or geometry."], "scenario_contexts": ["Dialing in stylus heat current on a Neumann lathe before cutting a reference lacquer.", "Reducing surface noise on quiet passages during a vinyl cut.", "Troubleshooting harsh high frequencies in a test cut by adjusting stylus heating."]}, "3cb67baf-8e54-4278-9bcb-b2971d8c4c48": {"definition": "In CD mastering and premastering, the process of checking that the subcode data (notably the Q channel, which carries track and index numbers, timing and offsets, ISRCs, the UPC/EAN catalog number, and pre-emphasis and copy-protection flags, while the P channel acts as a simple track-start/pause flag) in a Red Book master or DDP image is correct and standards-compliant before replication.", "plain_english": "Checking the hidden data on a CD master, like track numbers, start times, and ID codes, before the disc is copied. It is like proofreading a table of contents so every track lands in the right place.", "purpose_function": "It catches errors in track starts, pauses, indexes, and embedded codes before manufacturing, preventing costly faulty pressings and making sure metadata like ISRCs is correct.", "practical_application": "Before sending a DDP to the plant, the engineer reviews the PQ log, confirms track offsets and ISRC/UPC entries, and checks that pre-emphasis flags match the audio.", "category": "CD Mastering", "related_terms": ["PQ codes", "ISRC", "DDP", "Red Book", "Track index", "UPC/EAN"], "common_mistakes": ["Entering wrong or missing ISRC or UPC codes and not catching them before replication.", "Placing track start markers or indexes at the wrong offsets, cutting off audio.", "Ignoring the pre-emphasis flag so it does not match the actual audio."], "scenario_contexts": ["Reviewing a PQ sheet before exporting a DDP for a CD pressing plant.", "Confirming ISRC codes are embedded correctly for royalty tracking.", "Checking gapless or hidden-track offsets on a live album master."]}, "e1b7148f-2208-4fde-ad9d-3e1705751512": {"definition": "A stem consisting of all synthesizer parts in a production combined and rendered as a single grouped audio file for use in stem mixing or stem mastering.", "plain_english": "One sound file that holds all the synth parts mixed together. It lets someone change every synth at once instead of one at a time.", "purpose_function": "It groups the synth parts so a mix or mastering engineer can balance or process them as a unit while keeping them separate from drums, bass, and vocals.", "practical_application": "In stem mastering the engineer can lower or brighten the synthesizer stem if the synths clash with the vocal, without touching the other stems.", "category": "Stem Mastering", "related_terms": ["Stem mastering", "Submix", "Bus", "Strings stem", "Mixdown", "Master bus"], "common_mistakes": ["Printing the synth stem with automation or effects that differ from the final mix.", "Rendering the stem too hot so it clips on its own output.", "Leaving master-bus compression on the stem so it gets processed twice."], "scenario_contexts": ["Sending drums, bass, vocal, and synthesizer stems to a mastering engineer.", "Taming a harsh synth by EQ-ing just the synthesizer stem in stem mastering.", "Recalling a track later using its printed stems."]}, "29a2e700-7ba2-413d-8b5e-efa351429ab5": {"definition": "A mastering plug-in module in IK Multimedia's T-RackS suite that analyzes up to three user-loaded reference tracks (or genre presets) to build a target spectral and loudness profile, then automatically applies matching EQ and level processing to make the user's master resemble the tonal balance and loudness of those references.", "plain_english": "A mastering tool that listens to songs you like and then shapes your own track to match their tone and loudness. It is like copying the recipe of a finished dish so yours tastes similar.", "purpose_function": "It gives engineers a fast starting point for tone and loudness by automatically matching a master to trusted reference tracks, which helps with consistency and with less-experienced users.", "practical_application": "An engineer loads two or three reference songs, analyzes the loudest section of their own track, presses match, then dials the match amount back to taste instead of accepting 100%.", "category": "Mastering Software", "related_terms": ["Reference track", "Match EQ", "Loudness matching", "Mastering chain", "Limiter", "Spectral analysis"], "common_mistakes": ["Trusting the automatic match at 100% instead of adjusting it to taste.", "Matching to a poor or very different-genre reference and getting an odd result.", "Analyzing a quiet section instead of the loudest part, which skews the match."], "scenario_contexts": ["Quickly matching a mix's tone to a commercial reference during mastering.", "Giving a beginner a reference-based starting curve before fine EQ.", "Checking a master's tonal balance against several references."]}, "568dce4a-ca39-4f36-886e-7295a5dbc8c6": {"definition": "A media-identification system that applies machine-readable barcode labels to tape media (master or archive/backup tapes) so each reel or cartridge carries a unique ID for cataloging, tracking, retrieval, and inventory, commonly read by tape libraries or asset-management databases.", "plain_english": "A way to put scannable barcode labels on tapes so each one has its own ID. It works like the barcode on a grocery item, letting a system find and track each tape.", "purpose_function": "It gives every tape a unique, scannable identity so archives and automated tape libraries can locate, log, and manage large collections without relying on hand-written labels.", "practical_application": "An archivist or library operator applies a barcode label to each master or backup tape and scans it into a database that records its title, location, and history.", "category": "Media Archival", "related_terms": ["Master tape", "Media asset management", "Archival", "Catalog number", "Tape library", "Metadata"], "common_mistakes": ["Reusing or duplicating a barcode ID across two tapes, which breaks database tracking.", "Placing the label where it fouls the tape path or peels off in storage.", "Relying only on the barcode without backing metadata, so a lost database orphans the tape."], "scenario_contexts": ["Bar-coding a studio's master-tape archive for a database inventory.", "Automated tape libraries reading cartridge barcodes for backup rotation.", "Scanning a master tape's barcode to pull its session history before a reissue transfer."]}, "88e98450-8403-4172-8365-31999ab0701f": {"definition": "The specific level of high-frequency AC bias current a given magnetic tape formulation needs applied during recording to linearize its magnetic transfer and reach optimal sensitivity, distortion, and frequency response. Different formulations require different bias amounts, set by the bias adjustment during machine alignment.", "plain_english": "Recording tape needs a hidden high-pitched signal, called bias, mixed in so the sound records cleanly. Each type of tape needs its own amount of bias, so the machine must be set to match the tape you load.", "purpose_function": "Bias overcomes the tape's magnetic non-linearity so audio records with low distortion; the requirement tells the technician how much bias a specific tape needs for flat response and correct saturation.", "practical_application": "During alignment a tech adjusts bias per the tape maker's spec, often over-biasing by a set amount at a reference frequency, whenever changing tape stock on a machine.", "category": "Analog Tape", "related_terms": ["Tape formulation", "Tape coercivity", "Tape compression characteristic", "Machine alignment", "Record equalization", "Tape hiss characteristic"], "common_mistakes": ["Assuming one bias setting works for every tape brand or formulation", "Confusing AC record bias with DC erase or accidental magnetization", "Setting bias by ear instead of using a reference tape and level meter", "Over-biasing so far that high-frequency response is dulled"], "scenario_contexts": ["Aligning a multitrack machine before a session after switching tape stock", "Restoring an archival machine to play a tape recorded on a different formulation", "Setting up a mastering deck to match a client's preferred tape"]}, "9f806322-8823-4eea-ae38-3a14e2352fe0": {"definition": "The magnetic field strength (measured in oersteds or A/m) required to reduce the remanent magnetization of a tape's magnetic particles to zero; it indicates how strongly the tape resists demagnetization and erasure. Higher-coercivity formulations such as metal particle store high levels and short wavelengths better but need stronger bias and erase fields.", "plain_english": "Coercivity measures how hard it is to wipe or change the magnetism stored on a tape. High-coercivity tape holds its recording more firmly. It keeps loud and high sounds well but is harder to erase.", "purpose_function": "Coercivity determines how much signal a tape can hold and how resistant the recording is to accidental erasure, and it sets the bias and erase current the machine must supply.", "practical_application": "A tech checks a tape's coercivity rating to pick the right bias and erase settings and to know whether a bulk eraser is strong enough to fully wipe it.", "category": "Analog Tape", "related_terms": ["Tape formulation", "Tape bias requirement", "Tape compression characteristic", "Tape hiss characteristic", "Machine alignment", "Retentivity"], "common_mistakes": ["Confusing coercivity, which is resistance to erasure, with retentivity, the amount of flux retained", "Assuming a standard bulk eraser fully wipes high-coercivity metal tape", "Ignoring coercivity when matching a tape to a machine's bias and erase capability"], "scenario_contexts": ["Choosing bias and erase settings for a high-output formulation", "Verifying a degausser is strong enough to erase a given tape", "Comparing formulations when specifying stock for a project"]}, "bb7ead5b-d48e-4a9c-bd59-921894e32ac4": {"definition": "The gentle, program-dependent gain reduction and soft saturation an analog tape exhibits as recording level approaches magnetic saturation, rounding transient peaks and adding harmonic content without the hard clipping of digital overload. The onset and curve depend on formulation, bias, level, and tape speed.", "plain_english": "When you record loud onto tape, the tape cannot get any louder past a point, so it gently squashes the peaks instead of harshly cutting them off. This soft squashing is part of why tape often makes music sound warm and glued together.", "purpose_function": "This natural compression tames peaks and adds pleasing harmonics, which is why engineers deliberately drive tape to glue a mix and control dynamics without a separate compressor.", "practical_application": "A mix or mastering engineer sets record level to push the tape into mild saturation as a tone and dynamics tool; too much level smears transients and adds obvious distortion.", "category": "Analog Tape", "related_terms": ["Tape formulation", "Tape bias requirement", "Tape coercivity", "Tape hiss characteristic", "Headroom", "Harmonic distortion"], "common_mistakes": ["Confusing tape's soft saturation with a compressor's threshold-based gain reduction", "Overdriving until distortion and pitch smear become obvious", "Expecting the same character at every tape speed and bias setting"], "scenario_contexts": ["Printing a mix to tape to soften peaks and add warmth", "Tracking a loud snare to round its transient", "Choosing a tape-style plugin during mastering to mimic this behavior"]}, "4670a20e-2962-440a-9978-f5aa2a99918c": {"definition": "The systematic evaluation of an archival magnetic tape's physical and chemical state, checking for binder hydrolysis (sticky-shed), shedding, pack quality, warping, mould, and edge damage, to determine whether it can be safely played and what remediation such as baking or cleaning it needs.", "plain_english": "Before playing an old tape, you check its health: is it sticky, moldy, warped, or shedding bits of coating? This check tells you whether the tape is safe to play and whether it needs treatment first.", "purpose_function": "It prevents damage to fragile tapes and machines during playback and lets the tech plan restoration, so a valuable recording is not lost by playing a tape that should have been baked or cleaned first.", "practical_application": "An archivist or transfer engineer inspects each reel, notes defects, and decides whether to bake, clean, or reshell before a single-pass transfer to digital.", "category": "Tape Archival", "related_terms": ["Tape inspection report", "Tape lubricant condition", "Tape library catalog", "Tape formulation", "Sticky-shed syndrome", "Tape baking"], "common_mistakes": ["Playing a suspect tape before assessing it, risking shed coating and clogged heads", "Assuming all brands of a given era degrade the same way", "Baking a tape without first confirming its problem is binder hydrolysis", "Skipping documentation of the tape's condition before transfer"], "scenario_contexts": ["Preparing a 1980s reel for digitization", "Triaging a newly acquired tape collection", "Deciding whether a tape needs baking before a single safe playback"]}, "e52c2539-8455-488f-b4b6-b7cded364318": {"definition": "The specific composition of a magnetic tape's coating and base: the magnetic particle type (such as gamma ferric oxide, chromium dioxide, cobalt-doped, or metal particle), binder chemistry, and backing material and thickness, which together set its magnetic and mechanical performance. Each formulation has characteristic coercivity, output, bias needs, and noise.", "plain_english": "A tape's formulation is the recipe of magnetic material and plastic used to make it. The recipe sets how loud, clean, and tough the tape is. It also sets how the machine must be tuned.", "purpose_function": "The formulation defines a tape's electrical and physical behavior, so knowing it tells the tech how to bias, equalize, and handle the stock for the best results.", "practical_application": "A tech identifies the formulation from the box or leader to choose alignment settings and to anticipate issues like sticky-shed that are common to certain brands and eras.", "category": "Analog Tape", "related_terms": ["Tape coercivity", "Tape bias requirement", "Tape compression characteristic", "Tape hiss characteristic", "Sticky-shed syndrome", "Machine alignment"], "common_mistakes": ["Assuming all tape stocks share the same bias and EQ", "Mixing formulations on one reel and expecting consistent alignment", "Ignoring that some formulations are prone to sticky-shed"], "scenario_contexts": ["Selecting stock for a new recording", "Identifying an archival tape's type before transfer", "Setting machine alignment to match the loaded formulation"]}, "160c9db6-31b6-4d81-9108-db79acd6102a": {"definition": "The broadband, mostly high-frequency background noise inherent to analog tape, arising from the finite size and random distribution of the magnetic particles; its level and spectrum depend on formulation, tape speed, track width, and bias. It sets the noise floor that limits a tape system's dynamic range.", "plain_english": "Tape hiss is the steady shhh background sound you hear from analog tape, caused by the tiny magnetic grains in the coating. Finer grains, faster speed, and wider tracks make the hiss quieter.", "purpose_function": "Understanding hiss lets a technician predict a machine's noise floor and choose speed, track format, and noise reduction to keep quiet passages clean.", "practical_application": "A tech runs tape faster or applies noise reduction such as Dolby to lower audible hiss, and sets record level high enough to stay above it without saturating.", "category": "Analog Tape", "related_terms": ["Tape formulation", "Tape compression characteristic", "Tape coercivity", "Signal-to-noise ratio", "Noise reduction", "Headroom"], "common_mistakes": ["Recording too low and letting hiss dominate quiet parts", "Assuming hiss is a machine fault rather than inherent tape noise", "Forgetting that higher tape speed and wider tracks reduce hiss"], "scenario_contexts": ["Setting record levels to keep hiss below the music", "Choosing 30 ips over 15 ips for a cleaner master", "Deciding whether to apply noise reduction on a transfer"]}, "9cdb01eb-b7d9-49b9-bfdd-7000ebd69a6e": {"definition": "A written record documenting the observed physical and chemical condition of a magnetic tape, including defects such as shedding, sticky-shed, mould, warping, splices, and pack faults, along with any recommended handling or remediation, produced during condition assessment. It travels with the tape to guide safe playback and transfer.", "plain_english": "A tape inspection report is the written health record for a tape. It lists any problems found and what to do about them, so the next person knows how to handle the tape safely.", "purpose_function": "It preserves a documented history of a tape's condition and needed treatment so decisions about baking, cleaning, or transfer are consistent and the tape is not mishandled.", "practical_application": "An archivist fills out the report during inspection, noting defects and actions, and files it with the tape and its digital transfer metadata.", "category": "Tape Archival", "related_terms": ["Tape condition assessment", "Tape library catalog", "Tape lubricant condition", "Tape formulation", "Sticky-shed syndrome", "Tape baking"], "common_mistakes": ["Transferring a tape without recording its condition for future reference", "Using vague notes the next technician cannot act on", "Omitting the formulation or brand, which predicts likely faults"], "scenario_contexts": ["Documenting a reel's defects before a digitization session", "Passing condition notes to a restoration specialist", "Building a preservation file alongside a digital transfer"]}, "5deb21cf-ec1a-47db-9414-a5f68be0f01e": {"definition": "An organized inventory of an archive's or studio's tape holdings that records each item's identifier, title, format, formulation, recording data, storage location, and condition, enabling retrieval, tracking, and preservation planning. It is the master metadata index for physical tape assets.", "plain_english": "A tape library catalog is a master list of all the tapes an archive owns. It tells you what each tape is, where it lives, and what shape it is in, so you can find and care for it.", "purpose_function": "It exists so staff can locate any tape, track its condition and history, and plan preservation without physically searching shelves.", "practical_application": "Staff log every reel into the catalog with its ID, location, and condition, and update it when a tape is baked, transferred, or moved.", "category": "Tape Archival", "related_terms": ["Tape inspection report", "Tape condition assessment", "Tape lubricant condition", "Tape formulation", "Sticky-shed syndrome", "Tape baking"], "common_mistakes": ["Leaving the catalog out of date after tapes move or are transferred", "Recording only titles and skipping format, condition, and location", "Using inconsistent IDs that make retrieval unreliable"], "scenario_contexts": ["Locating a specific master reel for a reissue", "Auditing a collection's condition for preservation funding", "Tracking which tapes have already been digitized"]}, "755d6cde-a7cf-48c8-b9ce-23497d9c887a": {"definition": "The state of the lubricant incorporated in a magnetic tape's binder, which reduces friction between the tape and the heads and guides; loss, migration, or breakdown of this lubricant increases friction, squeal, and shedding and is often linked to binder degradation in aging tapes. Assessing it helps predict safe playability.", "plain_english": "Tape has a built-in lubricant that helps it slide smoothly past the heads. When that lubricant dries out or breaks down, the tape drags, squeals, and sheds, so checking its condition tells you if the tape will play safely.", "purpose_function": "The lubricant keeps tape moving smoothly with low friction and wear; assessing its condition warns the tech of squeal, stiction, or shedding before a fragile tape is played.", "practical_application": "During inspection a tech watches and listens for drag or squeal and may clean or, for binder-related problems, bake the tape to restore playability for a single transfer pass.", "category": "Tape Archival", "related_terms": ["Tape condition assessment", "Tape inspection report", "Tape library catalog", "Tape formulation", "Sticky-shed syndrome", "Tape baking"], "common_mistakes": ["Confusing lubricant loss with sticky-shed binder failure, though the two can occur together", "Playing a squealing tape repeatedly and worsening shed and head clogging", "Assuming cleaning alone fixes a binder or lubricant breakdown"], "scenario_contexts": ["Diagnosing tape squeal during a transfer", "Deciding whether to bake or just clean a reel", "Assessing an aged reel's playability before digitizing"]}, "d2bb0a40-748e-47a7-b263-2d7366ceaf88": {"definition": "The constant low-level background noise, heard as hiss, produced by an analog magnetic tape recording system when no program signal is present. It arises mainly from the random size and distribution of magnetic particles in the tape coating, plus electronic noise in the record and playback circuitry, and it sets the bottom of the system's usable dynamic range.", "plain_english": "This is the faint hiss you hear from a blank part of a tape, even with no music playing. It comes from tiny magnetic bits in the tape and from the machine's own circuits. Any sound quieter than this hiss gets lost in it.", "purpose_function": "It defines the lowest level a signal can occupy before hiss masks it, so it sets the tape format's dynamic range and how much noise reduction or level optimization a project needs.", "practical_application": "Engineers record as hot as headroom allows and often use noise reduction such as Dolby A, SR, or C to keep quiet passages well above the tape's hiss.", "category": "Analog Tape", "related_terms": ["Tape saturation level", "Tape operating level", "Signal-to-noise ratio", "Dynamic range", "Noise reduction", "Tape bias"], "common_mistakes": ["Confusing the tape noise floor with the noise floor of the console or converters, when the tape's hiss is usually the dominant source in an analog chain", "Assuming a higher operating level always improves signal-to-noise, ignoring the added distortion and lost headroom", "Believing noise reduction removes hiss for free, when a misaligned machine can cause audible mistracking artifacts"], "scenario_contexts": ["Setting record levels on a 2-inch multitrack so quiet instruments sit above the tape hiss", "Deciding whether to engage Dolby SR on a mastering deck for a wide-dynamic-range recording", "Comparing hiss between a new tape stock and an older, worn reel during a transfer"]}, "944326c1-9e2e-4b27-aeb6-14b2475a934d": {"definition": "The reference magnetic flux level (fluxivity, expressed in nanowebers per metre of track width) to which a tape machine and tape stock are aligned so that a standard reference tone reads 0 VU. Common values such as 185, 250, 320, 355, or 510 nWb/m set how hard the tape is driven and therefore the balance between headroom and noise.", "plain_english": "This is the standard 'zero' loudness a tape machine is set up to record and play back. It is measured against a reference tape so different studios can match each other. A higher setting drives the tape harder, giving less hiss but less room before distortion.", "purpose_function": "It provides a common reference so a recording made on one aligned machine plays back at the correct level on another, and it fixes where the working level sits between the noise floor and tape saturation.", "practical_application": "During alignment a technician plays a calibration tape and adjusts playback and record gains so the reference fluxivity reads 0 VU, choosing an operating level to suit the tape stock and program material.", "category": "Analog Tape", "related_terms": ["Tape saturation level", "Tape noise floor", "Calibration tape", "Fluxivity", "VU meter", "Tape bias"], "common_mistakes": ["Confusing operating level in nWb/m with the electrical +4 dBu line level, which references something different", "Running a high operating level on a tape stock not designed for it, increasing distortion and print-through", "Failing to note the operating level used, making later transfers or alignment inconsistent"], "scenario_contexts": ["Aligning a multitrack recorder to a 250 nWb/m calibration tape before a session", "Choosing an elevated operating level for a modern high-output tape to lower hiss", "Documenting the operating level on the tape box for the mastering engineer"]}, "bf72a85d-184e-42c6-8599-911c05c3deff": {"definition": "A planned, ongoing approach to protecting magnetic tape recordings and their content, combining controlled storage conditions, careful handling, periodic condition inspection, and timely transfer (migration) of the audio to stable formats before the physical carrier degrades.", "plain_english": "This is a plan for keeping old tapes and their sound safe for the long term. It covers how you store them, how you handle them, and when you copy them to a newer format. The goal is to save the music before the tape wears out.", "purpose_function": "It exists because magnetic tape decays over time, so the strategy aims to slow that decay and to move the content onto fresh media while the original is still playable.", "practical_application": "An archivist sets storage targets, schedules inspections, prioritizes at-risk tapes such as those with sticky-shed, and plans digitization so the audio survives even after the original tape becomes unplayable.", "category": "Tape Preservation", "related_terms": ["Tape shedding inspection", "Tape storage temperature", "Tape storage humidity", "Sticky-shed syndrome", "Tape baking", "Digitization"], "common_mistakes": ["Treating a single digital copy as a finished job instead of keeping checksummed backups and ongoing migration", "Delaying transfer of degrading tapes until they are already unplayable", "Storing tapes in uncontrolled attics or basements where heat and humidity swing widely"], "scenario_contexts": ["Building a plan to digitize a radio station's reel-to-reel archive", "Prioritizing which master tapes to bake and transfer first", "Setting handling and storage rules for a studio's tape library"]}, "5c71baf7-9b9b-4e5d-b20e-36d61d5e9f77": {"definition": "The residual magnetic flux density that remains in a tape's magnetic coating after the applied recording (magnetizing) field is removed; it is the retained magnetization that actually stores the recorded signal. The maximum value the coating can retain is its retentivity, a defining property of the magnetic material's hysteresis loop.", "plain_english": "This is the magnetism that stays behind in the tape after it passes the record head. That leftover magnetism is what holds the recorded sound. Without it, the tape could not remember anything once the head's field is gone.", "purpose_function": "Remanence is the physical mechanism by which tape stores audio, and its strength helps set how high a signal, and how good a signal-to-noise ratio, a given tape can hold.", "practical_application": "Engineers rely on remanence when they set bias and level, since higher-output tapes with greater retentivity allow hotter recordings and lower hiss.", "category": "Analog Tape", "related_terms": ["Tape saturation level", "Tape operating level", "Tape bias", "Coercivity", "Fluxivity", "Print-through"], "common_mistakes": ["Confusing remanence with coercivity, when remanence is retained flux and coercivity is the field needed to erase it", "Assuming remanence is unlimited, ignoring that the coating saturates", "Overlooking that print-through is unwanted remanence transferring between adjacent tape layers"], "scenario_contexts": ["Explaining why a recording survives after the record field is removed", "Selecting a high-retentivity tape for a low-noise master", "Diagnosing print-through echo on a tightly wound archival reel"]}, "e6be4935-118f-454b-8f9c-106376ea0aed": {"definition": "A planned timetable within a tape preservation program for periodically acting on stored tapes, historically by re-tensioning them with a controlled wind or by cycling working and backup copies, so that pack tension stays even and problems are caught early. Current archival guidance favors minimal handling, so routine rewinding is now applied selectively rather than automatically.", "plain_english": "This is a set schedule for regularly checking and, when needed, re-winding tapes that sit in storage. The idea is to keep the wound reel evenly tensioned and to spot trouble early. Modern advice is to handle tapes as little as possible, so this is done carefully, not just out of habit.", "purpose_function": "It aims to keep stored tapes in even, stable condition and to ensure at-risk reels are inspected on a regular cycle rather than forgotten, while balancing the risk that extra handling itself causes wear.", "practical_application": "An archive logs each reel and sets review intervals; staff inspect or re-tension selected tapes on schedule and cycle backup copies, recording every action so handling stays deliberate and minimal.", "category": "Tape Preservation", "related_terms": ["Tape preservation strategy", "Tape storage temperature", "Tape storage humidity", "Tape shedding inspection", "Print-through", "Library wind"], "common_mistakes": ["Rewinding every tape on a fixed cycle regardless of need, adding handling wear against current guidance", "Leaving tapes stored on an uneven or tails-out pack when a stable wind was intended", "Never inspecting stored tapes at all, so degradation goes unnoticed until playback fails"], "scenario_contexts": ["Planning periodic condition checks for a large master-tape library", "Deciding whether to retension reels that have sat unplayed for decades", "Cycling backup safety copies of critical masters on a set interval"]}, "5a9ce781-1613-45ea-a10e-77a03d3d223a": {"definition": "The recording level at which a tape's magnetic coating approaches magnetic saturation, so that further increases in input produce progressively less increase in remanent flux. Beyond this point the tape compresses transients and adds harmonic distortion, producing the characteristic warmth and soft limiting associated with tape saturation.", "plain_english": "This is the point where the tape can't get much louder no matter how hard you push it. Past this point, peaks get squashed and the sound takes on a warm, slightly gritty edge. Many engineers reach for this effect on purpose.", "purpose_function": "It marks the top of the tape's usable level range, and because saturation is gradual it also provides natural compression and harmonic color that engineers use for tone, not just as a headroom limit.", "practical_application": "An engineer pushes levels toward saturation to add warmth and glue on a mix or drum bus, backing off when the distortion or dulling of high frequencies becomes too strong.", "category": "Analog Tape", "related_terms": ["Tape operating level", "Tape noise floor", "Tape remanence", "Harmonic distortion", "Headroom", "Compression"], "common_mistakes": ["Believing tape saturation has a single hard clipping point rather than a gradual onset", "Overdriving the tape so that high-frequency detail and transients are lost", "Confusing tape saturation with digital clipping, which sounds harsh rather than smooth"], "scenario_contexts": ["Driving a drum bus to tape for punch and glue", "Choosing tape speed and level to control how early saturation sets in", "Emulating tape saturation with a plug-in during in-the-box mastering"]}, "ff1ecd57-9850-4280-a773-5ecb1c87f3d1": {"definition": "The visual and tactile examination of a magnetic tape for signs of binder deterioration, especially oxide and binder shedding caused by hydrolysis (sticky-shed syndrome), carried out before playback to avoid contaminating the transport or damaging an irreplaceable tape.", "plain_english": "This is checking an old tape for crumbling or sticky coating before you play it. A bad tape sheds a gummy powder that can clog the machine or ruin the tape. Spotting this first lets you treat the tape, often by baking it, before transfer.", "purpose_function": "It protects both the tape and the machine by catching degradation such as sticky-shed before a reel is threaded, and it flags tapes that need remediation like baking before they can be safely played.", "practical_application": "Before transferring an archival reel, a technician inspects the tape pack and leader, feels for stickiness, looks for shed residue, and decides whether baking or cleaning is needed first.", "category": "Tape Preservation", "related_terms": ["Sticky-shed syndrome", "Tape baking", "Tape preservation strategy", "Tape storage humidity", "Binder hydrolysis", "Digitization"], "common_mistakes": ["UNSAFE: Playing a shedding tape without inspection, which can jam the transport and permanently destroy a unique master", "Assuming every shedding tape can be baked, when acetate-base and some formulations behave differently", "Mistaking normal residue for shedding, or dismissing early squeal as a minor issue"], "scenario_contexts": ["Assessing a 1980s reel that squeals and leaves residue on the heads", "Screening a batch of archive tapes to decide which need baking", "Cleaning the transport after a shedding reel to protect the next tape"]}, "fa1b7255-08e0-45d6-ab5f-7cf530793eb6": {"definition": "The relative humidity maintained where magnetic tapes are stored, a key preservation parameter because high humidity accelerates binder hydrolysis (sticky-shed) and mold growth while very low humidity increases friction and static. Preservation guidance calls for moderate, stable relative humidity, commonly in the region of 25-45% for magnetic audio tape.", "plain_english": "This is how damp or dry the air is where tapes are kept. Too damp and the tape's glue breaks down or mold grows; too dry and the tape drags and builds up static. The aim is a middle, steady level, roughly 25 to 45 percent, without big swings.", "purpose_function": "Controlling storage humidity slows the chemical decay of the tape binder and prevents mold, extending the life of the recording and the reliability of later playback.", "practical_application": "An archivist uses a logging hygrometer and a conditioned store or HVAC to hold relative humidity within the recommended band, and lets tapes acclimatize before playing them.", "category": "Tape Preservation", "related_terms": ["Tape storage temperature", "Tape preservation strategy", "Sticky-shed syndrome", "Tape shedding inspection", "Binder hydrolysis", "Acclimatization"], "common_mistakes": ["Controlling temperature but ignoring humidity, which is the bigger driver of hydrolysis", "Allowing large humidity swings, which stress the tape more than a steady moderate level", "Playing a cold or damp tape without letting it acclimatize to the room first"], "scenario_contexts": ["Setting HVAC targets for a tape vault", "Investigating mold on reels stored in a humid basement", "Logging relative humidity in a store over a year to catch seasonal swings"]}, "d121d4f3-e117-4e25-9bd1-217205f0c003": {"definition": "The temperature maintained where magnetic tapes are stored; cooler, stable conditions slow the chemical decay of the tape binder and reduce print-through. Preservation guidance recommends cool, stable storage, commonly around 18-21 degrees C (about 65-70 degrees F) for access collections, with colder dedicated storage for long-term preservation.", "plain_english": "This is how warm or cool the room is where tapes are kept. Cooler, steady temperatures make tapes last longer and cut down faint echo between layers. Rooms used every day sit around 18 to 21 degrees Celsius, while long-term storage is kept colder.", "purpose_function": "Lower, stable temperatures slow the reactions that break down the tape binder and reduce print-through, so controlling temperature extends how long tapes stay playable.", "practical_application": "An archivist keeps the store cool and steady, avoids heat sources and swings, and acclimatizes tapes to room temperature before playing them to prevent condensation.", "category": "Tape Preservation", "related_terms": ["Tape storage humidity", "Tape preservation strategy", "Print-through", "Tape shedding inspection", "Acclimatization", "Binder hydrolysis"], "common_mistakes": ["Storing tapes near heaters, lights, or in hot attics that speed decay", "Moving a cold tape straight onto a warm machine, risking condensation", "Assuming everyday room temperature is fine for permanent archival storage"], "scenario_contexts": ["Specifying a climate-controlled vault for master tapes", "Acclimatizing tapes brought in from cold storage before a transfer", "Reviewing why tapes stored in a warm room show heavy print-through"]}, "ee694cba-806d-452d-873d-4a79b224e2c9": {"definition": "The condition and evenness with which magnetic recording tape is spooled onto its reel or hub, including uniform pack tension, flat and aligned tape edges, and a smooth, cinch-free wind. Poor winding causes edge damage, spoking, cinching, and increased print-through, degrading the stored analog master.", "plain_english": "This is how neatly and evenly a reel of recording tape is wound up. A loose or uneven wind can crease the tape or let one layer bleed faint sound into the next. It is like winding thread on a spool: neat and even keeps it safe, but sloppy winding tangles and damages it.", "purpose_function": "Good winding protects both the physical tape and the audio it holds, keeping a master playable and free of mechanical damage and print-through through storage and transport.", "practical_application": "Before archiving or shipping a tape master, a technician winds it smoothly at a steady play or library speed and stores it tails-out to reduce print-through.", "category": "Analog Tape", "related_terms": ["Print-through", "Tails-out storage", "Analog tape master", "Reel-to-reel", "Flutter"], "common_mistakes": ["Storing tape wound heads-out, which makes print-through pre-echo worse", "Winding at high fast-forward speed, which builds an uneven, cinch-prone pack", "Assuming tighter is always better; over-tension can stretch or emboss the tape"], "scenario_contexts": ["Archiving an analog master reel after a mastering transfer", "Preparing a tape master for shipment to a cutting or pressing facility", "Inspecting a vintage reel for spoking or edge damage before playback"]}, "4d2f4711-f7b2-4ee9-a2af-632ecd603f02": {"definition": "A lacquer disc (a nitrocellulose-coated aluminum blank) cut on a mastering lathe as a trial or reference before cutting the final production lacquers, used to check level, groove spacing, tracking, and overall sound of the cut.", "plain_english": "This is a trial record cut before the real ones are made. The cutting engineer makes it to hear how the music sits in the grooves and to catch problems early. It is like printing one test page before you run the whole print job.", "purpose_function": "It lets the cutting engineer and client hear and approve the actual cut on a physical disc before committing to the master lacquers used to make stampers, reducing costly mistakes.", "practical_application": "A cutting engineer plays a test lacquer on a reference turntable to check for distortion, sibilance, or groove skipping, then adjusts lathe settings before cutting the final lacquer.", "category": "Vinyl Cutting", "related_terms": ["Lacquer master", "Acetate", "Cutting lathe", "Stamper", "Test pressing evaluation", "Reference disc"], "common_mistakes": ["Treating a test lacquer as a finished record; it is a soft, one-off cut that wears quickly", "Judging the final release from the lacquer, which changes after plating and pressing", "Playing a lacquer many times, since each play wears the soft grooves"], "scenario_contexts": ["Approving a vinyl cut before ordering stampers", "Checking whether a loud, bass-heavy master tracks without skipping", "Sending a reference acetate to an artist for sign-off"]}, "710669c8-3bf3-4397-881a-7ebabe0de012": {"definition": "The critical listening and physical inspection of test pressings, a small number of sample records pressed from the finished stampers, to verify audio quality and check for surface noise, non-fill, warps, off-center pressing, and other defects before approving the full production run.", "plain_english": "This is checking a few sample records before the whole batch is made. You listen for noise, clicks, and skips, and look the disc over for damage. It is like tasting a test batch before you cook the full meal.", "purpose_function": "It catches manufacturing faults and mastering issues while only a few discs exist, preventing a bad full pressing run and protecting the release quality.", "practical_application": "The mastering engineer and label play test pressings all the way through on a good turntable, note any distortion, clicks, or warps, and either approve the run or ask for a re-cut or re-press.", "category": "Vinyl Manufacturing", "related_terms": ["Test lacquer", "Stamper", "Non-fill", "Surface noise", "Lacquer master", "Pressing plant"], "common_mistakes": ["Approving from a quick spot-check instead of listening to each side in full", "Blaming all noise on the pressing when the fault is in the cut or the master", "Evaluating on a poor turntable that hides real defects or adds its own"], "scenario_contexts": ["Signing off on a vinyl release before the plant runs thousands of copies", "Comparing channel balance and centering on a sample disc", "Rejecting a batch for non-fill in loud passages"]}, "7e07dd17-9dd0-440e-988d-4b43099f496e": {"definition": "A subdivision within a CD track defined by the subcode Q-channel INDEX field (values 00-99) under the Red Book standard (IEC 60908); INDEX 00 marks the pre-gap or pause and INDEX 01 marks the audio start, while higher index numbers can flag points inside a single track.", "plain_english": "On a CD, this is a marker that labels a spot inside a track. Index 1 is where the music starts, and index 0 is the short pause before it. Some discs use higher numbers to mark sections inside one long track, like movements in a piece.", "purpose_function": "Index points let a CD flag internal locations and pre-gaps so players and authoring systems can find the true start of audio and, on some discs, cue to sections within a track.", "practical_application": "In PQ editing a mastering engineer sets INDEX 01 at each track's audio start and INDEX 00 for the pause, and may add index marks within long tracks for navigation.", "category": "CD Mastering", "related_terms": ["PQ codes", "Track pause length", "Red Book", "Subcode", "Track start ID", "DDP"], "common_mistakes": ["Confusing an index point with a track number; indexes live inside one track", "Assuming all players can seek to index numbers above 01, since many ignore them", "Placing INDEX 01 late, so the first moment of audio is cut off"], "scenario_contexts": ["Setting track starts and pre-gaps during CD PQ editing", "Marking movements inside one long classical track", "Troubleshooting why a player jumps past the start of a song"]}, "be45a2b9-e9fa-419a-bd6b-49c01aa57472": {"definition": "The duration of the gap between the end of one CD track and the audio start of the next, encoded in the subcode as the pre-gap (INDEX 00) of the following track; the Red Book default convention is about two seconds, but it is adjustable and can be set to zero for gapless transitions.", "plain_english": "This is how long the silent gap is between two songs on a CD. The usual default is about two seconds, but you can make it longer, shorter, or zero. A zero gap lets one track flow straight into the next, like on a live album.", "purpose_function": "The pause sets the spacing and pacing between tracks, separating songs or removing the gap entirely for continuous, gapless playback.", "practical_application": "During CD assembly the engineer trims each track's pre-gap, often setting two seconds between separate songs and zero for a continuous live or concept album.", "category": "CD Mastering", "related_terms": ["Track index point", "PQ codes", "Pre-gap", "Gapless playback", "Red Book", "Track start ID"], "common_mistakes": ["Leaving the default two-second gap on a live album, which breaks the continuous flow", "Cutting a gap so tight that a song's reverb tail is chopped off", "Confusing the coded pause length with silence baked into the audio file"], "scenario_contexts": ["Spacing tracks on a pop album for natural pacing", "Setting zero gaps for a seamless live or DJ recording", "Adjusting pauses so segues line up between songs"]}, "17b06161-afb1-4923-822a-7cc707dd6c0e": {"definition": "Creating a CD in Track-At-Once (TAO) mode, where the recorder writes each track as a separate operation and turns the laser off between tracks, leaving link and run-in/run-out blocks at the joins; unlike Disc-At-Once, TAO is generally unsuitable as a replication premaster.", "plain_english": "This is burning a CD one track at a time, with the laser stopping between songs. Each stop leaves tiny link blocks at the joins. Because of those glitches, factories will not use this kind of disc as a master; they want a disc burned in one pass instead.", "purpose_function": "TAO lets tracks be added to a disc in separate steps, but the link blocks and forced gaps make it unfit for professional replication, where Disc-At-Once premasters are required.", "practical_application": "A technician preparing a master for a plant avoids TAO and instead delivers a Disc-At-Once CD-R or a DDP image so the master has no link errors and correct pre-gaps.", "category": "CD Mastering", "related_terms": ["Disc-at-once", "DDP", "Red Book", "Track pause length", "Premaster", "CD-R"], "common_mistakes": ["Sending a Track-At-Once CD-R to a plant as a master, which can be rejected for link errors", "Assuming TAO and Disc-At-Once sound different; the issue is disc structure, not audio", "Believing TAO can give zero pre-gaps, since it forces gaps at track joins"], "scenario_contexts": ["Burning a quick reference disc while avoiding TAO for the actual master", "Explaining to a client why a plant rejected their home-burned CD master", "Choosing Disc-At-Once over TAO when creating a replication premaster"]}, "77acce71-a320-4d57-87eb-75576862233c": {"definition": "A stem, meaning a grouped submix of a larger mix, delivered as part of trailer music, the high-impact music composed for film, game, or product trailers; common stems separate elements such as drums and percussion, brass, strings, choir, synths, and impact hits so editors can rebalance the cue to picture.", "plain_english": "Trailer music is the big, dramatic music you hear in movie previews. A stem is one grouped layer of that music, like all the drums or all the strings on their own. Giving editors separate stems lets them turn parts up or down to fit the trailer.", "purpose_function": "Delivering trailer music as stems lets a trailer editor or mixer adjust the balance of sections and fit the music to fast, changing picture edits without needing the original session.", "practical_application": "A composer or mastering engineer exports matched, full-length stems such as drums, brass, strings, and hits at a common reference level so a trailer house can remix them under dialogue and sound effects.", "category": "Stems & Deliverables", "related_terms": ["Stem", "Underscore mix", "Submix", "Print master", "Reference level", "Music and effects (M&E)"], "common_mistakes": ["Exporting stems that do not sum back to the full mix because of solo, mute, or plugin issues", "Delivering stems with different start points so they will not line up on import", "Baking master-bus processing onto individual stems, which blocks clean rebalancing"], "scenario_contexts": ["Delivering a trailer cue to a movie trailer house for re-editing", "Supplying separate percussion and impact-hit stems for a game reveal trailer", "Rebalancing music under a voiceover in a product launch trailer"]}, "37f1f257-1685-4dad-a0e4-6002181c28d5": {"definition": "A mastering session carried out without the client physically present, where the engineer works from supplied files, reference tracks, and written notes and returns masters and revisions remotely, as opposed to attended mastering where the client sits in the room.", "plain_english": "This is when the mastering engineer works on your music without you in the room. You send the mixes and notes, they master it, and send it back for approval. It is like mailing photos to a lab instead of standing at the counter while they print.", "purpose_function": "It lets clients anywhere use an engineer without travel, lowering cost and scheduling effort, while the engineer relies on clear notes and reference tracks in place of live feedback.", "practical_application": "A client uploads mixes, reference tracks, and revision notes; the engineer masters unattended, delivers files for approval, and handles revision rounds by email.", "category": "Mastering Workflow", "related_terms": ["Attended mastering", "Reference track", "Revision", "Stem mastering", "Print master", "Recall"], "common_mistakes": ["Sending mixes with no reference tracks or notes, leaving the engineer to guess the intended sound", "Expecting endless free revisions as if the engineer were sitting with you", "Uploading a non-final or wrong mix version, causing a master of the wrong file"], "scenario_contexts": ["An independent artist getting an album mastered by an engineer in another country", "Fast online single releases handled with email revision rounds", "A label sending final mixes to a remote engineer on a deadline"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a3ee441d-1e16-4f6a-a0cf-0fbc8f710728": {"definition": "A mix of music intended to play underneath dialogue, narration, or on-screen action in film, TV, and broadcast, balanced and often reduced in level or spectrally shaped so it supports the scene without masking speech; it is frequently delivered as a separate stem within the music-and-effects deliverables.", "plain_english": "This is a music mix made to sit quietly under talking or narration. It is balanced so you can still hear every word clearly. Think of the soft background music behind a documentary voice, filling the mood without covering the speech.", "purpose_function": "The underscore mix sets mood and continuity under dialogue while staying out of the way of speech, and its separate stem lets re-recording mixers and foreign-language versions adjust or replace it.", "practical_application": "A re-recording or mastering engineer delivers the underscore as its own stem at a controlled level so the dialogue stays clear and the music can be dipped or swapped for the music-and-effects version.", "category": "Post & Broadcast", "related_terms": ["Music and effects (M&E)", "Stem", "Dialogue", "Trailer music stem", "Ducking", "Dubbing"], "common_mistakes": ["Mixing the underscore too loud so it fights the dialogue", "Leaving wide-band content that masks speech instead of carving space around vocal frequencies", "Failing to deliver it as a separate stem, which blocks foreign-language re-versioning"], "scenario_contexts": ["Scoring background music under a documentary narration", "Delivering an M&E stem set for foreign-language dubbing", "Dipping music under dialogue in a TV drama re-recording mix"]}, "cb6e3622-859a-4e79-bd69-2347608d58c4": {"definition": "The embedding of a release's UPC/EAN barcode number into a master's metadata — for example the Red Book CD subcode Q-channel or a DDP fileset's PQ data — so the finished product carries a unique, machine-readable catalog identifier.", "plain_english": "A UPC is the barcode number that names a product. UPC encoding writes that number into the master file. Then shops and databases know exactly which release it is. It works like a name tag on the album so it can be tracked and sold.", "purpose_function": "It links the audio master to a unique commercial identifier so the release can be catalogued, distributed, sold, and tracked correctly across stores and databases.", "practical_application": "A mastering engineer enters the client's UPC/EAN into the DDP or disc-image metadata when finalizing a master, alongside the per-track ISRC codes, so the plant or distributor delivers a correctly tagged product.", "category": "Metadata", "related_terms": ["ISRC encoding", "DDP fileset", "PQ codes", "Red Book standard", "Production master"], "common_mistakes": ["Confusing the UPC, which identifies the whole product, with the ISRC, which identifies each individual track", "Entering the barcode with a wrong or missing check digit, which makes it invalid", "Assuming the mastering engineer generates the UPC rather than the label or distributor supplying it"], "scenario_contexts": ["Finalizing a DDP master for CD replication where the plant reads the UPC from the metadata", "Preparing a digital release package for a distributor that requires the UPC/EAN in the delivery", "Cross-checking the barcode printed on the artwork against the UPC encoded in the master"]}, "69c8f6f8-d10e-4517-b899-37c936244454": {"definition": "A disc-cutting lathe function that automatically varies the vertical depth of the cut groove in response to a preview of the program signal — cutting deeper where loud, low-frequency or out-of-phase content demands it and shallower during quiet passages to conserve lacquer surface.", "plain_english": "On a record, a cutter carves a groove into the lacquer. Variable groove depth makes that cut deeper for loud parts and shallower for quiet parts. This saves space so more music fits on the side. It also keeps loud grooves from crashing into each other.", "purpose_function": "It works together with variable pitch to maximize playing time and level per side while keeping the stylus safely in the groove, giving loud passages enough depth and wasting none on quiet ones.", "practical_application": "The cutting engineer sets a depth range on the lathe and feeds it an advanced preview signal, and the system then trims groove depth in real time as the lacquer is cut.", "category": "Disc Cutting", "related_terms": ["Variable groove pitch", "Vertical modulation control", "Vinyl mastering", "Cutting lathe", "Preview head"], "common_mistakes": ["Confusing depth, which is the vertical cut, with pitch, which is the spacing between grooves", "Cutting too shallow to save lacquer, which lowers level and causes mistracking on playback", "Forgetting that heavy out-of-phase bass forces deeper cuts and eats up side time"], "scenario_contexts": ["Cutting a bass-heavy track where depth increases to hold the loud low end", "Fitting a long album side by letting depth drop during sparse, quiet sections", "Setting minimum and maximum depth limits before a cut to protect the stylus and lacquer"]}, "05f92402-d61f-41d2-830f-562e7fd0e014": {"definition": "A disc-cutting lathe function that automatically varies the pitch — the spacing between adjacent grooves (lines per inch) — based on a preview of the program, widening spacing for loud or bass-heavy passages and narrowing it for quiet ones to balance playing time against cutting level.", "plain_english": "The grooves on a record run in a tight spiral. Variable groove pitch changes how far apart those grooves sit. It spreads them out for loud parts so they do not collide. It packs them close for quiet parts to fit more time on the side.", "purpose_function": "It exists to balance the trade-off between how long a side can play and how loud it can be cut, packing grooves tightly when it is safe and spreading them when the signal is large.", "practical_application": "The engineer sets a base pitch and pitch limits, and the lathe's preview system reads the audio ahead of the cut so the spacing opens just before a loud passage arrives.", "category": "Disc Cutting", "related_terms": ["Variable groove depth", "Vertical modulation control", "Vinyl mastering", "Cutting lathe", "Preview head"], "common_mistakes": ["Confusing pitch, the spacing between grooves, with depth, how deep each groove is cut", "Setting pitch too tight, so loud grooves overcut into each other and cause echo", "Assuming more grooves per inch is always better and ignoring the loss of level and time balance"], "scenario_contexts": ["Cutting a long side where tight pitch is needed to fit the running time", "Opening pitch automatically ahead of a loud chorus to keep adjacent grooves apart", "Deciding a maximum safe level after seeing how pitch limits affect total side time"]}, "69a91e52-1cbb-4fc8-b7dc-4dc9a0aee027": {"definition": "In stereo disc cutting, the management of the vertical (up-and-down) component of groove modulation — which carries the out-of-phase, left-minus-right difference signal — to keep it within safe limits, since excessive vertical motion can lift the stylus out of the groove or break through the groove wall.", "plain_english": "A stereo groove wiggles side to side and also up and down. The up-and-down part holds the difference between the left and right channels. Vertical modulation control keeps that movement small. That way the needle stays in the groove instead of jumping out or cutting through the wall. Engineers often do this by making the deep bass mono.", "purpose_function": "It protects both the cut and playback by limiting the vertical difference signal, preventing groove skipping, breakthrough, and tracing distortion, usually through mono-bass (elliptical) filtering and difference-signal limiting.", "practical_application": "A cutting engineer applies an elliptical EQ or bass-mono filter and watches a scope for the vertical component, summing low frequencies to mono and taming out-of-phase energy before it reaches the cutter head.", "category": "Disc Cutting", "related_terms": ["Variable groove depth", "Variable groove pitch", "Vinyl mastering", "Elliptical EQ", "Mono bass"], "common_mistakes": ["Leaving wide stereo bass in the mix, which creates large vertical swings that make the record skip", "Confusing lateral (side-to-side, sum) modulation with vertical (up-and-down, difference) modulation", "Over-tightening the elliptical filter, which needlessly narrows the low-end stereo image"], "scenario_contexts": ["Cutting a mix with out-of-phase sub-bass that must be summed to mono to stop skipping", "Using a scope to check the vertical component of a loud kick-and-bass section before cutting", "Setting an elliptical crossover frequency so only the problem lows are summed to mono"]}, "6e204390-8ae9-4387-9aba-c96f9098d4eb": {"definition": "The specialized mastering discipline of preparing and adapting audio for the vinyl record format — accounting for the RIAA pre-emphasis curve, the mechanical limits of the cutting lathe and playback stylus, mono or limited low-frequency and sibilance handling, and the level-versus-time trade-off of each side — culminating in a cut lacquer or DMM master.", "plain_english": "Vinyl mastering means getting a mix ready to become a record. A record has physical limits that a digital file does not. So the engineer tames loud bass, harsh \"s\" sounds, and side length. It is like tailoring a song to fit and play cleanly in a spiral groove.", "purpose_function": "It exists to translate a finished mix into a physically cuttable, reliably playable disc, solving the format's mechanical and geometric limits while preserving the intended sound.", "practical_application": "An engineer reviews the mixes, adjusts EQ, dynamics and stereo bass, sets the side splits and levels, and either cuts a reference lacquer or delivers a vinyl-specific master to a cutting facility.", "category": "Vinyl Mastering", "related_terms": ["Vinyl mastering engineer", "Vinyl production master", "Variable groove pitch", "Vertical modulation control", "RIAA equalization"], "common_mistakes": ["Sending a brickwalled, hyper-loud digital master and expecting it to cut and track cleanly", "Ignoring sibilance and wide stereo bass, which cause distortion and skipping on the disc", "Assuming the streaming or CD master will work unchanged for vinyl without side-length planning"], "scenario_contexts": ["Preparing a loud rock album so it still tracks on a home turntable", "Splitting a long album across sides to keep each side within safe time and level", "Taming a bright vocal mix to avoid sibilant distortion in the cut"]}, "ee0eec5e-b2d8-4afc-b7e2-05c9d8d83e43": {"definition": "The specialist mastering/cutting engineer who prepares audio for vinyl and operates the disc-cutting lathe, making the format-specific decisions — EQ, dynamics, stereo-bass and sibilance control, side sequencing, and pitch/depth settings — and cutting the lacquer or DMM master from which pressing parts are made.", "plain_english": "A vinyl mastering engineer is the person who turns a finished mix into a record. They fix anything that would not cut or play well. Then they run the cutting lathe that carves the master disc. Think of them as a tailor and a machinist for records combined.", "purpose_function": "This role exists to bridge the gap between a finished mix and the physical disc, applying craft and lathe skills so the record sounds right and plays reliably.", "practical_application": "On the job they audition mixes, dial in a cutting chain, set the lathe's pitch and depth, cut reference and final lacquers, and report side times and level limits back to the client and plant.", "category": "Roles", "related_terms": ["Vinyl mastering", "Cutting lathe", "Vinyl production master", "Mastering engineer", "Lacquer master"], "common_mistakes": ["Assuming any mastering engineer can cut vinyl without lathe training and format knowledge", "Thinking the engineer just presses a button rather than making creative and technical cutting choices", "Confusing the vinyl cutting engineer with the plating or pressing-plant technician"], "scenario_contexts": ["Cutting a lacquer master and a reference acetate for client approval", "Advising a band that a 25-minute side must be quieter or split to cut safely", "Setting up the lathe's pitch and depth computer for a specific album's dynamics"]}, "7cc5f393-06ef-48aa-9ac0-458ea76daa71": {"definition": "The final, approved master prepared specifically for vinyl manufacturing — either the vinyl-specific audio master delivered for cutting or the cut lacquer / DMM part sent to the plating and pressing plant to make stampers — as distinct from the master used for digital or CD release.", "plain_english": "A production master is the final, approved version of the music that a factory uses to make copies. The vinyl production master is that final version prepared just for making records. It is the \"go\" copy the pressing plant works from.", "purpose_function": "It exists to give the pressing plant one approved, format-correct source so every pressed record matches the artist's intended sound.", "practical_application": "After approval, the engineer delivers the vinyl production master — a cut lacquer, a DMM, or a flagged vinyl audio fileset — with side splits and notes, and the plant makes stampers from it.", "category": "Vinyl Mastering", "related_terms": ["Vinyl mastering", "Lacquer master", "DMM", "Production master", "Stamper"], "common_mistakes": ["Assuming the vinyl production master is the same file as the CD or streaming master", "Confusing the audio production master with the physical lacquer or DMM part sent for plating", "Not labeling side splits and running order on the delivered master"], "scenario_contexts": ["Delivering an approved lacquer to a plating facility to grow stampers", "Sending a vinyl-flagged fileset to a cutting house as the production master", "Archiving the approved vinyl production master for future repressings"]}, "1f039391-8486-43cf-990d-dd8f60462f5f": {"definition": "The mastering task of sequencing and distributing a release's program material across the record's sides so each side's total running time, level, and bass or dynamic demands stay within the format's physical limits, trading playing time against achievable loudness so no side is compromised.", "plain_english": "A record has two or more sides, and each side can only hold so much time before it must get quieter. Vinyl side balancing means splitting the songs across the sides so each one fits and sounds good. It is like packing bags evenly so none is overloaded.", "purpose_function": "It exists to keep every side within safe time-versus-level limits and to give a consistent listening experience, since a long side forces a lower level and a short side allows more.", "practical_application": "The engineer decides the running order and where to split sides, checks each side's total time and loudest passages, and may move a track or trim a gap so both sides cut cleanly.", "category": "Vinyl Mastering", "related_terms": ["Vinyl mastering", "Variable groove pitch", "Variable groove depth", "Side length", "Vinyl production master"], "common_mistakes": ["Cramming too much time on one side, which forces a quiet, thin cut", "Balancing only by time and ignoring that loud, bass-heavy tracks need more space", "Splitting sides purely by track count instead of by minutes and dynamics"], "scenario_contexts": ["Deciding whether a 44-minute album fits one LP or should spread to a double LP", "Moving the loudest track to a shorter side so it can be cut hotter", "Trimming inter-track gaps to keep a long side within safe playing time"]}, "e54c9c18-008f-4e52-9a90-cc5c678504fa": {"definition": "A professional two-channel digital dynamics processor from Weiss Engineering used in mastering, providing full-band or band-selective (frequency-selective) compression, limiting, and de-essing with mid/side operation and parallel-compression facilities, using 40-bit floating-point internal processing at sample rates up to 96 kHz over AES/EBU.", "plain_english": "The Weiss DS1-MK3 is a high-end digital box used by mastering engineers. It can compress, limit, and tame harsh \"s\" sounds. It can act on just one frequency band or on the whole signal. Think of it as a very precise control for a finished mix's volume and harshness.", "purpose_function": "It exists to give mastering engineers transparent, surgical control of dynamics and sibilance — for example squeezing a narrow band or de-essing without dulling the rest of the track.", "practical_application": "An engineer patches it into the mastering chain over AES/EBU, or uses the plugin version, sets a crossover band, and de-esses or compresses just the problem range while leaving the rest untouched.", "category": "Mastering Hardware", "related_terms": ["De-esser", "Multiband compression", "Mid/side processing", "Parallel compression", "Mastering chain"], "common_mistakes": ["Treating it as a simple loudness maximizer rather than a precise band and dynamics tool", "Over-de-essing until vocals sound lisped or dull", "Confusing the hardware unit with the plugin emulation and expecting identical routing"], "scenario_contexts": ["De-essing a bright lead vocal on a stereo master without dulling the cymbals", "Applying gentle band-selective compression to control a boomy low-mid region", "Using mid/side mode to compress the center vocal separately from the sides"]}, "f16edd98-ad1b-4981-9f65-f7a488e65284": {"definition": "The Weiss EQ1 is a reference-grade digital mastering equalizer from Weiss Engineering, offering seven identical parametric bands that each switch between peaking, high/low shelving, and high/low cut modes. It is built in minimum-phase, linear-phase (LP), and dynamic (DYN) variants and is prized for shaping tone without audible artifacts.", "plain_english": "The Weiss EQ1 is a top-quality digital equalizer used in mastering. An equalizer turns certain pitch ranges up or down. It has seven bands, so you can shape the sound in seven places at once. Engineers trust it because it changes tone cleanly, without adding noise.", "purpose_function": "It exists to make precise, clean tonal adjustments to a finished mix, letting a mastering engineer correct or enhance the frequency balance without introducing audible phase or distortion artifacts.", "practical_application": "A mastering engineer uses the EQ1 to make surgical or broad tonal moves, such as taming a harsh upper-midrange or adding gentle high-end air, often working in mid/side mode and choosing the linear-phase variant when phase accuracy matters most.", "category": "Mastering Equalizer", "related_terms": ["Parametric EQ", "Linear-phase EQ", "Mid/side processing", "Mastering chain", "Weiss MM-1", "Shelving filter"], "common_mistakes": ["Assuming linear-phase mode is always better; it can cause pre-ringing on transients, so minimum-phase is often the better choice", "Making large corrective boosts at the mastering stage instead of fixing tonal problems back in the mix", "Overusing mid/side EQ and creating an unnatural balance or mono-compatibility problems", "Expecting analog-style behavior from what is a fixed-sample-rate digital processor"], "scenario_contexts": ["Adding a gentle high-shelf lift to brighten a slightly dull master", "Using mid/side mode to reduce boomy bass only in the center while keeping stereo width", "Matching the tonal balance across an album's tracks for consistency"]}, "6cedcf10-bcc4-482f-9f61-a164524f4b61": {"definition": "The Weiss MM-1 is a mastering-grade dynamics and limiting plug-in (developed by Softube from the Weiss DS1-MK3) that pairs a mastering processing stage with a brick-wall limiter. It offers preset styles (Transparent, Loud, Punch, Wide, De-ess) to control dynamics and raise loudness on a finished master.", "plain_english": "The Weiss MM-1 is a mastering tool that makes a track louder and steadier. It pushes the loudest peaks down, so you can raise the overall volume without clipping. It also comes with ready-made styles, like 'Loud' or 'Punch', that set it up for you.", "purpose_function": "It exists to control dynamics and maximize the perceived loudness of a finished master while its brick-wall limiter guards against digital overs at the end of the chain.", "practical_application": "A mastering engineer places the MM-1 near the end of the chain, picks a style suited to the material, then dials in the Amount and Limiter Gain to reach a loudness target while watching the gain-reduction and output/true-peak meters.", "category": "Mastering Limiter", "related_terms": ["Brick-wall limiter", "Loudness (LUFS)", "True-peak", "Mastering chain", "Weiss EQ1", "Dither"], "common_mistakes": ["Pushing the Limiter Gain too hard, which crushes dynamics and causes distortion or pumping", "Relying on the 'Loud' style by ear-count alone instead of judging how the material actually sounds", "Ignoring true-peak/output levels and delivering a master that clips on lossy-codec playback", "Treating the MM-1 as a fix for a poorly balanced mix rather than mastering an already-good mix"], "scenario_contexts": ["Bringing a quiet mix up to a competitive streaming loudness target", "Adding weight and impact to a drum-heavy track with the 'Punch' style", "Setting the output trim to leave headroom (for example -1 dBFS) for lossy encoding"]}, "99dc77c8-bdce-4bf7-9268-4766b7498511": {"definition": "A wet score stem is a stem (grouped stereo submix) of a film, TV, or game score that has been printed with its effects, typically reverb, delay, and other processing, already applied. It is the 'wet' counterpart to a dry stem, which is delivered without those effects.", "plain_english": "A stem is a group of instruments mixed into one track. A 'wet' stem already has its effects, like reverb, baked in. So a wet score stem is a group of film-music parts with their echo and space added, ready to drop into the final mix.", "purpose_function": "It exists to carry the composer's intended sense of space and effects into the final mix, delivering the score with its reverb and ambience already in place so the sound matches the composer's vision.", "practical_application": "A composer or score mixer delivers wet stems, often alongside dry versions, so the dub-stage mixer can drop the score in with its built-in ambience, accepting that the printed effects can no longer be freely changed.", "category": "Score Stems", "related_terms": ["Stem", "Dry stem", "Reverb", "Submix", "Stem mastering", "Woodwinds stem"], "common_mistakes": ["Confusing a stem with a single instrument track; a stem is a grouped submix, not one instrument", "Delivering only wet stems, leaving the final mixer no way to adjust the reverb or effects", "Assuming 'wet' means fully drenched; it means the effects are printed in at whatever amount the mixer chose"], "scenario_contexts": ["A composer sending the dub stage a wet strings stem with concert-hall reverb already added", "Delivering both wet and dry score stems so the re-recording mixer can choose", "Dropping a wet score stem into a trailer edit to quickly hear the intended sound"]}, "7782ef18-ab38-409f-a245-af306622211f": {"definition": "A woodwinds stem is a stem (grouped stereo submix) containing only the woodwind instruments, such as flutes, oboes, clarinets, and bassoons, of an orchestral or score arrangement, bounced to a single track for use in mixing, mastering, or the final dub.", "plain_english": "A stem is a group of instruments bounced down to one track. A woodwinds stem holds just the woodwind instruments, like flutes, clarinets, and oboes, mixed together. Keeping them on one track lets the mixer change their volume without touching the rest.", "purpose_function": "It exists to give the mix or mastering engineer independent control over the woodwind section's level, tone, and effects without having to reopen the full multitrack session.", "practical_application": "In score delivery a composer bounces a woodwinds stem alongside the strings, brass, and percussion stems so the dub-stage or mastering engineer can balance each section against dialogue and effects.", "category": "Score Stems", "related_terms": ["Stem", "Wet score stem", "Submix", "Stem mastering", "Brass stem", "Strings stem"], "common_mistakes": ["Confusing a stem with a single instrument track; a woodwinds stem is a whole section mixed together", "Expecting to solo one instrument, such as just the flute, from the stem; individual control is lost once it is bounced", "Letting levels or effects drift between section stems, so the reassembled mix no longer matches the original"], "scenario_contexts": ["Delivering separate strings, brass, woodwinds, and percussion stems for a film's final mix", "Lowering the woodwinds stem under dialogue at the dub stage", "Stem-mastering an orchestral cue where the woodwinds need a slight tonal lift"]}, "6b8faa64-a21b-439f-b54f-1e1c303469de": {"definition": "Flux Pure Limiter (Pure Limiter) is a mastering-grade brickwall peak limiter plug-in from FLUX::. It combines look-ahead detection with a proprietary adaptive release-envelope algorithm to raise average loudness while holding the output below a set ceiling with minimal audible artifacts. It offers automatic, manual and advanced release modes plus a difference-monitoring (Diff) feature for checking transparency.", "plain_english": "Flux Pure Limiter is a plug-in that acts like a ceiling for your sound. It stops the loudest peaks from going past a level you set. That lets you turn the whole track up and make it louder without harsh clipping. It tries to do this so cleanly that the change is hard to hear.", "purpose_function": "It exists to maximize perceived loudness at the final stage of a mix or master while guaranteeing the signal never exceeds a chosen output ceiling, protecting against clipping and overs in the delivered file.", "practical_application": "A mastering or mix engineer places it as the last processor in the chain, sets the output ceiling (for example -1 dB), and drives the input until the track reaches its target loudness while watching gain reduction to avoid pumping or distortion.", "category": "Limiter Plugin", "related_terms": ["Brickwall Limiter", "True Peak", "LUFS", "Look-Ahead", "Makeup Gain", "Sonnox Limiter"], "common_mistakes": ["Pushing the input too hard for extreme loudness, which flattens dynamics and adds distortion or pumping.", "Setting the output ceiling to 0 dBFS, which can still leave inter-sample (true-peak) overs after conversion to lossy formats.", "Placing it before other dynamics or EQ instead of as the final stage of the chain.", "Assuming 'transparent' limiting means it can be pushed indefinitely with no audible loss."], "scenario_contexts": ["Final-stage loudness maximization on a master before export.", "Catching stray peaks on a stereo mix bus so the overall level can be raised safely.", "Meeting a streaming or broadcast loudness target while keeping peaks under the ceiling."]}, "57fbf4e2-81d6-47ca-853b-0d3cfb58023d": {"definition": "Sonnox Limiter (the Oxford Limiter) is a mastering peak limiter plug-in that uses logarithmic side-chain processing and look-ahead detection to control peak levels, plus a distinctive Enhance function that raises perceived loudness by adding controlled harmonics while preserving transient detail. It includes an ITU-R BS.1770 true-peak (Recon) meter with auto compensation, and TPDF dither with selectable noise-shaping for 16- or 24-bit output.", "plain_english": "The Sonnox Limiter is a plug-in that keeps your loudest sounds from going over a set level. It also has an 'Enhance' control that makes a track feel louder and fuller. It warns you about hidden peaks that show up after audio is saved as an MP3. Engineers use it as one of the last steps when finishing a song.", "purpose_function": "It exists to raise a master's loudness and prevent overs, using the Enhance stage to gain apparent level without the dulled transients typical of hard limiting, while its true-peak tools keep the file within legal delivery levels.", "practical_application": "An engineer sets the threshold and input gain to reach target loudness, dials in Enhance for extra perceived level, then uses the true-peak meter and auto compensation to keep the render below the required true-peak ceiling before dithering to the delivery bit depth.", "category": "Limiter Plugin", "related_terms": ["Brickwall Limiter", "True Peak", "Dither", "Noise Shaping", "Flux Pure Limiter", "LUFS"], "common_mistakes": ["Overusing the Enhance function so the master becomes harsh, fatiguing or distorted.", "Ignoring the true-peak (Recon) meter and delivering files with inter-sample overs.", "Forgetting to enable dither when reducing bit depth for the final export.", "Treating it as a general track compressor rather than a final-stage limiter."], "scenario_contexts": ["Loudness maximization on a master using the Enhance function for perceived level.", "Correcting inter-sample true-peak overs before delivery to streaming or broadcast.", "Dithering a 24-bit master down to 16-bit for CD or download."]}, "46aa40c8-8ecb-4f8d-90be-eff126927e1d": {"definition": "Youlean Loudness Meter is a loudness-metering plug-in that measures program loudness in LUFS to the ITU-R BS.1770 standard, displaying integrated, short-term and momentary loudness plus loudness range (LRA) and true-peak (dBTP) levels. It provides a scrolling loudness history graph and built-in presets for broadcast (EBU R128, ATSC A/85) and streaming targets (Spotify, YouTube, Apple, Tidal and others); it is offered as a free version alongside a paid PRO version.", "plain_english": "Youlean Loudness Meter is a plug-in that tells you how loud your track really sounds to a listener, not just how high the peaks are. It shows a number in LUFS and a graph over time. That lets you match the loudness that Spotify or YouTube expects. It comes in a free version, which makes it very popular.", "purpose_function": "It exists to let engineers verify that a mix or master meets a specific loudness target and stays under a true-peak ceiling before delivery, replacing guesswork with a standards-based measurement.", "practical_application": "An engineer places it on the master bus, plays the whole track to read the integrated LUFS and maximum true peak, then adjusts level or limiting so the numbers match the chosen streaming or broadcast preset.", "category": "Loudness Meter", "related_terms": ["LUFS", "True Peak", "Loudness Range", "EBU R128", "ITU-R BS.1770", "Integrated Loudness"], "common_mistakes": ["Reading momentary or short-term loudness instead of the integrated value when checking a delivery target.", "Measuring only part of the track, so the integrated LUFS reading is not representative.", "Confusing loudness (LUFS) with peak level (dBFS) and ignoring the true-peak reading.", "Trying to hit a loudness number by ear alone rather than measuring the full program."], "scenario_contexts": ["Checking a master's integrated LUFS against a streaming target such as -14 LUFS.", "Verifying a broadcast mix meets EBU R128 or ATSC A/85 requirements.", "Confirming true peak stays at or below -1 dBTP before exporting a final file."]}, "901c252a-e05e-4a2d-8ecf-c7b7544a3a48": {"definition": "The documented set of technical requirements a broadcaster, streaming service, or distributor mandates for finished program audio - covering loudness targets (e.g. -23 LUFS under EBU R128 or -24 LKFS under ATSC A/85), true-peak limits, file format and wrapper, sample rate, bit depth, channel and track layout, and required metadata - so the material conforms on ingest and plays back correctly.", "plain_english": "Delivery specifications are the rules a client gives you for making a finished audio file. They cover how loud it should be, the file type, and how many audio channels it has. This makes sure the file plays back right when they use it.", "purpose_function": "It exists to make finished material meet a distributor's technical standards so it passes automated quality control and plays back consistently across their platform. It removes guesswork by stating exact loudness, format, and metadata targets up front.", "practical_application": "Before final export a post engineer reads the spec sheet, then measures integrated loudness and true peak against the stated targets and sets the file format, sample rate, bit depth, and track layout to match before sending it to QC.", "category": "Delivery & QC", "related_terms": ["EBU R128", "True peak", "Integrated loudness", "Metadata", "Stem delivery", "Quality control"], "common_mistakes": ["Checking only peak level and ignoring integrated loudness, so the file misses the required LUFS target.", "Overlooking the true-peak ceiling, so inter-sample peaks clip after lossy encoding.", "Delivering the wrong sample rate, bit depth, or channel and track layout for the spec.", "Omitting or mislabeling required metadata, causing an automated QC rejection."], "scenario_contexts": ["Preparing a TV mix to a broadcaster's spec at -23 LUFS integrated with a -1 dBTP true-peak limit under EBU R128.", "Mastering a podcast or music track to a streaming platform's stated loudness target and file format.", "Exporting a film mix with the correct stem and channel layout, sample rate, and bit depth before studio QC.", "Reconforming a delivery that failed automated QC for exceeding the true-peak ceiling or using the wrong wrapper."]}, "2c3dad94-05b0-4ea1-854c-2a5d7a7eb41c": {"definition": "In text-to-speech synthesis, the acoustic model is the component that predicts acoustic features - such as a mel-spectrogram, fundamental frequency, and phoneme durations - from the linguistic or phonetic representation of the input text. A separate vocoder then converts these predicted features into an audible waveform.", "plain_english": "In a computer voice system, this is the part that turns written words into the sound details of speech, like pitch and timing. A later step then uses those details to build the voice you actually hear.", "purpose_function": "It bridges symbolic text and the acoustic detail of speech, letting a synthesizer generate natural pitch, timing, and timbre instead of stitching together fixed recordings. Without it a TTS system could not turn arbitrary text into expressive, intelligible speech.", "practical_application": "A producer relies on TTS acoustic models inside synthetic-voice tools to generate narration, ad reads, or a corrected word, picking a voice and adjusting pacing while the model produces the underlying speech features.", "category": "Speech Technology", "related_terms": ["Text-to-speech (TTS)", "Vocoder", "Automatic speech recognition (ASR)", "Phoneme", "Speech synthesis"], "common_mistakes": ["Confusing the TTS acoustic model (text to features) with the ASR acoustic model (audio to phonemes); they run in opposite directions.", "Assuming the acoustic model outputs finished audio, when it outputs acoustic features that a vocoder must still convert to a waveform.", "Thinking one acoustic model equals one fixed voice, when voice identity, style, and prosody can be handled as separate factors."], "scenario_contexts": ["Generating synthetic narration for a podcast segment from a written script.", "Producing an AI voice to fix a mispronounced word without re-recording the host.", "Comparing TTS voices for naturalness and prosody before choosing one for automated ad reads."]}, "982bdaa1-c516-4711-a5b7-cfe0fd720008": {"definition": "AI captioning is the automated generation of time-synchronized on-screen text from spoken audio using automatic speech recognition, producing caption or subtitle files aligned to the program timeline. The output is normally reviewed and corrected before publication.", "plain_english": "This is when software listens to the talking in your show and writes it on screen as text, timed to the audio. It saves you from typing out every caption by hand.", "purpose_function": "It provides accessibility for deaf and hard-of-hearing viewers and improves discoverability and engagement, far faster and cheaper than captioning by hand. It exists to meet accessibility needs and platform requirements at scale.", "practical_application": "A producer runs the finished episode video through a captioning tool, then edits the auto-generated file for misheard words, speaker labels, and timing before exporting a standard caption format for the platform.", "category": "AI Production Tools", "related_terms": ["AI transcription", "Automatic speech recognition (ASR)", "Closed captioning", "Subtitles", "Timecode"], "common_mistakes": ["Publishing auto-captions without proofreading, leaving misrecognized words, wrong speaker labels, and off timing.", "Assuming captions and subtitles are identical, when captions also include non-speech sound cues for accessibility.", "Ignoring the caption-file format and timing standards required by the target platform."], "scenario_contexts": ["Auto-generating captions for a video podcast before publishing to a platform.", "Creating subtitle files to meet accessibility requirements for a show.", "Producing burned-in captions for short social clips promoting an episode."]}, "7f09a819-419c-4205-83d8-824f7bb66a5d": {"definition": "AI editing is the use of machine-learning tools to perform or assist audio and video editing tasks - such as removing filler words and silences, leveling loudness, reducing noise, or text-based cutting driven by a transcript. A human editor reviews and approves the automated changes.", "plain_english": "This is using smart software to help edit a podcast, like cutting out 'um' sounds or evening out the volume. It does slow, fiddly jobs quickly that a person would otherwise do by hand.", "purpose_function": "It speeds up repetitive, time-consuming editing steps and lowers the skill barrier, letting creators turn out cleaner episodes faster. It exists to automate tedious work so the human can focus on creative and editorial choices.", "practical_application": "An editor loads a recording into an AI-assisted editor, accepts suggested cuts for filler words and long pauses, applies automatic leveling, then fine-tunes the result before export.", "category": "AI Production Tools", "related_terms": ["AI transcription", "Text-based editing", "Noise reduction", "Loudness normalization", "Automatic speech recognition (ASR)"], "common_mistakes": ["Blindly accepting every automated cut, which can clip breaths, words, or timing and make speech sound unnatural.", "Trusting AI leveling or noise reduction so heavily that artifacts or a pumping sound slip through.", "Skipping a full human review and quality check before export."], "scenario_contexts": ["Removing filler words and long silences from a raw interview recording.", "Applying automatic loudness leveling and noise reduction to a remote-recorded episode.", "Using text-based editing to cut audio by deleting words in the transcript."]}, "1698868f-85a5-41b1-98a3-e3b8457d21ce": {"definition": "AI transcription is the automatic conversion of recorded speech into written text using automatic speech recognition, often with speaker labels and word-level timestamps. Accuracy depends on audio quality, accents, and vocabulary, so the output usually needs proofreading.", "plain_english": "This is when software listens to a recording and writes down what was said as text. It is like an automatic note-taker for your audio.", "purpose_function": "It produces searchable, editable text from audio for show notes, captions, and text-based editing, replacing slow manual transcription. It exists to make spoken content usable as text quickly and cheaply.", "practical_application": "A producer uploads an interview and receives a timestamped transcript, which they clean up for show notes, quote pulling, and to drive text-based editing of the audio.", "category": "AI Production Tools", "related_terms": ["Automatic speech recognition (ASR)", "AI captioning", "Text-based editing", "Diarization", "Show notes"], "common_mistakes": ["Treating the raw transcript as error-free instead of proofreading names, jargon, and punctuation.", "Expecting high accuracy from noisy, overlapping, or heavily accented audio.", "Forgetting that timestamps and speaker labels may still need manual correction."], "scenario_contexts": ["Generating a timestamped transcript to write show notes and pull quotes.", "Producing a transcript to drive text-based audio editing.", "Creating a searchable text archive of past episodes."]}, "ddf71d99-ea23-4c8c-abed-51f8284a0dc1": {"definition": "An air studio (on-air studio) is the studio room from which a live radio, streaming, or broadcast program originates, equipped with microphones, a broadcast console, and monitoring. It is the space actively feeding the transmission or stream while a program is on air.", "plain_english": "This is the studio a show is actually broadcast or streamed from while it is live. It is the room that is 'on air' at that moment.", "purpose_function": "It gives presenters a controlled, acoustically suitable place to perform while the program is mixed for broadcast, keeping live output isolated from other production work. It exists to reliably originate live content.", "practical_application": "A technician preps the air studio before a live show, checking mic channels, headphone feeds, talkback, and the on-air light so the presenter can go live without technical faults.", "category": "Broadcast Facilities", "related_terms": ["Announce booth", "Central apparatus room", "Control room", "Broadcast console", "Talkback"], "common_mistakes": ["Confusing the air studio with the control room; the air studio is where the program is performed and originated.", "UNSAFE: Servicing live mains-powered console or rack wiring in an on-air studio without lockout/tagout and de-energizing per OSHA 29 CFR 1910.147 and NFPA 70E.", "Forgetting to check the on-air/tally light and monitor muting, causing feedback or unintended dead air."], "scenario_contexts": ["Prepping the air studio for a live streamed talk show.", "Switching program origination between two air studios for back-to-back shows.", "Troubleshooting a dead mic channel in the air studio minutes before going live."]}, "6e62379a-28ae-480a-ac0b-c1d4975b316b": {"definition": "An announce booth is a small, acoustically treated and sound-isolated room designed for recording or broadcasting a single voice, such as a narrator, announcer, or host. Its treatment minimizes outside noise and internal reflections for a clean, dry vocal recording.", "plain_english": "This is a small, quiet, sound-treated room used just for recording one person's voice. Its walls hold back noise and echo so the voice sounds clean.", "purpose_function": "It isolates the voice from room noise and equipment sound so recordings stay intelligible and consistent. It exists to give voice work a controlled acoustic space separate from the control room and other areas.", "practical_application": "A voiceover artist records narration in the announce booth while the engineer monitors and directs from the control room over talkback, capturing clean takes for editing.", "category": "Broadcast Facilities", "related_terms": ["Air studio", "Central apparatus room", "Control room", "Acoustic treatment", "Talkback"], "common_mistakes": ["Assuming the booth is fully soundproof, when light treatment only reduces, not eliminates, outside noise.", "Over-treating the booth until it sounds unnaturally dead and boxy.", "Forgetting ventilation, so long sessions get hot and HVAC or handling noise creeps in."], "scenario_contexts": ["Recording clean voiceover narration for an episode intro.", "Tracking a host's solo segments isolated from control-room noise.", "Capturing pickup lines to patch into an already-edited episode."]}, "1015457d-c1b1-4444-b4a3-ddd0f803a3d9": {"definition": "ASR is the abbreviation for automatic speech recognition, the technology that converts spoken language into written text automatically. Modern ASR systems use trained acoustic and language models to transcribe speech.", "plain_english": "ASR is short for automatic speech recognition. It means software that turns spoken words into written text on its own.", "purpose_function": "As shorthand for automatic speech recognition, it underlies transcription, captioning, and voice-command features by turning spoken audio into machine-readable text. It exists so systems can record or act on what is said.", "practical_application": "A producer leans on ASR-powered tools to auto-transcribe episodes and generate captions, then corrects recognition errors before publishing.", "category": "Speech Technology", "related_terms": ["Automatic speech recognition (ASR)", "AI transcription", "AI captioning", "Language model", "Acoustic model (TTS)"], "common_mistakes": ["Reading ASR as one specific product rather than the general technology of automatic speech recognition.", "Assuming ASR understands meaning, when it transcribes words but does not truly comprehend them.", "Expecting perfect accuracy regardless of audio quality or accent."], "scenario_contexts": ["Choosing an ASR-based service to auto-transcribe recorded interviews.", "Using ASR to power automatic captions on a livestream.", "Enabling voice commands in a production tool built on ASR."]}, "7eb5a29a-66ec-41b9-a8e6-7edb95472041": {"definition": "Automatic speech recognition (ASR) is the machine process of converting spoken audio into text, typically combining an acoustic model, a pronunciation/lexicon component, and a language model, or using an end-to-end neural network. Its accuracy is commonly measured by word error rate.", "plain_english": "This is technology that listens to speech and writes it out as text by itself. It is the engine behind voice typing and automatic captions.", "purpose_function": "It lets machines transcribe and respond to human speech, powering transcription, captioning, voice search, and voice assistants. It exists to turn the sound of speech into structured text that software can process.", "practical_application": "In podcast production, ASR drives automatic transcription and captioning; the technician picks a service, feeds it clean audio for best accuracy, and reviews the text output for errors.", "category": "Speech Technology", "related_terms": ["ASR", "AI transcription", "AI captioning", "Acoustic model (TTS)", "Language model"], "common_mistakes": ["Confusing ASR (speech to text) with TTS (text to speech); they are opposite processes.", "Assuming ASR performs equally across accents, languages, and noisy conditions.", "Judging ASR only by polished demo clips instead of word error rate on real material."], "scenario_contexts": ["Feeding clean, single-speaker audio to an ASR engine to maximize transcription accuracy.", "Comparing ASR services by word error rate on sample episodes.", "Using ASR output as the basis for captions and text-based editing."]}, "80225d05-63f4-40fd-8bc6-1aade3074c33": {"definition": "The central apparatus room (CAR), also called the central equipment or central technical area, is the core technical space in a broadcast or production facility that houses central routing, distribution, signal processing, and interconnection equipment. Studios and control rooms interconnect through it, and it is environmentally controlled for the equipment.", "plain_english": "This is the central technical room in a broadcast building that holds the main routing and signal gear. Think of it as the hub where all the audio and video signals meet and get sent where they need to go.", "purpose_function": "It centralizes the facility's signal routing and core hardware so signals can be distributed reliably among studios, control rooms, and transmission and maintained in one place. It exists to keep the technical infrastructure organized, cooled, and accessible.", "practical_application": "An engineer configures router crosspoints, sync/reference generators, and distribution amplifiers in the central apparatus room to route sources between studios and to air.", "category": "Broadcast Facilities", "related_terms": ["Air studio", "Announce booth", "Control room", "Signal routing", "Patch bay"], "common_mistakes": ["Confusing the CAR with a studio or control room; it holds shared core routing and processing gear, not presenters.", "UNSAFE: Servicing energized racks, PDUs, or mains distribution in the CAR without lockout/tagout and PPE per OSHA 29 CFR 1910.147 and NFPA 70E.", "Neglecting cooling and cable management, causing overheating or hard-to-trace signal faults."], "scenario_contexts": ["Patching a new source into the router in the central apparatus room.", "Tracing a signal fault back to distribution gear in the CAR.", "Installing and cooling new processing hardware in the central apparatus room."]}, "bf223b85-9638-49fe-a749-1ba289fe5c74": {"definition": "A small, acoustically isolated enclosure at an event venue or studio from which a commentator or announcer speaks into a microphone for a live or recorded broadcast. Its treatment limits crowd noise and spill so the presenter's voice stays clean.", "plain_english": "A small, sound-proofed room where a sports or event announcer talks into a mic. The walls keep out crowd noise, so listeners hear the voice clearly.", "purpose_function": "It gives commentators a quiet, controlled space so their voice is captured cleanly and kept separate from crowd and field noise.", "practical_application": "A broadcast technician wires the booth's microphones, headphones, and talkback to the console, then sets levels so the commentator hears program and cue feeds while speaking.", "category": "Recording Space", "related_terms": ["Commentary position", "Isolation booth", "Talkback", "Lip microphone", "Outside broadcast"], "common_mistakes": ["Assuming the booth is fully soundproof and skipping a directional or noise-cancelling mic, so crowd noise still bleeds in.", "Forgetting to feed clean talkback and program audio to the commentator's headphones, leaving them unable to follow cues.", "Placing the booth without sightlines to the action, so the commentator cannot see what they are describing."], "scenario_contexts": ["A stadium sports broadcast where announcers call the game from a booth overlooking the field.", "A convention or esports event where hosts commentate from an isolated booth beside a noisy hall.", "A studio show that records play-by-play style commentary in an acoustically treated booth."]}, "82c492a4-d2a7-489f-b23e-87483ca11afa": {"definition": "A designated operating point at a venue, equipped with a commentary unit (microphone, headphones, and talkback controls), from which one or more commentators contribute audio to a broadcast. A venue may host many positions, each feeding a central mix.", "plain_english": "The exact spot at an event where a commentator sits to work. It has a mic, headphones, and controls so their voice reaches the broadcast.", "purpose_function": "It provides a fixed, pre-wired place for commentators to plug in, hear the show, and talk, so venues can host many broadcasters in an organized way.", "practical_application": "Technicians assign and cable each commentary position to the outside-broadcast truck, label its channel, and check the mic, headphone, and talkback path before the event.", "category": "Recording Space", "related_terms": ["Commentary booth", "Commentary unit", "Talkback", "Mix-minus", "Outside broadcast"], "common_mistakes": ["Confusing a commentary position with a full booth; a position may be an open desk with no acoustic isolation.", "Not confirming the mix-minus feed to each position, so a commentator hears an echo of their own voice.", "Mislabeling positions, so the wrong commentator's microphone reaches air."], "scenario_contexts": ["A multi-language broadcast where each network gets its own commentary position along a stadium gantry.", "An awards show with several commentary positions feeding one central mix.", "A radio sports broadcast where two presenters share one commentary position."]}, "abbdc69a-04e2-41d6-9689-004789bf42df": {"definition": "A compact, self-contained recording and production space outfitted for an individual content creator, typically combining a treated room, microphone, camera, lighting, and an audio interface or all-in-one recorder for podcasts and video. It is scaled for one person or a small team rather than a full commercial facility.", "plain_english": "A small, ready-to-use studio set up for a single creator. It bundles a mic, camera, lights, and recording gear so one person can make podcasts or videos.", "purpose_function": "It packages the core recording tools in one manageable space so a solo creator can produce professional-sounding content without a large commercial studio.", "practical_application": "A technician helps a creator lay out the studio: positioning the mic and acoustic treatment, setting camera and lighting, and configuring the interface so levels stay consistent across sessions.", "category": "Recording Space", "related_terms": ["Home studio", "Podcast studio", "Audio interface", "Acoustic treatment", "Portable recorder"], "common_mistakes": ["Spending on cameras and lights while ignoring acoustic treatment, so the room sounds echoey.", "Choosing a mic that is too sensitive for an untreated room, which then picks up background noise.", "Not setting a repeatable gain and gear layout, so each recording sounds different."], "scenario_contexts": ["A solo podcaster building a spare-room studio for weekly episodes.", "A video creator setting up a corner studio for talking-head content.", "A small team sharing a compact studio to record interviews."]}, "ae8d75a0-327b-49cd-8095-93958b26f30c": {"definition": "Descript is a commercial audio and video editing application that transcribes a recording and lets the user edit the media by editing its text transcript; deleting words removes the matching audio and video. It also bundles tools such as filler-word removal, voice enhancement, and synthetic voice generation.", "plain_english": "Descript is an app that turns your recording into text, then lets you edit the audio or video by editing that text. Delete a word in the transcript and the matching sound is cut too.", "purpose_function": "It speeds up podcast and video editing by letting creators work in a familiar word-processor style instead of dragging clips along a timeline.", "practical_application": "An editor imports a raw interview, cleans up the transcript, removes filler words and mistakes by deleting text, then exports the finished episode.", "category": "Editing Software", "related_terms": ["Filler-word removal", "Diarization", "Forced alignment", "Transcription", "Multitrack editing"], "common_mistakes": ["Trusting the auto-transcript without proofreading, so wrong words lead to bad edits.", "Deleting filler words so aggressively that the speech sounds choppy and unnatural.", "Assuming AI voice or enhancement features can fully fix a poor original recording."], "scenario_contexts": ["Editing a two-host podcast by cleaning up the transcript.", "Cutting a long video interview into short clips by deleting text.", "Correcting a mispronounced word using synthetic voice tools."]}, "3debbf34-ac65-43f9-8225-558ecd5f7ecd": {"definition": "Diarization (speaker diarization) is the process of partitioning an audio recording into segments labeled by speaker identity, answering 'who spoke when' without necessarily knowing the words. It groups speech regions so each is attributed to a distinct speaker.", "plain_english": "Diarization is a way for software to figure out who is talking and when. It splits the audio into pieces and labels each one with a speaker, like Speaker 1 or Speaker 2.", "purpose_function": "It labels multi-speaker audio so transcripts, captions, and edits can show who said what.", "practical_application": "A podcast editor uses diarization in a transcription tool to auto-tag each host and guest, then fixes only the few sections it mislabels.", "category": "Speech Processing", "related_terms": ["Transcription", "Forced alignment", "Voice activity detection", "Descript", "Speaker embedding"], "common_mistakes": ["Assuming diarization also transcribes words; it only separates speakers, not what they say.", "Expecting perfect labels when speakers talk over each other, which causes errors.", "Not correcting swapped speaker labels before publishing a transcript."], "scenario_contexts": ["Auto-labeling hosts and guests in a multi-person podcast transcript.", "Separating speakers in a recorded interview for accurate captions.", "Indexing a meeting recording by who spoke."]}, "3183c94f-0fb2-4b97-844f-f7a08b5bc0ee": {"definition": "Enhance Speech v2 is Adobe's second-generation AI speech-enhancement tool, part of Adobe Podcast, that removes background noise and reverberation from voice recordings and re-synthesizes the speech to sound as if recorded in a studio. Version 2 improves fidelity and adds an adjustable strength control over how much processing is applied.", "plain_english": "Enhance Speech v2 is a free Adobe web tool that cleans up voice recordings. It strips out background noise and echo and makes the voice sound like it was recorded in a good studio.", "purpose_function": "It rescues voice recordings made in noisy or echoey spaces so creators can publish clear audio without re-recording.", "practical_application": "A podcaster uploads a noisy remote-guest track, applies Enhance Speech v2, and dials back the strength if the processed voice starts to sound artificial.", "category": "Speech Enhancement", "related_terms": ["Noise reduction", "De-reverberation", "Audio restoration", "Descript", "Diarization"], "common_mistakes": ["Pushing the enhancement to full strength, which can make the voice sound robotic or 'underwater'.", "Using it as an excuse to record in a bad room instead of fixing the source.", "Running music or multi-source audio through it, when it is designed only for speech."], "scenario_contexts": ["Cleaning a remote interview recorded on a laptop mic in an echoey room.", "Salvaging a field recording with traffic noise in the background.", "Improving a phone-quality voice memo before adding it to an episode."]}, "355ed18c-7716-4879-8263-648b8b895e5f": {"definition": "Filler-word removal is an editing process, often automated, that detects and deletes disfluencies such as 'um', 'uh', 'like', and 'you know' from recorded speech. In transcript-based editors it flags these words so they can be removed individually or in bulk.", "plain_english": "Filler-word removal cuts out sounds like 'um' and 'uh' from a recording. Editing software can find them for you, so you delete them in one step.", "purpose_function": "It tightens speech and helps a host sound more confident and polished without changing the meaning.", "practical_application": "An editor runs automatic filler-word detection on an interview, reviews the flagged words, and keeps a few natural pauses so the speech does not sound clipped.", "category": "Editing", "related_terms": ["Descript", "Transcription", "Disfluency", "Audio editing", "Enhance Speech v2"], "common_mistakes": ["Removing every filler word, which makes speech sound rushed and unnatural.", "Trusting the automatic tool without listening, so real words get cut.", "Cutting fillers without smoothing the edit, leaving audible clicks or jumps."], "scenario_contexts": ["Cleaning up a nervous guest's answers in an interview episode.", "Tightening a rambling monologue before publishing.", "Preparing a short clip for social media where every second counts."]}, "d54d4569-63fa-48da-b70f-cb42265fa0be": {"definition": "Forced alignment is a speech-processing technique that automatically time-aligns a known transcript to its audio, producing start and end times for each word and often each phoneme. It 'forces' the recognizer to follow the supplied text rather than guessing the words.", "plain_english": "Forced alignment lines up a written script with its recording. It marks exactly when each word is spoken, giving a time stamp for every word.", "purpose_function": "It creates accurate word timings used for captions, transcript-based editing, word highlighting, and speech research.", "practical_application": "A transcript-based editor relies on forced alignment so that clicking a word in the text jumps to that exact moment in the audio.", "category": "Speech Processing", "related_terms": ["Diarization", "Transcription", "Speech recognition", "Phoneme", "Descript"], "common_mistakes": ["Feeding a transcript that does not match the audio, which throws off all the timings.", "Assuming alignment stays accurate through long silences or noise, where it can drift.", "Confusing forced alignment with speech recognition; alignment needs the text supplied."], "scenario_contexts": ["Syncing captions to a video so words appear exactly as spoken.", "Enabling word-level editing where deleting text cuts the matching audio.", "Building a phonetics dataset with word and phoneme timings."]}, "1d4f753c-d5ac-4338-a614-2f7f34ac9d3e": {"definition": "Griffin-Lim is an iterative algorithm that reconstructs a time-domain signal from the magnitude of its short-time Fourier transform by estimating the missing phase. It repeatedly converts between the spectrogram and waveform, forcing consistency until the reconstructed magnitude matches the target.", "plain_english": "Griffin-Lim is a method that turns a spectrogram back into real sound. A spectrogram is a picture of a sound's frequencies. That picture leaves out the timing part called phase, so the method guesses the phase and improves it step by step until the sound fits.", "purpose_function": "It lets systems recover playable audio from a spectrogram alone, which is useful in speech synthesis and in effects that work in the frequency domain.", "practical_application": "A developer building a text-to-speech or vocoder pipeline uses Griffin-Lim to turn a generated spectrogram into audio when no learned vocoder is available.", "category": "Signal Processing", "related_terms": ["Short-time Fourier transform", "Spectrogram", "Phase", "Vocoder", "Speech synthesis"], "common_mistakes": ["Expecting perfect quality; Griffin-Lim often leaves a slight metallic or 'phasey' artifact.", "Running too few iterations, which leaves the audio rough and robotic.", "Assuming it can invent detail that is missing from the magnitude spectrogram."], "scenario_contexts": ["Generating audio from a spectrogram in a classic text-to-speech system.", "Reconstructing sound after editing a magnitude spectrogram.", "Serving as a baseline vocoder before switching to a neural one."]}, "2e7556d6-25b4-4f32-9fb9-d8c59f0f5f77": {"definition": "HiFi-GAN is a neural vocoder built on a generative adversarial network (GAN) that converts a mel-spectrogram into a raw audio waveform for high-fidelity speech synthesis. Introduced in 2020, it pairs a generator with multi-period and multi-scale discriminators to model the periodic patterns of speech, producing near-human-quality audio far faster than real time.", "plain_english": "HiFi-GAN is an AI tool that turns a sound picture, called a spectrogram, into real audio you can hear. It is trained to make computer voices sound clear and natural, and it runs very fast. Think of it as the last step that gives a synthetic voice its lifelike sound.", "purpose_function": "It exists to generate the final audio waveform in a text-to-speech pipeline, taking the acoustic features an earlier model predicts and rendering them as clean, natural-sounding speech quickly enough for practical use.", "practical_application": "A podcast producer meets HiFi-GAN inside AI voice and dubbing tools, where it is the vocoder stage that turns a synthesized voice's spectrogram into the finished audio used for narration, corrections, or synthetic hosts.", "category": "Speech Synthesis", "related_terms": ["Neural vocoder", "Neural TTS", "Mel-spectrogram", "Text-to-speech", "Voice cloning", "Waveform"], "common_mistakes": ["Thinking HiFi-GAN creates speech from text on its own; it only converts a mel-spectrogram into a waveform and needs an acoustic model in front of it", "Assuming a vocoder trained on one voice or sample rate will sound just as good on another without fine-tuning", "Confusing the GAN vocoder with the whole text-to-speech system"], "scenario_contexts": ["Generating a synthetic narrator voice inside an AI text-to-speech plugin", "Rendering corrected words in an overdub tool so they blend with the original recording", "Producing a cloned host voice for automated podcast intros"]}, "5f653dac-6284-48d9-8576-942135839741": {"definition": "An ingest room is a space in a media production facility that houses the ingest stations used to capture, digitize, and import incoming audio and video into the facility's shared storage and media asset management (MAM) system. It is where recorded or live source material is quality-checked, tagged with metadata, and made available for editing and production.", "plain_english": "An ingest room is where a studio brings raw recordings into its computers and storage. Staff load or record the material, label it, and check it is clean before anyone edits it. Think of it as the loading dock where all the audio and video first comes in.", "purpose_function": "It exists to get source media into the production system reliably, with the correct format, file naming, and metadata, so the material is ready and easy to find for later editing.", "practical_application": "A technician in an ingest room captures feeds from recorders, cameras, or remote links, confirms levels and file integrity, and imports the files into shared storage so editors can start work.", "category": "Production Facility", "related_terms": ["Media-management room", "Media asset management", "Metadata", "Post-production", "News studio", "Mobile production unit"], "common_mistakes": ["Skipping metadata and clear file naming at ingest, which makes clips almost impossible to find later", "Ingesting at the wrong sample rate, bit depth, or format and creating sync or quality problems downstream", "Assuming ingest is just copying files, when it also includes quality-checking and logging the material"], "scenario_contexts": ["Importing field recordings from an interview shoot into shared storage", "Digitizing older tape archives into files for a documentary podcast", "Capturing an incoming remote feed and tagging it before an editor pulls it up"]}, "58c16408-1b5b-406b-9bc7-98ae900bf8b5": {"definition": "An interview studio is an acoustically treated room set up to record conversations between a host and one or more guests, equipped with individual microphones, headphones, and often cameras. It is designed for controlled, low-noise capture with each participant on a separate channel.", "plain_english": "An interview studio is a quiet, sound-treated room built for recording people talking together. Each person gets a mic and headphones, so their voices stay clear and separate. It is like a small meeting room, but tuned so voices sound clean and free of echo.", "purpose_function": "It exists to capture clear, separate recordings of each speaker in a controlled acoustic space, giving the editor clean tracks to balance and process.", "practical_application": "A podcast engineer sets up an interview studio by placing a mic and headphones for each guest, routing every mic to its own channel, and checking levels and room noise before the conversation starts.", "category": "Production Facility", "related_terms": ["News studio", "Multitrack recording", "Acoustic treatment", "Microphone", "Ingest room", "Mobile production unit"], "common_mistakes": ["Recording all speakers to one shared channel, which removes the ability to fix one person's level or tone later", "Ignoring room acoustics and capturing echo or HVAC noise that cannot be cleaned up afterward", "Forgetting headphones or spill control, so mics pick up each other and cause phase problems"], "scenario_contexts": ["Recording a two-guest interview with each person on a separate track", "Tracking a guest locally in the studio while the host sits in the same room", "Setting mic levels and checking background noise before a live-to-tape session"]}, "5ba34a15-3373-49c7-848a-607aff2456d4": {"definition": "A media-management room is the facility space where staff operate the systems that store, catalog, move, and archive a production's media assets, typically centered on a media asset management (MAM) system and shared storage. It is where files are organized, backed up, transcoded, and tracked through their lifecycle.", "plain_english": "A media-management room is where a studio keeps track of all its audio and video files. Staff there store, label, back up, and archive the material so nothing gets lost. Think of it as the library and filing office for everything the studio records.", "purpose_function": "It exists to keep a production's growing library of files organized, safely backed up, and easy to search, so the right version of any asset can be found and reused.", "practical_application": "A media manager uses this room to check files into the MAM, run backups and transcodes, archive finished projects to free up fast storage, and make sure editors can locate assets.", "category": "Production Facility", "related_terms": ["Media asset management", "Ingest room", "Metadata", "Archive", "Network operations center", "Post-production"], "common_mistakes": ["Treating storage as unlimited and never archiving, so fast drives fill up and the whole workflow slows", "Relying on a single copy with no backup, risking permanent loss of recordings", "Letting file naming and metadata drift, which makes assets impossible to find later"], "scenario_contexts": ["Archiving a finished season to long-term storage to free up working drives", "Restoring an older episode's project files for a re-edit", "Running nightly backups of a shared media library"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"b4fcd732-45d0-43ce-a9d6-cf125fed3901": {"definition": "A mobile production unit is a vehicle or transportable rig fitted out as a complete production facility, containing mixing, recording, monitoring, and signal-routing equipment so a crew can capture and produce content on location. It is the outside-broadcast equivalent of a fixed control room, brought to events away from the studio.", "plain_english": "A mobile production unit is a truck or van built to work like a studio on wheels. It carries the mixers, recorders, and screens a crew needs to record and produce a show at an event. Think of it as a control room you can drive to wherever the action is.", "purpose_function": "It exists to bring full production and monitoring capability to remote locations, letting a crew record, mix, and sometimes broadcast an event that cannot be brought into a fixed studio.", "practical_application": "An engineer uses a mobile production unit to patch in mics and feeds from a venue, mix and record the show inside the vehicle, and send finished audio to a recorder or transmission link.", "category": "Production Facility", "related_terms": ["Network operations center", "Ingest room", "Remote production", "Signal routing", "Interview studio", "Live broadcast"], "common_mistakes": ["Assuming venue power is clean and adequate instead of checking the supply and grounding before connecting gear", "UNSAFE: Running cables across walkways or tying into mains power without proper protection and bonding, creating trip and shock hazards", "Underestimating cable runs and channel counts, then arriving without enough infrastructure for the site"], "scenario_contexts": ["Recording a live podcast or concert from the venue's parking area", "Producing a multi-guest event on location with the mix done inside the truck", "Feeding a remote link back to the main studio from a sports or news event"]}, "85bded86-6832-4c7c-82f0-4082016bdecf": {"definition": "A network operations center (NOC) is a centralized room from which staff continuously monitor and control a broadcaster's or network's distribution, transmission, and IT infrastructure. Operators watch signal quality, system health, and alarms, and respond to faults to keep content flowing to the audience.", "plain_english": "A network operations center, or NOC, is a control room where staff watch over a network's signals and systems around the clock. Screens show them what is working and warn them when something breaks. Think of it as the mission control that keeps shows reaching listeners and viewers.", "purpose_function": "It exists to give one place with full visibility of the delivery chain, so problems are spotted and fixed quickly and content keeps reaching the audience without interruption.", "practical_application": "NOC operators watch monitoring dashboards and alarms for streams, feeds, and servers, log incidents, and either fix issues remotely or dispatch engineers when a signal or system fails.", "category": "Production Facility", "related_terms": ["Media-management room", "Mobile production unit", "Distribution", "Signal monitoring", "Ingest room", "Playout"], "common_mistakes": ["Confusing a NOC with a production control room; a NOC monitors delivery and infrastructure, not the creative mix", "Ignoring or silencing alarms instead of investigating them, letting small faults grow into outages", "Assuming monitoring alone fixes problems, when clear escalation and response steps are what actually restore service"], "scenario_contexts": ["Monitoring around the clock that all live streams and feeds stay online", "Catching a failing encoder from an alarm and switching to a backup", "Coordinating with an on-site engineer during a transmission fault"]}, "8a335f96-e183-46a7-b31d-f39710d0de1d": {"definition": "Neural TTS (text-to-speech) is speech synthesis that uses deep neural networks to convert written text into natural-sounding spoken audio. A typical system first predicts acoustic features such as a mel-spectrogram from the text, then a neural vocoder turns those features into a waveform.", "plain_english": "Neural TTS is technology that reads text out loud using AI-trained voices. Instead of stitching together recorded clips, it learns from lots of speech to make a voice that sounds natural. It is what lets an app turn a written script into a smooth, human-like voice.", "purpose_function": "It exists to produce speech from text that sounds natural and expressive, replacing older robotic methods so synthetic voices are pleasant and easy to understand.", "practical_application": "A podcast producer uses neural TTS to generate narration, ad reads, or a synthetic host voice from a script, then edits the timing and pronunciation to fit the show.", "category": "Speech Synthesis", "related_terms": ["Neural vocoder", "HiFi-GAN", "Mel-spectrogram", "Voice cloning", "Text-to-speech", "Prosody"], "common_mistakes": ["Thinking neural TTS understands meaning; it predicts sound from text and can still mispronounce names or stress words wrongly", "Expecting perfect output with no editing, when pronunciation, pacing, and emphasis often need manual fixes", "Confusing the full TTS system with the vocoder, which is only the final waveform-generating stage"], "scenario_contexts": ["Turning a written script into a narrated segment", "Generating consistent ad reads across many episodes", "Creating a synthetic voice for automated show intros and outros"]}, "d1f8cc07-8163-411d-92bb-9d142485ea64": {"definition": "A neural vocoder is a deep neural network that generates a time-domain audio waveform from a compact acoustic representation, most often a mel-spectrogram. It is the final stage of modern speech-synthesis pipelines, replacing traditional signal-processing vocoders to produce more natural audio.", "plain_english": "A neural vocoder is an AI model that builds real, hearable audio from a compressed sound picture like a spectrogram. It learns from lots of recordings how a natural voice should sound. It is the part that gives a computer voice its final, lifelike audio.", "purpose_function": "It exists to reconstruct high-quality audio waveforms from acoustic features, giving text-to-speech and voice tools natural sound that older rule-based vocoders could not match.", "practical_application": "A producer encounters neural vocoders inside AI voice, dubbing, and voice-cloning tools, where they render the final audio from features an acoustic model predicts; well-known examples include WaveNet and HiFi-GAN.", "category": "Speech Synthesis", "related_terms": ["HiFi-GAN", "Neural TTS", "Mel-spectrogram", "Voice cloning", "Text-to-speech", "Waveform"], "common_mistakes": ["Confusing a neural vocoder with a classic music vocoder effect; here it means an AI model that generates a speech waveform", "Assuming the vocoder alone makes speech from text, when it needs an acoustic model to supply the features", "Expecting one trained vocoder to handle any voice or sample rate without fine-tuning"], "scenario_contexts": ["Producing the final audio in an AI text-to-speech tool", "Rendering a cloned voice for narration", "Regenerating clean audio for corrected words in an overdub editor"]}, "e51d0933-2fed-4a2d-8a4e-101e5e9edf85": {"definition": "A news studio is an acoustically controlled broadcast studio built to produce news programs, typically featuring an anchor desk, presenter microphones, multiple cameras, lighting, and links to a control room. It is designed for clear speech capture and reliable, repeatable live or recorded production.", "plain_english": "A news studio is the room where news shows are made, with a desk, cameras, lights, and mics for the presenters. It is sound-treated so voices come through clearly for live or recorded programs. Think of the familiar set where a news anchor sits and reads the headlines.", "purpose_function": "It exists to provide a controlled, camera- and mic-ready space for presenting news reliably, capturing clean speech and feeding a control room for live or recorded output.", "practical_application": "An audio technician in a news studio sets presenter mics (often lavalier or headset), manages levels and background noise, and sends the mix to the control room for broadcast or recording.", "category": "Production Facility", "related_terms": ["Interview studio", "Ingest room", "Acoustic treatment", "Microphone", "Mobile production unit", "Live broadcast"], "common_mistakes": ["Letting studio HVAC or lighting noise into open mics instead of controlling the background noise", "Poor lavalier or headset mic placement causing rustle, popping, or uneven levels", "Ignoring acoustic treatment, so a bright, reflective set makes speech sound harsh or echoey"], "scenario_contexts": ["Micing two anchors at a desk for a live bulletin", "Recording a scripted news segment to feed post-production", "Balancing presenter and guest levels during a live cross to a reporter"]}, "848fada5-4637-4fc7-bac6-4f8dd7eeb6bf": {"definition": "A playout room (or playout centre) is the technical space in a broadcast or streaming facility where finished programme content and its schedule are assembled and transmitted, 'played out', to air or to a distribution network. It houses playout servers, broadcast automation, and master-control switching that insert idents, graphics, and advertising at their scheduled times.", "plain_english": "A playout room is where a TV or streaming channel sends its shows out to viewers. Computers here follow a schedule and play each program at the right time. They also drop in things like logos and ads. Think of it as the room that runs the channel's whole daily lineup.", "purpose_function": "It exists to turn a programme schedule into a continuous, on-time broadcast signal, automatically switching between shows, breaks, and branding so the channel runs without gaps.", "practical_application": "A technician in the playout room loads the day's schedule into the automation system, confirms that media files and graphics are ingested and ready, and monitors the outgoing signal, stepping in manually if a clip fails or the schedule changes.", "category": "Broadcast Facility", "related_terms": ["Master control", "Production control room", "Sound control room", "Broadcast automation", "Transmission control room", "Playout server"], "common_mistakes": ["Confusing playout with live production; playout transmits finished, scheduled content rather than creating it live", "Assuming playout is fully hands-off; operators must still monitor the output and handle failures", "Forgetting to confirm that media and graphics are ingested and ready before the scheduled air time"], "scenario_contexts": ["Automatically airing a channel's evening lineup of pre-recorded shows and ad breaks", "Switching to a live feed from a production control room at the scheduled time", "Recovering on air when a scheduled clip is missing or corrupted"]}, "1e0034ec-1601-4430-815a-d6638f4f4c56": {"definition": "A podcast studio is a room or facility set up for recording, and sometimes live-streaming, podcast episodes, typically equipped with microphones, headphones, a mixer or audio interface, and acoustic treatment to control room reflections. It can range from a small treated booth to a multi-seat room fitted with cameras for a video podcast.", "plain_english": "A podcast studio is a room built for recording podcasts. It has microphones, headphones, and a mixer to capture clear voices. The walls often have soft panels that cut echo. Many studios also add cameras so the show can be filmed as well as heard.", "purpose_function": "It exists to give hosts and guests a quiet, acoustically controlled space with the gear needed to capture clean, consistent speech for an episode.", "practical_application": "A technician sets up and gain-stages each microphone, hands out headphones, checks levels on the mixer or interface, and records the session while watching for clipping, background noise, and room echo.", "category": "Recording Facility", "related_terms": ["Production control room", "Sound control room", "Acoustic treatment", "Audio interface", "Microphone technique", "Live streaming"], "common_mistakes": ["Recording in an untreated, echoey room and expecting a clean broadcast sound", "Setting microphone gain too high, causing clipping that cannot be fixed later", "Ignoring steady background noise such as HVAC or computer fans", "Not giving guests headphones, which leads to speaker bleed and echo in the recording"], "scenario_contexts": ["Recording a multi-host interview with each speaker on a separate microphone track", "Streaming a live video podcast to an audience while also recording", "Tracking a solo narration episode in a small treated booth"]}, "53b1356f-21de-41ca-bd2b-1fae7d50b1d1": {"definition": "A production control room (PCR), also called a gallery, is the room in a television or live-video facility from which a programme is directed and technically controlled in real time. It houses the vision mixer/switcher, monitor wall, and operating positions for the director, technical director, and others who select shots, cue sources, and assemble the live output.", "plain_english": "A production control room is the room where a live TV show is put together as it happens. Staff here watch many screens and pick which camera goes on air. The director calls the shots, and an operator switches between cameras and clips. It is the control center of a live broadcast.", "purpose_function": "It exists to bring every video source, graphic, and cue into one place so a team can direct, switch, and assemble a live or recorded programme in real time.", "practical_application": "A technician in the PCR routes camera and playback sources to the switcher, builds graphics and effects, and follows the director's cues to cut the live show, coordinating with the sound control room over intercom.", "category": "Broadcast Facility", "related_terms": ["Sound control room", "Playout room", "Vision mixer", "Master control", "Intercom", "Remote-production hub"], "common_mistakes": ["Confusing the production control room with master control; the PCR builds the show, while master control transmits it", "Assuming the PCR handles the audio mix; the sound is usually mixed in a separate audio or sound control room", "Overlooking clear intercom communication, which is essential for cueing a live show"], "scenario_contexts": ["Directing a multi-camera live news broadcast", "Cutting between cameras and replays during a live sports show", "Switching a video podcast or webcast that uses several camera angles"]}, "6d55ce02-8de4-4d8b-8457-f3bde0f23aa4": {"definition": "A remote-integration facility is a central production site used in the remote-integration (REMI) model, where camera, audio, and data feeds from a distant venue are carried back over IP or dedicated links and the programme is switched, mixed, and produced by staff who do not travel to the event. It concentrates the switcher, audio, graphics, and production crew in one permanent location that can serve many remote sites.", "plain_english": "A remote-integration facility is a home base that produces live events happening far away. Cameras and microphones at the venue send their signals back over a network. The crew then switches and mixes the show from this central building. This saves sending a big truck and full team to every event.", "purpose_function": "It exists to let one fixed, well-equipped facility produce events at many distant venues, cutting the cost and logistics of sending full crews and mobile units to each site.", "practical_application": "A technician at the facility receives the venue feeds, confirms signal timing and sync, and works the switcher or audio mix locally while staying in contact with a small on-site crew handling cameras and connections.", "category": "Broadcast Facility", "related_terms": ["Remote-production hub", "Production control room", "Sound control room", "SMPTE ST 2110", "Master control", "Latency"], "common_mistakes": ["Underestimating network latency and jitter, which can break lip-sync and cueing between the venue and the facility", "Assuming no on-site crew is needed; local staff still set up and troubleshoot at the venue", "Overlooking backup connectivity, since a single link failure can take the whole show off air"], "scenario_contexts": ["Producing a regional sports game from a central facility without sending a production truck", "Mixing audio for a distant concert while cameras are operated on site", "Switching several venues' feeds through one facility across the same day"]}, "11be7f99-d075-4ba3-a2e7-590bd9e2630c": {"definition": "A remote-production hub is the centralized location in a remote (REMI) or distributed production workflow where signals from one or more remote venues are aggregated, and where switching, audio mixing, graphics, and production decisions are made. It acts as the nerve center that links on-site capture with a production team working elsewhere.", "plain_english": "A remote-production hub is the central spot that runs live shows filmed somewhere else. Signals from the event travel over a network to this hub. Here the team switches cameras, mixes sound, and adds graphics. It links the people at the venue with the crew making the show.", "purpose_function": "It exists to gather feeds from remote sites into one place so a central team can produce multiple events efficiently without traveling to each location.", "practical_application": "A technician at the hub monitors incoming venue feeds, manages routing and sync, and supports the switching and audio teams, coordinating with on-site operators by intercom or messaging.", "category": "Broadcast Facility", "related_terms": ["Remote-integration facility", "Production control room", "Sound control room", "SMPTE ST 2110", "Latency", "Master control"], "common_mistakes": ["Treating the hub as identical to a traditional control room; it must also manage long-distance links, latency, and remote sync", "Ignoring redundancy on the connections between the venue and the hub", "Assuming bandwidth alone guarantees quality, while latency and packet loss still matter"], "scenario_contexts": ["Centralizing production of several live streams from different cities in one facility", "Running a live sports broadcast from a hub while cameras stay at the stadium", "Coordinating a remote video podcast with guests and cameras in separate locations"]}, "5e7b3ecd-ecf2-451a-a9f9-704f2ee6608b": {"definition": "Self-supervised learning (audio) is a machine-learning approach in which a model learns useful audio or speech representations from large amounts of unlabeled sound by solving pretext tasks it generates from the data itself, such as predicting masked or future portions of the signal. The pretrained model is then fine-tuned on much smaller labeled datasets for tasks like speech recognition or speaker identification.", "plain_english": "Self-supervised learning lets a computer learn from audio that no one has labeled. The model hides part of a sound clip, then trains itself to guess the missing part. Doing this over huge amounts of speech teaches it the patterns of audio. Later, only a little labeled data is needed to fine-tune it for a real job, like writing out speech.", "purpose_function": "It exists to cut the need for large hand-labeled datasets, letting models learn strong general audio representations from cheap, plentiful unlabeled recordings before being adapted to specific tasks.", "practical_application": "In podcast and speech tools, self-supervised models such as wav2vec 2.0 or HuBERT power transcription, speaker recognition, and audio search after being fine-tuned on a small labeled set for the target task.", "category": "Audio AI", "related_terms": ["Speech-to-text", "Speaker diarization", "Machine learning", "Transfer learning", "Neural network", "Automatic speech recognition"], "common_mistakes": ["Confusing self-supervised with unsupervised learning; here the training signal is created automatically from the data itself", "Assuming a pretrained model works well with no fine-tuning or adaptation to the target task", "Expecting good results on audio very different from the pretraining data, such as noisy or non-speech sound"], "scenario_contexts": ["Pretraining a speech model on thousands of unlabeled podcast hours before fine-tuning it to transcribe episodes", "Building a speaker-recognition feature with only a small labeled dataset", "Improving transcription accuracy for accents by adapting a pretrained model"]}, "8c14b25d-80e1-4dff-9aba-f5d5954ceff6": {"definition": "A sound control room, also called an audio control room (ACR), is the room in a television or live-production facility, separate from the production/vision control room, where a programme's audio is mixed and monitored. It houses the audio mixing console, monitoring loudspeakers, and processing, and is where the audio engineer (A1) balances microphones, playback, and other sources to loudness standards.", "plain_english": "A sound control room is the room where a show's audio is mixed. It sits apart from the room that handles the video. Inside are a mixing desk, speakers, and an engineer who balances all the microphones and sound sources. Its job is to make sure the sound going out is clear and at the right level.", "purpose_function": "It exists to give the audio engineer a quiet, acoustically controlled space to mix and monitor a programme's sound separately from the busy video control room.", "practical_application": "The A1 engineer in the sound control room sets microphone levels, mixes sources live, and monitors loudness on meters to meet standards such as EBU R 128, coordinating with the director in the production control room.", "category": "Broadcast Facility", "related_terms": ["Production control room", "Playout room", "Mixing console", "Loudness (LUFS)", "EBU R 128", "Monitoring"], "common_mistakes": ["Confusing the sound control room with the production control room; audio and video are usually controlled in separate rooms", "Mixing in a room with poor acoustics or the wrong monitor level, which gives an inaccurate picture of the sound", "Ignoring loudness standards, leading to programmes that are too loud or too quiet on air"], "scenario_contexts": ["Mixing microphones and playback for a live TV broadcast", "Balancing commentary, crowd, and effects for a live sports show", "Metering a programme to EBU R 128 loudness before it airs"]}, "28ce6451-8917-4264-9f7f-c9c84b10ed63": {"definition": "Speaker diarization is the process of partitioning an audio recording into segments according to who is speaking, answering the question 'who spoke when' without necessarily knowing the speakers' identities. It typically combines speech detection, segmentation, and clustering of voice features so each segment is labeled with a distinct speaker.", "plain_english": "Speaker diarization figures out who is talking and when in a recording. It splits the audio into pieces and groups together the parts spoken by the same voice. It does not need to know people's names; it just labels them as Speaker 1, Speaker 2, and so on. This is how a transcript can show who said each line.", "purpose_function": "It exists to add speaker structure to audio, so transcripts and analytics can attribute each spoken segment to the right person even when the identities are unknown.", "practical_application": "In podcast production, diarization is run alongside transcription so the finished transcript separates each host and guest, making editing, show notes, and captions easier.", "category": "Audio AI", "related_terms": ["Speech-to-text", "Self-supervised learning (audio)", "Automatic speech recognition", "Voice activity detection", "Speaker recognition", "Transcription"], "common_mistakes": ["Confusing diarization (who spoke when) with speaker recognition (identifying a specific known person)", "Expecting accurate results on heavily overlapping speech, which remains hard for diarization", "Assuming diarization transcribes words; it only segments speakers and is usually paired with a separate transcription step"], "scenario_contexts": ["Labeling each speaker in a multi-guest podcast transcript", "Separating talkers in a recorded meeting for minutes and search", "Preparing captions that show who is speaking in an interview"]}, "2598a00d-5db9-4699-a5be-0f7e621f659a": {"definition": "Speech-to-text (STT), also known as automatic speech recognition (ASR), is the technology that converts spoken audio into written text. Modern systems use trained neural-network models to map the acoustic features of speech to words, often combined with a language model to improve accuracy on natural phrasing.", "plain_english": "Speech-to-text turns spoken words into written text. Software listens to the audio and writes down what it hears. It is the tech behind voice typing, captions, and podcast transcripts. Modern systems use trained models that have heard huge amounts of speech, so they can handle many voices and accents.", "purpose_function": "It exists to make spoken content available as text, enabling transcripts, captions, search, and voice control from audio input.", "practical_application": "Podcast producers run episodes through speech-to-text to create transcripts, captions, and show notes, then correct names and terms the model misheard before publishing.", "category": "Audio AI", "related_terms": ["Speaker diarization", "Self-supervised learning (audio)", "Automatic speech recognition", "Transcription", "Language model", "Captioning"], "common_mistakes": ["Assuming transcripts are perfect; STT still errs on names, jargon, accents, and crosstalk and needs proofreading", "Feeding in noisy or overlapping audio and expecting clean text", "Confusing speech-to-text (audio to text) with text-to-speech (text to audio), which is the reverse"], "scenario_contexts": ["Generating a rough transcript of a podcast episode for editing and show notes", "Creating captions or subtitles for a video version of a show", "Making an episode searchable by indexing its transcribed text"]}, "f95145e5-2bde-4f7e-8ee9-fee577068e03": {"definition": "The clean, controlled, professionally polished audio quality characteristic of a purpose-built recording space: low background noise, minimal room reflections, and an even tonal balance, so a voice or instrument sounds close, clear, and free of distracting artifacts.", "plain_english": "Studio sound is the clean, clear audio you get in a proper recording room. There is very little background noise or echo, so voices sound close and easy to hear. It is the opposite of a voice recorded on a phone in a kitchen.", "purpose_function": "It defines the quality target a podcast producer aims for, marking a recording as low-noise, low-echo, and tonally balanced so listeners hear speech clearly and comfortably.", "practical_application": "A technician reaches studio sound by treating the room, choosing a suitable microphone and placement, setting gain correctly, and keeping background noise low during the take.", "category": "Sound Quality", "related_terms": ["Voice-over booth", "Acoustic treatment", "Signal-to-noise ratio", "Reverberation", "Proximity effect"], "common_mistakes": ["Believing an expensive microphone alone produces studio sound while ignoring room acoustics", "Recording too far from the mic, which adds room tone and echo", "Trying to fix a poor-sounding room with heavy processing instead of treating it", "Confusing loudness with clean, balanced sound"], "scenario_contexts": ["Recording a podcast episode intended to sound professional", "Comparing a home recording with a treated-studio recording", "A client asking for broadcast-quality voice"]}, "8acd7d97-466b-49a1-b141-cb33f13a4c8e": {"definition": "A dedicated waiting space, often called a green room, where hosts, guests, and other on-air talent stay before, between, and after their time on microphone or camera, kept separate from the active recording space.", "plain_english": "This is a waiting room for guests and hosts before they go on. It is often called the green room. People relax there until it is their turn to record.", "purpose_function": "It keeps talent comfortable, prepared, and out of the recording space so their noise and movement do not disturb an active session.", "practical_application": "A producer stages the next guest in the holding area, then brings them into the studio when the previous segment wraps.", "category": "Studio Facility", "related_terms": ["Talk-show studio", "Video podcast studio", "Voice-over booth", "Technical operations center"], "common_mistakes": ["Placing the holding area so close to the studio that talk bleeds into the recording", "Not asking talent to silence phones and devices there", "Forgetting to brief or mic-check guests while they wait"], "scenario_contexts": ["A multi-guest talk show with staggered arrivals", "Back-to-back interview scheduling", "A live event with rotating guests"]}, "3b48a813-3870-4d7c-9b93-4d043dacb165": {"definition": "A studio configured for conversational, multi-participant programming, with a host and one or more guests seated together, each on a dedicated microphone, often supported by cameras, mix-minus feeds, and space for crew or a small audience.", "plain_english": "This is a studio built for talk shows. A host and guests sit together, each with their own microphone. It is set up so several people can talk and still be recorded clearly.", "purpose_function": "It supports interview and panel formats by giving each speaker a dedicated microphone and a layout that lets people see and hear each other while staying separate on the recording.", "practical_application": "An engineer sets up a talk-show studio with individual mics on each chair, a small mixer, headphone feeds, and often return audio for remote guests.", "category": "Studio Facility", "related_terms": ["Video podcast studio", "Voice-over booth", "Talent holding area", "Technical operations center", "Studio Sound"], "common_mistakes": ["Using one shared microphone for several people instead of one mic each", "Not providing headphones so guests can hear remote callers", "Ignoring crosstalk and bleed between open mics", "Forgetting mix-minus for phone or remote guests, causing echo"], "scenario_contexts": ["Recording a panel discussion", "An interview podcast with an in-studio guest", "A live-audience talk format"]}, "22b75519-8baa-4161-9fc6-1324b2fc82be": {"definition": "A centralized room or area where technical staff monitor, route, and control the signals and infrastructure of a broadcast or production facility, including feeds, distribution, recording, and equipment health, from a single coordinated point.", "plain_english": "This is the control hub of a large studio or broadcast site. Staff there watch and manage all the audio and video signals from one place. Think of it as mission control for the technical gear.", "purpose_function": "It centralizes signal routing, monitoring, and fault response so many studios and feeds can be run and troubleshot from one location.", "practical_application": "In a large podcast network or broadcast plant, a technician in the operations center routes studio feeds to recorders or streams and responds to alarms and signal loss.", "category": "Studio Facility", "related_terms": ["Talk-show studio", "Video podcast studio", "Talent holding area", "Studio Sound"], "common_mistakes": ["Confusing the operations center with a single studio's control room", "Assuming a small solo podcast setup needs one", "Failing to document signal routing so faults are hard to trace"], "scenario_contexts": ["A multi-studio podcast network", "A live broadcast plant", "A large event with many simultaneous feeds"]}, "9c2e2dda-0841-452c-974e-046d0380ecb7": {"definition": "A technology that converts written text into synthesized spoken audio, using software to generate a voice that reads the text aloud.", "plain_english": "Text-to-speech turns written words into a spoken voice. You type or paste text, and the computer reads it out loud. Screen readers and voice assistants use it.", "purpose_function": "It lets producers create spoken audio without a live recording, which is useful for automated narration, accessibility, and placeholder voice tracks.", "practical_application": "A podcaster may use text-to-speech for a machine-voice segment, an accessibility read-out, or a scratch narration used to time an edit before the real voice is recorded.", "category": "Speech Technology", "related_terms": ["TTS", "Voice activity detection", "Voice-over booth", "Studio Sound"], "common_mistakes": ["Expecting a synthetic voice to match human timing and emotion", "Not disclosing to listeners that a voice is AI-generated", "Letting it mispronounce names or acronyms without correction"], "scenario_contexts": ["Accessibility narration of written content", "Automated read-out of show notes", "A placeholder scratch track before the final voice recording"]}, "065ef9df-f5e3-4b96-8492-1c3631baad8d": {"definition": "The common abbreviation for text-to-speech: a technology that converts written text into synthesized spoken audio using software that reads the text aloud in a generated voice.", "plain_english": "TTS is short for text-to-speech. It turns typed words into a spoken voice read aloud by a computer. Voice assistants and screen readers rely on it.", "purpose_function": "It lets producers create spoken audio without a live recording, which is useful for automated narration, accessibility, and placeholder voice tracks.", "practical_application": "A podcaster may use TTS for a machine-voice segment, an accessibility read-out, or a scratch narration used to time an edit before the real voice is recorded.", "category": "Speech Technology", "related_terms": ["Text-to-speech (TTS)", "Voice activity detection", "Voice-over booth", "Studio Sound"], "common_mistakes": ["Expecting a synthetic voice to match human timing and emotion", "Not disclosing to listeners that a voice is AI-generated", "Letting it mispronounce names or acronyms without correction"], "scenario_contexts": ["Accessibility narration of written content", "Automated read-out of show notes", "A placeholder scratch track before the final voice recording"]}, "4516286a-cd7d-42a1-9633-f44afa165a6f": {"definition": "A studio equipped to capture synchronized high-quality audio and video for podcasts, combining broadcast-style microphones, cameras, lighting, and monitoring so an episode can be released as both an audio and a video program.", "plain_english": "This is a studio set up to record a podcast with both sound and video. It has good microphones, cameras, and lighting. The result can be posted as a video and as an audio-only show.", "purpose_function": "It lets creators produce audio and video versions of a show in one session, meeting demand for video podcasts while keeping broadcast-grade sound.", "practical_application": "An engineer arranges cameras, lighting, per-person microphones, and a recorder or switcher, and keeps audio and video in sync for later editing.", "category": "Studio Facility", "related_terms": ["Talk-show studio", "Voice-over booth", "Talent holding area", "Technical operations center", "Studio Sound"], "common_mistakes": ["Prioritizing the video and neglecting audio quality", "Not slating or syncing audio and video, making edits hard to line up", "Using poor lighting that undercuts an otherwise good shoot", "Forgetting a dedicated microphone for each person"], "scenario_contexts": ["A video podcast released on a streaming platform", "A multi-camera interview shoot", "A live-streamed simulcast of a show"]}, "d9e877e1-2d79-4061-9779-ca92be3db9b2": {"definition": "A signal-processing technique that automatically determines whether human speech is present in an audio stream at a given moment, distinguishing speech from silence or background noise.", "plain_english": "Voice activity detection is software that senses when someone is actually talking. It tells speech apart from silence or background noise. Apps use it to know when to start and stop.", "purpose_function": "It lets systems act only when speech is present, which saves bandwidth, triggers recording or gating, and improves later processing such as transcription and noise reduction.", "practical_application": "In remote recording and conferencing tools, it gates microphones, powers auto-mute, and helps editors automatically find and trim silent gaps.", "category": "Speech Technology", "related_terms": ["Text-to-speech (TTS)", "Automatic speech recognition (ASR)", "Noise gate", "Studio Sound"], "common_mistakes": ["Assuming detection stays accurate in a noisy room", "Confusing it with a simple noise gate", "Setting thresholds so tight that the start of words gets clipped"], "scenario_contexts": ["Auto-mute on a remote interview platform", "Automatic silence trimming during editing", "Voice-triggered start and stop of recording"]}, "182810fd-1048-46a5-bbe0-2094d5c52f58": {"definition": "A small, acoustically isolated and treated enclosure designed for recording spoken voice such as voice-overs, narration, and podcast vocals, minimizing outside noise and internal reflections to capture a clean, dry voice.", "plain_english": "A voice-over booth is a small, quiet room built for recording talking. Its walls block outside noise and soak up echo. That gives a clean, close voice with no room sound.", "purpose_function": "It isolates the voice from outside noise and controls reflections so recordings are clean, consistent, and easy to edit or process.", "practical_application": "A narrator works at a microphone inside the booth with headphones while recording, capturing minimal room tone and outside noise.", "category": "Studio Facility", "related_terms": ["Studio Sound", "Talk-show studio", "Acoustic treatment", "Proximity effect", "Video podcast studio"], "common_mistakes": ["Over-deadening the booth so the voice sounds boxy and unnatural", "Poor ventilation that adds fan noise or makes long sessions uncomfortable", "Standing too far from the microphone and picking up room tone", "Ignoring HVAC or computer-fan noise leaking into the take"], "scenario_contexts": ["Recording narration or a commercial voice-over", "A solo podcast host recording alone", "Recording dialogue pickups or re-records"]}, "258107ff-32f7-4d29-a7b2-91aa63081765": {"definition": "wav2vec is a self-supervised speech representation framework from Facebook AI Research (Meta AI) that learns useful acoustic features directly from large amounts of unlabeled audio, which are then fine-tuned for tasks such as automatic speech recognition. Its successor, wav2vec 2.0, masks parts of the raw audio and learns to predict them, producing strong recognition accuracy with far less transcribed training data.", "plain_english": "wav2vec is a computer model that learns the sounds of speech by listening to huge amounts of audio on its own, without needing text labels first. This is like a child learning to hear words before anyone teaches them to read. After that, it needs only a little labeled speech to turn talking into text well.", "purpose_function": "It exists to learn speech features from cheap, plentiful unlabeled audio so that accurate speech-to-text can be built without needing enormous hand-transcribed datasets. This lowers the cost of building recognition for languages and accents that have little labeled data.", "practical_application": "A podcast technician meets wav2vec inside transcription and captioning tools, where it powers the model that converts recorded speech into editable text, and it is also used as the alignment engine that snaps words to precise times.", "category": "Speech AI Model", "related_terms": ["Whisper", "Automatic speech recognition", "Word-level timestamps", "WhisperX", "Transcription", "Forced alignment"], "common_mistakes": ["Thinking wav2vec produces text by itself; the base model only learns audio features and must be fine-tuned or paired with a decoder to output words", "Assuming it works equally well in noisy or musical podcast beds; recognition accuracy still drops with heavy background noise", "Confusing the original wav2vec with wav2vec 2.0, which uses a different masked, transformer-based approach", "Expecting perfect results on strong accents or specialist jargon without any fine-tuning"], "scenario_contexts": ["Generating a rough transcript of an interview episode for editing and show notes", "Providing the phoneme alignment that gives a caption file accurate per-word timing", "Building speech recognition for a language that has very little transcribed audio available"]}, "d4d27f39-cf25-4478-bf77-f394b7ac4920": {"definition": "WaveGlow is a flow-based generative neural network from NVIDIA that synthesizes speech audio waveforms from mel-spectrograms in a single, non-autoregressive pass. By combining ideas from Glow and WaveNet, it generates high-quality audio quickly without needing sample-by-sample recursion.", "plain_english": "WaveGlow is a computer model that turns a picture of sound, called a spectrogram, into an actual audio waveform you can hear. It is a vocoder, the part of a text-to-speech system that makes the final voice. Because it builds the whole sound at once instead of one tiny piece at a time, it is fast.", "purpose_function": "It exists to act as a vocoder, converting the spectrogram output of a text-to-speech system into a natural-sounding waveform, and it was designed to do this fast enough for practical use. This solves the slow, one-sample-at-a-time bottleneck of earlier waveform models.", "practical_application": "A podcast producer encounters WaveGlow inside text-to-speech pipelines that generate synthetic narration or voice segments, where it is paired with a spectrogram model such as Tacotron 2 to produce the finished voice audio.", "category": "Speech AI Model", "related_terms": ["WaveNet", "WaveRNN", "Text-to-speech", "Vocoder", "Mel-spectrogram", "Speech synthesis"], "common_mistakes": ["Thinking WaveGlow generates speech from text; it only turns a spectrogram into audio and needs a separate model to create that spectrogram first", "Assuming it runs well on any computer; high-quality real-time use generally needs a capable GPU", "Confusing the vocoder stage with the overall voice; the naturalness of the words and rhythm comes from the earlier acoustic model", "Expecting it to clean up or improve a bad input spectrogram"], "scenario_contexts": ["Rendering a synthetic host or narrator voice for an automated podcast segment", "Serving as the vocoder stage after a Tacotron 2 acoustic model in a text-to-speech system", "Producing voiceover audio for dynamically inserted ad reads or announcements"]}, "82467af6-4abf-4dc1-bbe5-b30f5e84cc78": {"definition": "WaveNet is a deep autoregressive generative model of raw audio waveforms, introduced by DeepMind, that predicts each audio sample conditioned on all previous samples using stacked dilated causal convolutions. It set a new quality benchmark for text-to-speech and can also model music and other audio.", "plain_english": "WaveNet is a computer model that creates realistic speech by building the sound one tiny slice at a time, guessing each slice from the slices before it. This is like drawing a wave dot by dot until it looks smooth and natural. It made computer voices sound much more human than older methods.", "purpose_function": "It exists to generate very natural-sounding synthetic speech and audio by modeling the raw waveform directly rather than stitching together pre-recorded pieces. This produces smoother, more human voices for applications like text-to-speech assistants.", "practical_application": "A podcast producer meets WaveNet-based voices in cloud text-to-speech services used to generate narration, and understands it as the technology that raised the quality bar for synthetic speech, though its original form was slow to generate.", "category": "Speech AI Model", "related_terms": ["WaveRNN", "WaveGlow", "Text-to-speech", "Vocoder", "Speech synthesis", "Autoregressive model"], "common_mistakes": ["Assuming the original WaveNet is fast; sample-by-sample generation made it slow, which later models were built to fix", "Thinking it works from text alone; it is conditioned on features such as a spectrogram or linguistic input from another model", "Confusing WaveNet the waveform model with the complete text-to-speech system it sits inside", "Believing every modern synthetic voice is WaveNet; many services now use faster successor models"], "scenario_contexts": ["Generating natural narration through a cloud text-to-speech voice for an episode intro", "Explaining why modern synthetic podcast voices sound far more natural than older ones", "Serving as the vocoder that turns acoustic features into a finished speech waveform"]}, "a91d9d8d-7765-4971-accc-a00ac0143124": {"definition": "WaveRNN is an efficient neural vocoder from DeepMind that uses a compact single-layer recurrent neural network to generate audio waveforms from acoustic features. It was designed to match the quality of large autoregressive models like WaveNet while being much faster and light enough to run in real time, including on limited hardware.", "plain_english": "WaveRNN is a computer model that turns sound features into a finished audio waveform, built to be small and fast. It is a vocoder, the part that makes the final voice you hear. Its whole point is to sound good while running quickly, even on modest devices.", "purpose_function": "It exists to generate high-quality speech waveforms with far less computing power than earlier models, making real-time synthetic speech practical on phones and other limited hardware. This addresses the speed problem of sample-by-sample audio generation.", "practical_application": "A podcast technician encounters WaveRNN as the efficient vocoder inside text-to-speech tools where speed matters, converting a spectrogram into the final spoken audio for narration or automated voice segments.", "category": "Speech AI Model", "related_terms": ["WaveNet", "WaveGlow", "Text-to-speech", "Vocoder", "Speech synthesis", "Mel-spectrogram"], "common_mistakes": ["Thinking WaveRNN creates speech from text; it only converts acoustic features into audio and needs an earlier model to supply them", "Assuming faster means lower quality; WaveRNN was designed to keep quality high while cutting compute cost", "Confusing the vocoder with the full text-to-speech pipeline it belongs to", "Expecting it to fix errors in the input features rather than faithfully rendering them"], "scenario_contexts": ["Rendering synthetic voice audio in a tool that must run quickly or on modest hardware", "Acting as the vocoder stage after an acoustic model in a text-to-speech system", "Producing real-time or on-device narration for automated podcast content"]}, "c08897f5-3e54-480a-9784-7e2897a3e0e5": {"definition": "A webcast studio is a room or facility equipped to produce and stream live audio or video content over the internet to an online audience. It typically combines microphones, cameras, a mixer or production switcher, lighting, and an encoder that sends the program feed to a streaming platform.", "plain_english": "A webcast studio is a room set up to broadcast live over the internet. It has the microphones, cameras, mixers, and encoding gear needed to send a live show to viewers online. Think of it as a small TV or radio station built for streaming instead of the airwaves.", "purpose_function": "It exists to give creators a controlled space with the right gear to deliver reliable, good-quality live streams to an online audience. Centralizing the equipment and signal flow makes live production repeatable and less prone to failure.", "practical_application": "A podcast team uses a webcast studio to record or livestream episodes with guests, routing microphones and cameras through a mixer and encoder so the show reaches platforms like YouTube or a streaming service in real time.", "category": "Production Facility", "related_terms": ["Encoder", "Live streaming", "Audio mixer", "Podcast studio", "Broadcast", "Remote recording"], "common_mistakes": ["Under-provisioning internet upload bandwidth, causing dropped or buffering live streams", "Ignoring room acoustics and treating only the picture, which leaves the audio echoey or noisy", "Forgetting to monitor the actual outgoing stream, so problems go unnoticed until viewers complain", "UNSAFE: Overloading power circuits or running trip-hazard cabling for lights and gear instead of following safe electrical and cable-management practice"], "scenario_contexts": ["Livestreaming a podcast episode with in-studio guests to an online audience", "Producing a live Q&A or event broadcast that mixes several microphones and cameras", "Recording a video podcast for later editing while also streaming it live"]}, "00e1cdea-a5d1-4393-bd54-f587ed49345c": {"definition": "Whisper is an open-source automatic speech recognition model from OpenAI, trained on a very large and diverse set of multilingual audio to transcribe speech and translate it into English. Built as an encoder-decoder Transformer, it is known for robust performance across accents, background noise, and technical language.", "plain_english": "Whisper is a free computer model from OpenAI. It listens to speech and turns it into text. It learned from a huge, mixed set of audio. So it handles many languages, accents, and noisy recordings well. It can also turn other spoken languages into English text.", "purpose_function": "It exists to provide accurate, general-purpose speech-to-text and speech translation that works across many languages and difficult audio conditions without task-specific tuning. Its broad training makes it reliable on real-world, messy recordings.", "practical_application": "A podcast producer runs episode audio through Whisper to auto-generate transcripts, captions, and searchable show notes, often as the first step before editing or publishing.", "category": "Speech AI Model", "related_terms": ["WhisperX", "wav2vec", "Automatic speech recognition", "Transcription", "Word-level timestamps", "Speaker diarization"], "common_mistakes": ["Trusting the transcript blindly; Whisper can invent plausible-sounding text, called hallucination, especially during silence or music", "Expecting precise per-word timing from base Whisper, whose native timestamps are only approximate", "Assuming it separates or labels who is speaking; diarization needs additional tooling", "Choosing a small model for accuracy-critical work when a larger model would transcribe far better"], "scenario_contexts": ["Auto-transcribing a recorded interview to produce an editable script and show notes", "Generating caption or subtitle text for a video version of an episode", "Translating a foreign-language guest segment into English text for reference"]}, "26d949da-329a-4fb1-bac3-5a84ce2ab26d": {"definition": "WhisperX is an open-source system that extends OpenAI's Whisper to provide fast, accurate word-level timestamps for long-form audio. It adds voice-activity detection, batched inference, and a forced-alignment step using a phoneme model to correct Whisper's imprecise timing.", "plain_english": "WhisperX is a tool that improves OpenAI's Whisper by pinning down exactly when each word is spoken. Plain Whisper gives rough timing, so WhisperX lines the words up to the audio much more precisely. It also runs faster on long recordings and can help mark who is speaking.", "purpose_function": "It exists to fix Whisper's weak timing and speed on long files, delivering reliable per-word timestamps needed for captions, subtitles, and precise editing. The alignment step matches each transcribed word to its true position in the audio.", "practical_application": "A podcast editor uses WhisperX to get accurate word timings so captions sync tightly to speech and so text-based editing tools can cut audio at exact word boundaries.", "category": "Speech AI Model", "related_terms": ["Whisper", "wav2vec", "Word-level timestamps", "Forced alignment", "Speaker diarization", "Transcription"], "common_mistakes": ["Thinking WhisperX replaces Whisper; it builds on Whisper's transcript and adds alignment and timing on top", "Assuming alignment fixes wrong words; it improves timing but does not correct recognition errors in the text", "Expecting speaker labels automatically; diarization is a separate optional step that needs its own model", "Overlooking that alignment quality still depends on clean audio and correct language selection"], "scenario_contexts": ["Producing tightly synced captions or subtitles for a video podcast", "Enabling text-based editing where cutting a word also cuts the audio at the right point", "Preparing a transcript with precise timings for interactive show-note navigation"]}, "056431cc-7001-4f9c-8b79-5f9bafae8cf7": {"definition": "Word-level timestamps are metadata that pair each transcribed word with its start and end time in the source audio. They let software align text precisely to the recording, unlike coarser segment- or line-level timing.", "plain_english": "Word-level timestamps tell you exactly when each single word is spoken in a recording, marking the start and end time of every word. It is like giving every word its own moment on the clock. This lets captions and editing tools line up perfectly with the audio.", "purpose_function": "They exist to link written text tightly to the audio so tools can highlight, search, caption, or cut speech at the exact word. This precise timing is what makes karaoke-style captions and text-based audio editing possible.", "practical_application": "A podcast editor relies on word-level timestamps so that deleting a word in the transcript removes the matching audio, and so captions highlight each word as it is spoken.", "category": "Transcription Metadata", "related_terms": ["WhisperX", "Whisper", "Forced alignment", "Transcription", "Subtitles", "Speaker diarization"], "common_mistakes": ["Confusing word-level timing with segment-level timing, which only marks whole phrases or lines rather than each word", "Assuming every transcription tool provides accurate word timing; base models often give only approximate marks", "Trusting timestamps on noisy or overlapping speech, where alignment can drift or fail", "Forgetting that wrong words still get timestamps, so bad text yields precisely timed but incorrect captions"], "scenario_contexts": ["Creating word-by-word highlighted captions that follow the speaker in real time", "Powering text-based editing so cutting text also trims the matching audio", "Letting listeners jump to the exact spot where a searched word is spoken"]}, "a60b6710-c88c-43bc-9395-9f6e28bae877": {"definition": "A monitoring feed or dedicated receiver that reproduces a station's actual off-air signal, letting staff hear the program exactly as the audience does, after all processing, encoding, and transmission delay.", "plain_english": "A speaker or radio that plays back what the station is really sending out. It lets the crew hear just what people at home hear, after all the gear has done its job.", "purpose_function": "It confirms the station is on the air and that the signal still sounds right after processing and transmission, catching dead air, distortion, or the wrong content.", "practical_application": "An engineer or host keeps the air monitor up to verify the broadcast and to spot faults before listeners call in to complain.", "category": "Monitoring", "related_terms": ["Air chain", "Modulation monitor", "Broadcast delay", "Audio control room", "Air-check recording"], "common_mistakes": ["Assuming the console output matches the air signal, ignoring processing and transmission delay", "Confusing the air monitor with the console monitor feed", "Turning the air monitor off during a shift and missing dead air or an outage"], "scenario_contexts": ["An engineer verifying the transmitter is passing clean audio", "A host checking that a recorded spot actually aired", "Troubleshooting distortion heard by listeners but not on the console"]}, "87ce8af6-c37e-493f-a0fb-a347cbeb399d": {"definition": "The microphone used by on-air talent (announcer, host, or DJ) to deliver spoken program audio; in radio it is typically a large-diaphragm cardioid dynamic mic chosen for a warm, present voice and strong rejection of room noise.", "plain_english": "The mic the on-air host talks into. It is usually a tough dynamic mic that makes the voice sound full and blocks out room noise.", "purpose_function": "It captures the presenter's voice at broadcast quality while rejecting background noise and handling close, loud speech without popping or distortion.", "practical_application": "Engineers mount it on a shock-mounted boom arm with a pop filter, set it a few inches from the mouth, and route it through a mic processor before the console.", "category": "Microphones", "related_terms": ["Announcer booth", "Announcer feed", "Audio control room", "Air monitor", "Air-check recording"], "common_mistakes": ["Working too far from the mic, which raises room noise and lowers voice level", "Skipping the pop filter, so plosives cause loud popping", "Setting gain too high and clipping loud speech", "Treating a rugged dynamic mic like a fragile condenser and vice versa"], "scenario_contexts": ["A morning-show host speaking live on a music station", "A sportscaster calling play-by-play from a booth", "Voice-tracking pre-recorded segments for later airing", "A news reader delivering a live top-of-hour bulletin"]}, "e4ca64dc-f7a3-4a72-9320-1b5e8f7f01ea": {"definition": "A recording of a station's actual broadcast output, captured for later review, talent critique, compliance logging, or as a demo of on-air work.", "plain_english": "A recording of what a station actually put on the air. People use it to review how a show sounded or to prove what was broadcast.", "purpose_function": "It documents exactly what went out over the air so managers can coach talent, confirm content ran, and meet legal logging rules.", "practical_application": "A host saves an aircheck of their shift to build a demo, while engineers keep automated airchecks to settle complaints and provide regulatory proof.", "category": "Recording", "related_terms": ["Aircheck recorder", "Air monitor", "Air talent microphone", "Audio control room", "Off-air signal"], "common_mistakes": ["Recording the console feed instead of the true off-air signal, missing processing changes", "Not logging continuously and losing proof of what aired", "Confusing an edited demo aircheck with an unedited compliance log"], "scenario_contexts": ["A DJ compiling a demo reel from recent shows", "Reviewing a broadcast after a listener complaint", "Keeping a legal log of everything transmitted"]}, "38390a37-3383-4928-ab8f-6f843b2f08f1": {"definition": "A device or software system that automatically records a station's on-air signal, often as a continuous logging recorder or as a skimmer that captures only the mic-open talk segments.", "plain_english": "A machine or program that records what the station broadcasts, usually all day long. Some versions only save the parts where the host is talking.", "purpose_function": "It provides an automatic archive of the broadcast for legal logging, complaint resolution, and reviewing talent performance without anyone hitting record.", "practical_application": "Engineers feed it the off-air or console output; a skimmer mode triggered by the mic switch stores short talk breaks so a host can grab an aircheck quickly.", "category": "Recording", "related_terms": ["Air-check recording", "Air monitor", "Audio control room", "Off-air signal", "Air talent microphone"], "common_mistakes": ["Feeding it a pre-processing source, so the log does not match the true air signal", "Letting the storage fill and overwrite required legal logs", "Assuming skimmer mode captured everything when it only records mic-open segments"], "scenario_contexts": ["Maintaining a 24-hour legal log of the broadcast", "A host retrieving a talk-break aircheck for a demo", "Pulling archived audio after a compliance query"]}, "43b1ced3-4e67-40e1-8144-22614356ecda": {"definition": "A small, acoustically treated room built for a presenter to record or broadcast voice, isolated from control-room and studio noise so speech is captured cleanly.", "plain_english": "A small, sound-treated room where the announcer talks into the mic. It is quiet and isolated so the voice is recorded clearly.", "purpose_function": "It gives the announcer a quiet, low-reflection space so the microphone picks up a clean, dry voice free of room echo and outside noise.", "practical_application": "A technician sets up the talent mic, headphones, and a talkback link inside the booth, then treats the walls to cut reflections and seals the door for isolation.", "category": "Facilities", "related_terms": ["Air talent microphone", "Audio control room", "Announcer feed", "Air monitor", "Air-check recording"], "common_mistakes": ["Assuming any small room is dead enough without acoustic treatment", "Leaving noisy fans or computers inside the booth", "Poor door sealing that lets control-room sound leak into the mic"], "scenario_contexts": ["Recording station voice-overs and imaging", "A news anchor reading live from an isolated booth", "Tracking narration for a documentary or promo"]}, "10eee908-2ec7-43ce-8200-94083913ad0c": {"definition": "A dedicated audio feed carrying the on-air announcer's voice, routed separately from music and other program elements so it can be mixed, distributed, or sent to remote sites on its own.", "plain_english": "A separate audio path that carries just the announcer's voice. Keeping it on its own makes it easy to mix or send it where it is needed.", "purpose_function": "It isolates the announcer's voice as a discrete signal so it can be balanced against program audio, recorded alone, or delivered to another site or network.", "practical_application": "An engineer splits the talent mic to a dedicated bus, then routes that announcer feed to the console, a remote codec, or a separate recorder.", "category": "Signal Routing", "related_terms": ["Air talent microphone", "Announcer booth", "Audio control room", "Audio contribution codec", "Mix-minus"], "common_mistakes": ["Confusing the announcer feed with a full program mix that already includes music", "Sending a feed with the announcer's own return audio, causing echo instead of a clean mix-minus", "Not labeling routing, so the wrong source reaches a remote site"], "scenario_contexts": ["Feeding an announcer's voice to a remote sports venue", "Routing a clean voice track to a separate recorder", "Sending narration to another studio for a shared broadcast"]}, "e94d99bf-0f9d-4bae-b96c-c75edf3eb7df": {"definition": "A set of microphones arranged to capture audience sound, such as applause, laughter, and crowd ambience, during a broadcast or recorded event, then mixed in to convey atmosphere.", "plain_english": "A group of mics aimed at the crowd to pick up clapping, laughter, and general noise. The sound is mixed in so the show feels live.", "purpose_function": "It captures the room's reaction and ambience so the broadcast sounds live and energetic instead of dry, while keeping crowd noise controllable in the mix.", "practical_application": "A technician places several mics around the seating, balances their levels to avoid feedback and harshness, and rides the crowd level up during applause.", "category": "Microphones", "related_terms": ["Air talent microphone", "Audio control room", "Announcer feed", "Air monitor", "Audio contribution codec"], "common_mistakes": ["Placing mics where they pick up the PA and feed back", "Leaving crowd mics wide open, raising the noise floor between reactions", "Too few mics for the space, giving thin or uneven audience sound"], "scenario_contexts": ["Broadcasting a live comedy or game show", "Covering a sports event to capture crowd reaction", "A live concert broadcast that needs audience ambience"]}, "7e43d8ec-fb14-4257-84d4-40d01336906f": {"definition": "An audio codec, in hardware or software, that encodes and transports high-quality contribution audio, meaning program material sent from a remote site back to the studio or network, typically over IP, ISDN, or dedicated links with an emphasis on quality and low latency.", "plain_english": "A box or program that squeezes high-quality audio so it can travel from a remote spot back to the studio. It aims for great sound and little delay, not just small file size.", "purpose_function": "It carries program-grade audio between locations reliably and with low delay, so remote broadcasts sound as good as studio audio while using available network links.", "practical_application": "An engineer connects the codec at a remote venue over IP or ISDN, sets a codec algorithm and bit rate, and monitors latency and dropouts across the link.", "category": "Transmission", "related_terms": ["Announcer feed", "Audio control room", "Air monitor", "Mix-minus", "Air chain"], "common_mistakes": ["Confusing contribution links with lower-quality distribution codecs", "Choosing a low-latency setting without enough network headroom, causing dropouts", "Ignoring buffer and jitter settings, so audio glitches over IP"], "scenario_contexts": ["Sending a reporter's audio from the field to the studio", "Linking two studios for a shared program", "Backhauling a live remote concert to the broadcast center"]}, "c301e9fd-b476-49e5-893e-10c48461aa74": {"definition": "The room in a broadcast facility that houses the main mixing console and audio processing and routing gear, where an operator mixes and controls all program audio for a studio or on-air channel.", "plain_english": "The room with the main mixing desk where an operator controls all the sound for a show. It is where the audio for the broadcast is put together.", "purpose_function": "It centralizes mixing, monitoring, and routing so one operator can combine mics, playback, and remote feeds into the finished program audio.", "practical_application": "An engineer works the console here to balance talent mics, music, and remote sources, monitor the air signal, and send the mix on down the air chain.", "category": "Facilities", "related_terms": ["Announcer booth", "Air talent microphone", "Air monitor", "Announcer feed", "Air chain"], "common_mistakes": ["Confusing the audio control room with the on-air studio or talent booth", "Poor monitor calibration, so mixes sound wrong on the air", "Cluttered routing labels that cause the wrong source to go to air"], "scenario_contexts": ["Operating the console for a live radio show", "Mixing a live sports broadcast from the control room", "Routing and monitoring remote feeds during a special broadcast"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"2447208f-3798-438b-9187-65913ee8e567": {"definition": "A self-contained mobile facility, typically a van, truck, or trailer, fitted with mixing consoles, recorders, communications, and transmission links to capture and produce audio programming at a remote site away from the studio. It is the audio-focused member of a broadcaster's outside-broadcast (OB) fleet, used for sports, concerts, and live events.", "plain_english": "It is a truck or van packed with audio gear. A crew drives it to a game or concert. From inside, they mix the sound and send it back to the station.", "purpose_function": "It brings a full studio's worth of audio production and transmission capability to events that cannot come to the studio, letting a broadcaster originate live or recorded programming from the field.", "practical_application": "A radio engineer parks the vehicle at a stadium, patches microphone and stage feeds into its console, and sends the finished mix back to the station over an IP, ISDN, or satellite link.", "category": "Remote Broadcast", "related_terms": ["Broadcast audio console", "Broadcast audio matrix", "Backup program source", "Studio-transmitter link", "Audio codec"], "common_mistakes": ["Confusing an audio-only OB vehicle with a full television OB truck, which also carries video switching and camera systems", "Assuming the vehicle needs no independent power and grounding plan once parked on site", "UNSAFE: Powering the vehicle from an unverified venue mains outlet without checking grounding and bonding, risking shock and equipment damage"], "scenario_contexts": ["Broadcasting live match commentary from a stadium car park", "Producing a multi-day music festival radio show from the site", "Covering breaking news from a remote location where no studio exists"]}, "a5ea757c-6033-4ba5-b018-294e4d94b5e4": {"definition": "An operating mode of a radio broadcast automation (playout) system in which a live operator manually triggers and sequences programme elements, such as songs, jingles, adverts, and links, while the software handles file loading, logging, and playback. It sits between fully manual live operation and fully unattended automation, keeping a human in control of timing and content.", "plain_english": "The computer lines up the songs and ads for the show. But a person clicks to play each one. So the show feels live, with a human in charge of the timing.", "purpose_function": "It lets a presenter drive a live-sounding show while keeping the log accuracy and safety net of automation, so timing and content stay under human control and the system does the file handling.", "practical_application": "A daytime presenter runs the show in assist mode, hitting play-next after each song so links land naturally, then switches the system to full automation when leaving for the night.", "category": "Automation", "related_terms": ["Backup program source", "Broadcast audio console", "Broadcast alarm system", "Playout system", "Voice tracking"], "common_mistakes": ["Believing elements fire on time by themselves; in assist mode items only play when the operator triggers them, so inattention causes dead air", "Confusing live-assist with voice tracking, where links are pre-recorded rather than performed live", "Forgetting that the on-air log still records what actually played, so skipped adverts create reconciliation problems"], "scenario_contexts": ["A live morning show where the host controls timing around traffic and news", "Dropping a live sports result into an otherwise automated schedule", "Training a new presenter to drive the playout system before trusting full automation"]}, "e2ac95e0-80d5-4a39-9f7e-c2cba63e34e3": {"definition": "A secondary audio source held ready to feed the air chain when the primary programme feed fails, ranging from an emergency playout of stored content to an alternate studio, satellite, or network feed. It is selected automatically by a changeover or silence-sensing device, or manually by an operator, to prevent dead air.", "plain_english": "It is a spare source of sound for the station. If the main feed dies, the station switches to it. This stops silence from going out on air.", "purpose_function": "It exists to keep programming on the air during a failure of the main source, protecting against dead air that can breach licence conditions and drive listeners away.", "practical_application": "An engineer loads several hours of evergreen music onto an emergency player and wires it to a silence sensor so it takes over automatically if the studio feed drops.", "category": "Redundancy", "related_terms": ["Broadcast alarm system", "Automation assist mode", "Audio outside-broadcast vehicle", "Silence sensor", "Studio-transmitter link"], "common_mistakes": ["Never testing the backup source, so it fails when it is finally needed", "Routing the backup through the same failure-prone path (same server or link) as the primary", "Assuming automatic changeover repairs the primary; someone must still fix it and switch back"], "scenario_contexts": ["Studio automation crashes overnight and the backup player keeps music on air", "A satellite network feed drops and the station falls back to local content", "A silence sensor detects dead air and switches to the emergency source"]}, "22f2a3f2-f756-41bb-9090-91da52deff12": {"definition": "A monitoring and warning system in a broadcast facility that detects fault conditions in the air chain, such as prolonged silence (dead air), loss of carrier, over-modulation, or transmitter faults, and alerts staff or triggers automatic corrective action. It typically combines silence sensors, remote-control telemetry, and audible, visual, or messaging alerts.", "plain_english": "It watches the station's sound and gear for problems. If the air goes silent or a fault appears, it warns the staff. Some systems can even switch to a backup on their own.", "purpose_function": "It protects continuity of service by catching failures, especially dead air, quickly, so staff can respond before listeners are lost or licence rules are broken.", "practical_application": "An engineer sets a silence sensor to trigger after a few seconds of quiet, sending a text alert and switching to the backup source automatically.", "category": "Monitoring", "related_terms": ["Backup program source", "Broadcast archive server", "Automation assist mode", "Silence sensor", "Transmitter remote control"], "common_mistakes": ["Setting silence thresholds so tight that quiet passages of programme trigger false alarms", "UNSAFE: Bypassing or muting transmitter fault alarms to stop nuisance alerts, masking conditions that can damage the transmitter or breach RF exposure limits", "Relying on alarms that nobody monitors outside office hours"], "scenario_contexts": ["Overnight unattended operation where alarms are the only line of defence", "Detecting a stuck audio feed that has gone silent", "Warning staff of a transmitter power fault at a remote site"]}, "262dac5e-217c-4eab-9133-a451f2b20a4e": {"definition": "A networked storage system that ingests, catalogues, and retains broadcast audio, including finished programmes, raw recordings, and continuous off-air logs, for reuse, repurposing, and regulatory compliance. It provides searchable, often long-term storage kept separate from the fast online storage used for daily playout.", "plain_english": "It is a big storage computer for a station's audio. It keeps old shows and recordings in an organized way. Staff can search it and pull files back when they need them.", "purpose_function": "It preserves programme material and legally required recordings so content can be found and reused later, while keeping the active playout storage free for current work.", "practical_application": "A producer searches the archive server for a past interview, retrieves the file, and re-edits it into a new feature.", "category": "Storage", "related_terms": ["Broadcast audio post suite", "Backup program source", "Broadcast alarm system", "Logging recorder", "Playout system"], "common_mistakes": ["Treating the archive as a backup; it stores masters, but without a second copy it is not disaster-proof", "Failing to enter consistent metadata, which makes files impossible to find later", "Ignoring the retention period that regulators require for off-air logs"], "scenario_contexts": ["Retrieving a broadcast recording to answer a listener complaint or regulator request", "Repurposing archived material into a highlights programme", "Meeting a legal duty to retain recordings of everything aired"]}, "76a69c61-b4b1-4ebb-8410-9e3833decf59": {"definition": "A recorder or recording system that captures immersive Dolby Atmos audio, meaning channel beds plus object-based elements carrying positional metadata, for broadcast and streaming production. It stores the multichannel audio together with its metadata so the immersive mix can be reproduced and re-rendered downstream.", "plain_english": "It records surround sound that can also come from above you. It saves the sound plus data about where each sound sits. This lets the full 3D mix play back later.", "purpose_function": "It exists to capture immersive, object-based audio for programmes made in Dolby Atmos, keeping the audio and its positional metadata intact through the production chain.", "practical_application": "An audio engineer on a live concert broadcast records the Atmos bed and objects so the immersive mix can be finished and delivered for streaming.", "category": "Immersive Audio", "related_terms": ["Broadcast audio post suite", "Broadcast audio console", "Object-based audio", "Loudness normalization", "Digital audio workstation"], "common_mistakes": ["Recording only the channel bed and losing the object metadata, which collapses the immersive mix", "Assuming an Atmos recording folds down to stereo automatically without checking the downmix", "Confusing Dolby Atmos with plain 5.1 surround, which has no height or object layer"], "scenario_contexts": ["Capturing an immersive mix of a live orchestral broadcast", "Recording sports crowd atmosphere in Atmos for a streaming platform", "Delivering an Atmos programme master for on-demand playback"]}, "919f9d4a-4630-4ae1-96ed-5cc1da1acc4e": {"definition": "A mixing console designed for on-air broadcast use, combining program and audition (off-air) buses, mix-minus outputs, telephone and codec integration, and monitor-muting/tally logic for the studio. It routes and mixes microphones, playout, and remote sources into the station's programme feed.", "plain_english": "It is the mixing desk in a radio studio. It blends mics, music, and phone callers into one feed for air. It also mutes the studio speakers when a mic is live, to stop feedback.", "purpose_function": "It is the central point where all studio and remote audio is combined, leveled, and routed to air, adding broadcast-specific features such as mix-minus and mic-triggered monitor muting.", "practical_application": "A presenter opens their mic fader, brings up a music bed, and takes a phone caller on a mix-minus bus so the caller does not hear their own delayed voice.", "category": "Mixing", "related_terms": ["Broadcast audio matrix", "Audio outside-broadcast vehicle", "Automation assist mode", "Mix-minus", "Playout system"], "common_mistakes": ["Sending a caller or remote guest a full mix instead of mix-minus, causing echo or feedback", "Ignoring monitor-muting logic and creating howl-round when the studio mic is live over the speakers", "Confusing the audition/cue bus with the program bus and putting off-air content to air"], "scenario_contexts": ["Running a live phone-in show with multiple callers", "Mixing a live music session in the on-air studio", "Handing a remote OB feed onto air through the console"]}, "75d4efa3-9ab9-4f08-8d46-30839d15ea74": {"definition": "A crosspoint routing system that connects many audio sources to many destinations in a broadcast facility, letting any input be assigned to any output under operator or automation control. Modern implementations are commonly networked over AES67 audio-over-IP, distributing signals across studios, playout, and transmission paths.", "plain_english": "It is a big audio switchboard for the station. It can send any source to any place. Staff pick which input goes to which output, by hand or by software.", "purpose_function": "It provides flexible, central signal distribution so any source can reach any studio, processor, or transmitter path without repatching physical cables.", "practical_application": "An engineer uses the router control panel to send the incoming satellite network feed to Studio 2's console and to the transmitter path at the same time.", "category": "Routing", "related_terms": ["Broadcast audio console", "Audio outside-broadcast vehicle", "Backup program source", "Audio over IP", "Studio-transmitter link"], "common_mistakes": ["Making a routing change on air without checking which destinations are live, cutting a source off air", "Assuming a salvo or preset recalls levels as well as routes when it may only recall crosspoints", "Confusing an audio matrix with a mixing console; a matrix routes but does not mix or blend levels"], "scenario_contexts": ["Distributing a shared network feed to several studios at once", "Switching the transmitter feed from the main studio to a backup studio", "Routing remote OB returns to the correct production room"]}, "f02ba2da-1c47-4fff-93af-457e94469bbd": {"definition": "A dedicated production room and its equipment, including a digital audio workstation, calibrated monitoring, and processing, used to edit, mix, and finish audio for broadcast programmes after acquisition. Work includes dialogue editing, sound design, music, and a loudness-compliant final mix that meets the broadcaster's delivery specifications.", "plain_english": "It is an editing room for finishing a show's sound. Staff clean up speech, add music and effects, and set the loudness. The result is ready to broadcast.", "purpose_function": "It exists to turn raw recorded material into a polished, loudness-compliant final mix that meets the broadcaster's technical delivery standards.", "practical_application": "An audio editor cuts the dialogue for a documentary in the post suite, adds effects and music, then mixes to the required loudness target before delivery.", "category": "Post-Production", "related_terms": ["Broadcast archive server", "Broadcast Atmos recorder", "Broadcast audio console", "Loudness normalization", "Digital audio workstation"], "common_mistakes": ["Mixing to peak level instead of the required integrated loudness target, so the programme is rejected or re-leveled", "Monitoring at inconsistent levels, leading to dialogue that is too quiet or too loud on air", "Delivering in the wrong file format or channel layout for the broadcaster's specification"], "scenario_contexts": ["Finishing the audio mix of a radio drama or documentary", "Editing and sweetening a pre-recorded interview before transmission", "Mixing a programme to EBU R128 or ATSC A/85 loudness compliance"]}, "11df48eb-a496-4eb1-b417-545b26302a74": {"definition": "The craft and workflow of capturing, editing, mixing, and processing audio content such as programs, news, commercials, and station imaging for transmission over radio or television.", "plain_english": "This is the work of making the sound you hear on radio and TV. Someone records voices and music, then mixes them so they play clearly on air.", "purpose_function": "It turns raw recordings into polished, consistent audio that meets a station's sound and loudness targets, so the audience gets a clear and professional listening experience.", "practical_application": "A technician records voice tracks, edits ads, and mixes shows in a DAW or on an on-air console, then delivers the finished audio to playout or the air chain.", "category": "Broadcast Production", "related_terms": ["Broadcast automation system", "Broadcast audio router", "Air chain", "Loudness normalization", "Studio-to-transmitter link"], "common_mistakes": ["Ignoring loudness targets so segments air noticeably louder or quieter than the rest of the programming", "Over-processing voice audio until it sounds pumped or distorted", "Mixing to studio monitors without checking how content sounds on typical listener devices"], "scenario_contexts": ["Editing and mixing a recorded interview for a scheduled news program", "Producing a 30-second commercial spot to a station's loudness spec", "Preparing station imaging and jingles for insertion by the automation system"]}, "4c4128e6-de6f-4cf6-b40b-8e4e90347881": {"definition": "A matrix switching device that can connect any of many audio input sources to any of many outputs under operator or automation control, serving as the central signal-distribution hub of a broadcast facility.", "plain_english": "This is a big switchboard for sound in a station. It can send any input, like a studio or a phone line, to any output, like the transmitter.", "purpose_function": "It lets a facility route sources to destinations quickly and reliably, so studios, feeds, and transmitters can be reconfigured without repatching cables by hand.", "practical_application": "An operator selects a source-to-destination crosspoint on a router panel or control software to send a studio's output to air or to feed a recorder.", "category": "Signal Routing", "related_terms": ["Broadcast automation system", "Broadcast clean feed", "Air chain", "Studio-to-transmitter link", "Crosspoint"], "common_mistakes": ["Taking the wrong crosspoint and routing the wrong source to air", "Assuming a route change is instant when clean switching depends on proper synchronization", "Confusing a router destination with a physical output and patching the signal twice"], "scenario_contexts": ["Switching a live studio to air at the top of the hour", "Feeding a network program to multiple outputs at once", "Routing an incoming remote feed to a recorder and to the monitor bus"]}, "ce50119b-9540-4824-8801-c1ff3a6360d7": {"definition": "A software and hardware system that schedules, sequences, and plays out audio content such as songs, ads, jingles, and voice tracks automatically according to a program log, with or without a live operator.", "plain_english": "This is a computer system that plays radio content on its own. It follows a playlist, so songs and ads play in the right order even with no one in the room.", "purpose_function": "It ensures programming airs on time and in the correct order around the clock, cutting staffing needs and reducing human error during playout.", "practical_application": "A technician builds the daily log, imports audio, and monitors the automation as it plays tracks, fires ads, and switches over to live shows.", "category": "Playout & Automation", "related_terms": ["Broadcast audio router", "Broadcast backup recorder", "Program log", "Voice tracking", "Air chain"], "common_mistakes": ["Leaving a gap or bad entry in the log so the system airs silence or dead air", "Importing audio with the wrong start point so tracks clip on or off", "Trusting automation without monitoring, so a failed event goes unnoticed"], "scenario_contexts": ["Running an unattended overnight music shift from a scheduled log", "Firing scheduled commercial breaks between live segments", "Voice-tracking a show so recorded links play between songs as if live"]}, "4e83365c-b8b2-44a1-a3a0-ce8b8e0acb77": {"definition": "A recorder that continuously captures a program or air-chain signal as a redundant copy, allowing content recovery or re-airing if the primary source or playout system fails.", "plain_english": "This machine keeps recording the show as a spare copy. If the main system crashes, you still have the audio to play or to fix the problem.", "purpose_function": "It provides redundancy so a station can recover content and stay on air after an equipment failure, a lost file, or a playout crash.", "practical_application": "Engineers pull from the backup recording to fill dead air, re-air a lost segment, or check what actually left the studio.", "category": "Logging & Recording", "related_terms": ["Broadcast compliance recorder", "Broadcast automation system", "Air chain", "Redundancy", "Playout"], "common_mistakes": ["Assuming a backup recorder also satisfies legal logging, which is the job of a compliance recorder", "Never testing the recording, then finding the backup was silent when it was needed", "Letting the storage fill up so old recordings block new ones"], "scenario_contexts": ["Recovering a segment after the playout server crashes mid-show", "Filling dead air by replaying recently captured programming", "Reviewing the capture to confirm what audio actually aired"]}, "1ee7f391-780c-4b2e-9a64-ec62f1d16a1e": {"definition": "A program audio feed sent to a remote contributor that carries the full mix minus that contributor's own audio, preventing them from hearing their own voice delayed back; in audio production it is also called a mix-minus.", "plain_english": "This is the sound sent back to a guest in another place. It has everything except the guest's own voice, so they don't hear a distracting echo of themselves.", "purpose_function": "It gives remote guests the program audio they need to react to while removing their own delayed voice, which would otherwise cause confusing echo and disrupt the conversation.", "practical_application": "An engineer builds a mix-minus on the console for each phone caller or remote guest so they hear the host and program but not themselves.", "category": "Signal Feeds", "related_terms": ["Broadcast dirty feed", "Mix-minus", "Broadcast codec link", "IFB", "Broadcast audio router"], "common_mistakes": ["Sending the guest the full mix so they hear their own delayed voice as an echo", "Building one mix-minus and sharing it across several remote sources", "Assuming clean feed always means video without graphics; in audio it means the mix-minus feed"], "scenario_contexts": ["Feeding a phone-in caller during a live talk show", "Sending program audio back to a reporter in the field over a codec", "Providing a remote studio guest a return feed free of their own voice"]}, "664ed620-6f25-4c4a-9df7-d346107a80d6": {"definition": "A point-to-point audio connection that uses an encoder/decoder to compress and carry broadcast-quality audio over IP, ISDN, or similar networks, used for remote contributions and studio-to-transmitter links.", "plain_english": "This is a way to send radio-quality sound over the internet or phone lines. A box squeezes the audio at one end and unpacks it at the other.", "purpose_function": "It moves high-quality audio between distant points reliably and with low delay, connecting field reporters, remote studios, and transmitter sites.", "practical_application": "An engineer configures an IP codec to send a reporter's audio from a remote location back to the studio or to feed the transmitter site.", "category": "Contribution Links", "related_terms": ["Studio-to-transmitter link", "Broadcast clean feed", "Air chain", "IP audio", "Broadcast audio router"], "common_mistakes": ["Mismatching the encode and decode settings so the link fails to connect or drops out", "Ignoring network jitter and buffer settings, causing audio glitches on the link", "Choosing a heavily compressed low-bitrate mode when quality audio is required"], "scenario_contexts": ["Sending a field reporter's live report back to the studio over IP", "Linking a remote broadcast site to the main studio", "Carrying the main program from studio to the transmitter over a dedicated link"]}, "57ec87ed-7cda-4ee5-b8b0-73c009809251": {"definition": "A recorder that continuously logs a station's off-air output to create a retained archive proving what was broadcast, used to meet regulatory, contractual, and dispute-resolution requirements; also called a logging or air-check recorder.", "plain_english": "This records everything a station puts on air and keeps it. If someone asks what was broadcast, or the rules require proof, the log has it.", "purpose_function": "It satisfies legal retention rules and provides evidence for listener complaints, royalty checks, and verification that content actually aired.", "practical_application": "Staff pull a logged segment to answer a complaint, confirm an ad ran, or meet a regulator's request for proof of what was broadcast.", "category": "Logging & Recording", "related_terms": ["Broadcast backup recorder", "Air check", "Program log", "Air chain", "Loudness normalization"], "common_mistakes": ["Confusing a compliance log with a backup recorder; the log is for legal proof, not re-airing quality", "Letting the retention period lapse so required recordings are already deleted", "Assuming the logger is running without checking it actually captured audio"], "scenario_contexts": ["Retrieving a recording to answer a regulator's request about aired content", "Verifying a scheduled commercial actually ran at the logged time", "Reviewing a logged segment to resolve a listener complaint"]}, "6ca66575-99e6-43f6-a831-26cb8b5312e3": {"definition": "The full program feed that includes every added element, such as the remote contributor's own audio in a return feed or, in television, station graphics and local inserts, in contrast to a clean feed from which specific elements are removed.", "plain_english": "This is the full feed with all the extra parts left in. It is the opposite of a clean feed, where one part is taken out.", "purpose_function": "It carries the complete program exactly as presented, useful where a downstream point needs everything included rather than a stripped-down version.", "practical_application": "A master control operator monitors the dirty feed to see the complete output an audience receives, including all inserts and, in TV, graphics.", "category": "Signal Feeds", "related_terms": ["Broadcast clean feed", "Mix-minus", "Broadcast audio router", "Master control", "Program feed"], "common_mistakes": ["Sending a dirty feed to a remote guest, so they hear their own delayed voice", "Confusing the dirty feed with the clean feed and stripping needed elements", "Assuming every downstream point wants the full feed when some need a clean version"], "scenario_contexts": ["Monitoring the complete as-aired output in master control", "Feeding a downstream point that needs the full program with all inserts", "Comparing the dirty and clean feeds to confirm what each destination receives"]}, "5aa10b65-5fcb-41f7-b8dc-4fc96a4b1754": {"definition": "A microphone deployed to capture ambient or event sounds such as crowd noise, applause, atmosphere, or specific action sounds rather than speech, mixed in to add realism and presence to a broadcast.", "plain_english": "This is a mic that picks up background sound, like a cheering crowd. It makes a broadcast feel live and real instead of flat.", "purpose_function": "It provides atmosphere and a sense of place under the commentary, so the audience feels present at the event.", "practical_application": "At a sports broadcast, an engineer places effects mics around the field to capture crowd noise and on-field sounds mixed beneath the commentators.", "category": "Microphones", "related_terms": ["Broadcast clean feed", "Mix-minus", "Ambience", "Shotgun microphone", "Commentary"], "common_mistakes": ["Mixing effects mics too loud so they bury the commentary", "Placing effects mics where they mainly pick up nearby commentators instead of the crowd", "Forgetting wind protection on outdoor effects mics, causing rumble"], "scenario_contexts": ["Capturing crowd atmosphere at a live sports broadcast", "Miking the field or court to pick up on-field action sounds", "Adding audience applause and ambience to a live concert broadcast"]}, "cc6d442f-5e94-4ccd-b0e1-ba0da8644974": {"definition": "A system that continuously captures a broadcaster's transmitted output together with a time-stamped record of on-air events, so that what actually aired can later be reviewed for regulatory compliance, quality checking, and dispute resolution. Modern loggers store low-bit-rate reference audio and video plus metadata such as as-run playlists, loudness readings, and alarm events.", "plain_english": "This is a box that quietly records everything a station puts on air, along with a timed list of what played. If someone later asks what was broadcast at 9pm, the log has the answer. Think of it like a security camera aimed at the station's own output.", "purpose_function": "It exists to prove what was actually transmitted and when, so a station can meet legal retention rules, settle complaints, and check technical quality after the fact.", "practical_application": "A technician checks the logger to confirm an advert ran at its booked time, to pull proof of what aired during a complaint, or to review loudness and silence alarms from an overnight shift.", "category": "Monitoring & Logging", "related_terms": ["As-run log", "Compliance recording", "Loudness monitoring", "Playout automation", "Air chain"], "common_mistakes": ["Confusing the event logger with the main program recorder, when the logger keeps a long, low-resolution reference copy rather than a broadcast-quality master", "Assuming the log proves quality, when it only proves what aired unless the logger also measures loudness and faults", "Letting log storage fill up so the required retention window is lost"], "scenario_contexts": ["Pulling proof-of-transmission for an advertiser billing query", "Investigating a viewer complaint about content shown at a specific time", "Reviewing overnight silence or loudness alarms during a compliance audit"]}, "f8141f95-d82f-4c38-a17d-828da405673a": {"definition": "The building and technical plant from which a broadcaster produces and transmits programming, housing studios, control rooms, machine and equipment rooms, master control and the air chain, plus the supporting power, cooling, and cabling infrastructure.", "plain_english": "This is the whole building where a TV or radio station is made and sent out. It holds the studios, control rooms, and racks of gear, plus the power and cooling that keep them running. It is basically the station's home base.", "purpose_function": "It brings all the people, studios, and equipment needed to create and transmit programs together in one controlled, powered, and climate-managed place.", "practical_application": "A technician moves through the facility's studios, rack rooms, and master control to patch signals, service equipment, and trace faults from a microphone all the way to the transmitter feed.", "category": "Facilities & Spaces", "related_terms": ["Master control room", "Broadcast gallery", "Air chain", "Machine room", "Broadcast ingest system"], "common_mistakes": ["UNSAFE: Working in equipment and rack rooms without following the facility's electrical safety and lockout/tagout procedures around mains power and high-current supplies", "Thinking the facility is just the studios and forgetting the technical core, such as master control, machine rooms, and the transmitter link, that keeps it on air", "Ignoring environmental needs like cooling and clean power that the facility must provide"], "scenario_contexts": ["Commissioning a new studio within an existing broadcast facility", "Tracing a signal path across the facility from studio to master control", "Planning power and cooling for added equipment racks"]}, "d90dcfb0-42ae-465b-9fd9-9877757678ce": {"definition": "In UK and European television practice, the production control room, or \"gallery\", overlooking or adjacent to a studio, from which the director, vision mixer, and production team cut the program live; it is often divided into a production gallery, a sound gallery (sound control room), and a lighting and vision control area.", "plain_english": "The gallery is the control room where a TV show is directed as it happens. The director, vision mixer, and team sit here watching monitors and choosing which camera goes to air. The sound team often works in a linked room called the sound gallery.", "purpose_function": "It gives the production team a single control point to view every source, switch cameras, mix sound, and coordinate the live program in real time.", "practical_application": "A broadcast technician sets up and checks the gallery's monitor wall, vision mixer, talkback, and audio console before a live studio recording or transmission.", "category": "Facilities & Spaces", "related_terms": ["Production control room", "Vision mixer", "Sound gallery", "Talkback", "Master control room"], "common_mistakes": ["Confusing the gallery, a studio production control room, with master control, which handles station-wide playout and transmission", "Assuming a gallery is always one room, when sound and lighting often have their own linked galleries", "Forgetting talkback setup, so the director cannot cue the studio floor"], "scenario_contexts": ["Directing a live studio panel show from the production gallery", "Setting up the sound gallery console and talkback before a broadcast", "Coordinating camera cuts and graphics during a live transmission"]}, "59c25d7d-32bb-4988-8407-d146a3b095be": {"definition": "The subsystem that captures incoming media, whether live feeds, files, or tape, into a broadcast production or playout environment, encoding it to house formats, applying time-stamps and metadata, and registering it in storage or asset management for downstream editing, playout, or archive.", "plain_english": "This is the front door for getting video and audio into a station's computer systems. It records or imports feeds and files, labels them, and files them so editors and playout can find them. Without ingest, nothing new gets into the system.", "purpose_function": "It exists to bring outside material into the facility in the right format with correct labeling, so content can be reliably found, edited, and aired.", "practical_application": "An operator schedules and monitors ingest of a live satellite feed or a batch of delivered files, checking that each clip encodes cleanly and lands with correct metadata.", "category": "Media Workflow", "related_terms": ["Media asset management", "Playout automation", "Encoder", "Metadata", "Broadcast facility"], "common_mistakes": ["Starting ingest without confirming the correct format and metadata, which breaks searches and downstream automation", "Assuming ingest is only for tape or files and overlooking live feed capture", "Not allowing enough storage or bandwidth, so recordings drop frames or fail"], "scenario_contexts": ["Capturing a live sports feed into the production server", "Batch-ingesting delivered commercials for playout", "Digitizing archive tapes into the asset management system"]}, "d47e198e-2288-4f34-9e02-7e01b7a76ccd": {"definition": "The complete signal path serving an on-air microphone, typically running from the mic through its preamplifier and dynamics and EQ processing to the console and on toward the air chain, engineered for consistent, intelligible, controlled-level speech.", "plain_english": "This is everything a broadcast microphone's sound passes through on its way to air: the mic, its preamp, the processing that evens out the voice, and the mixing console. Each stage is set so the presenter always sounds clear and at a steady level. It is like an assembly line that polishes the voice step by step.", "purpose_function": "It exists to turn a presenter's raw voice into a clean, consistent, correctly leveled signal ready for mixing and transmission.", "practical_application": "A technician sets gain first, then processing, along the mic chain so the presenter sits at the right level with controlled peaks and no clipping before the signal reaches the console.", "category": "Microphone Systems", "related_terms": ["Broadcast microphone processor", "Microphone preamplifier", "Air chain", "Gain staging", "Compressor"], "common_mistakes": ["Setting compression or EQ before proper gain staging, so noise and clipping get locked into the chain", "Patching phantom power into a ribbon microphone that cannot tolerate it, risking damage to the mic", "Treating each processing stage as fixed instead of tuning the chain to the specific voice and mic"], "scenario_contexts": ["Setting up a presenter position in a radio studio", "Troubleshooting distortion somewhere along the on-air mic path", "Matching two presenters' voices so they sit at the same level"]}, "624722b2-8829-4320-a8f5-c0c7736cb6bf": {"definition": "A dedicated single- or multi-stage signal processor inserted in the on-air microphone path that combines mic preamplification with gating or expansion, compression, de-essing, EQ, and limiting to deliver a clean, consistent, controlled-level voice ready for broadcast.", "plain_english": "This is one box that shapes a presenter's voice for air. It boosts the mic, smooths loud and soft parts, tames harsh \"s\" sounds, and stops peaks from clipping. It turns an uneven voice into a steady, polished sound.", "purpose_function": "It exists to make speech sit at a consistent level and tone with peaks safely controlled, so presenters stay intelligible and loudness limits are respected.", "practical_application": "A technician dials in gate, compression, EQ, and de-essing on the processor to match a presenter's voice, then sets the limiter so the output never overshoots into the console or transmitter.", "category": "Microphone Systems", "related_terms": ["Broadcast microphone chain", "Compressor", "De-esser", "Limiter", "Microphone preamplifier"], "common_mistakes": ["Over-compressing until the voice sounds pumped and tiring, and background noise rises between words", "Skipping the gate or expander, so studio noise and headphone spill are always audible", "Setting the limiter like a normal fader instead of a safety ceiling, which causes constant distortion"], "scenario_contexts": ["Setting up a new presenter's voice sound at a radio desk", "Adding a processor to a podcast or voiceover mic path", "Standardizing voice processing across several studios"]}, "17110769-9a5d-4486-9e82-81daaee7d2d3": {"definition": "A passive transformer or active device that takes one microphone signal and feeds it to two or more independent destinations, for example a broadcast mix, front-of-house, and a recording rig, while maintaining isolation and, where needed, ground-lift to prevent hum loops.", "plain_english": "This splits one microphone so its sound can go to several places at once, such as the broadcast mix, the venue's speakers, and a recording. Each output stays separate, so one desk cannot upset another. It is like a splitter that lets several people use the same source at the same time.", "purpose_function": "It exists so a single mic can serve broadcast, live sound, and recording at the same time without those systems interfering with each other.", "practical_application": "At a live event a technician patches stage mics through a splitter, sending isolated feeds to the broadcast truck, the house console, and the recording rig, lifting grounds as needed to kill hum.", "category": "Microphone Systems", "related_terms": ["Microphone splitter", "Ground loop", "Direct box", "Front of house", "Broadcast microphone chain"], "common_mistakes": ["UNSAFE: Lifting the mains safety earth to cure hum, which defeats grounding meant to protect people; only the audio signal ground should ever be lifted", "Forgetting that phantom power can usually come from only one side of a transformer split, leaving condenser mics unpowered elsewhere", "Overloading a passive split with too many outputs, causing level loss and loading of the microphone"], "scenario_contexts": ["Splitting stage mics between a broadcast truck and the house PA", "Feeding an isolated record rig from the same mics as the live mix", "Curing hum between broadcast and PA systems with transformer isolation and ground lift"]}, "18000394-2194-424e-b1a0-c5e3c46d5983": {"definition": "A recorder that captures multiple discrete audio channels simultaneously in a broadcast production, such as individual mics, submixes, and clean feeds, so a program can be remixed, corrected, or re-versioned after the event rather than only as a finished stereo mix.", "plain_english": "This records many separate audio tracks at once during a broadcast, not just the final mix. Each mic or feed gets its own track. That way engineers can fix or rebalance the sound later, instead of being stuck with one mixed version.", "purpose_function": "It exists to preserve separate audio elements so a show can be remixed, repaired, or re-versioned later, and to provide a safety backup of the live mix.", "practical_application": "For a concert or sports broadcast a technician records each mic and submix to its own track, giving the post team clean elements to rebuild the mix for a highlights package or archive.", "category": "Recording Systems", "related_terms": ["Broadcast music recording", "Clean feed", "Stem", "Digital audio workstation", "Multitrack recording"], "common_mistakes": ["Recording only the final mix, then having no way to fix a buried voice or bad balance later", "Not checking track record-arming and levels before the event, so key elements are lost", "Assuming timecode and sync will match later without locking the recorder to house reference"], "scenario_contexts": ["Capturing a live concert broadcast for later remix and release", "Recording sports commentary, effects, and crowd on separate tracks", "Keeping a multitrack safety of a live studio session"]}, "68bfa179-918a-409d-b083-c568f79558ec": {"definition": "The practice of recording musical performances specifically for broadcast, in studios, concert halls, or outside-broadcast settings, capturing and mixing them to broadcast technical and loudness standards, often for live transmission or later programming.", "plain_english": "This is recording music so it can be played on radio or TV. It might be a studio session, a concert, or an outdoor event, captured and mixed to meet broadcast rules for sound and loudness. The goal is music that sounds right when it goes to air.", "purpose_function": "It exists to capture musical performances at broadcast quality and to the loudness and technical standards required for transmission or later programming.", "practical_application": "A technician sets up mics, splits, and a multitrack for a session or concert, then mixes to broadcast loudness targets for live air or delivers tracks to post for a later program.", "category": "Recording Systems", "related_terms": ["Broadcast multitrack recorder", "Broadcast microphone split", "Loudness monitoring", "Outside broadcast", "Air chain"], "common_mistakes": ["Mixing to studio-album loudness instead of the broadcaster's loudness target, so the audio is rejected or re-leveled", "Neglecting a multitrack safety, leaving no way to fix problems found after the performance", "Forgetting that live-to-air music has no second take, so monitoring and backups must be solid"], "scenario_contexts": ["Recording a live session for a radio music show", "Capturing an orchestral concert for broadcast and archive", "Mixing a festival performance to broadcast loudness for live transmission"]}, "ae5f1d02-4de9-4684-9877-ae6004c538c7": {"definition": "A centralized, staffed facility within a broadcast plant where program signals are monitored, switched, quality-checked, and routed toward transmitters or distribution links. It acts as the master control point supervising the on-air output of one or more stations or channels.", "plain_english": "It is the control hub of a radio or TV station. Staff there watch every signal on its way to air and switch sources so the right show goes out cleanly and on time.", "purpose_function": "It gives a facility one central point to supervise, switch, and route all on-air signals, so faults are caught early and programming reaches the transmitter reliably. It exists to protect the continuity and quality of what listeners and viewers receive.", "practical_application": "A technician staffs the operations center to watch meters and off-air confidence feeds, switch between program sources, and respond to alarms or loss of signal before it affects air. During live events they coordinate feeds, backups, and hand-offs between studios and remote sites.", "category": "Broadcast Facility", "related_terms": ["Broadcast routing system", "Broadcast signal chain", "Broadcast playout system", "Broadcast scheduler", "Broadcast production room"], "common_mistakes": ["Confusing the operations center with a single on-air studio; it is the master control and monitoring point, not the talk studio", "Assuming automation removes the need for staffing; operators must still monitor alarms and take manual action on signal loss", "Overlooking backup and failover paths, so a single fault takes the station off air"], "scenario_contexts": ["An operator switches from network programming to a local break and back at scheduled times", "Staff detect a dead-air alarm on a confidence monitor and switch to a backup source", "During severe weather, the center inserts emergency alert audio and coordinates feeds across multiple stations"]}, "f50cc3a0-c60b-4c46-a525-f2889908190c": {"definition": "The software component of a radio automation system that manages and sequences the ordered list of audio elements, such as songs, commercials, jingles, and voice tracks, for playback. It resolves the playlist into a timed sequence and passes each item to the playout system in turn.", "plain_english": "This is the software brain that lines up songs, ads, and jingles in the right order. It feeds that list to the system that plays them on air, one item after another.", "purpose_function": "It exists to turn a scheduled log of content into a reliable, correctly ordered stream of playback events, handling transitions, overlaps, and timing between elements. This automates continuous programming without an operator starting each item by hand.", "practical_application": "An operator or programmer builds or edits the playlist, and the engine cues, times, and triggers each element into the on-air chain. Technicians troubleshoot it when items play out of order, fail to load, or overlap incorrectly.", "category": "Broadcast Automation", "related_terms": ["Broadcast playout system", "Broadcast scheduler", "Broadcast recording log", "Broadcast signal chain", "Broadcast operations center"], "common_mistakes": ["Confusing the playlist engine with the playout hardware; the engine orders and cues content while the playout system reproduces the audio", "Assuming the engine creates the schedule itself, when it usually executes a log built by a separate scheduler", "Ignoring segue and crossfade settings, which causes gaps or clashing overlaps between elements"], "scenario_contexts": ["An automated overnight music block plays songs, station IDs, and spots in sequence with no operator present", "A voice-tracked show interleaves pre-recorded host segments between songs at the right points", "An operator inserts a live break into the running playlist and the engine resumes the sequence afterward"]}, "ea448cc0-93a0-44cb-af93-9322f55eea7b": {"definition": "The combined hardware and software system that reproduces scheduled audio or video content to air, typically a playout server driven by automation. It plays each logged element on cue and delivers it into the station's on-air signal chain.", "plain_english": "This is the gear and software that actually plays scheduled audio on air. Think of it as an automatic DJ that starts each track and ad at the planned moment.", "purpose_function": "It exists to store program material and play it out accurately and on time, so a station can run continuous, scheduled output with minimal manual operation. It bridges the content library and the transmission chain.", "practical_application": "Technicians load or ingest media into the playout server, verify that scheduled items are present, and monitor that each plays at the correct time and level. When an item is missing or corrupt they replace it before it reaches air.", "category": "Broadcast Automation", "related_terms": ["Broadcast playlist engine", "Broadcast scheduler", "Broadcast signal chain", "Broadcast operations center", "Broadcast recording log"], "common_mistakes": ["Treating playout and scheduling as the same thing; the playout system reproduces content that a scheduler and playlist engine have already ordered", "Failing to confirm that scheduled media files are actually ingested, leading to missing-file dead air", "Neglecting redundancy, so a single server failure interrupts the entire air output"], "scenario_contexts": ["A radio station runs unattended for hours as the playout server airs logged music and spots", "A missing commercial audio file triggers an alarm and the operator loads a replacement", "A backup playout server automatically takes over when the primary fails during a live shift"]}, "7e54e7fc-2500-44a9-8794-0bbc0fd18294": {"definition": "A studio room used to create and record broadcast content such as commercials, promos, imaging, and pre-recorded segments, separate from the live on-air studio. It is equipped with a console, microphones, monitors, and recording or editing tools for offline production.", "plain_english": "This is a studio used to make and record station content like ads and promos. It keeps that work separate from the room that is live on air.", "purpose_function": "It exists to give staff a dedicated space for producing and editing material without tying up or risking the on-air studio. This lets production continue while the station stays live from another room.", "practical_application": "A producer records voiceovers, mixes commercials, and edits segments in the production room, then files the finished audio for scheduling and playout. Technicians maintain its console, mics, and monitoring to match on-air quality standards.", "category": "Broadcast Facility", "related_terms": ["Broadcast room microphone", "Broadcast operations center", "Broadcast recording log", "Broadcast playout system", "Broadcast signal chain"], "common_mistakes": ["Confusing the production room with the on-air studio; production work is offline and does not feed the transmitter directly", "Monitoring at inconsistent levels, so produced audio sounds too loud or quiet once aired", "Failing to label and file finished audio correctly, causing the wrong version to reach the log"], "scenario_contexts": ["A producer records and mixes a 30-second commercial for later scheduling", "A host tracks pre-recorded show segments while another host is live on air", "Station imaging and promos are edited and mastered before being added to the playout library"]}, "50a19c56-4d87-431c-9200-ce74570b28b6": {"definition": "A documented record of material recorded or aired by a station, listing each element with its time, source, and identifying details. It commonly serves as an as-run record used to confirm that programming and commercials aired as scheduled and to meet regulatory and billing requirements.", "plain_english": "This is a record of what actually aired and when. Stations keep it to prove that ads and shows ran as planned and to meet legal rules.", "purpose_function": "It exists to provide an accurate, timed account of what was broadcast or recorded, supporting verification, billing, copyright reporting, and regulatory compliance. It gives the station proof and a reference for reconciling the planned log against actual output.", "practical_application": "Staff generate the log automatically from the playout system or complete it manually, then reconcile it against the planned schedule to confirm spots and programs ran. It is used to bill advertisers, report music usage, and answer regulatory or client queries.", "category": "Broadcast Documentation", "related_terms": ["Broadcast scheduler", "Broadcast playout system", "Broadcast playlist engine", "Broadcast operations center", "Broadcast production room"], "common_mistakes": ["Confusing the planned schedule with the as-run log; the recording log documents what actually aired, not just what was intended", "Assuming automated logs never need review, when discrepancies from aborts or manual overrides must be reconciled", "Failing to retain logs for the required period, creating compliance and billing gaps"], "scenario_contexts": ["Traffic staff reconcile the as-run log to confirm a paid commercial aired before invoicing the client", "A station uses logs to report music performances for royalty accounting", "An engineer reviews the log to trace when and why a program element failed to air"]}, "ed1f2b73-3e89-4b94-b6d3-31fb845f295d": {"definition": "A microphone used in a broadcast studio to capture the voice of an announcer, host, or guest for on-air or recorded use. These are typically large-diaphragm dynamic or condenser models chosen for a warm, close voice sound with good rejection of room noise and handling of plosives.", "plain_english": "This is the mic a host or announcer talks into in a studio. It is built to capture a clear, close voice while ignoring room noise.", "purpose_function": "It exists to reproduce speech cleanly and consistently at close range, giving the polished, intelligible vocal sound expected on air. Its directional pattern and internal shielding help reject background noise and studio reflections.", "practical_application": "A technician mounts the mic on a boom arm with a shock mount and pop filter, sets gain for consistent speech level, and positions it a hand's width from the presenter. Common studio choices include cardioid dynamics such as the Shure SM7B and Electro-Voice RE20.", "category": "Broadcast Equipment", "related_terms": ["Broadcast production room", "Broadcast signal chain", "Broadcast operations center", "Broadcast routing system", "Broadcast recording log"], "common_mistakes": ["Placing the mic too far away, which raises room noise and forces excess gain and hiss", "Skipping the pop filter or off-axis angle, so plosive blasts distort the voice", "Assuming any mic pattern works; an omnidirectional mic in a live studio picks up too much room and monitor spill"], "scenario_contexts": ["A morning show host speaks into a boom-mounted dynamic mic during a live segment", "A guest is set up with a matched second mic positioned and gained to sit level with the host", "A producer records a voiceover in the production room using the same broadcast-grade mic chain"]}, "dbfcdb85-6567-4c6f-ae29-a0cef5655c49": {"definition": "A signal routing system, typically a router or matrix switcher, that connects any of many audio or video sources to any of many destinations within a broadcast facility. It lets operators select which source feeds each output, such as studios, recorders, monitoring, or the air chain.", "plain_english": "This is the switchboard for audio and video signals in a station. It sends any source, such as a studio or a feed, to any destination, such as the air chain or a recorder.", "purpose_function": "It exists to flexibly and reliably interconnect the many sources and destinations in a facility without repatching cables by hand. This lets staff reconfigure signal flow quickly for different shows, feeds, and failover situations.", "practical_application": "An operator selects source-to-destination crosspoints from a control panel or software to route a studio to air, send a feed to a recorder, or reroute around a fault. Technicians configure and label the router and verify that salvo or preset routes fire correctly.", "category": "Broadcast Infrastructure", "related_terms": ["Broadcast operations center", "Broadcast signal chain", "Broadcast playout system", "Broadcast room microphone", "Broadcast scheduler"], "common_mistakes": ["Confusing a router with a mixer; a router selects and switches whole signals while a mixer combines and blends them", "Mislabeling sources or destinations, so an operator routes the wrong feed to air", "Forgetting that a single crosspoint change can take a studio off air if made on the wrong destination"], "scenario_contexts": ["An operator routes the active studio to the air chain at the start of a shift", "A network feed is switched from the router to a recorder for later playback", "During a fault, staff reroute program audio around a failed processor using a preset salvo"]}, "509f3a72-5305-4006-b70a-60be47fec49d": {"definition": "Software that plans and orders programming and content into a timed broadcast schedule or log, covering elements such as music, programs, commercials, and station imaging. It applies rules and clocks to build the sequence that the playlist engine and playout system then execute.", "plain_english": "This is software that plans what airs and when. It builds the daily lineup of shows, songs, and ads that the playout system then runs.", "purpose_function": "It exists to translate programming policy, format clocks, and advertising sales into a structured, rule-checked log for each broadcast day. This ensures content airs in the right order, spacing, and rotation without manual list-building.", "practical_application": "A music or traffic scheduler sets rotation rules, clocks, and separation constraints, then generates the daily log and hands it to automation. Staff edit the schedule for live shows, breaking news, or last-minute spot changes.", "category": "Broadcast Automation", "related_terms": ["Broadcast playlist engine", "Broadcast playout system", "Broadcast recording log", "Broadcast operations center", "Broadcast signal chain"], "common_mistakes": ["Confusing the scheduler with the playout system; the scheduler decides what airs and when, while playout reproduces it", "Ignoring rotation and separation rules, so the same song or advertiser repeats too closely", "Failing to reconcile the scheduled log with the as-run log after manual overrides"], "scenario_contexts": ["A programmer builds the next day's music log using format clocks and rotation rules", "Traffic staff schedule sold commercial spots into available break positions", "An operator edits the day's schedule to accommodate a live sports broadcast"]}, "1a813bc0-226a-4bb0-9171-c6f0ae6a9ba1": {"definition": "The ordered path a program signal follows from its source through every processing and distribution stage to the transmitter or delivery point, often called the air chain. Typical stages include the microphone or source, console, audio processing and loudness control, studio-to-transmitter link, and transmitter.", "plain_english": "This is the whole path a signal takes from the mic to the transmitter. Each stage, such as the console and processing, passes the sound to the next until it reaches listeners.", "purpose_function": "It exists to carry program audio from source to air with controlled level, quality, and consistency at every stage. Understanding the chain lets engineers place processing correctly and locate faults by following the signal from end to end.", "practical_application": "A technician traces the signal chain stage by stage to isolate distortion, level, or dropout problems, and sets audio processing so on-air loudness meets target standards. During installation they document each stage so gain structure and monitoring points are known.", "category": "Signal Flow", "related_terms": ["Broadcast routing system", "Broadcast operations center", "Broadcast playout system", "Broadcast room microphone", "Broadcast production room"], "common_mistakes": ["Placing loudness or peak processing in the wrong order, which degrades on-air consistency and control", "Setting poor gain structure between stages, causing noise or clipping partway down the chain", "Troubleshooting at random instead of following the chain in order from source to transmitter"], "scenario_contexts": ["An engineer follows the air chain from studio console to transmitter to find where audio is being lost", "Audio processing is inserted late in the chain to meet a loudness target before transmission", "A new studio is commissioned by documenting and level-checking every stage of its signal chain"]}, "23b30238-cae4-4c29-96c3-d51fcb889815": {"definition": "A control or device in a broadcast chain that chooses which of several audio (or audio/video) sources is routed to a given destination, most often the program (on-air) bus. It is the point at which an operator or automation system commits a specific source to air.", "plain_english": "It is a switch that picks which sound feed goes on the air. Think of it like choosing a channel on a TV, but for what the station sends out.", "purpose_function": "It lets an operator or automation route exactly one chosen source to the program output at a time, so the air chain always carries the intended feed. It exists to make source changes clean, deliberate, and repeatable.", "practical_application": "A radio operator uses it to swap the on-air source between the studio microphone, a network feed, and a playout system without dead air or overlap. In automated stations the selector is driven by the playout schedule.", "category": "Signal Routing", "related_terms": ["Air chain", "Program bus", "Routing switcher", "Playout system", "Master control", "Broadcast studio"], "common_mistakes": ["Confusing the source selector with a full routing switcher; a selector chooses one source for a destination, while a router cross-connects many sources to many destinations", "Switching sources without checking levels or fade, causing an audible jump or click on air", "Assuming the selected source is on air without confirming on program metering and monitoring"], "scenario_contexts": ["A talk-radio operator moves the on-air feed from the host mic to a syndicated network program at the top of the hour", "An automation system selects the next scheduled audio source for playout", "An engineer selects between main and backup studio outputs during a fault"]}, "a1d943f6-7a42-42fc-92e5-d7fdd13e5e5a": {"definition": "A signal-distribution arrangement that splits microphone or line sources into multiple isolated feeds so that the broadcast mix, house PA, and recording can each receive the same sources independently. Transformer-isolated (and sometimes active) splits keep the feeds electrically separated to avoid ground loops and cross-loading.", "plain_english": "It takes one microphone signal and copies it to several places at once. That way the on-air mix, the room speakers, and the recorder each get their own clean copy.", "purpose_function": "It exists so several consoles can share the same stage sources without one console's settings or grounding affecting the others. Isolation protects each feed and prevents hum caused by ground loops between systems.", "practical_application": "At a concert broadcast, the technician runs the stage mics into a splitter that sends one leg to the broadcast truck, one to front-of-house PA, and one to monitors. The broadcast leg is usually the transformer-isolated output to keep it hum-free.", "category": "Signal Distribution", "related_terms": ["Microphone splitter", "Broadcast stagebox", "Ground loop", "Broadcast truck recording", "Front of house", "Isolation transformer"], "common_mistakes": ["UNSAFE: Defeating an isolated split's ground lift or relying on a mains ground-defeat adapter to cure hum, which can leave equipment chassis unbonded and create a shock hazard", "Overloading a passive split with too many parallel destinations, loading down the source and reducing level", "Assuming phantom power passes to every leg; typically only one leg carries phantom to the mic while others are isolated"], "scenario_contexts": ["A live music broadcast where truck, PA, and monitors each need the same stage mics", "A multi-broadcaster event where several networks each take an isolated split of the sources", "A house-of-worship service split between the broadcast feed and the room sound system"]}, "27cbd915-03c7-4424-bbae-a6c6d202f129": {"definition": "A microphone placed close to a specific source, instrument, or section to capture it individually for the broadcast mix, supplementing the main and ambience microphones. Its close pickup gives the broadcast mixer direct control over that source's level and presence.", "plain_english": "It is a mic placed close to one thing, like a single singer or drum. It picks up that one source clearly so it stands out in the on-air mix.", "purpose_function": "It exists to give the broadcast engineer a clean, isolated pickup of an important source that the wider main pair may not capture with enough clarity. This lets specific parts be reinforced or balanced without moving the main array.", "practical_application": "Covering an orchestra broadcast, an engineer adds spot mics on a soloist and on quiet sections so they can be lifted in the mix relative to the main stereo pickup. The spots are usually blended slightly behind the mains and time-aligned where needed.", "category": "Microphones", "related_terms": ["Main microphone", "Ambience microphone", "Stereo microphone technique", "Broadcast split system", "Time alignment", "Broadcast stereo recorder"], "common_mistakes": ["Mixing spot mics too loud, collapsing the natural depth and imaging provided by the main array", "Ignoring time-of-arrival differences between spot and main mics, causing comb filtering when combined", "Treating a spot mic as the primary source instead of a supplement to the mains"], "scenario_contexts": ["An orchestral concert broadcast where soloists and weak sections get individual spot mics", "A panel discussion where each guest has a close spot mic feeding the broadcast mix", "A live event where a specific instrument needs reinforcement in the on-air balance"]}, "f138d4e3-e76c-4976-abfb-5d551597955a": {"definition": "A rack- or floor-mounted input/output unit placed at the performance area that collects microphone and line signals and carries them to the broadcast console or outside-broadcast truck. It links the stage to the mixing point using an analog multicore or a digital audio network such as MADI, AES50, or Dante.", "plain_english": "It is a box on the stage where all the mic cables plug in. It then sends every signal down one cable or network to the mixing desk or truck.", "purpose_function": "It exists to gather many stage signals at the source and transport them over a single tidy link instead of running dozens of long individual cables. Digital stageboxes also place the mic preamps at the stage, keeping signal quality high over long runs.", "practical_application": "Setting up a remote broadcast, a technician patches stage mics into the stagebox and runs one fiber or cat cable back to the truck, where the console addresses each input remotely. Preamp gain is often controlled from the console over the network.", "category": "Signal Distribution", "related_terms": ["Digital snake", "MADI", "Dante", "Broadcast truck recording", "Microphone preamplifier", "Broadcast split system"], "common_mistakes": ["Exceeding the network's channel count or sample-rate limits and losing inputs", "Forgetting that phantom power is enabled per input at the stagebox, so condenser mics get no power if it is not switched on", "Running an unshielded or over-length data cable and getting dropouts on a digital snake"], "scenario_contexts": ["A remote concert broadcast feeding stage inputs to a truck over fiber", "A studio linking talent-area mics to the control room console over a digital snake", "A shared stagebox split between broadcast and PA consoles at a festival"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"b8818426-6776-42a2-9167-b3d76d312c98": {"definition": "A two-channel audio recorder used in broadcast to capture or play back the stereo program feed. It provides an archive, a time-delay source, or a playback record of the left/right program as broadcast.", "plain_english": "It is a recorder that captures sound in two channels, left and right. Radio uses it to save or replay the on-air program.", "purpose_function": "It exists to log or store the stereo program so it can be archived, replayed, or delayed. A reliable two-channel record of exactly what went to air is also useful for compliance and review.", "practical_application": "An engineer feeds the program bus into a stereo recorder to keep a clean archive of a live broadcast for later playout or checking. The same recorder can replay a pre-recorded stereo segment into the air chain on cue.", "category": "Recording", "related_terms": ["Program bus", "Air chain", "Broadcast surround recorder", "Logging recorder", "Playout system", "Broadcast studio"], "common_mistakes": ["Recording with the wrong reference level or headroom, so the archive clips or sits too low", "Assuming a stereo recorder captures surround; it stores only two channels", "Forgetting to confirm the recorder is armed, ending up with no archive of a live event"], "scenario_contexts": ["Archiving a live stereo radio broadcast for later replay", "Playing a pre-recorded stereo segment into the air chain on cue", "Keeping a compliance record of the stereo program feed"]}, "da7c585b-23e1-4c2c-8ad0-154500898c02": {"definition": "An acoustically treated room equipped for radio or television production, housing the mixing console, microphones, monitoring, and on-air equipment used to produce or transmit programs. It is designed for controlled acoustics and low noise so that speech and music are captured cleanly.", "plain_english": "It is a quiet, sound-treated room built for making radio or TV. It holds the mixing desk, mics, and speakers used to put a show together.", "purpose_function": "It exists to give producers a controlled acoustic space and the equipment needed to originate a broadcast. Treating the room for low noise and even response keeps the on-air sound clear and consistent.", "practical_application": "A presenter and engineer work in the broadcast studio using the console, mics, and monitors to run a live show or record a segment. The studio's acoustic treatment keeps reflections and background noise out of the program audio.", "category": "Facilities", "related_terms": ["Control room", "Broadcast source selector", "Air chain", "Broadcast technical operations center", "Acoustic treatment", "Monitoring"], "common_mistakes": ["Assuming any quiet room is broadcast-ready without proper acoustic treatment and noise control", "Confusing the studio (where the program originates) with master control or the transmitter site", "Monitoring too loud, which skews mix decisions and risks hearing exposure over long shifts"], "scenario_contexts": ["A live radio show hosted from an on-air studio", "Recording a voice-over or interview segment for later broadcast", "A TV set audio feed originating from a treated broadcast studio"]}, "a232589e-cf18-443e-8c83-5156fadab0c9": {"definition": "A multichannel recorder used in broadcast to capture or replay surround-sound program material, such as a 5.1 mix. It stores the discrete surround channels together so the immersive program can be archived, delayed, or played back in sync.", "plain_english": "It is a recorder that captures many channels of sound, not just two. This lets a show be saved in surround, like 5.1, with speakers all around you.", "purpose_function": "It exists to record or replay the full set of surround channels as a single locked group, preserving the spatial mix exactly as produced. This supports archiving, delayed transmission, and playback of surround broadcasts.", "practical_application": "For a live sports or concert broadcast in 5.1, an engineer records all surround channels together so the show can be reviewed or replayed with its spatial image intact. Channel assignments follow the standard surround order to stay compatible downstream.", "category": "Recording", "related_terms": ["5.1 surround", "Broadcast stereo recorder", "Channel mapping", "Program bus", "Broadcast truck recording", "Loudness metering"], "common_mistakes": ["Mislabeling or swapping surround channels so the playback image is wrong (for example, swapping center and LFE)", "Losing channel sync by recording surround channels on unlinked devices", "Assuming a stereo downmix preserves the surround image; the discrete channels must be recorded to keep it"], "scenario_contexts": ["Capturing a 5.1 live sports broadcast for archive and replay", "Recording a surround concert mix in an outside-broadcast truck", "Storing a surround program for delayed transmission"]}, "733fe016-0809-4338-9d37-0bcdd3a6e7f5": {"definition": "The central technical facility of a broadcast operation where signals are routed, monitored, and controlled, and where the station's transmission paths and technical infrastructure are managed. It is the hub through which program and support feeds pass on their way to air.", "plain_english": "It is the control hub of a station where all the signals come together. Staff there route, watch, and fix the feeds that go out to viewers or listeners.", "purpose_function": "It exists to centralize routing, monitoring, and fault management so that program feeds reach air reliably and problems are caught quickly. Concentrating these functions gives engineers one place to switch sources and respond to failures.", "practical_application": "An operator in the technical operations center watches program and confidence monitors, routes network and studio feeds, and switches to backup paths when a fault appears. It coordinates closely with master control and the studios feeding it.", "category": "Facilities", "related_terms": ["Master control", "Routing switcher", "Broadcast source selector", "Air chain", "Broadcast studio", "Signal monitoring"], "common_mistakes": ["Confusing the technical operations center with a single studio; it serves and connects many program sources", "Making a route change without confirming it on confidence monitoring, sending the wrong feed to air", "Assuming redundancy is automatic instead of verifying backup paths are armed and healthy"], "scenario_contexts": ["Routing a live network feed to the correct transmission path", "Switching to a backup studio or feed when a primary source fails", "Monitoring multiple program channels for signal loss or level faults"]}, "dfa8eab3-9b9a-471f-844c-03fd1deca123": {"definition": "The capture of audio, and often video, at a live remote event using the equipment inside an outside-broadcast (OB) or mobile production truck. The truck houses consoles, recorders, and routing so a full production and multitrack record can be made on site.", "plain_english": "It is recording sound from inside a special truck parked at an event. The truck is like a full studio on wheels for concerts and sports.", "purpose_function": "It exists to bring a complete, controlled production and recording facility to venues that have no permanent studio. Recording on the truck preserves the multitrack and program feeds for live transmission, later mixing, or archive.", "practical_application": "At a concert or sports event, the audio engineer in the OB truck records every stage input as multitrack plus the stereo or surround program off the console. Stage sources reach the truck through a stagebox and split so the truck feed stays independent of the PA.", "category": "Remote Production", "related_terms": ["Outside broadcast", "Broadcast stagebox", "Broadcast split system", "Multitrack recording", "Broadcast surround recorder", "Program bus"], "common_mistakes": ["UNSAFE: Energizing the truck from venue power without verifying proper grounding/bonding and correct supply, risking shock and equipment damage", "Recording only the stereo program and no multitrack, leaving no way to remix later", "Not confirming record arm and disk space before the event, losing the capture of a one-time performance"], "scenario_contexts": ["Multitrack recording a live concert from an OB truck for later album mixing", "Producing and recording a live sports broadcast on site", "Capturing a festival's stage feeds via a split to the truck alongside the PA"]}, "7c61cfc7-e4e7-4d79-b338-a93988b51c50": {"definition": "A monitoring device or circuit in the air chain that must keep sensing a valid on-air signal (or a periodic system 'heartbeat') within a set interval; if that interval elapses without one, it assumes a fault such as prolonged silence or a stalled playout system and triggers an alarm, a changeover to a backup source, or an automatic restart.", "plain_english": "It is a safety timer that watches the on-air signal. If the sound stops or the computer freezes for too long, the timer runs out. Then it switches to a backup or restarts the gear, so listeners do not hear silence.", "purpose_function": "It protects against unattended failures such as dead air, a crashed playout PC, or a lost feed by detecting the fault quickly and forcing a recovery action without waiting for a human operator.", "practical_application": "Engineers wire a silence-sensing watchdog near the final on-air point so that, if audio drops below a set level for a chosen number of seconds, it fires a relay to swap in an emergency player and raises an alert.", "category": "Air chain / Redundancy", "related_terms": ["Silence detection", "Dead air", "Automatic changeover", "Playout automation", "Confidence recording"], "common_mistakes": ["Setting the silence threshold too high or the delay too short, so normal quiet passages trigger a false changeover.", "Assuming the watchdog confirms the audio is correct, when it only detects presence and level, not whether the right program is playing.", "Forgetting the watchdog needs its own reliable power and a truly independent backup source, or it can fail at the same moment as the main path.", "UNSAFE: Defeating or bypassing the watchdog to stop 'nuisance' switching, leaving the station with no automatic protection against extended dead air."], "scenario_contexts": ["An unattended overnight automation PC crashes and the watchdog detects the silence and switches to a backup player.", "A satellite network feed drops out and the timer expires, rolling local emergency programming.", "A studio-to-transmitter link fails and a watchdog at the transmitter site starts a local backup loop."]}, "afbd0795-95c5-41d5-9dca-9e86c6f4a273": {"definition": "A mixer input/fader dedicated to caller audio delivered through a telephone hybrid, which separates the incoming caller signal from the outgoing send so a listener's phone call can be added to the on-air mix while, via a mix-minus feed, the caller hears the program minus their own returned voice.", "plain_english": "It is the channel on the mixing desk that a phone caller comes in on. A special box called a hybrid splits the call so the caller's voice can go on air, while the caller hears the show minus their own voice, which stops echo.", "purpose_function": "It lets talk and phone-in shows put listeners on air with clean, controllable audio and prevents the feedback and echo that occur if a caller hears their own delayed voice.", "practical_application": "A talk-show operator screens a caller, opens the call-in fader when the host takes the call, and sets a mix-minus send so the caller monitors the program but not their own return.", "category": "Studio sources", "related_terms": ["Telephone hybrid", "Mix-minus", "Profanity delay", "On-air fader", "Continuity studio"], "common_mistakes": ["Forgetting to set up a proper mix-minus, so the caller hears their own voice delayed and the line howls or echoes.", "Leaving the call-in fader open when no call is active, letting hybrid noise or a dial tone leak to air.", "Not using a broadcast delay, so a caller's profanity or slip reaches air with no chance to dump it."], "scenario_contexts": ["A morning talk show takes listener calls during an on-air debate.", "A sports phone-in lets fans react live right after a match.", "A radio request line puts a caller on air to dedicate a song."]}, "5dec2129-cb86-45a0-80bf-ba7f795e050f": {"definition": "An audio feed carrying a commentator's or announcer's spoken description of an event, kept separate from the effects and atmosphere sound so it can be mixed in, replaced, or supplied in several languages; in a full broadcast mix the commentary is typically placed in the centre while a clean effects feed can be sent to other broadcasters who add their own commentary.", "plain_english": "It is the feed that carries just the commentator's voice. It stays apart from the crowd and game sounds. That way, each station can add its own voice over the same crowd sound, often in another language.", "purpose_function": "Separating commentary from the effects and atmosphere lets one event's sound serve many outlets and languages and lets the mixer balance voice against crowd cleanly.", "practical_application": "At a match the sound supervisor routes each commentator to their own feed and sends a clean effects mix plus the commentary feeds back to the broadcaster, who combines the chosen language with the atmosphere.", "category": "Program feeds", "related_terms": ["Contribution feed", "Crowd microphone pair", "Concert broadcast mix", "Clean feed", "Mix-minus"], "common_mistakes": ["Mixing commentary permanently into the effects, so other broadcasters cannot add their own language.", "Letting crowd and atmosphere sit too high in the centre, masking the commentary and leaving no gap when the commentator's mic is muted.", "Forgetting to give the commentator a clean IFB or mix-minus so they can hear the program without their own delayed voice."], "scenario_contexts": ["An international football final where a clean effects feed goes worldwide and each country adds its own commentary.", "A radio sports desk taking a commentary feed from a stadium commentary position.", "A multilingual event offering separate English and Spanish commentary feeds."]}, "6f158bf2-0b1f-4ece-944e-8f118c0d9093": {"definition": "A scheduled interruption in program content during which advertisements, sponsor messages, or station promotions are aired, inserted at defined junctions in a programme so the broadcaster can carry paid spots; technically these breaks are timed and triggered from the traffic log by the playout automation.", "plain_english": "It is the ad break, the planned gap in a show where commercials play. The station's schedule software knows exactly when each break starts and fires the ads in the right order.", "purpose_function": "Commercial breaks let a station earn revenue by airing paid advertisements while giving programming a predictable structure of segments between breaks.", "practical_application": "An operator or the automation system starts the break at the logged time, plays the spot cluster, and returns to programming, checking that the break length matches the traffic log.", "category": "Programming", "related_terms": ["Traffic log", "Playout automation", "Continuity studio", "Loudness normalisation", "Station identification"], "common_mistakes": ["Running a break long or short so it does not match the logged duration and a network join or top-of-hour is missed.", "Airing commercials noticeably louder than programme content, breaching loudness rules such as EBU R128 or the CALM Act.", "Leaving a gap or dead air between spots because a break element failed to load."], "scenario_contexts": ["A music station's automation fires a scheduled ad cluster every quarter hour.", "A live host hands to a commercial break before a network newscast.", "A traffic department schedules spots into breaks to fill the day's advertising log."]}, "0841d2f3-bd5b-4587-8bda-73e0a360b2e2": {"definition": "A dedicated mix of a live concert created for transmission or recording rather than for the venue PA, balanced for the at-home listener over loudspeakers or headphones; it blends close and spot microphones on the performers with audience and ambience microphones to deliver both clarity and a sense of the room, and is built independently of the front-of-house PA mix.", "plain_english": "It is the mix of a live concert made for people listening at home, not for the crowd in the room. The engineer blends close mics on the musicians with audience mics so it sounds clear but still feels live.", "purpose_function": "It exists because the PA mix is tuned for the room and often leaves quiet instruments low; the broadcast mix instead delivers a full, balanced sound suited to home listening and captures the live atmosphere.", "practical_application": "A broadcast mixer takes a split of the stage mics plus dedicated audience and ambience pairs and builds a separate stereo or surround mix in an OB truck, monitoring on reference speakers for the home listener.", "category": "Broadcast mixing", "related_terms": ["Crowd microphone pair", "Commentary feed", "Contribution feed", "Ambience microphone", "Front-of-house mix"], "common_mistakes": ["Just taking a feed of the front-of-house PA mix, which is balanced for the room and usually sounds thin or lopsided at home.", "Using too little audience and ambience, so the recording sounds dry and lifeless with no sense of a live show.", "Letting spill and hall PA dominate, blurring the close-mic clarity the broadcast needs."], "scenario_contexts": ["A festival set mixed in an OB truck for live radio broadcast.", "An orchestral concert mixed for a surround broadcast with audience ambience pairs.", "A televised awards show where the music is mixed separately from the room PA."]}, "2a8c0cd1-9831-4b36-84b8-32db35737cde": {"definition": "A recording captured at the same time as a live transmission or a primary recording, used to confirm that the material is actually being captured or aired correctly and to serve as a safeguard copy; the term derives from tape practice, where a three-head machine's separate playback (repro) head let the operator monitor the just-recorded signal off the medium a moment after recording it.", "plain_english": "It is a second recording made at the same time as the main one, so you can be sure the audio is really being captured. It comes from tape decks that could play back what they had just recorded, a split second later, to prove it worked.", "purpose_function": "It gives the operator confidence that the record path is truly working and provides a backup copy if the primary recording or the live feed is lost.", "practical_application": "During an important session or live show an engineer runs a separate confidence recorder, or monitors off the playback head, so a failure in the main recorder does not lose the material.", "category": "Air chain / Redundancy", "related_terms": ["Broadcast watchdog timer", "Logging recorder", "Off-tape monitoring", "Backup recording", "Continuity studio"], "common_mistakes": ["Assuming the input meter proves a good recording, when only monitoring off the playback path confirms the medium actually captured it.", "Running the confidence recorder from the same power or the same source split as the main recorder, so both fail together.", "Never checking the confidence copy, so a silent or corrupt backup is discovered only when it is needed."], "scenario_contexts": ["A studio runs a confidence recorder alongside the main multitrack during a one-take live session.", "A broadcaster keeps a simultaneous recording of the air signal as a safeguard and reference.", "An engineer monitors off the repro head to verify a master is being captured cleanly."]}, "8edc76bb-9936-4ee2-a986-8a63d986036b": {"definition": "A small broadcast studio, also called a continuity or presentation suite, from which the station's output is controlled and continuity is kept between programmes: station identification, announcements, links, and smooth junctions from one item to the next; it usually houses a self-operated announcer position with the switching to take the transmission line.", "plain_english": "It is a small studio that keeps the station running smoothly between shows. From here an announcer gives the station name, reads links, and makes sure one programme joins the next with no awkward gaps.", "purpose_function": "It keeps the on-air output seamless, filling and bridging the joins between programmes and handling identification, trails, and last-minute changes so the channel never falls silent or overlaps.", "practical_application": "A continuity announcer works the desk self-op, opening their mic for links, firing station idents and trails, and switching sources to hand cleanly from one programme to the next.", "category": "Studio / Facility", "related_terms": ["Commercial break", "Station identification", "Playout automation", "Self-op", "Broadcast watchdog timer"], "common_mistakes": ["Confusing continuity with the main programme studio; continuity handles the junctions and station presentation, not the programmes themselves.", "Missing a clean junction so two sources overlap or a moment of dead air falls between programmes.", "Leaving the announcer mic open after a link, letting off-air talk reach transmission."], "scenario_contexts": ["A TV network's continuity suite links from the end of one show into the next with an ident and trail.", "A radio station's presentation studio covers the junction when a live programme ends early.", "An announcer in continuity reads a schedule change and hands to a network newscast."]}, "b03f7f34-e906-4033-8e9a-1b3a37bcc9cb": {"definition": "A high-quality audio feed sent from a remote site, such as an outside broadcast, studio, or event venue, into the broadcaster's production centre for use in making a programme, as opposed to a distribution feed carrying finished programming out to the audience; contribution links use higher quality and lighter compression than distribution because the material may still be mixed and processed.", "plain_english": "It is the feed that comes from an event or a remote studio back to the station to help build a show. It is kept at higher sound quality than the feed sent out to listeners, because it still has to be mixed.", "purpose_function": "It brings remote sources into the production chain at a quality high enough to survive further mixing and processing, keeping the path into the broadcaster distinct from the distribution path out to the audience.", "practical_application": "An engineer at an outside broadcast sends the mixed event audio as a contribution feed over a codec or IP link, following EBU N/ACIP practice, to the studio, which folds it into the network programme.", "category": "Program feeds", "related_terms": ["Commentary feed", "Distribution feed", "Concert broadcast mix", "Outside broadcast", "Crowd microphone pair"], "common_mistakes": ["Confusing contribution, which goes into the broadcaster, with distribution, which goes out to the audience, and using an over-compressed distribution-grade codec for source material.", "Under-provisioning the link so the contribution feed drops or glitches during the event.", "Sending only a finished mix when the studio needs split feeds, such as clean effects plus commentary, for flexibility."], "scenario_contexts": ["An OB truck sends a match's audio as a contribution feed to the network studio.", "A remote reporter's studio feeds a contribution circuit into the main newsroom.", "A concert venue sends a contribution feed over IP to a broadcaster for live transmission."]}, "f0b2b2e3-5421-4951-a3b3-eed57cf8f219": {"definition": "A stereo pair of microphones aimed at the audience or spectators to capture crowd reaction and venue atmosphere for the broadcast mix; small-diaphragm condensers in a coincident or near-coincident array such as X/Y or ORTF are typically used so the atmosphere has a stable stereo image and good separation from the commentary and effects channels.", "plain_english": "It is a matched pair of mics pointed at the crowd to pick up their cheers and the atmosphere of the venue. Using a stereo pair makes the crowd sound spread naturally left and right instead of coming from one spot.", "purpose_function": "It captures the live energy of the audience in stereo so the broadcast mix feels like being there, while a proper pattern keeps the crowd from smearing into the commentary and effects.", "practical_application": "A broadcast sound crew rigs crowd pairs facing the stands, mixes them under the commentary and effects, and rides them up on big reactions such as goals or applause.", "category": "Microphone technique", "related_terms": ["Commentary feed", "Concert broadcast mix", "Contribution feed", "Ambience microphone", "Effects microphone"], "common_mistakes": ["Placing the pair too close to one section or a PA speaker, so the crowd sounds lopsided or full of announcements and music.", "Collapsing a spaced or wide pair to mono for the mix and getting comb-filtering and phase problems.", "Pushing crowd level so high it masks the commentary and leaves audible gaps when the commentator's mic closes."], "scenario_contexts": ["Stereo crowd pairs on the stands of a football stadium for a live broadcast.", "Audience ambience pairs at a concert feeding the broadcast mix.", "Crowd mics either side of an arena capturing reaction for a televised event."]}, "5cbbc299-d0cf-466d-a3c0-f520f757b0f9": {"definition": "A device or circuit in the air chain that continuously monitors program audio and raises an alarm or triggers a corrective action when the level stays below a set threshold for a defined interval, indicating unintended silence (dead air).", "plain_english": "A watchdog that listens to what is going out over the air. If the sound drops to silence for too long, it sets off an alarm or starts a backup so listeners do not hear nothing.", "purpose_function": "It detects unintended silence so staff or automation can restore audio quickly, because dead air loses listeners and can breach a station's operating and licensing obligations.", "practical_application": "A technician sets the silence threshold and hold time on a silence sensor so it fires only on genuine dead air, then wires its relay or logic output to trigger a backup player or send an alert.", "category": "Monitoring", "related_terms": ["Air chain", "Automation system", "Backup audio", "Distribution feed", "Silence sensor"], "common_mistakes": ["Setting the hold time too short, so natural pauses in speech or music trigger false alarms", "Setting the threshold too high, so quiet passages read as silence", "Assuming the detector fixes the fault rather than only reporting it", "Never testing the trigger path, so the alarm or backup fails when real dead air occurs"], "scenario_contexts": ["Unattended overnight automation where no operator is present to notice silence", "An STL or codec link failure that drops audio to the transmitter", "A source or playout dropout during a live show"]}, "4e43f535-ce34-4063-a013-74487ed84d87": {"definition": "The block of memory in a broadcast (profanity) delay that holds several seconds of program audio between the record point and the on-air playback point, so recently recorded audio can be removed before it reaches the transmitter.", "plain_english": "A short store of the last few seconds of the show. The audio is recorded into it and played out a moment later, so staff can cut something out before it reaches listeners.", "purpose_function": "It holds a time cushion of program audio ahead of transmission so objectionable content can be dumped before it airs.", "practical_application": "A technician sets the buffer size on the delay unit, typically from a few seconds up to around 80 seconds; larger buffers give more reaction time but take longer to build.", "category": "Broadcast delay", "related_terms": ["Delay system", "Dump button", "Delay rebuild", "Air chain", "Distribution feed"], "common_mistakes": ["Confusing the safety buffer with a fixed alignment delay used for lip-sync or loudspeaker timing", "Assuming the full buffer is available the instant the unit powers up", "Setting the buffer so short that there is no time to react to bad content"], "scenario_contexts": ["Live call-in talk radio where callers may swear on air", "Live sports or event coverage with unpredictable audio", "A morning show building buffer before going live"]}, "a02bab1b-5d8d-410e-abe1-88eae3a351c1": {"definition": "The process by which a broadcast delay gradually restores its full safety buffer after a dump or at start-up, by subtly time-expanding audio (typically during pauses) without an audible pitch change until the target delay is reached again.", "plain_english": "After someone cuts audio with the dump button, the safety cushion of stored sound gets smaller. Rebuild slowly stretches the sound during quiet spots to grow the cushion back to full, and it does this without changing the pitch.", "purpose_function": "It brings the delay back to full length after the buffer is shortened, restoring the ability to dump again.", "practical_application": "A technician configures how aggressively rebuild stretches audio and the silence threshold it uses, trading rebuild speed against how transparent the time-stretching sounds.", "category": "Broadcast delay", "related_terms": ["Delay buffer", "Dump button", "Delay system", "Air chain"], "common_mistakes": ["Expecting the delay to return to full length instantly after a dump", "Setting rebuild too aggressive, so the time-stretching becomes audible", "Dumping repeatedly before rebuild finishes, leaving little or no protection"], "scenario_contexts": ["Recovering the safety margin after dumping a caller's profanity", "Building the initial delay when the unit is first entered into the air chain", "A busy talk segment with several dumps close together"]}, "e35d72bf-b581-4687-a8d0-338c0fdf03e5": {"definition": "In broadcast, the equipment and configuration that introduces a controlled, adjustable time offset (typically several seconds) into the air chain, so program audio reaches the transmitter later than it is produced and objectionable content can be removed before transmission.", "plain_english": "The whole setup that puts a few seconds of gap between the studio and the transmitter. That gap gives staff time to catch and cut anything that should not go out live.", "purpose_function": "It provides the time cushion and dump capability that let a station keep unwanted content off the air while still sounding live.", "practical_application": "A technician patches the delay system into the chain between the studio output and the transmitter or STL, sets the delay amount, and verifies the dump and rebuild behavior before going live.", "category": "Broadcast delay", "related_terms": ["Delay buffer", "Dump button", "Delay rebuild", "Air chain", "Distribution feed"], "common_mistakes": ["Placing the delay after the point being monitored, so operators hear content too late to dump it", "Forgetting that the system needs time to build before protection is available", "Leaving the delay bypassed and assuming it is protecting the air"], "scenario_contexts": ["Live call-in and talk programming", "Live award shows or sports carried on radio", "Any live remote where content cannot be fully controlled"]}, "ec748be8-25fa-46cc-818e-ad8cbb534cd3": {"definition": "A DSP-based broadcast device that interfaces a telephone or VoIP line to the console, using digital adaptive processing to separate the caller's receive audio from the studio's send audio on the shared line and to suppress echo and leakage so callers can be aired cleanly.", "plain_english": "A box that connects a phone call to the studio. A phone line carries both voices on one pair of wires, so this device uses digital processing to split them apart. That way the caller is heard cleanly on air and your own voice does not echo back.", "purpose_function": "It separates send and receive audio and removes echo so caller audio can be broadcast at good quality without feedback.", "practical_application": "A technician connects the hybrid between the phone line and the console, provides a mix-minus feed, and sets caller gain, ducking, and processing to balance the caller against studio audio.", "category": "Telephone interface", "related_terms": ["Mix-minus", "Distribution feed", "Air chain", "Digital hybrid", "Caller ducking"], "common_mistakes": ["UNSAFE: Connecting studio equipment directly to a telephone line without an approved interface, risking hazardous line and ringing voltages", "Feeding the hybrid a full mix instead of a mix-minus, so the caller hears themselves echoed", "Expecting to manually null the hybrid when the digital unit adapts automatically"], "scenario_contexts": ["Live call-in talk and request shows", "Phone interviews with remote guests", "Traffic or news reports phoned in from the field"]}, "8e3993ea-ce8d-4545-b861-a8517e9b071d": {"definition": "An audio (or audio/video) output routed to and shared among multiple downstream destinations, such as a program feed sent to affiliates, recorders, monitoring, and further processing, usually through a distribution amplifier so each destination receives an isolated copy.", "plain_english": "One audio signal sent out to many places at once. It is like copying a program feed to several recorders, receivers, or stations so they all get the same sound.", "purpose_function": "It delivers the same source to many destinations without letting them load or interfere with each other.", "practical_application": "A technician takes a program or bus output into a distribution amplifier and patches its isolated outputs to the transmitter, logger, monitoring, and any network or affiliate feeds.", "category": "Signal routing", "related_terms": ["Distribution amplifier", "Air chain", "Mix-minus", "Program bus", "Dead-air detector"], "common_mistakes": ["Paralleling one output to many inputs instead of using a distribution amplifier, causing loading and level loss", "Not labeling feeds, so a wrong or dead feed goes unnoticed", "Assuming every destination needs the same level and format without checking"], "scenario_contexts": ["Sending a network program feed to multiple affiliate stations", "Splitting a main output to the transmitter, logger, and monitoring", "Providing a clean feed to a recording or streaming encoder"]}, "888e208a-a763-49d7-8683-e1859042bc66": {"definition": "The control on a broadcast delay that, when pressed, immediately removes several seconds of buffered audio by moving the record point toward the playback point, so objectionable material already in the buffer never reaches the transmitter.", "plain_english": "The panic button on a broadcast delay. Press it and the last few seconds of audio are thrown away before they go out, so a swear word or mistake never reaches listeners.", "purpose_function": "It lets an operator delete unwanted content from the safety buffer before it airs.", "practical_application": "A technician sets the dump amount, commonly a few seconds per press, and places the button where the host or producer can reach it instantly during a live show.", "category": "Broadcast delay", "related_terms": ["Delay buffer", "Delay rebuild", "Delay system", "Air chain"], "common_mistakes": ["Pressing dump too late, after the content has already passed the playback point and aired", "Dumping repeatedly and exhausting the buffer, removing all protection", "Forgetting that the buffer must rebuild before another dump is possible"], "scenario_contexts": ["A caller swears during a live call-in show", "A guest says something legally risky on air", "An unexpected loud or unwanted sound during live coverage"]}, "77a5f45d-1b0b-4ca5-8e1c-c0771b4d3e86": {"definition": "A dedicated mix of a live festival performance created for broadcast or streaming, separate from the front-of-house PA mix, balanced for at-home listeners and typically built at an outside-broadcast truck or flypack from stage splits, with audience and ambience mics and commentary added as needed.", "plain_english": "A separate mix of a festival made for people watching or listening at home, not the crowd at the show. It is balanced for TV and phone speakers, and often adds crowd sound to capture the feel of the event.", "purpose_function": "It gives broadcast and streaming audiences a mix tuned for their playback, independent of the loud PA mix aimed at the live crowd.", "practical_application": "A broadcast engineer works from an isolated split of the stage inputs, blends performance, audience, and ambience mics, and delivers the mix to the distribution feed or recording system.", "category": "Remote production", "related_terms": ["Flypack recording system", "Distribution feed", "Mix-minus", "Microphone split", "Ambience mics"], "common_mistakes": ["Reusing the front-of-house mix, which lacks crowd and ambience and is tuned for the room rather than home listeners", "Neglecting audience mics, so the broadcast sounds flat and lifeless", "Not securing an isolated split, leaving the broadcast mix dependent on the PA console"], "scenario_contexts": ["Radio or TV coverage of a multi-stage music festival", "A live stream of a concert to online viewers", "Recording festival sets for later broadcast or release"]}, "bff4fe30-dc0f-4fce-89c2-d6289e5b30b5": {"definition": "A portable, rack-mounted production and recording system built into flight cases that can be shipped or flown to a remote venue as an alternative to an outside-broadcast truck, containing the recorders, routing, and processing needed to capture and produce a multichannel remote broadcast.", "plain_english": "A production kit built into wheeled road cases that can be flown or trucked to a venue. It does the job of a broadcast truck but packs down to travel, holding the recorders and gear needed to capture a show.", "purpose_function": "It brings full remote-production capability to venues where a truck is impractical, by packaging the gear into transportable cases.", "practical_application": "A technician racks recorders, routers, and interfaces into flight cases, ships them to the venue, and cables them to stage splits and the distribution feed to capture and mix the event.", "category": "Remote production", "related_terms": ["Festival broadcast mix", "Distribution feed", "Microphone split", "Outside broadcast", "Multitrack recorder"], "common_mistakes": ["Underestimating cabling, power, and setup time compared with a pre-wired truck", "Skipping a full bench test before shipping, so faults appear on site", "Failing to plan power distribution and grounding for the rack at the venue"], "scenario_contexts": ["Recording a festival or concert at a venue with no truck access", "A one-off remote broadcast at a hard-to-reach location", "Air-freighting a production kit to an overseas event"]}, "fd01bb7c-565f-43be-9751-5cb9803bf18e": {"definition": "A microphone provided at a broadcast or podcast position for an interviewee or guest, separate from the host's microphone and routed to its own console channel so its gain, processing, muting, and routing can be controlled independently. It lets the operator balance the guest against the host and handle each talent position on its own.", "plain_english": "It is a separate mic set up for a visitor on a show. It gets its own channel on the mixer. So the operator can set its volume by itself, apart from the host's mic.", "purpose_function": "It gives each guest a dedicated input so the operator can set gain, add processing, and mute the guest independently of the host, keeping every voice at a consistent, controllable level.", "practical_application": "A technician patches the guest mic to its own fader, sets gain for that person's voice, checks it in the mix-minus feed, and assigns a cough or mute button so the guest can be dropped during breaks.", "category": "Studio Microphones", "related_terms": ["Host microphone", "Cough switch", "Mix-minus", "Talkback", "Microphone preamplifier", "On-air light"], "common_mistakes": ["Assuming the guest mic inherits the host channel's gain and processing, and leaving the guest far too quiet or too loud.", "Forgetting to open (unmute) the guest fader before the interview starts, so the guest is not heard on air.", "Not providing the guest a cough or mute control, so unwanted noise gets aired during the show.", "Setting guest gain from the empty studio instead of during actual speech, then having to ride it constantly."], "scenario_contexts": ["Setting up a second mic for an in-studio interview guest with its own fader and mute.", "Adding several guest mics around a round-table discussion, each on its own channel.", "Providing a remote guest position mic feeding a mix-minus so the guest does not hear their own delayed voice."]}, "f66e1609-a68b-4e63-9106-8714b688f8a4": {"definition": "A program feed of an event distributed to broadcasters in other countries that carries the full effects, music, and audience atmosphere but omits the host broadcaster's local-language commentary and announcements. Receiving broadcasters add their own commentary in their own language over this clean audio.", "plain_english": "This is a feed of an event's sound with the local host's talking left out. Stations in other countries take this clean sound. Then they add their own announcers in their own language.", "purpose_function": "It exists so rights-holding broadcasters worldwide can present an event to their own audience by laying their own commentary over a common, complete atmosphere-and-effects mix instead of the originating broadcaster's speech.", "practical_application": "At a major sports or ceremony event, a technician builds a clean international feed that carries pitch, crowd, and music but no home commentary, and routes it to visiting broadcasters' contribution codecs.", "category": "Program Distribution", "related_terms": ["Clean feed", "Mix-minus", "International sound", "Effects mix", "Contribution feed", "Commentary circuit"], "common_mistakes": ["Confusing the international clean feed with the domestic on-air mix and accidentally leaving home commentary in it.", "Forgetting the crowd and effects bed, so foreign broadcasters receive a lifeless feed with no atmosphere.", "Mislabeling feeds at the distribution point so a broadcaster records the wrong mix.", "Assuming 'clean' means music-and-effects only when the event also needs public-address and announcement audio included."], "scenario_contexts": ["Providing crowd-and-effects audio without home commentary to overseas broadcasters at a World Cup match.", "Feeding an international ceremony's clean atmosphere to rights holders who add their own hosts.", "Distributing a concert's clean effects mix so foreign networks can voice their own introductions."]}, "7409f1ea-1a5c-4cb3-9fb0-17d98f3db4c2": {"definition": "A hardware or software device that encodes real-time broadcast audio for transport over IP networks and decodes it at the far end, used for studio-to-transmitter links, remote broadcasts, and studio interconnection. It applies coding schemes such as AAC, Opus, or linear PCM and manages buffering, error concealment, and connection setup over the internet or private IP links.", "plain_english": "This is a box or app that squeezes audio to send it over the internet. Another one at the far end opens it back up. Stations use it to link studios and live sites without a phone line.", "purpose_function": "It carries low-delay, high-quality broadcast audio across ordinary IP networks, replacing legacy circuits so stations can send program and contribution audio over the internet or managed IP links.", "practical_application": "An engineer configures an IP codec at a remote venue, selects an algorithm and bit rate, sets jitter-buffer and connection settings, and dials the studio codec to send the live feed back to air.", "category": "Audio Codecs", "related_terms": ["ISDN codec", "Studio-to-transmitter link", "AES67", "Jitter buffer", "Contribution feed", "Opus"], "common_mistakes": ["Setting the jitter buffer too low for a lossy network, causing dropouts, or too high, adding needless delay.", "Choosing a high-bit-rate algorithm the available upload bandwidth cannot support, so audio breaks up.", "Ignoring network QoS and port forwarding, then failing to establish a stable connection to the studio.", "Assuming both ends must be the same brand when a common standard algorithm would interoperate."], "scenario_contexts": ["Sending a live remote broadcast back to the studio over a venue's internet connection.", "Running a studio-to-transmitter link over a managed IP circuit as a main or backup path.", "Connecting two stations to share a live program feed across cities via IP."]}, "f65fb226-202c-46e6-bfe0-d0bbeda8cdd8": {"definition": "An audio codec that establishes a real-time, low-delay program link over Integrated Services Digital Network (ISDN) telephone circuits, encoding audio with schemes such as ITU-T G.722 or MPEG Layer 2/3 for contribution and remote broadcasts. Two units dial each other over dial-up ISDN B-channels to pass studio-quality audio in both directions.", "plain_english": "This is a box that sends studio-quality audio over a special phone line called ISDN. One box packs the sound, another unpacks it. Radio used it for years to link places before internet codecs took over.", "purpose_function": "It provided reliable, low-latency broadcast-quality audio over switched digital phone lines for remotes, voice-over sessions, and station links before IP codecs became common, offering a dialed connection with predictable quality.", "practical_application": "A technician connects the studio and remote ISDN codecs, matches the coding algorithm and sample rate on both ends, and dials the far unit's ISDN number to open the program link for a live hit or voice session.", "category": "Audio Codecs", "related_terms": ["IP audio codec", "G.722", "Contribution feed", "Remote broadcast", "Studio-to-transmitter link", "Voice-over"], "common_mistakes": ["Mismatching the coding algorithm or sample rate between the two codecs, so the link will not sync or sounds wrong.", "Assuming ISDN service is still readily available when many carriers have retired it in favor of IP.", "Forgetting that both B-channels are needed for the higher-quality modes and dialing only one.", "Not agreeing on which end dials, leaving both units waiting for an incoming call."], "scenario_contexts": ["Linking a voice-over talent's home ISDN codec to a studio for a session.", "Running a live remote broadcast back to the station over a dialed ISDN connection.", "Maintaining a legacy ISDN link as a fallback while migrating to IP codecs."]}, "a1bd9edf-e4b9-404d-b056-c911aa62eab2": {"definition": "A recording of a single source or channel captured separately from the main program mix, commonly called an iso feed, so that the individual element can be reviewed, edited, or remixed on its own later. It is typically split off before the main mix bus so its content is independent of fader moves made for the live program.", "plain_english": "This is a recording of just one source on its own, like a single mic. It is kept apart from the main mix. That way you can fix or reuse that one part later.", "purpose_function": "It preserves individual sources independently of the broadcast mix so producers can re-edit, sweeten, or salvage a specific element after the fact without being locked to the live balance.", "practical_application": "An engineer routes each key mic or camera source to its own recorder track as an iso feed, so a problem line reading or a single instrument can be repaired or remixed in post.", "category": "Program Distribution", "related_terms": ["Multitrack recording", "Direct output", "Program mix", "Mix-minus", "Split feed", "Post production"], "common_mistakes": ["Taking the iso feed post-fader by mistake, so live fader moves and mutes end up baked into the isolated recording.", "Failing to confirm the iso recorder is actually armed and rolling before the event.", "Not labeling iso tracks, making it hard to identify which source is which in post.", "Assuming the main mix can substitute for an iso and losing the ability to fix one element later."], "scenario_contexts": ["Recording each interview mic to its own track so a single guest can be edited later.", "Capturing an iso of a live band's vocal for sweetening before rebroadcast.", "Keeping isolated feeds of every source at a panel event for archive and re-edit."]}, "0d161fed-bf4b-44d6-8e69-af8e155f1233": {"definition": "The station identification a broadcaster is required by regulation to transmit, consisting of its official call sign followed by the community of license, made at natural program breaks near the top of each clock hour. In the United States it is defined by FCC rule 47 CFR 73.1201, and it must be presented in the prescribed form and order.", "plain_english": "This is the short station ID a broadcaster must give by law. In the US it is the call letters and the home city. Stations say it near the top of each hour.", "purpose_function": "It exists so regulators and listeners can positively identify the licensed station on the air, confirming who is transmitting and that the licensee is meeting its identification obligation.", "practical_application": "An operator schedules or reads the legal ID as call sign plus city of license at a natural break close to the top of the hour, and automation systems are programmed to insert it on time.", "category": "Regulatory Compliance", "related_terms": ["Call sign", "Community of license", "Top of hour", "Station identification", "Automation", "Program log"], "common_mistakes": ["Airing a slogan or nickname instead of the required call sign and community of license in the legal ID.", "Missing the top-of-hour window because a long segment or song runs past the natural break.", "Putting the city and call sign in the wrong order or omitting the community of license.", "Assuming a promotional liner counts as the legal ID when it does not meet the regulated form."], "scenario_contexts": ["Programming automation to fire the legal ID at a break just before the top of each hour.", "A live host reading the call sign and city of license coming out of a music set.", "Reviewing the program log to confirm the legal ID aired within the required window."]}, "97d5ec24-4e94-473a-86f8-19b37569c432": {"definition": "A broadcast automation mode in which a live operator drives the show while the automation system handles cued elements such as music, spots, and jingles at the operator's command. It blends manual, real-time presentation with computer-assisted playback, letting the jock start, stop, and reorder elements rather than running fully automated.", "plain_english": "This is software that helps a live host run a radio show. The host talks live, and the system plays songs and ads at a click. It is a mix of live work and computer control.", "purpose_function": "It lets one operator present live while the playout system manages timing and playback of scheduled elements, reducing workload and errors while keeping a human in control of the show's flow.", "practical_application": "A jock works from the automation screen, talking live over intros and clicking to fire the next song, spot, or jingle, while the system tracks the log and timing in live-assist mode.", "category": "Automation", "related_terms": ["Broadcast automation", "Playout system", "Program log", "Voice tracking", "Segue", "Hot clock"], "common_mistakes": ["Confusing live assist with full automation and walking away, leaving elements unfired and dead air on the log.", "Loading the wrong log or clock so scheduled spots and songs play out of order.", "Not previewing the next element, then firing an unexpected or wrong cut on air.", "Ignoring timing to the top of hour and running long into the legal ID window."], "scenario_contexts": ["A morning host running a live show while the playout system fires spots and beds on cue.", "An operator covering multiple stations, taking one live in assist mode during a shift.", "Switching a station from full automation to live assist when a host arrives to go live."]}, "2eff836f-ad9b-4a99-8a25-f85aee2a5cda": {"definition": "The transmission of a musical performance as it happens, capturing the performance with microphones and a mix and sending it to air or online in real time. It applies live-sound and broadcast-mixing craft to deliver a balanced program mix of the performance to a remote audience with minimal delay.", "plain_english": "This is airing a music performance as it happens. Mics and a mixer capture the show. The sound goes out over the air or online in real time.", "purpose_function": "It brings a live performance to a remote audience in real time, requiring a broadcast-quality mix and a reliable contribution path so listeners hear a balanced program as the event unfolds.", "practical_application": "An engineer builds a broadcast mix from the stage or a split of the live console, monitors levels and loudness, and sends the program over a codec or link to the station for real-time airing.", "category": "Program Types", "related_terms": ["Remote broadcast", "Contribution feed", "Split feed", "IP audio codec", "Loudness normalization", "Program mix"], "common_mistakes": ["Sending the front-of-house mix straight to air, which is balanced for the room, not for broadcast.", "Ignoring broadcast loudness targets, so the music airs too hot or too quiet against other programming.", "Relying on a single unmonitored link with no backup, risking dead air if it drops.", "Forgetting to secure music rights and reporting for the broadcast."], "scenario_contexts": ["Broadcasting a concert live to radio from a dedicated broadcast mix off the stage split.", "Streaming a live club set online in real time with a separate broadcast mix.", "Airing a live studio session with a balance built for listeners rather than the room."]}, "380aa186-2271-4e21-94fb-e300b4db7469": {"definition": "An advertisement, sponsor message, or announcement delivered live on air by the host or announcer rather than played from a pre-recorded spot. It is read from a script in real time, often woven into the show, so the endorsement carries the host's own voice and delivery.", "plain_english": "This is an ad the host reads out loud on air, live. It is not recorded ahead of time. Listeners hear the real host say it in the moment.", "purpose_function": "It lets a station air a sponsor message in the trusted voice of its own talent, adding a personal, in-the-moment endorsement that a pre-produced spot cannot match.", "practical_application": "A host reads the sponsor's script live during the show at the scheduled point, and the operator logs the live read for billing and compliance instead of firing a recorded spot.", "category": "On-Air Presentation", "related_terms": ["Spot", "Program log", "Sponsor", "Copy", "Live assist system", "Legal identification"], "common_mistakes": ["Skipping or shortening the scheduled live read, so the sponsor does not get the paid mention.", "Reading outdated or wrong copy because the script was not checked before air.", "Not logging the live read, causing billing and compliance problems.", "Ad-libbing off the approved copy and dropping required disclaimers or claims."], "scenario_contexts": ["A morning host reading a sponsor's live commercial from a script during the show.", "An announcer delivering a live-read promo for a station event between songs.", "Logging a completed live read for the traffic and billing department."]}, "dc04b8d3-a0b8-4b8c-b2af-7a05effdd4f2": {"definition": "The real-time balancing of a musical performance's audio for a live television broadcast, combining stage, vocal, and ambience sources into a program mix delivered to the transmission/air chain while meeting broadcast loudness targets.", "plain_english": "It is mixing music live for a TV show while it airs. The engineer blends the band, singers, and crowd into one balanced sound that goes out right away.", "purpose_function": "Gives viewers a polished, consistent music mix in real time and keeps program loudness within broadcast limits.", "practical_application": "A broadcast mixer builds this on a console during live events such as awards shows or concerts, riding faders and effects as the show happens.", "category": "Broadcast Mixing", "related_terms": ["Live-stream audio mix", "Master control room", "Mobile recording truck", "Off-air monitor", "On-air studio"], "common_mistakes": ["Ignoring broadcast loudness targets so the mix is too loud or too quiet next to other programming", "Burying dialogue or vocals under music and crowd sound", "Not building a backup or safety mix in case a key source fails"], "scenario_contexts": ["Mixing a live awards-show music performance for network TV", "Balancing a house band and audience mics during a late-night talk show", "Sending a music mix from an OB truck to master control"]}, "d56ae00a-df1f-406a-a5fd-e330c939f864": {"definition": "The audio mix prepared specifically for an internet live stream, blending program sources into a stereo or immersive feed sent to the streaming encoder, typically metered to the platform's loudness target and kept separate from the PA or broadcast mix.", "plain_english": "It is the sound mix made just for a live internet stream. It blends the sources into one feed for the stream, which is often different from what the room speakers or a TV feed get.", "purpose_function": "Gives online viewers a clear, balanced sound and holds stream loudness steady, independent of the venue's live PA mix.", "practical_application": "A streaming engineer sets this up on a console send or a separate mixer, feeding the encoder while checking level on headphones and meters.", "category": "Broadcast Mixing", "related_terms": ["Live television music mix", "Off-air monitor", "Master control room", "On-air studio", "Mobile recording truck"], "common_mistakes": ["Sending the raw PA mix to the stream, which often sounds unbalanced to online listeners", "Letting loudness drift so the stream is much louder or quieter than other content", "Not checking mono compatibility for phone listeners"], "scenario_contexts": ["Streaming a church service or concert to an online platform", "Mixing a webcast panel on a separate bus from the room PA", "Feeding a dedicated stream mix to an encoder in an OB truck"]}, "ac777c9c-f529-457f-910c-4593fa6269ee": {"definition": "A broadcast-automation operating mode in which a live operator manually starts each on-air element while the automation system loads, cues, and logs the playlist; a middle ground between fully automated playout and fully manual live operation.", "plain_english": "It is a radio mode where the computer lines up the songs and clips, but a person presses start for each one. The machine does the prep work while the operator controls the timing live.", "purpose_function": "Lets a live host keep hands-on control of pacing and talk-ups while the automation handles queuing, logging, and file playback.", "practical_application": "A board operator uses this during live shows, hitting play or a segue button as the system stands ready with the next scheduled items.", "category": "Broadcast Automation", "related_terms": ["On-air studio", "Master control room", "News insert", "Live assist system", "Broadcast automation"], "common_mistakes": ["Assuming the system will auto-segue and missing a manual start, which causes dead air", "Not watching the queue, so wrong or out-of-order elements play", "Forgetting to reconcile the as-run log after manual changes"], "scenario_contexts": ["A morning-show host driving the board in assist mode during a music sweep", "Manually firing news and weather inserts between automated songs", "Taking manual control to extend a live interview past its scheduled slot"]}, "9401b94e-c327-4428-bae6-576b5878d8ec": {"definition": "The central technical hub of a broadcast facility where program signals from studios, networks, and remote sources are routed, monitored, switched, and readied for transmission to the transmitter or distribution network; the final quality-control point of the air chain.", "plain_english": "It is the control hub of a TV or radio station. Every program signal passes through here to be checked and switched before it goes out to the audience.", "purpose_function": "Acts as the final gatekeeper of the air chain, making sure the correct program, at the right level and quality, reaches the transmitter or network.", "practical_application": "A master control operator watches monitors and meters here, switches sources, inserts commercials and station IDs, and responds to alarms or signal faults.", "category": "Broadcast Facilities", "related_terms": ["On-air studio", "Off-air monitor", "News insert", "Manual assist mode", "Mobile recording truck"], "common_mistakes": ["Confusing master control with a production control room; master control handles transmission, not show production", "Missing a loudness or level problem before it reaches air", "UNSAFE: Assuming transmitter or power gear is de-energized; work on such equipment requires lockout/tagout and station safety procedures"], "scenario_contexts": ["Switching from a network feed to local news at the top of the hour", "Rolling a scheduled commercial break and station ID", "Responding to a loss-of-signal alarm on the air chain"]}, "7f89c198-80d6-4866-aa83-466ec7d6023f": {"definition": "A vehicle outfitted as a self-contained mobile control room for recording or broadcasting events at remote locations, housing mixing consoles, routing, monitoring, communications, and often transmission or recording equipment; also called an outside-broadcast (OB) truck or remote production unit.", "plain_english": "It is a truck built as a rolling control room. Crews drive it to concerts or games and mix, record, or broadcast the event from inside it.", "purpose_function": "Brings a full production and control facility to venues that have no fixed studio, so remote events can be recorded or aired.", "practical_application": "An audio engineer works from the truck's console, taking splits from stage mics and sending finished mixes back to the network or a recorder.", "category": "Broadcast Facilities", "related_terms": ["Master control room", "Live television music mix", "Live-stream audio mix", "On-air studio", "Off-air monitor"], "common_mistakes": ["UNSAFE: Powering the truck from site mains without proper grounding and bonding and a verified safe connection", "Underestimating the cable runs and mic splits needed between stage and truck", "Not coordinating comms and tie-lines with the venue and network early"], "scenario_contexts": ["Broadcasting a live sports game from a stadium compound", "Recording a multitrack concert for later release", "Providing a mobile mix for a remote awards ceremony"]}, "36a35d3c-4340-435c-a416-c572a9d40780": {"definition": "A small, acoustically treated studio space used to record or broadcast spoken news segments, voice-overs, and updates, typically equipped with a microphone, headphones, a small mixer or interface, and a talkback link to the control room.", "plain_english": "It is a small, quiet room for reading the news on air. It has a mic and headphones and keeps outside noise out so the voice sounds clean.", "purpose_function": "Gives news readers an isolated, quiet space so recorded or live voice reports sound clear and free of background noise.", "practical_application": "A reporter or anchor uses the booth to voice bulletins and inserts, cueing off the control room and monitoring their own level in headphones.", "category": "Broadcast Facilities", "related_terms": ["News insert", "On-air studio", "Master control room", "Off-air monitor", "Manual assist mode"], "common_mistakes": ["Working too close to the mic without a pop filter, causing plosives and distortion", "Ignoring room noise such as HVAC that the treatment does not fully block", "Setting the level too hot and clipping the interface"], "scenario_contexts": ["Voicing an hourly radio news update", "Recording a news insert to drop into a later bulletin", "Doing a live two-way with the main studio from the booth"]}, "3ddc78b8-bfd6-4bdc-8e3b-8b4dbfff906c": {"definition": "A pre-recorded or remotely originated news segment, such as a reporter's package, actuality, or bulletin, played into a live program or newscast at a scheduled point in the running order.", "plain_english": "It is a ready-made news clip dropped into a show. The clip, like a reporter's report, plays at a set spot in the running order.", "purpose_function": "Lets stations add prepared or field-sourced news content into live programming without interrupting the studio flow.", "practical_application": "An operator or presenter fires the insert on cue from the playout system or console, then returns to the live studio.", "category": "Broadcast Production", "related_terms": ["News booth", "On-air studio", "Manual assist mode", "Master control room", "Off-air monitor"], "common_mistakes": ["Firing the insert at the wrong time or over live speech", "Not checking the insert's level and loudness against the program", "Forgetting to update the running order so the insert is skipped or doubled"], "scenario_contexts": ["Playing a reporter's package during the evening newscast", "Dropping a recorded news bulletin between automated music tracks", "Rolling an actuality clip during a live interview"]}, "66e59ba4-05fd-4d3d-a170-c58131fc7cfd": {"definition": "A monitoring device or feed that receives and demodulates the station's actual transmitted (off-air) signal, letting operators confirm what is genuinely being broadcast rather than only the console or pre-transmission output; used for confidence and compliance checking.", "plain_english": "It is a receiver that listens to what the station is really putting out on air. It lets staff check the true broadcast, not just the signal before it leaves the building.", "purpose_function": "Confirms the transmitted signal is present and correct, catching faults that occur after the console but before or at the transmitter.", "practical_application": "An operator checks the off-air monitor to verify audio is actually going out, comparing it against the studio feed for delay, dropout, or quality problems.", "category": "Broadcast Monitoring", "related_terms": ["Master control room", "On-air studio", "News insert", "Live-stream audio mix", "Manual assist mode"], "common_mistakes": ["Trusting only the console meter and missing a fault that appears after transmission", "Confusing the delayed off-air return with the live studio feed while talking on air", "Not accounting for the transmission delay when comparing feeds"], "scenario_contexts": ["Verifying the transmitter is passing audio during a live show", "Catching a silent transmitter while the console still shows signal", "Comparing off-air quality after a processing or antenna change"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"5f68c421-408f-4024-b5fa-64791ee9a673": {"definition": "The broadcast studio currently originating live programming and feeding the air chain, equipped with the on-air console, microphones, playout, and monitoring from which presenters host and control the live output.", "plain_english": "It is the studio that is live on air right now. The host sits here and controls the show that listeners or viewers are getting.", "purpose_function": "Serves as the origination point for live programming, giving the presenter the console and tools to control what goes to air.", "practical_application": "A presenter or board operator runs the show from here, opening mics, playing elements, and segueing while monitoring the output.", "category": "Broadcast Facilities", "related_terms": ["Master control room", "News booth", "Off-air monitor", "Manual assist mode", "News insert"], "common_mistakes": ["Leaving a mic open when it should be closed, putting unwanted audio on air", "Not confirming this studio is actually the one switched to air before speaking", "UNSAFE: Ignoring high headphone or monitor levels that risk hearing damage over long shifts"], "scenario_contexts": ["Hosting a live morning radio show", "Anchoring a live TV news segment", "Switching air origination from one studio to another between programs"]}, "94b25fce-134a-4dfc-9e7d-2ea3b9281328": {"definition": "A self-contained package of broadcast equipment—microphones, mixer, monitoring, communications and a transmission or return link—assembled to originate a radio or television program from a location away from the main studio. Commonly abbreviated OB unit; the North American equivalent is the remote broadcast kit or 'remote'.", "plain_english": "It is a portable kit of radio gear that lets a station broadcast from somewhere other than its studio, such as a concert or a sports ground. Think of it as a small studio you can pack up and carry to the event.", "purpose_function": "It lets a station cover live events at the actual location and feed that audio back to base and on to air. It exists so programming is not limited to what happens inside the building.", "practical_application": "A technician sets up and tests the OB unit's mics, mixer and return link before an event, then keeps the feed clean and connected during the live broadcast.", "category": "Remote Broadcasting", "related_terms": ["Outside-broadcast vehicle", "Program source", "Program chain", "Radio control room", "Radio air studio"], "common_mistakes": ["Confusing the outside broadcast unit (the equipment package) with the vehicle that carries it", "Failing to test the return or transmission link before the event, so the feed fails on air", "Assuming studio-grade acoustics on location and not controlling background noise at the mic"], "scenario_contexts": ["Covering a live sports match from the stadium", "Broadcasting a music festival set back to the station", "Reporting live from a news scene or public event"]}, "2e5eea5f-b28a-42c4-a7f0-b906054663a1": {"definition": "A vehicle—van, truck or trailer—fitted out as a mobile control room with mixing, monitoring, power and transmission equipment for producing broadcasts on location. Commonly called an OB van; the closely related North American rig is termed a production or remote truck.", "plain_english": "It is a van or truck built to work like a mobile studio, so a crew can make a broadcast right at an event. It carries the mixing desk, screens, power and links needed to send the show back.", "purpose_function": "It provides a weatherproof, powered, fully equipped workspace so a crew can mix and send a program from the event site. It exists to bring studio capability to places that have none.", "practical_application": "Engineers run cabling from the event into the van, mix the program inside, and manage the link that carries it back to base or the transmitter.", "category": "Remote Broadcasting", "related_terms": ["Outside broadcast unit", "Program source", "Radio control room", "Program chain"], "common_mistakes": ["UNSAFE: Drawing site or generator power without proper grounding and bonding and residual-current (RCD/GFCI) protection, risking shock from a faulted vehicle or cabling", "Confusing the vehicle with the outside broadcast equipment package it houses", "Underestimating cable runs and power capacity for the event"], "scenario_contexts": ["Parking the OB van outside a stadium for a match broadcast", "Producing a live festival broadcast from the vehicle", "Providing a mobile control room for election-night coverage"]}, "d73cb706-4794-4459-bef0-653d7a13a38c": {"definition": "A licensed collection of pre-recorded music beds, sound effects, jingles and stingers kept on hand for producing commercials, promos and station imaging. Also called a production music or sound-effects library.", "plain_english": "It is a stored set of ready-made music clips and sound effects that producers drop into ads and station spots. It is like a pantry of audio ingredients you pull from instead of making each one fresh.", "purpose_function": "It gives producers cleared, ready-to-use audio so spots can be built quickly without recording original music every time. It exists to speed production and keep usage rights clear.", "practical_application": "A producer browses the library for a music bed and effects, drops them under the voice track in the DAW, and mixes the finished spot.", "category": "Production", "related_terms": ["Promo production", "Program source", "Radio air studio", "Radio control room"], "common_mistakes": ["Using a track outside its license terms, creating a rights or clearance problem", "Overusing the same recognizable bed so spots sound repetitive", "Not logging which library cut was used, making later clearance or edits hard"], "scenario_contexts": ["Choosing a music bed for a 30-second commercial", "Pulling a stinger for a station promo", "Adding sound effects to an imaging piece"]}, "28e16b97-c8bd-4c3c-9636-56421d214fd6": {"definition": "The ordered series of equipment a broadcast program signal passes through from its source to the transmitter input—typically mixing, routing, distribution and audio-processing stages. Closely related to, and often used interchangeably with, the term air chain.", "plain_english": "It is the line-up of gear a radio show's sound travels through on its way from the studio to the transmitter. Think of it as a relay race where each piece of equipment hands the audio to the next.", "purpose_function": "It defines the path and order of processing that shapes and delivers the program to air. It exists so each stage—mixing, routing and processing—happens in a known, controlled sequence.", "practical_application": "An engineer traces the program chain stage by stage to find where audio is lost or distorted, checking levels at each point from source to transmitter.", "category": "Air Chain", "related_terms": ["Program source", "Radio announcer chain", "Radio control room", "Outside broadcast unit"], "common_mistakes": ["Confusing the program chain (the whole path to air) with a single processor inside it", "Placing the final loudness or peak processor in the wrong spot, so the transmitter is over- or under-driven", "Chasing a level problem at the desk when the fault is later in the chain"], "scenario_contexts": ["Signal-flow troubleshooting from studio to transmitter", "Adding a new processor and re-checking gain staging along the chain", "Documenting the station's path to air for maintenance"]}, "65ebc907-3aca-4bad-8e39-cd5e797c3bf1": {"definition": "Any origination point of program audio feeding a broadcast system—such as a live microphone, playout automation, a recorded item, a network or satellite feed, or a remote/OB link. Sources are selected and combined at the mixing console or router for air.", "plain_english": "It is anywhere the sound for a show comes from, such as a mic, a computer playout, or a live feed from elsewhere. The studio picks and mixes these sources to build the program.", "purpose_function": "It is the input material a station selects, mixes and sends to air. Naming and managing sources lets operators switch cleanly between what goes on the program bus.", "practical_application": "An operator selects the right program source on the console or router—mic, automation or network feed—and fades between them during the show.", "category": "Air Chain", "related_terms": ["Program chain", "Radio control room", "Outside broadcast unit", "Radio air studio"], "common_mistakes": ["Putting a source to air before confirming it is present and at correct level, causing dead air or a level jump", "Confusing a source with the bus or output it is routed to", "Forgetting a remote or network source carries delay, causing overlaps in handovers"], "scenario_contexts": ["Switching from live mic to automation at the top of the hour", "Taking a network news feed as the program source", "Cueing a recorded item before airing it"]}, "7d2646b7-38a5-4a1b-af55-675254a2b55e": {"definition": "The creation of short promotional announcements—'promos'—that advertise a station's own programs, events or brand, typically combining voice-over, music beds and effects. It is a form of station imaging, distinct from paid commercial (spot) production.", "plain_english": "It is making the short adverts a station runs for its own shows and events. These promos mix a voice, music and effects to get listeners to tune in.", "purpose_function": "It promotes the station's content and identity on its own air. It exists to build audience and reinforce the station's brand between programs.", "practical_application": "A producer works from a script, records the voice-over, and mixes it with a bed and effects in the DAW to build the finished promo.", "category": "Production", "related_terms": ["Production library", "Program source", "Radio air studio", "Radio control room"], "common_mistakes": ["Mixing the promo too quietly or too loudly relative to surrounding audio", "Cluttering a short promo with too much copy so the message is lost", "Confusing self-promos with paid commercial spots in scheduling"], "scenario_contexts": ["Producing a promo for an upcoming morning-show contest", "Creating an imaging sweep between songs", "Cutting a promo for a station-sponsored live event"]}, "e658d28f-049d-44d7-ba94-9ac036209a6b": {"definition": "The studio from which live programming is presented and put to air, containing the on-air console, presenter microphone(s), playout and monitoring. Also called the on-air studio or air room.", "plain_english": "It is the room where the presenter sits and talks live on the radio. It holds the mixing desk, mic and playout used to run the show as it goes out.", "purpose_function": "It is the working space where live programming is presented and controlled in real time. It exists to give the presenter everything needed to run the show and put it to air.", "practical_application": "A presenter or operator runs the show from the air studio—opening the mic, playing items and watching levels—while it broadcasts.", "category": "Broadcast Facilities", "related_terms": ["Radio control room", "Radio announcer chain", "Program source", "Program chain"], "common_mistakes": ["Leaving the microphone open when it should be closed, putting off-air talk to air", "Confusing the air studio (on-air) with a production studio (offline)", "Poor acoustic treatment letting room reflections colour the presenter's mic"], "scenario_contexts": ["Presenting a live morning show", "Reading a news bulletin on air", "Hosting a live phone-in from the air studio"]}, "a52456ce-7c75-47b8-97f9-6f467fbfbf60": {"definition": "The signal-processing chain applied to a presenter or announcer microphone—typically preamp followed by de-esser, compressor, equalizer and gating—used to make the voice consistent and intelligible before it reaches the console or air. Also called the voice or mic-processing chain.", "plain_english": "It is the set of processors a presenter's mic passes through to make the voice clear and even. Like tuning a voice, it smooths loud and quiet parts and cuts harsh sounds before it goes on air.", "purpose_function": "It shapes and controls the announcer's voice so it stays clear, even and easy to hear over music and effects. It exists to keep spoken word consistent from presenter to presenter and moment to moment.", "practical_application": "An engineer sets the compressor, EQ and de-esser on the announcer chain to suit a presenter's voice, then saves it as a recallable preset for that person.", "category": "Air Chain", "related_terms": ["Program chain", "Radio air studio", "Program source", "Radio control room"], "common_mistakes": ["Over-compressing the voice so it sounds pumped and fatiguing", "Skipping the de-esser and letting sibilance become harsh on air", "Setting the chain for one voice and forgetting to recall the right preset for another presenter"], "scenario_contexts": ["Dialing in mic processing for a new presenter", "Taming sibilance on a bright voice", "Saving per-presenter voice presets on the console"]}, "e3fc3ce9-b949-4a69-ae22-b033680091b0": {"definition": "The technical room in a radio station where program audio is mixed, routed, monitored and sent toward the transmitter, housing the console, routing, processing and monitoring equipment. In small stations it may be combined with the air studio; in larger ones it is a separate technical operations area.", "plain_english": "It is the technical room where a station's sound is mixed, checked and sent on toward the transmitter. Think of it as the control center that keeps everything going out cleanly.", "purpose_function": "It centralizes mixing, routing and monitoring so program audio can be controlled and sent to air from one place. It exists to give operators command of the station's signal flow.", "practical_application": "An operator or engineer works from the control room to route sources, monitor levels and keep the program feeding correctly to the transmitter.", "category": "Broadcast Facilities", "related_terms": ["Radio air studio", "Program chain", "Program source", "Radio announcer chain"], "common_mistakes": ["Confusing the control room with the on-air studio in stations where they are separate", "Not monitoring off-air (post-transmitter) audio, so a downstream fault goes unnoticed", "Mis-routing a source and putting the wrong feed to air"], "scenario_contexts": ["Routing and monitoring program feeds to the transmitter", "Handling a source changeover during live programming", "Diagnosing an on-air audio fault from the control room"]}, "5f921e90-1e78-47fd-9f93-cc4893c7947e": {"definition": "A production session dedicated to creating a station's imaging elements: the branded sweepers, station IDs, stingers, promos, and voiced transitions that give a radio station its recognizable on-air identity. Voice takes are recorded and layered with music beds and effects, then edited and processed into finished short-form audio for insertion into the air chain.", "plain_english": "A studio session where a team makes the short branded clips you hear between songs. These include station name jingles and voice drops that give the station its own sound.", "purpose_function": "It produces the short branded audio pieces that identify the station and tie its programming together, reinforcing listener recognition and format consistency between songs and segments.", "practical_application": "A production engineer records a voice actor, layers the take over music beds and effects in a DAW, and exports finished imaging cuts that are loaded into the automation or playout system for on-air use.", "category": "Radio Production", "related_terms": ["Radio production studio", "Recorded spot", "Voice tracking", "Sweeper", "Air chain", "Station ID"], "common_mistakes": ["Confusing imaging (station branding elements) with commercial spots (paid advertising); they serve different purposes.", "Recording voice takes too hot or without processing, so the imaging does not sit cleanly over the music bed.", "Failing to match imaging loudness to the station's on-air processing, so drops sound weak or distorted on air."], "scenario_contexts": ["Producing a new set of station IDs and sweepers when a station rebrands or changes format.", "Recording a guest voice actor for seasonal promos and layering them over music beds.", "Refreshing daily transition drops and stingers loaded into the automation system."]}, "0c6225c3-3399-4ed0-8e81-9189de814434": {"definition": "A dedicated studio space used to produce recorded audio (commercials, promos, imaging, and voice tracks) separately from the live on-air studio. It typically houses a mixing console or DAW, microphone, monitors, and audio processing, and is acoustically treated so recordings are clean and not broadcast live.", "plain_english": "A room set up for recording and editing radio audio, like ads and station clips. It is kept apart from the live on-air room so this work does not go out over the air.", "purpose_function": "It gives staff a controlled space to record and mix content without tying up or interfering with the on-air studio, keeping production work off the live broadcast.", "practical_application": "An engineer books the room between shifts to cut voice tracks, edit spots, or mix a pre-recorded segment, then exports the finished audio to the playout system.", "category": "Studio Facilities", "related_terms": ["Radio production studio", "Radio studio", "Recorded spot", "Radio imaging session", "Voice tracking", "Air chain"], "common_mistakes": ["Assuming the production room feeds the air directly; its output is recorded and scheduled, not broadcast live.", "Neglecting acoustic treatment, so recorded voice picks up room reflections and noise.", "Leaving monitor levels uncalibrated, so mixes translate poorly to the on-air chain."], "scenario_contexts": ["Recording and editing a batch of commercial spots between on-air shifts.", "Cutting voice tracks for an announcer's automated evening show.", "Producing a sponsored feature or interview away from the live studio."]}, "4e31e3bf-ae4f-4fa4-93c0-ee19340d3666": {"definition": "A studio equipped for producing recorded radio content (spots, imaging, promos, and pre-recorded segments) as opposed to originating live broadcasts. It centers on a DAW or production console with microphone, monitoring, and processing for recording, editing, and mixing finished audio.", "plain_english": "A studio built for making recorded radio audio instead of going live on air. Engineers record voices and mix ads, promos, and shows in it.", "purpose_function": "It provides the equipment and acoustic environment for creating polished recorded content, separating production work from the live origination done in the on-air studio.", "practical_application": "A producer records and edits interviews, spots, and imaging here, then delivers the finished files to traffic and automation for scheduled airing.", "category": "Studio Facilities", "related_terms": ["Radio production room", "Radio studio", "Radio imaging session", "Recorded spot", "Radio show production", "Voice tracking"], "common_mistakes": ["Treating it as interchangeable with the on-air studio; it is optimized for recording, not live origination.", "Skipping gain staging on the DAW or console and clipping recorded takes.", "Exporting at the wrong sample rate or level for the playout system."], "scenario_contexts": ["Producing imaging and promos for the station's brand.", "Mixing a pre-recorded interview program for later airing.", "Editing and sweetening voice tracks and commercials."]}, "9c7f1c5a-aa62-442a-ac50-633f20fddcf6": {"definition": "The capture of a radio program as a finished audio recording for later broadcast rather than airing it live. It lets the program be edited, quality-checked, and scheduled into the playout system for transmission at the intended time.", "plain_english": "Recording a full radio show ahead of time so it can be played later. This lets the team edit it and air it in the right slot.", "purpose_function": "It lets stations prepare polished programs in advance, control airtime scheduling, and archive or rebroadcast content, separating production from the moment of transmission.", "practical_application": "An engineer records a host and guests in the studio, edits out mistakes and gaps, then loads the finished file into automation to air in its scheduled slot.", "category": "Radio Production", "related_terms": ["Radio show production", "Radio production studio", "Recorded spot", "Air chain", "Voice tracking", "Playout system"], "common_mistakes": ["Recording without headroom and clipping the program master.", "Failing to slate or log takes, making editing and scheduling error-prone.", "Not matching loudness targets, so the pre-recorded program is louder or quieter than surrounding content."], "scenario_contexts": ["Pre-recording a weekend interview show for airing while staff are off.", "Capturing a live concert or event for delayed broadcast.", "Recording a program for distribution to affiliate stations."]}, "eb6baed4-8463-4453-b548-2641dcc7b848": {"definition": "The end-to-end process of creating a radio show: planning content and segments, recording or hosting the audio, and editing, mixing, and adding imaging to produce a finished program for broadcast, whether aired live or pre-recorded.", "plain_english": "The whole job of planning, recording, and editing a radio show. It turns raw ideas and clips into a finished program ready to air.", "purpose_function": "It organizes talent, content, and audio elements into a coherent, well-paced program that fits the station's format and airtime.", "practical_application": "A producer scripts segments, coordinates hosts and guests, runs or records the session, then edits and sweetens the audio before it airs or is scheduled.", "category": "Radio Production", "related_terms": ["Radio program recording", "Radio production studio", "Radio imaging session", "Recorded spot", "Voice tracking", "Air chain"], "common_mistakes": ["Under-planning segment timing, so the show runs long or short against the clock.", "Ignoring level and loudness consistency between voice, music, and inserts.", "Keeping no backup recording of a live show for reair or correction."], "scenario_contexts": ["Producing a daily morning-drive show with hosts, calls, and features.", "Assembling a themed music program with voiced links and imaging.", "Coordinating a talk show with live guests and pre-recorded packages."]}, "39a6110b-f830-4a5d-95ad-d648756fc27d": {"definition": "The on-air studio from which a radio broadcast originates, housing the broadcast (air) console, announcer microphones, playout and automation, source equipment, and monitoring. It is the origination point of the air chain, where live and automated program audio is mixed and routed toward the transmitter.", "plain_english": "The room where a radio broadcast comes from, with the mic, mixing desk, and playback gear. This is where the host talks live to listeners.", "purpose_function": "It provides the controlled, acoustically treated environment and signal-routing hub where program audio is created and sent into the broadcast chain.", "practical_application": "An announcer operates the air console here, opening the mic, firing spots and music from the playout system, and monitoring the air signal while an engineer maintains levels and routing.", "category": "Studio Facilities", "related_terms": ["Radio production studio", "Air chain", "Recorded spot", "Playout system", "Broadcast console", "Radio program recording"], "common_mistakes": ["Confusing the on-air studio with the production studio; only the air studio originates live broadcasts.", "Leaving the microphone open (live) while cueing or talking off-air.", "Poor gain staging on the air console, sending over-processed or distorted audio to the transmitter."], "scenario_contexts": ["Hosting a live on-air shift, mixing mic, music, and spots to air.", "Running automated programming overnight from the studio's playout system.", "Conducting a live in-studio interview broadcast to listeners."]}, "817708c8-e3c3-4ed9-bd2e-b69ff4f8dadc": {"definition": "A pre-recorded radio commercial or announcement stored as a finished audio file and played from the automation or playout system during scheduled breaks, rather than read live by an announcer. Spots are typically fixed-length (for example 15, 30, or 60 seconds) and produced with voice, music, and effects.", "plain_english": "A pre-recorded ad or short message saved as an audio file. The station plays it during breaks instead of reading it live.", "purpose_function": "It delivers paid advertising or station messaging consistently and at a controlled length, ensuring the client's approved content airs exactly as produced without a live read.", "practical_application": "A production engineer produces the spot in a DAW, exports it to the traffic and automation system at the correct length and loudness, and it plays automatically in the scheduled commercial break.", "category": "Radio Production", "related_terms": ["Radio imaging session", "Radio production studio", "Air chain", "Playout system", "Voice tracking", "Radio program recording"], "common_mistakes": ["Delivering a spot that is off-length (for example 32 seconds for a 30-second slot), causing it to be clipped or to overlap.", "Ignoring broadcast loudness standards so the spot is noticeably louder than programming.", "Overwriting or mislabeling spot files, causing the wrong or an expired ad to air."], "scenario_contexts": ["Producing a 30-second client commercial for a scheduled ad break.", "Loading a batch of dealer spots into the traffic system for the week.", "Replacing an expired promotional spot with a new campaign."]}, "82e044e4-3aa0-4b89-b4b6-58c0f4d2405d": {"definition": "A hardware or software audio codec used to encode and transport program audio between a remote location and the studio over IP, ISDN, or POTS links, and decode it at the far end. It applies low-latency compression (such as AAC, Opus, aptX, or MPEG) with error concealment so a broadcast-quality contribution feed can travel over networks with limited or variable bandwidth.", "plain_english": "A box that squeezes audio so it can travel over a phone or internet link from an outside event back to the station. It also unpacks the audio at the other end so it sounds clear on air.", "purpose_function": "It lets a station send or receive broadcast-quality audio to and from the field over ordinary networks, making live remotes and contribution feeds possible without a dedicated broadcast circuit.", "practical_application": "An engineer connects a portable codec (such as a Comrex, Telos, or Tieline unit) at a remote site to an IP or cellular network, connects to a matching codec at the studio, and sends the on-site mix back for air.", "category": "Broadcast Equipment", "related_terms": ["Remote production unit", "Air chain", "Radio studio", "Contribution feed", "IP audio", "Latency"], "common_mistakes": ["Mismatching the algorithm or settings between ends, so the link will not connect or the audio is garbled.", "Ignoring network jitter and buffer settings, causing dropouts on a live remote.", "Underestimating end-to-end latency and creating awkward delays during two-way on-air conversations."], "scenario_contexts": ["Sending a live sports play-by-play mix from a stadium back to the studio.", "Connecting a remote broadcast from a client's business over cellular IP.", "Receiving a syndicated host's contribution feed from another city."]}, "4b1b054c-49ae-4b85-8552-d6c170d4a7b3": {"definition": "A self-contained package of broadcast equipment, ranging from a portable field kit to a fully equipped outside-broadcast (OB) vehicle, used to originate radio (or TV) programming from a location away from the main studio. It typically includes microphones, a mixing console, audio processing, monitoring, power distribution, and a remote codec or link back to the studio.", "plain_english": "Gear or a vehicle that lets a crew broadcast from outside the station, like a concert or a game. It carries the mics, mixer, and link gear needed to send audio back home.", "purpose_function": "It provides the mixing, monitoring, and transmission capability needed to capture and send a professional broadcast from the field, extending the studio's production reach to live events and locations.", "practical_application": "A crew deploys the unit to an event, sets up mics and the mixer, links back to the studio through a codec, and produces the on-site portion of the broadcast.", "category": "Broadcast Equipment", "related_terms": ["Remote broadcast codec", "Radio studio", "Air chain", "Outside broadcast", "Contribution feed", "Radio show production"], "common_mistakes": ["Failing to confirm connectivity (IP or cellular) and audio return before going live.", "UNSAFE: Powering the unit from unverified or ungrounded mains or generator sources without proper grounding and GFCI/RCD protection, risking shock or equipment damage.", "Carrying no backup link or power, so a single failure takes the remote off air."], "scenario_contexts": ["Broadcasting a live morning show from a sponsor's storefront.", "Covering a festival or sporting event from the field.", "Setting up an election-night or emergency remote from a public venue."]}, "8b653777-304b-49df-ac3e-b2e3fb2d0396": {"definition": "A device or software function in the broadcast air chain that monitors program audio and triggers an alarm or automatic action when the level falls below a set threshold for a defined time, indicating unintended dead air. Recovery actions can include switching to a backup audio source, alerting staff, or logging the fault.", "plain_english": "It listens to what the station is putting on air. If the sound drops out for too long, it sets off an alarm or plays a backup so the station is not left silent.", "purpose_function": "It detects prolonged dead air caused by a fault upstream and prompts recovery, so the station does not broadcast long stretches of silence unnoticed.", "practical_application": "An engineer sets the level threshold and time delay, wires the detector to switch to a backup playlist or alert on-call staff, and tests it during maintenance.", "category": "Broadcast Equipment", "related_terms": ["Dead air", "Studio-transmitter link", "Air chain", "Automation", "Backup audio"], "common_mistakes": ["Setting the silence threshold so high that quiet passages trigger false alarms.", "Setting the delay so long that noticeable dead air airs before any action is taken.", "Assuming the detector fixes the fault when it only alerts to it or switches sources."], "scenario_contexts": ["Overnight automation stalls and the detector switches to a backup playlist.", "A satellite or network feed drops and the detector alerts the on-call engineer.", "A studio source fails and the detector logs the silence for review."]}, "204d28fa-963e-4c46-a2dd-8c3b768ed3c6": {"definition": "A single audio mix prepared for simultaneous broadcast across two or more outlets or formats, such as television and radio, or FM and a webstream. It is balanced so the same content and levels work within the technical constraints of every distribution path at once.", "plain_english": "One sound mix made to go out on more than one channel at the same time, like radio and TV together. It has to sound right on all of them at once.", "purpose_function": "It lets one program air on several platforms at once while keeping content and loudness correct for each, avoiding the cost and mismatch of separate mixes.", "practical_application": "A broadcast mixer folds a stereo or surround mix so it also translates to the radio simulcast, checking mono compatibility and meeting each outlet's loudness target.", "category": "Radio Production", "related_terms": ["Loudness normalization", "Mono compatibility", "Downmix", "Air chain", "Stadium ambience array"], "common_mistakes": ["Skipping the mono compatibility check, so the radio simulcast loses key content or cancels out.", "Mixing only for one platform's loudness target and leaving the others too loud or too quiet.", "Forgetting that a surround mix must fold down cleanly for the radio outlet."], "scenario_contexts": ["A televised concert also carried live on FM radio from one mix.", "A sports broadcast fed to TV, radio, and a streaming app at the same time.", "An awards show simulcast on a network and its companion webstream."]}, "f3f43c4d-703a-4cbe-bab7-90b3ffacdef1": {"definition": "A set of microphones placed around a stadium or arena to capture crowd noise and venue ambience for a sports or event broadcast. Their signals are combined into an ambience bed that sits under the commentary and on-field effects microphones.", "plain_english": "A group of microphones spread around a stadium to pick up the crowd and the sound of the place. Mixed together, they make the broadcast feel like you are really there.", "purpose_function": "It captures the sense of the live venue, crowd reaction and room sound, so the broadcast feels immersive rather than dry and distant.", "practical_application": "A broadcast mixer places and levels several crowd microphones around the bowl, riding them up to lift the ambience during big moments without burying the commentators.", "category": "Broadcast Production", "related_terms": ["Effects microphone", "Commentary mix", "Ambience bed", "Simulcast audio mix", "Air chain"], "common_mistakes": ["Pushing crowd microphones so hot that commentary becomes hard to hear.", "Placing microphones where they mainly pick up the venue PA rather than the crowd.", "Ignoring phase problems when many spaced microphones are summed together."], "scenario_contexts": ["A televised football match where crowd noise swells after a goal.", "A basketball broadcast lifting arena ambience during a close finish.", "A concert broadcast needing audience response captured between songs."]}, "36bf4679-0c72-42b6-b77b-836e92462e1e": {"definition": "The on-air announcement that identifies a broadcast station by its call sign and community of license. In the United States, FCC rules require an official station identification at the beginning of each hour of operation, made at a natural programming break near the top of the hour.", "plain_english": "The short on-air message that tells listeners which station they are hearing, using its call letters and city. Stations must give it by law at set times.", "purpose_function": "It legally identifies the licensed station to listeners and regulators at required times and reinforces the station's brand on air.", "practical_application": "Engineers and automation schedule the legal ID to fire close to the top of each hour, and live hosts make sure it airs even during continuous programming.", "category": "Broadcast Regulation", "related_terms": ["Call sign", "Stopset", "Sweep production", "Automation", "Air chain"], "common_mistakes": ["Confusing a branded promo or sweeper with the required legal identification.", "Airing the legal ID outside the required window near the top of the hour.", "Leaving the community of license out of the official identification."], "scenario_contexts": ["Automation fires the legal ID at 11:59 just before the news.", "A live host reads the station ID at the top of the hour.", "An engineer verifies the ID timing during a compliance review."]}, "ef74499d-16ad-43ff-b42c-3a628bbd299d": {"definition": "A scheduled cluster of non-program content, such as commercials, promos, and sponsor messages, aired together as a single break between segments of programming on a radio station. Stopsets are placed at planned positions in the hourly clock.", "plain_english": "A commercial break on the radio: the block where ads and promos all play in a row. The programming stops for it, then picks back up.", "purpose_function": "It groups paid and promotional spots into planned breaks so program segments run uninterrupted and airtime is sold and scheduled efficiently.", "practical_application": "Traffic and programming staff build stopsets into the log, and live hosts or automation trigger them at set clock positions each hour.", "category": "Programming", "related_terms": ["Traffic insert", "Sweep production", "Hot clock", "Recorded spot", "Station identification"], "common_mistakes": ["Running a stopset long so the hour drifts off its scheduled clock.", "Stacking too many spots in one break and driving listeners away.", "Airing spots in the wrong stopset compared with the log."], "scenario_contexts": ["A music station plays a four-minute stopset at :20 and :50 each hour.", "Automation rejoins network programming right after the local stopset.", "A host counts down to the stopset before a segue."]}, "860a04e4-5f86-473a-b896-06d263198a08": {"definition": "The communication link that carries a station's program audio, and often control and telemetry data, from the studio to the transmitter site. It may be implemented over a licensed aural microwave path (in the US, the 950 MHz band), a leased line, an IP network, or another transport, usually with a backup path.", "plain_english": "It carries the station audio from the studio to the transmitter. The transmitter is often far away. The link can run over a radio hop or over the internet.", "purpose_function": "It reliably delivers finished program audio from where it is produced to the transmitter that broadcasts it, since the two are usually in different locations.", "practical_application": "An engineer installs and monitors the STL, whether a licensed 950 MHz microwave path or an IP codec link, and keeps a backup path so audio keeps reaching the transmitter.", "category": "Broadcast Equipment", "related_terms": ["Air chain", "Transmitter", "Silence detector", "Remote broadcast codec", "Backup audio"], "common_mistakes": ["UNSAFE: Working near STL antennas or the transmitter without observing RF exposure limits and lockout/tagout procedures.", "Running no backup STL path, so any single failure results in dead air.", "Ignoring the latency difference between the main and backup STL when switching."], "scenario_contexts": ["A 950 MHz microwave STL carries FM program audio to a mountaintop transmitter.", "An IP codec STL fails over to a backup internet path during an outage.", "An engineer aligns a new microwave STL dish during a site upgrade."]}, "a1c275e1-a0c4-4b4a-bd48-87fe82680b77": {"definition": "The production of sweeps: short, produced station-imaging elements built from music beds, sound design, and voiceover that transition between songs or segments while reinforcing the station brand without a full stop in programming.", "plain_english": "Making the quick station clips that play between songs. They mix a voice, music, and sound effects to keep the flow going and remind you which station you are on.", "purpose_function": "It keeps programming moving and branded across transitions, tying songs together and reinforcing station identity between stopsets.", "practical_application": "An imaging producer builds sweeps in a DAW, timing the voiceover to a song's intro ramp so the voice ends just as the vocal begins.", "category": "Radio Production", "related_terms": ["Station identification", "Radio imaging session", "Sweeper", "Stopset", "Voice tracking"], "common_mistakes": ["Timing the sweep so the voice talks over the vocal of the next song.", "Making sweeps so long they slow down the segue.", "Leaving loudness inconsistent between the sweep and the surrounding music."], "scenario_contexts": ["A hit-music station runs a produced sweep over each song intro.", "An imaging producer cuts a themed sweep package for a holiday weekend.", "A programmer refreshes daily sweeps to match a format change."]}, "c27d02fd-b1b3-4142-9de7-16974201a242": {"definition": "An on-air element that states the current time to listeners, delivered live by a presenter or as an automated or produced time check. It is often placed at set points in the hour and is sometimes sponsored.", "plain_english": "The moment on air when the current time is given, like saying it is now 8:15. A host may read it, or it can be automated.", "purpose_function": "It gives listeners a regular time reference, which serves commuters during drive time and reinforces the station's live, local feel.", "practical_application": "Presenters give time checks at set points each hour, and automation can insert a spoken or produced time announcement tied to the station clock.", "category": "Programming Element", "related_terms": ["Station identification", "Sweep production", "Traffic insert", "Hot clock", "Automation"], "common_mistakes": ["Reading a time check that is wrong because the studio clock has drifted.", "Giving time checks so often that they clutter the break.", "Airing a pre-recorded time announcement at the wrong minute."], "scenario_contexts": ["A morning host gives frequent time checks for commuters.", "A sponsored time announcement airs just before the traffic report.", "Automation inserts a time check tied to the on-air clock overnight."]}, "c2e8bc21-e674-46f5-868b-d001f65ba0ba": {"definition": "A road-traffic report inserted into a station's programming at scheduled times, covering current road and commute conditions. It is often supplied by a traffic-reporting service or read by staff and placed at fixed positions in the hourly clock, such as on the tens.", "plain_english": "A short road-traffic report dropped into the broadcast at set times. It tells drivers about jams, crashes, and delays, often on a regular schedule.", "purpose_function": "It gives listeners timely commute information at predictable points in the hour, serving drive-time audiences and often carrying sponsorship.", "practical_application": "A producer schedules traffic inserts at fixed clock positions and cues the reporter or automation to drop the report in ahead of the stopset.", "category": "Programming Element", "related_terms": ["Time announcement", "Stopset", "Hot clock", "Station identification", "Automation"], "common_mistakes": ["Airing stale traffic information that no longer matches actual road conditions.", "Placing the insert off its scheduled clock position so listeners miss it.", "Confusing the on-air traffic report with the traffic (commercial scheduling) log."], "scenario_contexts": ["A morning show runs traffic inserts every ten minutes during rush hour.", "A sponsored traffic report airs just before the top-of-hour news.", "Automation drops a service-supplied traffic report into the drive-time clock."]}, "b7ad9f26-a80d-4d28-9cdb-31b23a9311c0": {"definition": "The complete signal path a broadcast program travels from the studio output, through audio processing and the studio-to-transmitter link, to the transmitter and antenna that radiate it to receivers. It is frequently used interchangeably with 'air chain.'", "plain_english": "It is the whole path a radio show takes from the studio to your radio. The sound moves through a line of gear, one box after another, until an antenna sends it out.", "purpose_function": "It defines every stage the program signal must pass through to reach listeners, so engineers can design, align, and troubleshoot the broadcast path as one connected system.", "practical_application": "A broadcast engineer traces the transmission chain stage by stage to find where audio is lost, distorted, or delayed when the station sounds wrong on air.", "category": "Air Chain", "related_terms": ["Transmission feed", "Transmission monitoring", "Studio-to-transmitter link", "Audio processing", "Transmitter", "Modulation"], "common_mistakes": ["Thinking the transmission chain is just the transmitter, when it also includes studio processing, the STL, and the antenna", "Assuming a fault heard on air is at the studio, when it can be at any point along the chain", "Overlooking gain staging between stages, which causes overmodulation or a weak, noisy signal"], "scenario_contexts": ["Commissioning a new FM station and aligning levels through every stage of the chain", "Diagnosing distorted audio reported by listeners by testing each link in turn", "Documenting the full signal path for a station's technical records"]}, "14af7dff-c964-47d5-83cb-6dbc3d20a090": {"definition": "The program audio signal delivered from the studio to the transmitter site for broadcast, typically carried over a studio-to-transmitter link (STL) such as a dedicated radio hop, IP circuit, or leased line.", "plain_english": "This is the sound sent from the studio out to the transmitter so it can go on air. Think of it as the pipe that carries the show to the tower.", "purpose_function": "It carries the finished program from where it is made to where it is broadcast, keeping the two sites connected even when they are miles apart.", "practical_application": "An engineer checks the transmission feed for level, silence, or dropouts to confirm the transmitter is receiving clean program audio before it goes to air.", "category": "Air Chain", "related_terms": ["Studio-to-transmitter link", "Transmission chain", "Transmission monitoring", "Program feed", "Silence detection", "Codec"], "common_mistakes": ["Confusing the transmission feed (studio to transmitter) with the off-air signal that returns for monitoring", "Running with no backup feed, so a single link failure takes the station off air", "Ignoring codec delay, which can cause timing problems with backup or split feeds"], "scenario_contexts": ["Switching to a backup IP feed when the main STL radio link fails", "Setting reference levels on the feed so the transmitter is correctly modulated", "Troubleshooting dead air traced to a lost feed between studio and transmitter"]}, "41f38ed4-8465-460c-8711-1e05fc301004": {"definition": "The practice of continuously checking a station's transmitted output — modulation, signal quality, and transmitter status — usually by receiving the off-air signal and reading modulation and telemetry meters to confirm quality and regulatory compliance.", "plain_english": "This means keeping an eye on what the station is actually putting out over the air. Staff listen to the station's live off-air signal and watch meters to catch faults as they happen.", "purpose_function": "It confirms that what listeners receive is clean, loud enough, and within legal limits, and it warns staff quickly when the transmitter or feed fails.", "practical_application": "An engineer watches a modulation monitor, an off-air receiver, and remote telemetry to spot overmodulation, silence, or transmitter faults and respond before listeners are affected.", "category": "Air Chain", "related_terms": ["Modulation monitor", "Off-air monitoring", "Transmission chain", "Transmission feed", "Telemetry", "Overmodulation"], "common_mistakes": ["Monitoring only the studio output and assuming the transmitted signal matches it", "Allowing overmodulation, which distorts the signal and interferes with adjacent channels in breach of regulations", "Relying on a single monitor point with no alarm, so faults go unnoticed"], "scenario_contexts": ["Watching modulation meters during a loud live broadcast to stay within legal peak deviation", "Receiving a remote alarm that the off-air signal has gone silent", "Verifying signal quality after transmitter maintenance"]}, "4e82cea0-b110-40f1-a6ea-a712a35c217b": {"definition": "The room at a station or transmitter site that houses the transmitter and its supporting equipment — exciter, power supplies, patching, monitoring, and antenna feed — where the broadcast signal is generated and sent to the antenna.", "plain_english": "This is the room that holds the transmitter and its gear. It is where the signal gets its power and is passed up to the antenna.", "purpose_function": "It gives the transmitter and related high-power equipment a controlled, secure space with proper cooling, power, and grounding so the station can stay on air reliably.", "practical_application": "A technician enters the transmission room to inspect the transmitter, check cooling and meters, and carry out maintenance under the site's electrical safety procedures.", "category": "Broadcast Facility", "related_terms": ["Transmitter", "Transmission chain", "Antenna", "Studio-to-transmitter link", "Exciter", "Dummy load"], "common_mistakes": ["UNSAFE: Working on or near an energized transmitter without following lockout/tagout and confirming high-voltage supplies are de-energized and discharged", "UNSAFE: Ignoring RF exposure limits when working near an energized antenna feed or transmission line", "Confusing the transmission room at the transmitter site with the studio control room"], "scenario_contexts": ["Performing scheduled transmitter maintenance during a low-listenership overnight window", "Responding to a high-temperature alarm in the transmission room", "Switching to a backup transmitter after a main transmitter fault"]}, "9bd532bc-993a-4153-97bb-5d501702468f": {"definition": "A radio production technique in which a presenter pre-records the spoken links — introductions, back-announcements, and talk breaks — that will play between songs and other elements, so an automation system can assemble them into a broadcast that sounds live.", "plain_english": "This is when a radio host records their talking bits ahead of time. A computer later drops them between the songs, so the show sounds live even though it was not.", "purpose_function": "It lets one presenter quickly produce many hours of local-sounding radio, or program several stations, without staying live on air the whole time.", "practical_application": "A presenter loads the upcoming music log, records each link while hearing the song intros and endings, and the automation system plays the links back in sequence on air.", "category": "Radio Production", "related_terms": ["Automation system", "Playout system", "Music log", "Back-announce", "Segue", "Dead air"], "common_mistakes": ["Referring to songs or events by absolute clock time, which breaks when the log shifts", "Recording links that clash with song intros or endings because the presenter did not hear the transitions", "Leaving gaps or dead air between tracked links and the music elements"], "scenario_contexts": ["Pre-recording an evening show so a daytime presenter can voice both", "Voicing local links for several networked stations from one studio", "Recording weekend programming in advance so no live staff are needed"]}, "9e093137-c156-4b58-ae14-b105fcea8c99": {"definition": "A short weather report segment placed into a broadcast at scheduled points, often pre-recorded or delivered as a live update, and dropped into the program by the presenter or the automation system.", "plain_english": "This is a quick weather update slotted into a radio show. It can be recorded early or read live, and it plays at set times.", "purpose_function": "It gives listeners timely local weather at predictable points in the schedule without breaking up the main flow of programming.", "practical_application": "A producer records or cues a weather insert and schedules it in the playout log, or a presenter reads it live at the top of the hour.", "category": "Radio Production", "related_terms": ["Voice tracking session", "Automation system", "Playout system", "News insert", "Cart", "Segue"], "common_mistakes": ["Airing a pre-recorded weather insert whose forecast is already out of date", "Scheduling or labeling the insert so the wrong region's weather plays", "Leaving level or timing mismatches so the insert clashes with the surrounding audio"], "scenario_contexts": ["Dropping a live weather update into a morning drive show", "Scheduling automated hourly weather inserts overnight", "Updating a pre-recorded forecast when conditions change suddenly"]}, "8634c6ea-40dc-4153-8fd1-4151df253798": {"definition": "A production space configured to capture audio (and usually video) and deliver it in real time to online viewers, pairing a conventional studio's acoustically treated room, microphones, mixing console or audio interface and monitoring with a dedicated streaming signal chain. That added chain routes the program mix to an encoder, which compresses it into a chosen codec and bitrate and sends it over an internet connection to a streaming platform or content delivery network.", "plain_english": "A streaming studio is a room set up to send live sound and video to people watching online. It has normal studio gear like mics, a mixer and speakers. It also has a device called an encoder that packs the audio into a small stream and pushes it out over the internet. Think of it as a small live TV station you can run from one room.", "purpose_function": "It exists to turn a live or recorded performance into a broadcast-quality online stream from a single controlled space, so the audio and video reach a remote audience in real time with consistent quality. Bringing capture, mixing, monitoring and encoding into one room lets an operator control the whole signal chain rather than depending on a venue or an outside service.", "practical_application": "A technician uses a streaming studio to run live shows, podcasts, webinars or concerts, setting mic and instrument levels on the console, sending a dedicated stream mix to the encoder, and checking the outgoing bitrate, codec and connection so the audience hears clean, glitch-free audio. They also watch for dropouts and manage the latency between the studio and the streaming platform.", "category": "Streaming Production", "related_terms": ["Encoder", "Bitrate", "Codec", "Latency", "Content delivery network", "Audio interface"], "common_mistakes": ["Sending the main monitor or PA mix to the stream instead of a separate broadcast mix, so the online audience hears the wrong balance or missing sources.", "Setting the encoder bitrate higher than the available upload bandwidth, which causes buffering, dropouts or a dropped stream.", "Ignoring gain staging into the encoder, letting the stream clip or sit too quiet.", "Forgetting the latency between the studio and the platform, so live interaction or synced audio and video drift out of time."], "scenario_contexts": ["A band plays a ticketed concert live-streamed from a treated studio room to a paying online audience.", "A podcast or talk show is recorded and streamed at the same time to a video platform and a podcast feed.", "A corporate webinar or product launch is produced in-house from a streaming studio with multiple cameras and a mixed audio feed.", "A house of worship streams its weekly service from a dedicated streaming room."]}, "483c61d9-018b-4182-8d29-6f6bf1df9576": {"definition": "The systematic checking of every stage in a station's air chain — the complete signal path from studio playout through the audio processor, encoder, and studio-to-transmitter link to the transmitter — to confirm each stage passes audio correctly and meets its technical, modulation, and loudness targets.", "plain_english": "The air chain is the whole path a station's sound travels, from the studio to the transmitter. Air-chain verification means checking each step in that path. You make sure the sound gets through cleanly and at the right level.", "purpose_function": "It exists to catch broken, muted, or off-spec stages before they cause dead air, distortion, or a loudness-compliance failure on the transmitted signal.", "practical_application": "A technician sends test tone and program audio through the chain and confirms routing, levels, and processing at each point, often after equipment changes or before a major broadcast.", "category": "Broadcast operations", "related_terms": ["Aircheck analysis", "Broadcast audio processor", "Studio-to-transmitter link", "Broadcast logging system", "True peak", "Modulation"], "common_mistakes": ["Checking only that audio is present, not that each stage meets its level and loudness targets.", "Verifying the studio output but skipping the processor and transmitter link, where faults often hide.", "Assuming a chain that worked yesterday is still correct after firmware or routing changes."], "scenario_contexts": ["Commissioning a new transmitter site before going on air.", "Troubleshooting distorted or low audio reported by listeners.", "Routine pre-broadcast checks before a live sports or news event."]}, "cc25d837-d12f-4723-b438-7b9dd9c58f92": {"definition": "The review of an aircheck — a recording of a station's actual off-air or transmitted output as received by the audience — to evaluate content, technical quality, processing, and loudness/compliance performance.", "plain_english": "An aircheck is a recording of what a station actually put on the air. Aircheck analysis means listening back to that recording. You judge how it sounded and whether it met the rules.", "purpose_function": "It lets engineers and programmers hear the finished, processed sound the audience received, so they can confirm quality and compliance and improve the on-air product.", "practical_application": "A technician captures the off-air signal, then measures its loudness and true peak and listens for distortion, level jumps, or processing artifacts.", "category": "Broadcast monitoring", "related_terms": ["Air-chain verification", "Broadcast logging system", "Loudness measurement", "Broadcast audio processor", "True peak", "LKFS"], "common_mistakes": ["Judging loudness by ear alone instead of measuring it against the target.", "Analyzing a studio feed instead of the true off-air signal, missing processor and transmitter effects.", "Reviewing only content and ignoring technical loudness compliance."], "scenario_contexts": ["Checking a station's on-air sound after a processor adjustment.", "Investigating a listener complaint about loud commercials.", "Air talent reviewing their own show for coaching."]}, "2499742e-784e-49ba-8a4e-0968ece3cd57": {"definition": "A broadcast audio processor designed specifically for AM (medium-wave) transmission that applies gain control, equalization, compression, and peak limiting/clipping while restricting audio bandwidth (10 kHz or less) and applying NRSC-1 preemphasis, so the signal fits the AM channel and modulates the transmitter within legal limits.", "plain_english": "This is a sound processor built just for AM radio. It shapes and limits the audio and cuts off the highest tones. That keeps the signal inside the narrow space an AM station is allowed to use.", "purpose_function": "It exists to maximize loudness and coverage on AM while keeping the transmitted signal within the legal channel width and modulation limits.", "practical_application": "An engineer sets its bandwidth, preemphasis, and peak controls to meet the NRSC-1 standard and modulation rules, trading loudness against occupied bandwidth and interference.", "category": "Broadcast processing", "related_terms": ["Broadcast audio processor", "Preemphasis", "Modulation", "Broadcast clipping processor", "Occupied bandwidth", "Peak limiting"], "common_mistakes": ["Setting audio bandwidth wider than 10 kHz, causing second-adjacent-channel interference.", "Copying FM processor settings onto an AM chain, ignoring AM's preemphasis and bandwidth rules.", "Over-clipping to chase loudness, producing distortion and splatter."], "scenario_contexts": ["Setting up processing for a talk-format AM station.", "Reducing interference complaints from a neighboring station.", "Meeting NRSC-1 bandwidth requirements after an FCC inspection."]}, "8b75e14a-cdd9-484f-bd3a-33372fe371ab": {"definition": "A dedicated device or software placed at the end of the air chain that automatically controls a station's audio dynamics and spectrum — typically wideband AGC, multiband compression, limiting, and peak clipping, plus preemphasis where required — to deliver consistent loudness, prevent overmodulation or overload, and shape the station's on-air sound.", "plain_english": "This is the box that automatically controls a station's sound before it goes on air. It keeps the volume steady and stops peaks from getting too high. It also gives the station its signature sound.", "purpose_function": "It exists to keep loudness consistent and within limits and to prevent overmodulation or digital overload, while giving a station a competitive, consistent on-air sound.", "practical_application": "An engineer picks a preset and fine-tunes AGC, band gains, and limiting to hit the loudness target while avoiding audible pumping or distortion.", "category": "Broadcast processing", "related_terms": ["Multiband compression", "Peak limiting", "Broadcast clipping processor", "Broadcast limiter chain", "Loudness normalization", "Modulation"], "common_mistakes": ["Pushing processing too hard for loudness, causing listener fatigue and distortion.", "Placing the processor in the wrong spot so downstream gain undoes its peak control.", "Ignoring the loudness target and judging only by how loud it seems."], "scenario_contexts": ["Dialing in a new FM station's on-air sound.", "Meeting a loudness target for a digital or streaming feed.", "Reducing complaints about inconsistent volume between songs and ads."]}, "d56e37f8-8124-49b3-9d00-816457304141": {"definition": "The final peak-control stage in a broadcast processing chain that hard- or soft-clips the audio waveform to hold peaks at a fixed ceiling, allowing higher average modulation and loudness than limiting alone at the cost of added harmonic distortion, usually followed by band-limiting to control the resulting spectral spread.", "plain_english": "A clipper chops the very top off the loudest peaks of the sound. This lets a station run louder overall. But if you cut too much, it adds a harsh, distorted edge.", "purpose_function": "It exists to squeeze more average loudness and modulation out of the signal by removing brief peaks that would otherwise force the whole level down.", "practical_application": "An engineer sets clip drive to gain loudness, then checks for audible distortion and, on FM and AM, for splatter or bandwidth violations caused by the clipping.", "category": "Broadcast processing", "related_terms": ["Broadcast audio processor", "Peak limiting", "Broadcast limiter chain", "Modulation", "Occupied bandwidth", "True peak"], "common_mistakes": ["Driving the clipper too hard, trading a small loudness gain for obvious distortion.", "Forgetting that clipping creates harmonics that can widen occupied bandwidth and cause interference.", "Relying on the clipper alone for overmodulation control instead of a proper peak limiter."], "scenario_contexts": ["Tuning an FM chain for competitive loudness without audible grit.", "Diagnosing distortion traced to excessive clip drive.", "Balancing loudness against occupied-bandwidth limits on AM."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"db8fe4c1-3372-4e8b-8f9a-519e5cafb607": {"definition": "A formal technical document prepared by a station's engineering staff that records the measured status, performance, faults, and corrective actions of broadcast facilities — such as transmitter parameters, audio and modulation measurements, and compliance results — for management review and regulatory record-keeping.", "plain_english": "This is a written report from the engineers about how the station's gear is running. It lists measurements, any problems found, and what was fixed. That gives the station and the regulators a record.", "purpose_function": "It exists to document technical performance and compliance over time, support maintenance decisions, and provide evidence during inspections or audits.", "practical_application": "An engineer logs values like transmitter power, modulation, and loudness, notes any faults and repairs, and files the report on a routine schedule.", "category": "Broadcast operations", "related_terms": ["Broadcast logging system", "Air-chain verification", "Modulation", "Loudness measurement", "Transmitter", "Aircheck analysis"], "common_mistakes": ["Recording only that equipment 'works' without the actual measured values.", "Filing reports inconsistently, leaving gaps that fail an audit.", "Omitting the corrective action taken for a logged fault."], "scenario_contexts": ["Monthly transmitter and modulation performance review.", "Documenting a fault and repair for the station file.", "Preparing evidence for a regulatory inspection."]}, "174595fb-1922-4879-81b3-f21beca1c1b2": {"definition": "A station's defined operating practice for how much level margin (headroom) to keep below digital full scale and below maximum modulation across the air chain — for example, aligning program to a loudness target such as -24 LKFS (ATSC A/85) or -23 LUFS (EBU R128) while holding true peaks a set margin below 0 dBTP — so the signal never clips or overmodulates.", "plain_english": "Headroom is the safety gap between your normal sound level and the highest level allowed. A headroom policy is the station's rule for how big that gap should be. It keeps loud moments from clipping or overloading.", "purpose_function": "It exists to prevent clipping, overload, and overmodulation while keeping loudness consistent with the required target.", "practical_application": "An engineer sets gain staging and processor limits so program peaks stay a defined margin below full scale and modulation limits, matching the loudness standard in force.", "category": "Loudness compliance", "related_terms": ["True peak", "LKFS", "Loudness normalization", "Broadcast audio processor", "Modulation", "Peak limiting"], "common_mistakes": ["Confusing the loudness target with the peak ceiling and letting true peaks exceed 0 dBTP.", "Leaving so much headroom that the signal is too quiet against the target.", "Applying the policy at one stage but ignoring gain changes downstream."], "scenario_contexts": ["Setting gain structure for a new digital playout system.", "Aligning a feed to ATSC A/85 or EBU R128.", "Preventing inter-sample peak clipping on a streaming encoder."]}, "4d5fef52-53df-4f69-8cd0-8a3eb99f4572": {"definition": "The ordered series of limiting stages within a broadcast audio processor — typically a slower wideband/AGC stage, multiband limiters, and a fast final peak limiter or clipper — that together control dynamics and hold the signal below modulation and full-scale limits.", "plain_english": "This is the set of volume-control stages inside a broadcast processor, working one after another. Each stage handles a different job. Together they stop the sound from ever getting too loud for the transmitter.", "purpose_function": "It exists to progressively tame dynamics so the final signal is loud and consistent yet never overmodulates or overloads.", "practical_application": "An engineer sets the thresholds and speeds of each stage so they share the work, avoiding a single stage doing too much and causing pumping or distortion.", "category": "Broadcast processing", "related_terms": ["Broadcast audio processor", "Peak limiting", "Multiband compression", "Broadcast clipping processor", "Modulation", "AGC"], "common_mistakes": ["Making one stage do all the limiting, causing pumping or distortion.", "Setting later stages so hard that earlier gain control is wasted.", "Ignoring how the attack and release times of the stages interact."], "scenario_contexts": ["Tuning an FM processor for clean, loud output.", "Reducing audible pumping on speech.", "Matching a station's loudness to competitors without distortion."]}, "9af64f26-73f1-4754-96f0-4052af1fa578": {"definition": "A system that continuously records a station's on-air or off-air output, often with related metadata, for later review — providing a verifiable record of what was transmitted and supporting compliance, loudness, and quality monitoring; retention periods are set by regulation.", "plain_english": "This is a system that keeps a running recording of everything a station broadcasts. If someone questions what went out, or the rules require proof, the station can play back the log.", "purpose_function": "It exists to give a verifiable record of transmitted content for compliance, dispute resolution, and quality and loudness review.", "practical_application": "An engineer checks that the logger is capturing all channels reliably, then retrieves segments to prove compliance or investigate a complaint.", "category": "Broadcast monitoring", "related_terms": ["Aircheck analysis", "Broadcast engineering report", "Air-chain verification", "Loudness measurement", "Off-air monitoring", "Compliance"], "common_mistakes": ["Assuming the logger is running without checking it actually captures audio.", "Keeping recordings for less time than regulations require.", "Logging a pre-processed feed instead of the true transmitted output."], "scenario_contexts": ["Retrieving proof of broadcast for a legal or regulatory query.", "Investigating a loudness or content complaint.", "Confirming an emergency alert was aired correctly."]}, "e348271f-96c8-4276-8188-fbeb6c8a9fa4": {"definition": "The facility-wide practice of measuring and controlling program loudness so that all broadcast content meets a regulatory target loudness and true-peak limit, using loudness measurement per ITU-R BS.1770 (K-weighted, gated) together with normalization and processing rather than peak-based leveling. Targets are typically an integrated -23 LUFS under EBU R128 or -24 LKFS under ATSC A/85, with maximum true peak held near -1 dBTP.", "plain_english": "This is the work of keeping every show and advert at about the same loudness. Special meters measure the sound the way our ears hear it, not just the peaks, and staff adjust levels to hit a set target. It stops viewers from reaching for the remote when a program gets too loud or too quiet.", "purpose_function": "It exists to give viewers a steady listening level across programs, channels, and ads, and to keep a broadcaster legally compliant with loudness rules. It replaces older peak-meter leveling, which did not match how loud content actually sounds to people.", "practical_application": "An engineer sets loudness targets across the playout and processing chain, watches integrated loudness and true peak on compliance meters, and normalizes or reprocesses any file that falls outside tolerance before it airs.", "category": "Loudness Compliance", "related_terms": ["LUFS", "Integrated loudness", "True peak", "EBU R128", "ATSC A/85", "Loudness normalization"], "common_mistakes": ["Confusing loudness (LUFS/LKFS) with peak level (dBFS) and leveling by peaks instead of measured loudness.", "Assuming a limiter alone makes content compliant when its integrated loudness is still off target.", "Ignoring the true-peak limit, so a file passes on loudness but overshoots once a lossy codec is applied."], "scenario_contexts": ["Preparing episodic programs and ads to a -23 LUFS target before playout.", "Auditing an incoming file that meters at -18 LUFS and normalizing it to spec.", "Setting up a station's transmission chain to hold a consistent on-air loudness."]}, "26c148a5-1980-4768-8d6a-c29808e3c8a6": {"definition": "A dynamics processor that splits the audio spectrum into several frequency bands and applies independent compression, limiting, and automatic gain control to each band, used in the transmission or streaming chain to control loudness, tighten spectral balance, and create a consistent on-air sound. It is followed by a final peak or true-peak limiter to protect the transmitter or encoder from overshoots.", "plain_english": "This tool splits the sound into low, middle, and high parts and squeezes each part on its own. That keeps the bass, voices, and cymbals all steady, even when the music changes a lot. Radio and TV stations use it to get a full, even sound that does not jump in volume.", "purpose_function": "It exists to hold loudness and tone even across very different program material and to give a station its signature sound, while protecting the transmitter or encoder from level overshoots.", "practical_application": "A broadcast engineer installs a processor such as an Orban Optimod or Omnia unit, loads a preset, and adjusts band drive, compression, and final limiting to balance loudness, clarity, and compliance.", "category": "Broadcast Processing", "related_terms": ["Multiband compression", "Automatic gain control", "Peak limiter", "True peak", "Broadcast preset", "Loudness normalization"], "common_mistakes": ["Over-driving the bands to chase loudness, which causes pumping and audible distortion.", "Assuming heavy processing removes the need to meet an integrated-loudness target.", "Leaving the final true-peak limiter defeated, so overshoots reach the encoder and clip."], "scenario_contexts": ["Setting the on-air sound for an FM music station.", "Controlling loudness and tone for a live TV feed before the encoder.", "Tuning a streaming chain to hold a target loudness across different genres."]}, "6240e4c6-0455-48df-9139-ee20d6925a5d": {"definition": "A saved set of parameter values for a broadcast processor (band drive, compression ratios, automatic gain control, EQ, and limiting) that can be recalled to reproduce a specific processed sound, matched to a station format, daypart, or program genre.", "plain_english": "A preset is a saved recipe of settings for a broadcast sound processor. Instead of dialing in dozens of controls by hand, you load one and the sound is set. Stations keep different presets for talk, rock, or news.", "purpose_function": "It exists to make a complex processor quick and repeatable to set up, so a station's sound stays consistent and can be switched fast between formats or times of day.", "practical_application": "An engineer starts from a factory preset close to the wanted sound, tweaks it, and saves a custom version, then recalls or schedules it for different dayparts.", "category": "Broadcast Processing", "related_terms": ["Broadcast multiband processor", "Multiband compression", "Automatic gain control", "Daypart", "Equalization", "Loudness normalization"], "common_mistakes": ["Loading a loud factory preset without checking it still meets the loudness target.", "Overwriting the only copy of a working preset with no backup saved.", "Assuming a preset built for one processor model transfers exactly to another model."], "scenario_contexts": ["Loading a talk-format preset for a morning news block.", "Backing up custom processor presets before a firmware update.", "Switching presets between music programming and sports coverage."]}, "00f6d8e9-626f-4ad4-b983-c56d4f51f032": {"definition": "The continuous checking of technical audio and video parameters across the broadcast chain — including integrated and short-term loudness, true peak, signal presence, phase or correlation, and silence detection — to confirm compliance and detect faults in real time.", "plain_english": "This means watching the sound and picture all the time so problems get caught fast. Meters and alarms flag things like audio that is too loud, too quiet, silent, or out of phase. If something breaks, staff know right away instead of after viewers complain.", "purpose_function": "It exists to catch loudness violations, dropouts, silence, and phase problems before or as they reach air, protecting both compliance and the viewer's experience.", "practical_application": "An operator watches loudness and true-peak meters and automated alarms on a monitoring system, then responds to alerts for silence, over-loud segments, or a lost audio channel.", "category": "Broadcast Monitoring", "related_terms": ["Loudness metering", "True peak", "Integrated loudness", "Phase correlation", "Silence detection", "Broadcast statistics report"], "common_mistakes": ["Watching only peak meters and missing loudness (LUFS/LKFS) problems.", "Setting alarm thresholds so tight or so loose that the alerts get ignored.", "Monitoring only one point in the chain and missing faults added further downstream."], "scenario_contexts": ["Master-control staff watching many channels for silence and loudness alarms.", "Checking a live feed's loudness and phase during a broadcast.", "Catching a dropped audio channel before it reaches transmission."]}, "e03cfb2f-59e3-476c-bab7-f9fcd396c22c": {"definition": "A summary of measured loudness parameters for a program or time period — integrated (program) loudness, loudness range (LRA), maximum true peak, and maximum momentary and short-term loudness — computed per ITU-R BS.1770 and its metering supplements, used to document and verify compliance.", "plain_english": "This is a summary sheet of a show's loudness numbers. It lists the overall loudness, how much it moved from quiet to loud, and the highest peak. Staff read it to prove a file meets the rules.", "purpose_function": "It exists to condense a whole program's loudness behavior into a few standard numbers, so content can be checked against the target and kept as proof of compliance.", "practical_application": "An engineer generates the report from a loudness meter or file-analysis tool after measuring a deliverable, then compares its integrated loudness and true peak against the required spec.", "category": "Compliance & Reporting", "related_terms": ["Integrated loudness", "Loudness range", "True peak", "Momentary loudness", "Short-term loudness", "Compliance verification report"], "common_mistakes": ["Reading a momentary or short-term value as if it were the integrated target.", "Ignoring the maximum true-peak line when it exceeds the limit.", "Assuming a passing integrated-loudness number means true peak also passed."], "scenario_contexts": ["Attaching a loudness report to a delivered program as proof of spec.", "Reviewing an episode's integrated loudness and LRA before accepting it.", "Comparing statistics across a batch of files to find outliers."]}, "a62bc99a-595a-477b-a9b2-0692d5eb7a73": {"definition": "The practice and regulatory requirement that advertisements are broadcast at no greater loudness than the surrounding program, achieved by measuring and normalizing spots to the same loudness target per ITU-R BS.1770; in the United States it is mandated by the CALM Act, which adopts the ATSC A/85 recommended practice.", "plain_english": "This keeps adverts from being louder than the show around them. Each advert is measured and set to the same loudness target as the program. It is the reason ads no longer blast you when a show cuts to a break.", "purpose_function": "It exists to stop the long-standing problem of ads sounding much louder than programs, and to meet legal rules that require ads and programs at matched loudness.", "practical_application": "An engineer measures each commercial's integrated loudness, normalizes it to the station target (for example -24 LKFS), and rejects or reprocesses any spot that arrives too loud.", "category": "Loudness Compliance", "related_terms": ["CALM Act", "ATSC A/85", "Integrated loudness", "Loudness normalization", "LKFS", "True peak"], "common_mistakes": ["Judging a spot's loudness by ear or by peaks instead of measured integrated loudness.", "Assuming a spot mixed 'hot' will be accepted without normalization.", "Confusing per-ad peak limiting with matching the ad's integrated loudness to the program."], "scenario_contexts": ["Normalizing an incoming ad from -20 LKFS to the -24 LKFS target.", "Rejecting a commercial that exceeds the true-peak limit.", "Auditing a commercial break to confirm ads match program loudness."]}, "1c057bd7-1af1-4b3b-96f9-8ae4a77607dd": {"definition": "A retained store of loudness measurement logs, statistics reports, and as-run data kept as documentary evidence that broadcast content met the applicable loudness regulation over a required retention period.", "plain_english": "This is a saved record of loudness measurements kept as proof. If a regulator or client asks, the station can show that its shows and ads met the rules. It works like keeping receipts in case you are audited.", "purpose_function": "It exists to provide auditable proof of compliance over time, protecting a broadcaster if its loudness practices are questioned or an official complaint is filed.", "practical_application": "An engineer sets up a logging system to record continuous loudness data and reports, and retrieves the relevant period's records when answering an audit or complaint.", "category": "Compliance & Reporting", "related_terms": ["Broadcast statistics report", "Compliance verification report", "As-run log", "Loudness logging", "Integrated loudness", "CALM Act"], "common_mistakes": ["Keeping records for less than the required retention period.", "Logging loudness data with no time reference to match it to as-run events.", "Assuming a single report replaces continuous logs for audit purposes."], "scenario_contexts": ["Retrieving a week of loudness logs to answer a viewer complaint.", "Storing continuous loudness data to satisfy a retention rule.", "Matching an as-run log to loudness records during an audit."]}, "a82b0f6d-2a11-4690-9d2c-c107efa379d3": {"definition": "A formal attestation — for a program, deliverable, or facility — that measured loudness and true-peak values meet the applicable standard's targets and tolerances (such as EBU R128 or ATSC A/85), often issued as a signed report or an automated pass result accompanying delivery.", "plain_english": "This is an official 'passed' stamp on a file or facility. It says the loudness was checked and meets the rules. Broadcasters and clients ask for it before they accept content.", "purpose_function": "It exists to give a clear, documented statement that content meets loudness spec, so it can be accepted and aired without further checking.", "practical_application": "A technician runs a file through a loudness-analysis tool, confirms it meets the target and tolerance, and issues or attaches the pass certificate for delivery.", "category": "Compliance & Reporting", "related_terms": ["Compliance verification report", "EBU R128", "ATSC A/85", "Integrated loudness", "True peak", "Delivery specification"], "common_mistakes": ["Certifying to the wrong regional standard (for example -23 LUFS versus -24 LKFS).", "Passing a file on integrated loudness while ignoring a true-peak overshoot.", "Treating a certificate as valid after re-encoding the file changed its loudness."], "scenario_contexts": ["Issuing a pass certificate with a delivered program.", "Confirming a facility's chain meets a broadcaster's loudness spec.", "Checking a file's certificate before ingest."]}, "26da8e46-02d9-4e98-b18e-ba0e8754ac1c": {"definition": "A document confirming that a specific deliverable's measured loudness parameters — integrated loudness, loudness range, and maximum true peak — fall within the required target and tolerance of the applicable standard, with a clear pass or fail result.", "plain_english": "This report checks one file against the rules and says pass or fail. It lists the loudness numbers next to the limits they must meet. Staff read it to be sure a file is ready to air.", "purpose_function": "It exists to give a documented, per-file confirmation that content meets spec before it is accepted or aired, and to flag exactly which parameter failed if it does not.", "practical_application": "An operator measures a deliverable, generates the verification report, and either passes it on to delivery or returns it for correction when a value is out of tolerance.", "category": "Compliance & Reporting", "related_terms": ["Broadcast statistics report", "Compliance certification", "Integrated loudness", "Loudness range", "True peak", "Loudness normalization"], "common_mistakes": ["Airing a file that its own report marks as a fail.", "Reading the wrong tolerance for the target standard.", "Assuming a pass stays valid after the file is transcoded or trimmed."], "scenario_contexts": ["Verifying a delivered episode against a -23 LUFS spec.", "Returning a file to a producer because its true peak failed.", "Documenting pass results across a batch of files before ingest."]}, "f91ba847-6961-4249-87df-2c293e6e6617": {"definition": "The ongoing, real-time measurement of a program's loudness against a defined target throughout a broadcast, using a loudness meter compliant with ITU-R BS.1770 and reported in LUFS/LKFS. It tracks momentary, short-term, and integrated loudness so operators can confirm the signal stays within regulatory limits such as EBU R128 or ATSC A/85.", "plain_english": "It means watching how loud a show sounds the whole time it airs. A meter checks the sound against a set target so it never gets too loud or too quiet.", "purpose_function": "It exists to keep on-air loudness consistent and within legal limits, alerting staff before a program drifts louder or softer than the target. This helps prevent viewer complaints and regulatory violations.", "practical_application": "An operator keeps a loudness meter on the air feed during a live broadcast, watching the short-term and integrated readings and trimming gain if the program drifts away from the target.", "category": "Loudness Monitoring", "related_terms": ["Integrated loudness", "LUFS", "ITU-R BS.1770", "EBU R128", "Loudness history graph", "True peak"], "common_mistakes": ["Watching only the momentary reading and ignoring the integrated value that actually determines compliance", "Assuming a peak meter shows loudness, when peak level and loudness are different measurements", "Setting the meter to the wrong target or gating standard for the region's rules"], "scenario_contexts": ["Monitoring a live sports broadcast to keep it within ATSC A/85 limits", "Checking a network feed's integrated loudness across a full program", "Watching short-term loudness during a live news studio show"]}, "3882d30c-e7fe-408e-bbe3-f717b530d430": {"definition": "An audio processor designed for digital radio transmission systems such as DAB/DAB+ or HD Radio, conditioning the audio for perceptual codecs rather than an analog RF path. It manages loudness, dynamics, and spectral balance while avoiding the pre-emphasis and aggressive peak clipping used for analog FM.", "plain_english": "It is a sound processor made for digital radio instead of old analog radio. It shapes the audio so it still sounds clear after the digital codec squeezes it.", "purpose_function": "It exists to make audio sound loud, clean, and consistent through the data-compression codecs used in digital radio, where harsh analog-style processing would create artifacts.", "practical_application": "A broadcast engineer sets a digital radio processor to feed a DAB+ or HD Radio encoder, using gentler limiting than the FM path so the codec does not add distortion.", "category": "Broadcast Processing", "related_terms": ["FM processor", "HD Radio processor", "Final broadcast processor", "Loudness normalization engine", "Diversity delay"], "common_mistakes": ["Using aggressive FM-style clipping on a digital path, which the codec turns into audible artifacts", "Assuming pre-emphasis is needed, when digital radio does not use FM pre-emphasis", "Ignoring the loudness target and letting the digital and analog services mismatch in level"], "scenario_contexts": ["Feeding a DAB+ multiplex encoder at a radio station", "Setting up audio for an HD Radio digital service", "Aligning a digital service's loudness with its analog FM simulcast"]}, "067756c2-5d99-4998-bc52-407651c8c232": {"definition": "The last audio processor in the air chain before the transmitter or encoder, which sets the station's final loudness, peak control, and overall sonic signature. It guarantees the signal does not exceed modulation or true-peak limits regardless of the source material.", "plain_english": "It is the last sound processor before the signal leaves the station. It sets the final loudness and makes sure the audio never goes over the legal limit.", "purpose_function": "It exists to protect the transmission from over-modulation and to give the station one consistent, controlled sound no matter what program feeds it.", "practical_application": "An engineer places the final broadcast processor right before the FM exciter or stream encoder and adjusts its limiting so every program hits the target loudness without clipping.", "category": "Broadcast Processing", "related_terms": ["FM processor", "Digital radio processor", "True peak", "Loudness normalization engine", "Continuous loudness monitoring"], "common_mistakes": ["Adding gain or EQ after the final processor, which defeats its peak and modulation protection", "Overdriving the input and blaming the processor for distortion it is forced to create", "Chaining two aggressive processors so they fight each other and cause pumping"], "scenario_contexts": ["Setting the last stage before an FM transmitter's exciter", "Protecting a stream encoder from true-peak overshoots", "Giving a music station its signature on-air loudness and tone"]}, "63316d7c-216a-4299-8ac5-e78c9474828b": {"definition": "An audio processor optimized for analog FM broadcasting that applies pre-emphasis-aware limiting, tight peak control, and stereo composite (MPX) conditioning to maximize loudness and coverage without over-modulating. Typical units, such as the Orban Optimod-FM, also generate or feed the stereo multiplex signal.", "plain_english": "It is a sound processor built for FM radio. It makes the station sound loud and clear while keeping the signal inside FM's legal limits.", "purpose_function": "It exists to get the most consistent loudness and cleanest coverage from an FM signal while respecting the pre-emphasis curve and the strict peak-modulation limit.", "practical_application": "A radio engineer tunes an FM processor's multiband compression and final clipper to build a competitive on-air sound, then verifies that peak modulation stays within the legal limit.", "category": "Broadcast Processing", "related_terms": ["Final broadcast processor", "Pre-emphasis", "HD Radio processor", "Digital radio processor", "Composite clipping"], "common_mistakes": ["Ignoring the 75 us (US) or 50 us (Europe) pre-emphasis curve when setting high-frequency limiting", "Pushing the clipper so hard that distortion and multipath rise while loudness barely gains", "Confusing peak-modulation control with loudness, when the two need separate attention"], "scenario_contexts": ["Setting up an Orban or Omnia processor before an FM exciter", "Dialing in a station's competitive loudness for its local market", "Managing pre-emphasis limiting to control high-frequency energy"]}, "91816a76-9c9d-43c1-9454-4602e7b87a6b": {"definition": "An audio processor tailored for the HD Radio (IBOC) digital service, which conditions audio for the HDC codec and manages the diversity-delay alignment between the analog FM and digital signals. It applies gentler dynamics and peak control than the analog FM path to prevent codec artifacts.", "plain_english": "It is a sound processor for HD Radio, the digital version of a station. It shapes the audio for the digital codec. It also keeps the digital and analog signals lined up so they blend well.", "purpose_function": "It exists to make the digital audio sound clean through its codec and to match its level and timing with the analog FM signal so receivers blend between them without a jump.", "practical_application": "An engineer configures the HD Radio processor's digital path separately from FM, matching loudness and setting diversity delay so a receiver blending from digital to analog is seamless.", "category": "Broadcast Processing", "related_terms": ["FM processor", "Digital radio processor", "Diversity delay", "Final broadcast processor", "Loudness normalization engine"], "common_mistakes": ["Using the same harsh FM clipping on the digital path, which the HDC codec exposes as artifacts", "Mismatching analog and digital loudness so the blend is audible on air", "Forgetting to set or maintain diversity delay, causing an echo when receivers blend"], "scenario_contexts": ["Setting up an FM station's HD1 digital simulcast", "Aligning analog and digital loudness for a smooth blend", "Adjusting diversity delay after an air-chain change"]}, "aa59c072-689a-4748-910f-a2d526e433e7": {"definition": "The process of adjusting program audio so its measured loudness meets a defined target, either by a single offset gain change or by real-time adaptive processing, based on ITU-R BS.1770 measurement. It brings non-compliant content in line with standards such as EBU R128 or ATSC A/85.", "plain_english": "It means changing a program's level so it matches the loudness target. Sometimes one fixed gain shift is enough; other times a live processor keeps it on target.", "purpose_function": "It exists to make different programs and commercials sit at the same loudness, so viewers do not need to reach for the volume between segments.", "practical_application": "A technician measures a finished file's integrated loudness, then applies a fixed gain offset to hit the target, or routes live content through a real-time corrector for the same result.", "category": "Loudness Control", "related_terms": ["Loudness normalization engine", "Integrated loudness", "LUFS", "EBU R128", "ATSC A/85", "Dialnorm"], "common_mistakes": ["Normalizing to peak instead of loudness, which leaves programs sounding uneven", "Applying heavy dynamic processing when a simple gain offset would meet the target", "Correcting integrated loudness but ignoring the true-peak limit and causing clipping"], "scenario_contexts": ["Bringing a commercial's loudness down to match program content", "Batch-correcting a library of files to the target loudness", "Real-time correcting a live feed that arrives off-target"]}, "2d90a3c0-ea17-4b32-8edc-b9f5b70ce9ce": {"definition": "A time-based display on a loudness meter that plots loudness, typically momentary and short-term values, over the course of a program, letting operators see trends, peaks, and dips at a glance. It complements the numeric integrated reading defined in EBU Tech 3341 and ITU-R BS.1771 metering.", "plain_english": "It is a chart on a loudness meter that shows how loud a show has been over time. It lets you spot loud or quiet moments fast instead of reading just one number.", "purpose_function": "It exists to show loudness as a trend rather than a single value, making it easy to catch a section that drifted too loud or too soft during a program.", "practical_application": "An operator scans the loudness history graph after a segment to see where short-term loudness spiked, then goes back and fixes that part before delivery.", "category": "Loudness Monitoring", "related_terms": ["Continuous loudness monitoring", "Short-term loudness", "Momentary loudness", "Integrated loudness", "Loudness range", "LUFS"], "common_mistakes": ["Reading the graph's momentary peaks as the compliance value instead of the integrated result", "Confusing the loudness history graph with a peak-level meter", "Ignoring long quiet stretches that pull the integrated loudness below target"], "scenario_contexts": ["Reviewing a recorded program's loudness trend before delivery", "Spotting an over-loud commercial break on the history display", "Checking a live show's short-term loudness pattern in real time"]}, "aa0f9039-a3a0-402c-ae03-ce45971a1411": {"definition": "The automatic recording of loudness measurements over time to create a documented, time-stamped record of a channel's compliance with loudness rules. These logs, based on ITU-R BS.1770 measurement, provide proof of compliance for regulators under regimes such as the CALM Act or EBU R128.", "plain_english": "It means saving a record of how loud a channel was over time. Those records prove the station followed the loudness rules if anyone asks.", "purpose_function": "It exists to give stations documented proof that their audio met loudness limits, and to help engineers trace when and why a problem happened.", "practical_application": "An engineer runs a logging system on the channel output so that, if a viewer complaint or audit arrives, they can pull the time-stamped loudness record for that period.", "category": "Loudness Compliance", "related_terms": ["Continuous loudness monitoring", "Integrated loudness", "CALM Act", "ATSC A/85", "EBU R128", "LUFS"], "common_mistakes": ["Logging only integrated loudness and losing the detail needed to investigate a complaint", "Assuming logging fixes loudness, when it only records and does not correct", "Keeping logs too briefly to cover the regulator's required retention period"], "scenario_contexts": ["Producing a compliance record after a viewer loudness complaint", "Auditing a channel's loudness over a broadcast day", "Documenting delivered loudness for a network's quality control"]}, "ebb5f009-aab3-46ff-99f2-87288530b558": {"definition": "The processing block that measures program loudness and applies gain so the output matches a target level in LUFS/LKFS, per ITU-R BS.1770. It is the core of playout, streaming, and file-based systems that deliver every program at a consistent loudness.", "plain_english": "It is the part of a system that sets every program to the same loudness. It measures the sound and turns it up or down to hit one target level.", "purpose_function": "It exists to deliver all content at one consistent loudness automatically, so listeners hear an even level across programs, ads, and platforms.", "practical_application": "A streaming or playout engineer sets the engine's target, for example the broadcast or platform loudness level, and lets it align every asset before delivery.", "category": "Loudness Control", "related_terms": ["Loudness correction", "Integrated loudness", "LUFS", "EBU R128", "ATSC A/85", "Continuous loudness monitoring"], "common_mistakes": ["Normalizing to peak rather than integrated loudness, which leaves levels uneven", "Setting a target that ignores the true-peak ceiling and causes clipping", "Assuming one target fits every platform, when broadcast and streaming differ"], "scenario_contexts": ["Normalizing a playout server's programs to the broadcast target", "Aligning a streaming library to the platform's loudness target", "Passing off-target incoming feeds through the engine before air"]}, "2a121fa4-2027-4688-817d-629fe76ae192": {"definition": "A real-time loudness reading averaged over a 400 ms sliding window, expressed in LUFS and computed with the K-weighting of ITU-R BS.1770, and left ungated in momentary mode per EBU Tech 3341. It reflects the loudness of program audio over the most recent fraction of a second.", "plain_english": "This is a loudness reading taken over the last fraction of a second. It shows how loud the sound is right now, almost live. Think of it like a speedometer that reacts the instant the audio gets louder or softer.", "purpose_function": "It gives operators an instant sense of loudness so they can catch sudden loud moments while mixing, complementing the slower short-term and whole-program readings.", "practical_application": "A broadcast engineer watches the momentary meter to spot quick loudness spikes during live mixing and to trim faders or gain before they reach air.", "category": "Loudness Measurement", "related_terms": ["Short-term loudness measurement", "Program loudness measurement", "LUFS", "True peak", "EBU R128"], "common_mistakes": ["Treating the momentary reading as the value used for compliance, when compliance is judged on integrated program loudness.", "Confusing the 400 ms momentary window with the 3-second short-term window.", "Chasing every momentary spike with gain changes, which over-processes the audio."], "scenario_contexts": ["Riding levels during a live sports broadcast to catch sudden crowd surges.", "Checking a voice-over for instant loud peaks before it airs.", "Monitoring a live music feed where dynamics change quickly."]}, "affb635c-40f5-4378-b9d4-915dd96c2f92": {"definition": "A dedicated audio processor placed in the broadcast signal chain ahead of the transmitter or encoder that applies gain control, multiband compression, equalization, limiting and true-peak control to condition program audio for consistent loudness and to keep peaks within transmission limits. Established examples include the Orban Optimod and Telos/Omnia processor families.", "plain_english": "This is a box that automatically shapes a station's sound just before it goes out. It keeps the loudness even and stops the signal from getting too strong for the transmitter. It works like an automatic sound engineer that never takes a break.", "purpose_function": "It exists to deliver a consistent, controlled on-air sound and to keep peak levels within the limits the transmitter and regulations allow.", "practical_application": "Engineers load a preset into the on-air processor and tune its compression and limiting so the station sounds even across quiet and loud content without breaking peak or loudness rules.", "category": "Broadcast Processing", "related_terms": ["Program optimization processor", "Transmission peak control", "Processing preset recall", "Regulatory loudness compliance", "Multiband compression"], "common_mistakes": ["Over-driving the processor for loudness, which crushes dynamics and can push measured loudness above legal targets.", "Assuming the processor alone guarantees compliance without checking integrated program loudness.", "Confusing the processor's peak limiting with loudness normalization; they solve different problems."], "scenario_contexts": ["Setting up the sound signature for a new FM station.", "Adjusting a TV station's processor to meet loudness rules.", "Switching processor presets between talk and music dayparts."]}, "27a7a506-9868-4515-897c-1ceb5ef6fb16": {"definition": "The act of loading a stored set of audio-processor parameters — compression, EQ, limiting and loudness settings — into an on-air or program processor so a known configuration is restored at once. Presets let a station switch its processing for different formats, dayparts or program types.", "plain_english": "This means loading a saved group of settings into a sound processor. Instead of dialing everything in by hand, you pick a saved setup and it loads all at once. It is like choosing a saved profile on a game console.", "purpose_function": "It exists so operators can switch between tested processing setups quickly and repeatably, avoiding manual re-tuning and human error.", "practical_application": "An operator recalls a 'news' preset before a bulletin and a 'music' preset afterward, so the sound matches each program type without rebuilding settings by hand.", "category": "Broadcast Processing", "related_terms": ["On-air processor", "Program optimization processor", "Multiband compression", "Regulatory loudness compliance"], "common_mistakes": ["Recalling a preset without confirming it still meets the current loudness target.", "Saving over a proven preset by accident and losing the known-good settings.", "Assuming a preset built for one format is safe for all content."], "scenario_contexts": ["Loading a daypart preset at the start of a morning show.", "Restoring a backup preset after a processor is replaced.", "Switching presets between live sports and studio programming."]}, "2e5cce1e-5233-4ad2-9dc1-a741421ac9fd": {"definition": "The measurement of the overall loudness of a complete program or segment, computed as the gated integrated loudness over its full duration in LUFS (LKFS in ATSC) per ITU-R BS.1770 and EBU R128. This single value is the basis for loudness compliance and normalization.", "plain_english": "This is the average loudness of a whole show or clip, measured from start to end. It gives one number that describes how loud the program is overall. It is like an average grade for the whole program rather than one moment.", "purpose_function": "It provides the single, standardized loudness figure stations use to match programs to a target and to prove compliance.", "practical_application": "An engineer measures a finished program's integrated loudness and adjusts overall gain so it lands on the required target before delivery or air.", "category": "Loudness Measurement", "related_terms": ["Momentary loudness measurement", "Short-term loudness measurement", "Program normalization", "Regulatory loudness compliance", "LUFS"], "common_mistakes": ["Reading integrated loudness before the whole program has played, giving an incomplete value.", "Confusing program (integrated) loudness with peak level.", "Ignoring the gating rules and letting long silences drag the result down."], "scenario_contexts": ["Checking a finished episode against a -23 LUFS or -24 LKFS target.", "Verifying a commercial's loudness before it enters playout.", "Documenting program loudness for a broadcaster's delivery specs."]}, "c693caba-4da2-4309-a007-1a07f93aa70f": {"definition": "The process of adjusting a program's overall gain so its measured integrated loudness matches a defined target, for example -23 LUFS under EBU R128 or -24 LKFS under ATSC A/85. Normalization aligns different programs to a common loudness rather than to peak level.", "plain_english": "This means turning a whole program up or down so its loudness hits an agreed number. It makes different shows and ads sound about equally loud. It is like setting every song in a playlist to the same volume.", "purpose_function": "It exists to stop jarring loudness jumps between programs and commercials and to help content meet loudness rules.", "practical_application": "An operator measures a file's integrated loudness, then applies a fixed gain offset so it meets the station's loudness target before playout.", "category": "Loudness Compliance", "related_terms": ["Program loudness measurement", "Regulatory loudness compliance", "Program optimization processor", "True peak", "LUFS"], "common_mistakes": ["Normalizing to peak level instead of to integrated loudness.", "Applying so much gain that true-peak limits are exceeded.", "Assuming normalization also fixes internal dynamics; it only shifts overall level."], "scenario_contexts": ["Bringing a delivered episode to -24 LKFS for a US network.", "Leveling a batch of commercials to a common loudness target.", "Preparing streaming files to a platform's loudness spec."]}, "88b5d3d6-2de9-4cc7-a5db-60c770443235": {"definition": "An audio processor that conditions complete program audio for delivery or transmission, optimizing loudness, dynamics and spectral balance through gain control, multiband compression, equalization and limiting so the output meets loudness targets and sounds consistent. In practice it overlaps with the on-air processor, with emphasis on program-level optimization.", "plain_english": "This is a processor that fine-tunes a whole program's sound for broadcast. It balances loudness, punch and tone so the program sounds even and clean. Think of it as an automatic mastering tool for TV or radio.", "purpose_function": "It exists to make program audio consistent and on-target for loudness while keeping it clear and controlled across varied content.", "practical_application": "An engineer routes program audio through the optimization processor and tunes its settings so the output meets loudness and peak limits without obvious pumping.", "category": "Broadcast Processing", "related_terms": ["On-air processor", "Processing preset recall", "Program normalization", "Regulatory loudness compliance", "Multiband compression"], "common_mistakes": ["Pushing optimization for maximum loudness, which flattens dynamics and can exceed loudness targets.", "Treating optimization as a substitute for correct source levels.", "Not verifying the processed output with a compliant loudness meter."], "scenario_contexts": ["Conditioning a network feed before distribution.", "Optimizing a live program's audio for consistent delivery.", "Tuning a processor to balance loudness and quality on music content."]}, "a11428fe-2f7e-46b7-a768-1f6204b9085f": {"definition": "Meeting the legal or mandated loudness requirements that govern broadcast audio, such as the US CALM Act enforcing ATSC A/85 (target -24 LKFS) or EBU R128 (target -23 LUFS) in Europe. Compliance is judged mainly on gated integrated program loudness together with true-peak limits.", "plain_english": "This means following the loudness rules that broadcasters are legally required to obey. These rules keep shows and ads at similar loudness so nothing blasts the viewer. It is like a speed limit, but for how loud audio can be.", "purpose_function": "It exists to protect audiences from sudden loud content and to give broadcasters a clear, measurable standard to meet.", "practical_application": "Engineers measure integrated loudness and true peak against the required target and keep logs to prove a station meets the rules.", "category": "Loudness Compliance", "related_terms": ["Program loudness measurement", "Program normalization", "Transmission peak control", "True peak", "LUFS"], "common_mistakes": ["Assuming that meeting a peak level also meets loudness rules; loudness and peak are separate.", "Checking only momentary or short-term loudness instead of integrated program loudness.", "Failing to keep the compliance logs that regulators may require."], "scenario_contexts": ["Preparing content to satisfy the CALM Act in the United States.", "Delivering programs to a European broadcaster under EBU R128.", "Auditing commercials for loudness before they air."]}, "4cc93295-3156-48f6-b976-e75a8383eaf1": {"definition": "A loudness reading averaged over a 3-second sliding window, expressed in LUFS and computed with the K-weighting of ITU-R BS.1770, and left ungated in short-term mode per EBU Tech 3341. It reflects the loudness of audio over the most recent few seconds.", "plain_english": "This is a loudness reading taken over the last three seconds. It smooths out quick jumps and shows the loudness of a short passage. It is like a rolling average of how loud a scene or sentence is.", "purpose_function": "It exists to show the loudness trend of recent content, sitting between the instant momentary reading and the whole-program integrated value.", "practical_application": "A mixer watches the short-term meter to keep dialogue and scenes within a sensible loudness range while working.", "category": "Loudness Measurement", "related_terms": ["Momentary loudness measurement", "Program loudness measurement", "Loudness range", "LUFS", "EBU R128"], "common_mistakes": ["Confusing the 3-second short-term window with the 400 ms momentary window.", "Using short-term readings for compliance instead of integrated program loudness.", "Expecting short-term loudness to match the final program value exactly."], "scenario_contexts": ["Checking that a dialogue scene stays within a target loudness range.", "Balancing loudness between sections of a program while mixing.", "Spot-checking a segment's loudness during editing."]}, "f2bfd1e5-6b2c-457a-a529-1b61659a74d7": {"definition": "The management of peak signal levels in the transmission chain, typically through peak limiting and true-peak limiting, to prevent overmodulation, clipping and inter-sample overs that would distort the signal or breach peak limits (for example a maximum of -1 dBTP under EBU R128). It protects both signal quality and the transmission equipment.", "plain_english": "This means stopping the audio peaks from getting too high before the signal is sent out. It keeps the loudest moments from distorting or overloading the transmitter. It is like a guardrail that catches the tallest spikes.", "purpose_function": "It exists to keep the signal clean, hold peaks within legal limits, and protect transmission equipment from overload.", "practical_application": "Engineers set a true-peak limiter so program peaks stay below the allowed ceiling, avoiding distortion and overmodulation on air.", "category": "Broadcast Processing", "related_terms": ["True peak", "On-air processor", "Regulatory loudness compliance", "Program normalization", "Peak limiting"], "common_mistakes": ["Confusing sample peak with true peak; inter-sample peaks can exceed the sample reading.", "Setting the peak ceiling too high and causing overmodulation or clipping.", "Relying on peak control to fix loudness, which it does not address."], "scenario_contexts": ["Setting a -1 dBTP ceiling for an EBU R128 delivery.", "Preventing overmodulation on an FM transmission.", "Guarding against inter-sample overs when encoding for streaming."]}, "a3a88b6c-4323-4552-be9d-a5550d381b4b": {"definition": "The final audio processing stage in a broadcast signal chain, placed just ahead of the transmitter, exciter, or encoder, that conditions program audio for over-the-air or streamed delivery. It applies automatic gain control, multiband compression, and peak or true-peak limiting to hold loudness on target and prevent overmodulation; on FM it also adds pre-emphasis and stereo encoding.", "plain_english": "It is the last box the sound goes through before it leaves the station. It evens out the volume and stops the signal from getting too strong. That way every show and advert reaches people at a steady, legal level.", "purpose_function": "It exists to give a station a consistent, competitive sound while staying inside legal loudness and modulation limits, protecting audio quality and the transmitter from over-driven levels.", "practical_application": "A broadcast engineer installs and tunes it at the transmitter site or in master control, choosing presets and loudness targets so on-air audio meets EBU R128 or ATSC A/85 while keeping the station's signature tone.", "category": "Broadcast Processing", "related_terms": ["Loudness normalization", "True-peak limiting", "EBU R128", "ATSC A/85", "Dialnorm", "Multiband compression"], "common_mistakes": ["Confusing loudness (LKFS/LUFS) with sample peak level, so the signal reads legal on a peak meter but still sounds too loud or too quiet to listeners.", "Over-processing with heavy compression and clipping to chase loudness, which adds distortion and listener fatigue instead of clarity.", "Assuming the processor alone guarantees compliance while ignoring correct dialnorm and metadata set upstream of it."], "scenario_contexts": ["An FM station installs an on-air processor before the exciter to build a consistent, competitive sound within modulation limits.", "A TV station adds a transmission processor to hold dialog loudness near -24 LKFS and avoid CALM Act 'loud commercial' complaints.", "During a format change, an engineer loads a new preset to shift the station's tonal balance and loudness density."]}, "706d0a18-9df8-4df6-8def-83df91ac0b26": {"definition": "A document produced by broadcast compliance monitoring or logging systems that records the measured technical quality of transmitted (aired) content over a defined period. It typically summarizes integrated and short-term loudness (LKFS/LUFS per ITU-R BS.1770), true-peak levels, dialnorm metadata, and any deviations from the applicable loudness standard such as EBU R128 or ATSC A/85.", "plain_english": "It is a record that shows how good the signal that went out on air really was. It lists things like the volume levels and any moments that broke the rules, so the station can prove it followed the loudness laws.", "purpose_function": "It gives a station documented proof that its output met loudness and technical rules, and helps engineers spot problems, fix them, or answer a complaint from a regulator or client.", "practical_application": "An engineer or QC operator reads the report from a loudness logger to confirm programs and commercials stayed within limits, and pulls it as evidence if a regulator or client questions an aired segment.", "category": "Loudness Compliance", "related_terms": ["Loudness logging", "Integrated loudness", "True-peak", "EBU R128", "ATSC A/85", "As-run log"], "common_mistakes": ["Treating the report as a simple pass/fail stamp while ignoring short-term loudness spikes that can still draw viewer complaints.", "Measuring against the wrong target or gating, so the report reads 'compliant' but was checked to the wrong standard.", "Not retaining reports long enough to cover the period a regulator or client may later request."], "scenario_contexts": ["After a broadcast day, a station archives nightly loudness reports as evidence of CALM Act or EBU R128 compliance.", "A client challenges the loudness of a delivered spot, and the station pulls the transmission-quality report to show it met the agreed target.", "A QC engineer scans the report to find an over-peak event and trace it back to a mislabeled source file."]}, "cf094062-2aea-48a7-b075-fd27f18f3017": {"definition": "A section of a tempo map that scripts a gradual accelerando, a steady rise in tempo across a span of bars, so a click track or sequenced score speeds up smoothly instead of jumping in abrupt steps. It defines the start tempo, end tempo, and the shape of the ramp used to drive a metronome click or MIDI playback in film scoring and music production.", "plain_english": "A tempo map tells software the beats per minute. An accelerando map is the part that makes the beat speed up little by little instead of all at once. It works like a car easing onto the gas, so the music races ahead in a smooth, planned way.", "purpose_function": "It lets a composer or editor plan a smooth speed-up so performers, click tracks, and synced picture all follow the same rising tempo. Without it, a tempo change would jump abruptly and break the feel or the sync to picture.", "practical_application": "Scoring to picture, an engineer enters or draws an accelerando in the DAW tempo track so the click gradually quickens toward a hit point. Players record to that click and the recorded music lines up with the on-screen action.", "category": "Scoring & Sync", "related_terms": ["Tempo map", "Click track", "Accent click", "Hit point", "Ritardando", "MIDI sequencing"], "common_mistakes": ["Confusing an accelerando (gradual speed-up) with a single-step tempo change, which produces an abrupt jump instead of a smooth ramp.", "Setting only start and end tempos without shaping the curve, so the acceleration feels uneven.", "Forgetting that the click and the recorded parts must both follow the same map, causing sync drift against picture."], "scenario_contexts": ["Scoring a chase scene where the music must gradually build speed toward an impact.", "Preparing a click track for an orchestra so players follow a planned tempo rise.", "Editing a MIDI mockup so a sampled score accelerates smoothly into a downbeat."]}, "2f0a19ae-a094-4eff-9f0f-f80e57305cec": {"definition": "In a click track, the accent click is the emphasized metronome sound placed on the first beat of each bar (the downbeat), usually higher in pitch or louder than the other beats. It lets a performer hear where each measure begins while playing to a fixed tempo.", "plain_english": "A click track is a steady beep that keeps musicians in time. The accent click is a louder or higher beep on the first beat of each bar. It acts like a stressed syllable in a word, telling you where each measure starts.", "purpose_function": "It marks the start of each bar so the player stays oriented within the measure and does not lose the count during long or syncopated passages. This keeps a performance locked to the grid and to picture.", "practical_application": "A recording engineer sets the metronome so beat one is accented, then sends the click to the drummer through headphones. In film scoring, the accented click helps players find downbeats that must land on visual hits.", "category": "Scoring & Sync", "related_terms": ["Click track", "Tempo map", "Downbeat", "Metronome", "Accelerando map", "Cue"], "common_mistakes": ["Placing the accent on the wrong beat in odd time signatures, so bar one no longer lines up.", "Making the accent click too loud, so it bleeds into microphones or fatigues the player.", "Assuming every DAW accents beat one by default when it often must be enabled."], "scenario_contexts": ["Tracking drums to a click where the player needs to feel each bar's downbeat.", "Recording an ensemble to picture so measures align with edit points.", "Setting up a metronome in an odd meter like 7/8 where accent placement matters."]}, "23ee0335-b765-4007-a96e-d9d7c95d50f6": {"definition": "Acoustic occlusion is the attenuation and low-pass filtering of a sound because a solid barrier blocks every path — both direct and reflected — between the source and the listener. In game and interactive audio it is modeled so a sound heard through a wall becomes quieter and more muffled, and is distinguished from obstruction, where reflected sound can still reach the listener around the object.", "plain_english": "Occlusion is what happens when a solid wall sits between you and a sound. The sound gets quieter and more muffled because it cannot reach you cleanly. It is like hearing music through a closed door: you catch the low rumble but lose the crisp high notes.", "purpose_function": "It exists to make virtual or simulated spaces sound believable by dulling sounds that are hidden behind solid objects. This gives players or listeners accurate cues about what is blocking a sound and where it sits.", "practical_application": "A game audio designer assigns occlusion so gunfire behind a concrete wall is filtered and lowered, then opens up as the player rounds the corner. In spatial mixes, engineers tune occlusion curves to match how much a given material blocks sound.", "category": "Spatial Audio", "related_terms": ["Obstruction", "Acoustic portal", "Acoustic room", "Diffraction", "Low-pass filter", "Reverb"], "common_mistakes": ["Confusing occlusion (all paths blocked) with obstruction (only the direct path blocked), which leads to wrong filtering.", "Applying only volume loss with no low-pass filtering, so blocked sound stays unnaturally bright.", "Ignoring the reflected or reverb path, so occluded sound cuts off too abruptly."], "scenario_contexts": ["Muffling an enemy's footsteps heard through a closed door in a game.", "Simulating a voice behind a wall in VR so it sounds dull and distant.", "Tuning how much a thick barrier blocks sound in an interactive spatial mix."]}, "d1af2863-cdac-4f6f-98c0-a4b8892a2d7b": {"definition": "An acoustic portal is a defined opening, such as a doorway or window, that models how sound propagates between two adjacent acoustic spaces (rooms). Represented as an oriented bounding box, it carries and spatializes sound passing from one room's reverb and sources into the next, and governs how that sound diffracts and attenuates as the opening is approached or closed.", "plain_english": "A portal is an opening, like a door or window, that lets sound pass from one room into another. In audio software it controls how much sound leaks through and from which direction. Think of standing in a hallway and hearing a party through an open door: the portal is that doorway.", "purpose_function": "It exists so connected spaces sound linked rather than sealed, letting a sound in one room bleed realistically into the next through its opening. This gives listeners a sense of layout and direction as they move between spaces.", "practical_application": "A game audio designer places a portal in each doorway so a room's reverb and sounds spill through the gap and shift as the player walks through. Closing the door narrows the portal, muffling and quieting the sound.", "category": "Spatial Audio", "related_terms": ["Acoustic room", "Acoustic occlusion", "Obstruction", "Diffraction", "Reverb", "Spatial audio"], "common_mistakes": ["Placing a portal where there is no real opening, so sound leaks through solid walls.", "Mis-sizing or mis-orienting the portal box, so the sound seems to come from the wrong direction.", "Forgetting to link the portal to both rooms, which breaks the propagation between them."], "scenario_contexts": ["Letting a boss room's music spill through a doorway into the hall as a player approaches.", "Modeling a window so outdoor ambience leaks into an interior scene.", "Muffling a room's sound as its door closes on the portal."]}, "e1a72b08-f440-4e1a-a2b3-ffa8440553f6": {"definition": "In spatial audio, an acoustic room is a bounded volume representing a distinct acoustic environment, with its own reverb and attenuation properties, that connects to neighboring spaces through portals. Sounds inside share the room's reverb bus and are spatialized correctly whether the listener is inside or outside the space.", "plain_english": "An acoustic room is a marked-off space in audio software that has its own echo and sound feel. Every sound inside it shares that same room sound. It is like how a tiled bathroom makes voices ring while a closet swallows them: each space has its own signature.", "purpose_function": "It exists to group sounds that belong to the same space so they share one believable reverb and behave correctly as listeners move in and out. This builds a convincing sense of separate but connected environments.", "practical_application": "A game audio designer defines a room for each area so its reverb and ambience switch as the player crosses a portal. Sounds emitted inside the room fold into its reverb and attenuate naturally when heard from outside.", "category": "Spatial Audio", "related_terms": ["Acoustic portal", "Acoustic occlusion", "Reverb", "Aux send", "Spatial audio", "Room tone"], "common_mistakes": ["Overlapping rooms without clear boundaries, so reverb switches unpredictably.", "Assigning the same reverb to every room, which erases the sense of distinct spaces.", "Forgetting to connect rooms with portals, sealing sound in unnaturally."], "scenario_contexts": ["Giving a cathedral level a long reverb that differs from a small side chapel.", "Switching ambience as a player moves from a garage into a hallway.", "Making a source inside a room sound muffled when heard from an adjoining space."]}, "b4c4a63e-5343-4058-b5e8-a79481f39199": {"definition": "In dubbing, the adaptation writer (also called the dialogue writer or adapter) reworks a translated script into natural, performable target-language dialogue that matches the on-screen actors' lip movements, timing, and delivery. The role bridges the literal translation and the final recordable dubbing script.", "plain_english": "When a show is dubbed into another language, the words must fit the actors' mouths and timing. The adaptation writer reshapes the translated lines to do that. They work like a lyricist fitting new words to an existing tune so everything still lines up.", "purpose_function": "The role exists to turn a plain translation into believable dialogue that syncs with lip movements and screen action, so dubbed lines feel natural. Without it, translated lines would not match the actors' mouths or pacing.", "practical_application": "Working from a translation and the picture, the adaptation writer rewrites lines to hit lip-sync points and hands the adapted script to the dub director and voice actors. They adjust word choices and length so each line fits the on-screen delivery.", "category": "Dubbing & Localization", "related_terms": ["Adapted script", "ADR blend", "Lip sync", "Dub director", "Voice-over", "Localization"], "common_mistakes": ["Confusing the adaptation writer with the literal translator; the adapter reshapes text for sync and performance.", "Prioritizing exact translation over lip-sync, so lines fail to match the mouth.", "Ignoring line length and rhythm, leaving actors unable to fit the words to picture."], "scenario_contexts": ["Rewriting a translated film script so lines match the actors' lip movements.", "Adjusting dialogue length so a dubbed line ends when the character stops speaking.", "Localizing an animated series into several languages for dubbing."]}, "25793f70-76b7-4fa2-a74f-e6021b329bfd": {"definition": "An adapted script (or dubbing script) is the target-language dialogue reworked from a translation so it matches the actors' lip movements, timing, and performance, ready for voice actors to record in the dubbing studio. It typically carries the synchronized lines along with timing cues and character notes.", "plain_english": "An adapted script is the dubbing version of the words, rewritten so they fit the actors' mouths and timing on screen. It is what the voice actors read in the booth. Think of it as new lyrics written to match the beats of a song already recorded.", "purpose_function": "It exists to give voice actors lines that both carry the original meaning and fit the on-screen lip movements and pacing. This lets a dubbed performance look and sound natural to the audience.", "practical_application": "In the dubbing studio, voice actors record to picture from the adapted script while the director checks sync line by line. Engineers use its timing cues to line up each take with the original delivery.", "category": "Dubbing & Localization", "related_terms": ["Adaptation writer", "Lip sync", "ADR blend", "Dub director", "Localization", "Voice-over"], "common_mistakes": ["Treating the adapted script as a plain translation, so lines run too long or short for the mouth.", "Leaving out timing or character cues that actors and engineers need for sync.", "Editing lines in the booth without checking that changes still match lip movements."], "scenario_contexts": ["Voice actors recording a dubbed film from the adapted script.", "A dub director checking each line's sync against the adapted script.", "Localizing a streaming series where each language gets its own adapted script."]}}$j$::jsonb)) d
WHERE g.id = d.id;
COMMIT;
